/*-----------------
    Chart fill

    A chart mounted as a flex child so it grows with its card. The floor
    matters: a percentage chart height resolves against the parent, and
    without it the chart can collapse to nothing.
-----------------*/
.chart-fill {
  flex: 1 1 auto;
  min-height: 17.5rem;
}

/*-----------------
	Dashboard widgets — merged in from the former
	components/_ui-dashboard-widgets.scss. These are generic, reusable
	components; they live with their own kind rather than in a page-shaped file.
-----------------*/
/* ---------- PERFORMANCE ANALYTICS ---------- */
.performance-panel {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 12px;
}

/* compact variants — replace ad-hoc inline padding overrides */
.chart-sparkline {
  height: 34px;
  margin-top: 8px;
}

.chart-sparkline .ln {
  fill: none;
  stroke: currentColor;
  stroke-width: 2.4;
  stroke-linecap: round;
  stroke-linejoin: round;
}

.chart-sparkline .ar {
  fill: currentColor;
  opacity: 0.18;
}

/* compact stat strip — communication volume at a glance */
.communication-stats {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 8px;
  margin-bottom: 14px;
}

.chart-surface {
  padding: 9px 10px;
  border: 1px solid var(--border-soft);
  border-radius: var(--radius-list);
  background: var(--surface);
  border-left-width: 3px;
}

.chart-surface b {
  display: block;
  font-size: 16px;
  font-weight: 800;
  color: var(--heading);
  letter-spacing: -0.02em;
  line-height: 1.1;
}

.chart-surface span {
  font-size: 10.5px;
  color: var(--muted);
}

@media (max-width: 575.98px) {
  .communication-stats {
    grid-template-columns: repeat(2, 1fr);
  }
}
/* ---------- ATTENDANCE HEATMAP ---------- */
.heatmap {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(16px, 1fr));
  gap: 4px;
}

.heatmap span {
  aspect-ratio: 1;
  border-radius: 4px;
  background: var(--surface-soft);
}

.heatmap span.l1 {
  background: rgba(22, 163, 74, 0.25);
}

.heatmap span.l2 {
  background: rgba(22, 163, 74, 0.45);
}

.heatmap span.l3 {
  background: rgba(22, 163, 74, 0.68);
}

.heatmap span.l4 {
  background: rgba(22, 163, 74, 0.9);
}

.heatmap span.ab {
  background: rgba(220, 38, 38, 0.55);
}

.heatmap-legend {
  gap: 5px;
  font-size: 10.5px;
  color: var(--muted);
  margin-top: 8px;
}

.heatmap-legend i {
  width: 12px;
  height: 12px;
  border-radius: 3px;
  display: inline-block;
}

/* mini attendance donut */
.attendance-split {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 10px;
}

.attendance-split .v {
  font-size: 20px;
  font-weight: 800;
  color: var(--heading);
}

.attendance-split .l {
  font-size: 10.5px;
  color: var(--muted);
}

@media (max-width: 1199px) {
  .performance-panel {
    grid-template-columns: 1fr;
  }
}
/* ---------- SCORE RAIL ---------- */
/* headline ring plus supporting facts, used as the left rail of an
   analytics panel */
.performance-panel-rail {
  display: grid;
  grid-template-columns: 250px 1fr 300px;
  gap: 20px;
}

/* ---------- TREND + BAR CHART ---------- */
.trend-panel {
  padding: 12px 14px;
  border: 1px solid var(--border-soft);
  border-radius: var(--radius-list);
  background: var(--surface);
}

.trend-header {
  gap: 10px;
}

.trend-header b {
  font-size: 24px;
  font-weight: 800;
  letter-spacing: -0.03em;
  color: var(--heading);
  line-height: 1;
}

.trend-header b small {
  font-size: 13px;
  font-weight: 700;
  color: var(--muted);
}

.trend-header span {
  display: block;
  font-size: 10.5px;
  color: var(--muted);
  margin-top: 3px;
}

.trend-panel .chart-sparkline {
  height: 46px;
}

.bar-chart {
  display: grid;
  grid-auto-flow: column;
  grid-auto-columns: 1fr;
  gap: 8px;
  align-items: end;
  height: 128px;
  margin-top: 14px;
}

.bar-chart .b {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: flex-end;
  height: 100%;
  gap: 5px;
}

.bar-chart .val {
  font-size: 10.5px;
  font-weight: 700;
  color: var(--muted);
  font-variant-numeric: tabular-nums;
}

/* column height comes from an inline `height` so the value stays with the data */
.bar-chart .col {
  width: 100%;
  max-width: 30px;
  border-radius: 7px 7px 3px 3px;
}

.bar-chart .cap {
  font-size: 10px;
  color: var(--muted);
}

.bar-chart .b.on .val {
  color: var(--heading);
}

/* ---------- DONUT + LEGEND ---------- */
/* every legend row maps to an arc, so chart and legend always agree.
   Arc lengths are set inline via stroke-dasharray (circumference 339.3). */
.donut-chart {
  width: 158px;
  height: 158px;
  margin: 0 auto;
}

.donut-chart svg {
  transform: rotate(-90deg);
  width: 100%;
  height: 100%;
  overflow: visible;
}

.donut-chart circle {
  fill: none;
  stroke-width: 11;
}

.donut-chart .track {
  stroke: var(--surface-soft);
}

.donut-chart .seg {
  stroke: currentColor;
  stroke-linecap: round;
}

.donut-chart .c {
  position: absolute;
  inset: 0;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  text-align: center;
}

.donut-chart .c b {
  font-size: 27px;
  font-weight: 800;
  letter-spacing: -0.5px;
  color: var(--heading);
  line-height: 1;
}

.donut-chart .c span {
  font-size: 10.5px;
  color: var(--muted);
  margin-top: 2px;
}

.donut-chart .c em {
  font-style: normal;
  font-size: 10px;
  font-weight: 600;
  color: var(--heading);
  margin-top: 5px;
  padding: 2px 8px;
  border-radius: 999px;
  background: var(--surface-soft);
}

.chart-legend {
  gap: 8px;
}

.chart-legend > div {
  display: flex;
  align-items: center;
  gap: 7px;
  font-size: 12.5px;
  color: var(--muted);
}

.chart-legend .k {
  width: 10px;
  height: 10px;
  border-radius: 3px;
  flex-shrink: 0;
}

.chart-legend b {
  margin-left: auto;
  color: var(--heading);
  font-variant-numeric: tabular-nums;
}

@media (max-width: 1399px) {
  .performance-panel-rail {
    grid-template-columns: 200px 1fr 260px;
    gap: 16px;
  }
}
@media (max-width: 1199px) {
  .performance-panel-rail {
    grid-template-columns: 1fr 1fr;
  }
  .performance-panel-rail > .trend-column {
    grid-column: 1/-1;
  }
}
@media (max-width: 767px) {
  .performance-panel-rail {
    grid-template-columns: 1fr;
  }
}
