/*-----------------
	Dashboard widgets — merged in from the former
	components/_ui-dashboard-widgets.scss. These are generic, reusable
	components; they live with their own kind rather than in a page-shaped file.
-----------------*/
/* ring (shared) */
.progress-ring {
  --v: 0;
  width: 90px;
  height: 90px;
  border-radius: 50%;
  display: grid;
  place-items: center;
  background: conic-gradient(currentColor calc(var(--v) * 1%), var(--bs-secondary-bg) 0);
}

.progress-ring-hole {
  width: 68px;
  height: 68px;
  border-radius: 50%;
  background: var(--surface);
  display: flex;
  place-items: center;
  justify-content: center;
  flex-direction: column;
}

.progress-ring-hole b {
  font-size: 20px;
  font-weight: 800;
  color: var(--heading);
}

.progress-ring-hole span {
  font-size: 9px;
  color: var(--muted);
}

.score-rail {
  gap: 10px;
  padding: 16px 14px;
  border: 1px solid var(--border-soft);
  border-radius: var(--radius-list);
  background: linear-gradient(180deg, var(--tone-brand-soft), var(--surface) 62%);
}

/* ---------- SPLIT BAR ---------- */
/* one track divided into labelled segments — each segment carries a bg-* */
.split-bar {
  margin-top: 12px;
  padding-top: 12px;
  border-top: 1px solid var(--border-soft);
}

.split-bar-head {
  margin-bottom: 7px;
}

.split-bar-head span {
  font-size: 10px;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: var(--muted);
  font-weight: 650;
}

.split-bar-head b {
  font-size: 11px;
  color: var(--heading);
}

.split-bar-track {
  gap: 2px;
  height: 9px;
  border-radius: 999px;
  background: var(--surface-soft);
}

.split-bar-keys {
  gap: 4px 10px;
  margin-top: 8px;
}

.split-bar-keys > span {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  font-size: 10px;
  color: var(--muted);
}

.split-bar-keys > span > i {
  width: 8px;
  height: 8px;
  border-radius: 3px;
}

.progress-ring-sm {
  width: 72px;
  height: 72px;
}

.progress-ring-sm .progress-ring-hole {
  width: 54px;
  height: 54px;
}

.progress-ring-sm .progress-ring-hole b {
  font-size: 16px;
}

/* ---------- LABELLED PROGRESS ROWS ---------- */
.progress-list {
  gap: 12px;
}

.progress-list-item .top {
  display: flex;
  align-items: center;
  justify-content: space-between;
  font-size: 12.5px;
  color: var(--heading);
  margin-bottom: 5px;
}

.progress-list-item .top > span {
  display: inline-flex;
  align-items: center;
  gap: 6px;
}

.progress-list-item .top .ic {
  width: 24px;
  height: 24px;
  border-radius: 7px;
  display: grid;
  place-items: center;
  font-size: 13px;
}

