}
.card.card-bg-light .card-footer {
  background-color: rgba(0, 0, 0, 0.05) !important;
  color: #6A7287;
  border-block-start: #9CA1AF;
}
.card.card-bg-dark {
  background-color: #202C4B;
  color: #FFF;
}
.card.card-bg-dark .card-header {
  background-color: rgba(255, 255, 255, 0.1) !important;
