  white-space: normal;
}
.data-table {
  /*-----------------
      Table shell
  -----------------*/
}
.data-table > .table,
.data-table > .table-responsive > .table {
  width: 100%;
  margin-bottom: 0;
  border-collapse: separate;
  border-spacing: 0;
  /* Bootstrap paints cell backgrounds through this variable; clearing it
     lets the rules below own the surface and hover colours */
