  color: var(--bs-secondary-color);
  font-size: 12px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  padding: 14px 16px;
  border-bottom: 1px solid var(--bs-border-color);
  border-top: 0;
  white-space: nowrap;
  user-select: none;
  vertical-align: middle;
