  color: #dc2626;
}
.data-table .dt-ib.danger:hover {
  border-color: #dc2626;
  color: #dc2626;
  background: rgba(220, 38, 38, 0.08);
}
.data-table .dt-sortable {
  cursor: pointer;
  transition: color var(--transition);
}
.data-table .dt-sortable:hover {
  color: var(--bs-primary);
}
.data-table .dt-sortable .dt-sort-ic {
  font-size: 14px;
  opacity: 0.5;
  vertical-align: middle;
  transition: transform var(--transition), opacity var(--transition);
}
.data-table .dt-sortable.dt-sort-asc .dt-sort-ic {
  opacity: 1;
  color: var(--bs-primary);
}
.data-table .dt-sortable.dt-sort-desc .dt-sort-ic {
  opacity: 1;
  color: var(--bs-primary);
  transform: rotate(180deg);
}
.data-table .dt-resize {
  position: absolute;
  right: 0;
  top: 0;
  bottom: 0;
  width: 6px;
  cursor: col-resize;
  opacity: 0;
}
.data-table > .table > thead > tr > th:hover .dt-resize {
  opacity: 1;
  background: var(--tint-primary);
}
.data-table .dt-expand {
  width: 26px;
  height: 26px;
  border-radius: 7px;
  border: 1px solid var(--bs-border-color);
  background: var(--bs-body-bg);
  color: var(--bs-secondary-color);
  display: inline-flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  transition: all var(--transition);
}
.data-table .dt-expand i {
  transition: transform var(--transition);
}
.data-table .dt-expand[aria-expanded=true] {
  background: var(--bs-primary);
  border-color: var(--bs-primary);
  color: var(--bs-body-bg);
}
.data-table .dt-expand[aria-expanded=true] i {
  transform: rotate(90deg);
}
.data-table > .table > tbody > tr.dt-detail > td {
  padding: 0 !important;
  background: var(--bs-secondary-bg) !important;
  border-bottom: 0;
}
.data-table .dt-detail-inner {
  display: none;
  padding: 18px 20px;
}
.data-table > .table > tbody > tr.dt-detail.open > td {
  border-bottom: 1px solid var(--bs-border-color);
}
.data-table > .table > tbody > tr.dt-detail.open .dt-detail-inner {
  display: block;
}
.data-table > .table > tbody > tr:last-child > td,
.data-table > .table > tbody > tr:last-child > th {
  border-bottom: 0;
}

/*-----------------
    Selection column

    A checkbox that matches the grid rather than the browser default, plus the
    sticky first column it usually sits in.
-----------------*/
.data-table .dt-check {
  appearance: none;
  -webkit-appearance: none;
  width: 18px;
  height: 18px;
  border: 1.8px solid var(--bs-border-color);
  border-radius: 5px;
  background: var(--bs-body-bg);
  cursor: pointer;
  position: relative;
  transition: all var(--transition);
  vertical-align: middle;
}
.data-table .dt-check:hover {
  border-color: var(--bs-primary);
}
.data-table .dt-check:checked, .data-table .dt-check:indeterminate {
  background: var(--bs-primary);
  border-color: var(--bs-primary);
}
.data-table .dt-check:checked::after {
  content: "";
  position: absolute;
  left: 5px;
  top: 1.5px;
  width: 5px;
  height: 9px;
  border: solid var(--bs-body-bg);
  border-width: 0 2px 2px 0;
  transform: rotate(45deg);
}
.data-table .dt-check:indeterminate::after {
  content: "";
  position: absolute;
  left: 3px;
  top: 6px;
  width: 8px;
  height: 2px;
  background: var(--bs-body-bg);
  border-radius: 1px;
}
.data-table > .table > thead > tr > th.dt-pin,
.data-table > .table > tbody > tr > td.dt-pin {
  position: sticky;
  left: 0;
  z-index: 4;
  background: var(--bs-body-bg);
}
.data-table > .table > thead > tr > th.dt-pin {
  z-index: 6;
  background: var(--bs-secondary-bg);
}

/* ============================================================
   Opt-in mobile card mode — add `.dt-cards` to a `.data-table`
   and below the lg breakpoint its rows become stacked cards
   with sticky action buttons. Desktop is untouched; pages that
   don't opt in keep the horizontally-scrolling grid.
   ============================================================ */
@media (max-width: 991.98px) {
  .data-table.dt-cards {
    overflow: visible;
  }
  .data-table.dt-cards > .table {
    display: block;
  }
  .data-table.dt-cards > .table > thead {
    display: none;
  }
  .data-table.dt-cards > .table > tbody {
    display: block;
  }
  .data-table.dt-cards > .table > tbody > tr.dt-row {
    display: block;
    position: relative;
    border: 1px solid var(--bs-border-color);
    border-radius: 12px;
    margin: 0 12px 12px;
    padding: 42px 14px 6px;
    background: var(--bs-body-bg);
    box-shadow: 0 1px 2px rgba(17, 24, 39, 0.05);
  }
  .data-table.dt-cards > .table > tbody > tr.dt-row.dt-selected {
    box-shadow: 0 0 0 2px var(--bs-primary) inset;
  }
  .data-table.dt-cards > .table > tbody > tr.dt-row > td {
    display: block;
    width: auto !important;
    border: 0 !important;
    padding: 6px 0;
  }
  .data-table.dt-cards > .table > tbody > tr.dt-row > td.dt-pin,
  .data-table.dt-cards > .table > tbody > tr.dt-row > td.card-expand-toggle {
    position: absolute;
    top: 10px;
    width: auto !important;
    padding: 0;
    background: transparent;
  }
  .data-table.dt-cards > .table > tbody > tr.dt-row > td.dt-pin {
    left: 14px;
  }
  .data-table.dt-cards > .table > tbody > tr.dt-row > td.card-expand-toggle {
    right: 14px;
  }
  .data-table.dt-cards > .table > tbody > tr.dt-row > td:last-child {
    position: sticky;
    bottom: 0;
    z-index: 1;
    margin-top: 8px;
    padding: 8px 0 2px;
    border-top: 1px solid var(--bs-border-color) !important;
    background: var(--bs-body-bg);
  }
  .data-table.dt-cards > .table > tbody > tr.dt-row > td:last-child .dt-actions {
    justify-content: flex-start;
    flex-wrap: wrap;
  }
  .data-table.dt-cards > .table > tbody > tr.dt-detail {
    display: block;
    border: 0;
  }
  .data-table.dt-cards > .table > tbody > tr.dt-detail > td {
    display: block;
    padding: 0 12px;
  }
  .data-table.dt-cards > .table > tbody > tr.dt-detail:not(.open) {
    display: none;
  }
}
/* ============================================================
   CARD TOOLBAR / QUICKBAR / FOOTER
   Workspace chrome for a `.data-table` card — toolbar, quick
   filters, filter chips, empty state and pagination footer.
   Renamed from the sw-* workspace set so the data-table card
   owns these as self-contained components. Colour tokens come
   from the `--sw-*` custom properties set on `.data-workspace`
   with plain fallbacks for standalone use.
   ============================================================ */
/* ---------- Toolbar ---------- */
.card-toolbar {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 10px;
  width: 100%;
}
.card-toolbar .card-search {
  position: relative;
  flex: 0 1 250px;
  min-width: 180px;
}
.card-toolbar .card-search input {
  width: 100%;
  height: 34px;
  border: 1px solid var(--bs-border-color);
  border-radius: 8px;
  background: var(--bs-secondary-bg);
  padding: 0 58px 0 32px;
  font-size: 13px;
  transition: box-shadow var(--transition), border-color var(--transition), background var(--transition);
}
.card-toolbar .card-search input:focus {
  outline: none;
  background: var(--bs-body-bg);
  border-color: var(--bs-primary);
  box-shadow: 0 0 0 3px rgba(61, 94, 225, 0.1);
}
.card-toolbar .card-search .card-search-ic {
  position: absolute;
  left: 11px;
  top: 50%;
  transform: translateY(-50%);
  color: var(--bs-secondary-color);
  font-size: 15px;
  pointer-events: none;
}
.card-toolbar .card-search .card-search-kbd {
  position: absolute;
  right: 4px;
  top: 50%;
  transform: translateY(-50%);
  font-size: 10px;
  color: var(--bs-secondary-color);
  border: 1px solid var(--bs-border-color);
  border-radius: 7px;
  padding: 8px 5px;
  background: var(--bs-body-bg);
  line-height: 1;
}

/* ---------- Pill button ---------- */
.card-btn {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  height: 34px;
  padding: 0 11px;
  border: 1px solid var(--bs-border-color);
  border-radius: 8px;
  background: var(--bs-body-bg);
  color: var(--bs-body-color, #1f2937);
  font-size: 12.5px;
  font-weight: 500;
  line-height: 1;
  cursor: pointer;
  transition: all var(--transition);
  white-space: nowrap;
}
.card-btn i {
  font-size: 15px;
}
.card-btn:hover {
  background: var(--bs-tertiary-bg);
  border-color: var(--bs-primary);
  color: var(--bs-primary);
  transform: translateY(-1px);
  box-shadow: 0 1px 2px rgba(17, 24, 39, 0.06);
}
.card-btn.card-btn-icon {
  padding: 0;
  width: 34px;
  justify-content: center;
}
.card-btn.active, .card-btn[aria-pressed=true] {
  background: rgba(61, 94, 225, 0.1);
  border-color: var(--bs-primary);
  color: var(--bs-primary);
}

/* ---------- Density segmented control ---------- */
.card-density {
  display: inline-flex;
  border: 1px solid var(--bs-border-color);
  border-radius: 8px;
  overflow: hidden;
  background: var(--bs-body-bg);
}
.card-density button {
  border: 0;
  background: transparent;
  width: 32px;
  height: 34px;
  color: var(--bs-secondary-color);
  cursor: pointer;
  transition: all var(--transition);
  display: inline-flex;
  align-items: center;
  justify-content: center;
}
.card-density button i {
  font-size: 16px;
}
.card-density button.active {
  background: rgba(61, 94, 225, 0.1);
  color: var(--bs-primary);
}

/* ---------- Quick filter bar ---------- */
.card-quickbar {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-wrap: wrap;
  margin-top: 10px;
}
.card-quickbar .card-btn {
  height: 32px;
  padding: 0 10px;
}

.card-quick {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  height: 32px;
  padding: 0 12px;
  border-radius: 999px;
  border: 1px solid var(--bs-border-color);
  background: var(--bs-body-bg);
  color: var(--bs-secondary-color);
  font-size: 12.5px;
  font-weight: 500;
  cursor: pointer;
  transition: all var(--transition);
}
.card-quick i {
  font-size: 15px;
}
.card-quick .card-quick-count {
  background: var(--bs-secondary-bg);
  border-radius: 999px;
  padding: 1px 7px;
  font-size: 11px;
  font-weight: 600;
  color: var(--bs-body-color, #1f2937);
}
.card-quick:hover {
  border-color: var(--bs-primary);
  color: var(--bs-primary);
}
.card-quick.active {
  background: var(--bs-primary);
  border-color: var(--bs-primary);
  color: var(--bs-body-bg);
}
.card-quick.active .card-quick-count {
  background: rgba(255, 255, 255, 0.25);
  color: var(--bs-body-bg);
}

/* ---------- Active filter chips ---------- */
.card-chips {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-wrap: wrap;
  margin-top: 12px;
}
.card-chips:empty {
  display: none;
}
.card-chips .card-chip-clear {
  background: transparent;
  color: var(--bs-secondary-color);
  text-decoration: underline;
  cursor: pointer;
  border: 0;
  font-size: 12px;
}

.card-chip {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  height: 28px;
  padding: 0 6px 0 12px;
  border-radius: 999px;
  background: rgba(61, 94, 225, 0.1);
  color: var(--bs-primary);
  font-size: 12px;
  font-weight: 500;
}
.card-chip button {
  border: 0;
  background: rgba(0, 0, 0, 0.06);
  color: inherit;
  width: 18px;
  height: 18px;
  border-radius: 50%;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  font-size: 13px;
  line-height: 1;
  transition: background var(--transition);
}
.card-chip button:hover {
  background: rgba(0, 0, 0, 0.16);
}

/* ---------- Menu heading (inside dropdowns) ---------- */
.dropdown-menu .card-menu-head {
  font-size: 11px;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: var(--bs-secondary-color);
  padding: 6px 10px 4px;
  font-weight: 600;
}

/* ---------- Empty state ---------- */
.card-empty {
  display: none;
  text-align: center;
  padding: 60px 20px;
}
.card-empty.show {
  display: block;
}
.card-empty .card-empty-art {
  width: 132px;
  height: 132px;
  margin: 0 auto 18px;
  border-radius: 50%;
  background: radial-gradient(circle at 30% 30%, rgba(61, 94, 225, 0.1), transparent 70%);
  display: flex;
  align-items: center;
  justify-content: center;
}
.card-empty .card-empty-art i {
  font-size: 60px;
  color: var(--bs-primary);
}
.card-empty h5 {
  font-weight: 700;
  margin-bottom: 6px;
}
.card-empty p {
  color: var(--bs-secondary-color);
  max-width: 380px;
  margin: 0 auto 18px;
}

/* ---------- Pagination footer ---------- */
.card-foot {
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 10px;
  padding: 10px 12px;
  border-top: 1px solid var(--bs-border-color);
}

.card-foot-info {
  font-size: 12.5px;
  color: var(--bs-secondary-color);
}
.card-foot-info span {
  color: var(--bs-heading-color, #111827);
  font-weight: 600;
}

.card-foot-size {
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: 12.5px;
  color: var(--bs-secondary-color);
  margin-left: auto;
}
.card-foot-size .form-select {
  height: 30px;
  width: auto;
  padding: 0 26px 0 9px;
  font-size: 12.5px;
}

.card-pagination {
  display: flex;
  align-items: center;
  gap: 3px;
}

.card-page-numbers {
  display: inline-flex;
  gap: 3px;
  align-items: center;
}

.card-page-btn {
  min-width: 30px;
  height: 30px;
  padding: 0 6px;
  border: 1px solid var(--bs-border-color);
  background: var(--bs-body-bg);
  border-radius: 8px;
  color: var(--bs-body-color, #374151);
  font-size: 12.5px;
  font-weight: 500;
  cursor: pointer;
  transition: all var(--transition);
  display: inline-flex;
  align-items: center;
  justify-content: center;
}
.card-page-btn i {
  font-size: 15px;
}
.card-page-btn:hover:not(:disabled) {
  border-color: var(--bs-primary);
  color: var(--bs-primary);
}
.card-page-btn.active {
  background: var(--bs-primary);
  border-color: var(--bs-primary);
  color: var(--bs-body-bg);
}
.card-page-btn:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}

/* ---------- Fullscreen ---------- */
.data-workspace.card-fullscreen {
  position: fixed;
  inset: 0;
  z-index: 1055;
  background: var(--bs-body-bg, var(--bs-body-bg));
  padding: 18px;
  overflow: auto;
}
.data-workspace.card-fullscreen .data-table {
  max-height: calc(100vh - 260px);
  overflow: auto;
}

/* ---------- Toolbar extras (filter menus, count badges, search clear) ---------- */
.card-filter-menu {
  min-width: 340px;
  max-width: 92vw;
}

.card-col-menu {
  min-width: 210px;
  max-width: 92vw;
}

.card-search-x[hidden],
.card-count[hidden],
.card-clear-quick[hidden] {
  display: none;
}

.card-search .card-search-x {
  position: absolute;
  right: 10px;
  top: 50%;
  transform: translateY(-50%);
  width: 20px;
  height: 20px;
  border: 0;
  border-radius: 50%;
  background: var(--bs-secondary-bg);
  color: var(--bs-secondary-color, var(--bs-secondary-color));
  display: flex;
  place-items: center;
  font-size: 13px;
  cursor: pointer;
  align-items: center;
  justify-content: center;
  transition: all var(--transition);
}
.card-search .card-search-x:hover {
  background: var(--bs-primary);
  color: var(--bs-body-bg);
}

.card-vcount {
  margin-left: auto;
  font-size: 11px;
  font-weight: 700;
  color: var(--bs-secondary-color, var(--bs-secondary-color));
}

.card-count {
  display: inline-grid;
  place-items: center;
  min-width: 18px;
  height: 18px;
  padding: 0 5px;
  border-radius: 999px;
  background: var(--bs-primary);
  color: var(--bs-body-bg);
  font-size: 10px;
  font-weight: 700;
  line-height: 1;
}

/* ============================================================
   DATA-TABLE STATUS + PRESENCE EXTENSIONS
   ============================================================ */
/* extra status pills */
.dt-pill.is-blocked {
  background: rgba(220, 38, 38, 0.12);
  color: #b91c1c;
}

.dt-pill.is-suspended {
  background: rgba(217, 119, 6, 0.14);
  color: #b45309;
}

.dt-pill.is-review {
  background: rgba(99, 102, 241, 0.12);
  color: #4338ca;
}

.dt-pill.is-completed {
  background: rgba(13, 148, 136, 0.12);
  color: #0f766e;
}

.dt-pill.is-active .dt-pill-dot {
  background: #16a34a;
}

.dt-pill.is-inactive .dt-pill-dot {
  background: var(--bs-secondary-color);
}

.dt-pill.is-pending .dt-pill-dot {
  background: #d97706;
}

.dt-pill.is-blocked .dt-pill-dot {
  background: #dc2626;
}

.dt-pill.is-suspended .dt-pill-dot {
  background: #ea580c;
}

.dt-pill.is-review .dt-pill-dot {
  background: #6366f1;
}

.dt-pill.is-completed .dt-pill-dot {
  background: #0d9488;
}

/* live statuses get a soft pulse ring */
.dt-pill.is-active .dt-pill-dot,
.dt-pill.is-pending .dt-pill-dot,
.dt-pill.is-review .dt-pill-dot {
  position: relative;
}

.dt-pill.is-active .dt-pill-dot::after,
.dt-pill.is-pending .dt-pill-dot::after,
.dt-pill.is-review .dt-pill-dot::after {
  content: "";
  position: absolute;
  inset: -3px;
  border-radius: 50%;
  background: inherit;
  opacity: 0.45;
  animation: dt-pill-pulse 1.8s ease-out infinite;
}

@keyframes dt-pill-pulse {
  0% {
    transform: scale(0.6);
    opacity: 0.5;
  }
  70% {
    transform: scale(1.9);
    opacity: 0;
  }
  100% {
    opacity: 0;
  }
}
/* online presence dot on the profile avatar */
.dt-user .dt-avatar {
  position: relative;
  overflow: visible;
}

.dt-user .dt-avatar .dt-presence {
  position: absolute;
  right: -1px;
  bottom: -1px;
  width: 11px;
  height: 11px;
  border-radius: 50%;
  background: #9ca3af;
  border: 2px solid var(--bs-body-bg);
  box-shadow: 0 0 0 0 rgba(22, 163, 74, 0.5);
}

.dt-user .dt-avatar .dt-presence.on {
  background: #16a34a;
  animation: dt-presence-pulse 2s ease-out infinite;
}

@keyframes dt-presence-pulse {
  0% {
    box-shadow: 0 0 0 0 rgba(22, 163, 74, 0.5);
  }
  70% {
    box-shadow: 0 0 0 6px rgba(22, 163, 74, 0);
  }
  100% {
    box-shadow: 0 0 0 0 rgba(22, 163, 74, 0);
  }
}
/* ---------- Last-login cell ---------- */
.dt-login {
  line-height: 1.35;
}

.dt-login-date {
  font-weight: 500;
  color: var(--bs-body-color, #1f2937);
}

.dt-login-time {
  font-size: 12px;
  color: var(--bs-secondary-color, var(--bs-secondary-color));
}

.dt-login-rel {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  font-size: 11px;
  color: var(--bs-secondary-color, var(--bs-secondary-color));
  margin-top: 2px;
}

.dt-login-rel i {
  font-size: 12px;
}

.dt-login.is-never .dt-login-date {
  color: var(--bs-secondary-color, var(--bs-secondary-color));
  font-weight: 400;
}

[data-bs-theme=dark] .dt-login-date {
  color: #e9edf5;
}

.data-table.dt-scroll {
  max-height: calc(100vh - 300px);
  min-height: 260px;
}

/* An absent row is tinted rather than recoloured, so its text stays as legible
   as every other row. Bootstrap's `.table-*` row variants cannot do this here:
   the grid paints an opaque background on the cells themselves, and the
   variant's `--bs-table-color` washes the roll and admission numbers out. */
.data-table > .table > tbody > tr.dt-absent > td {
  background: rgba(234, 179, 0, 0.08);
}

.data-table > .table > tbody > tr.dt-absent:hover > td {
  background: rgba(234, 179, 0, 0.14);
}

/* ============================================================
   Class Routine — weekly schedule workspace
   A day × time grid of subject cards, plus the mobile agenda.
   Scoped to .rt-* so it never touches the rest of the app.
   ============================================================ */
.rt-grid table {
  width: 100%;
  border-collapse: separate;
  border-spacing: 0;
  min-width: 940px;
}
.rt-grid thead th {
  position: sticky;
  top: 0;
  z-index: 3;
  background: var(--bs-secondary-bg);
  font-size: 12px;
  font-weight: 600;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  color: var(--bs-secondary-color);
  padding: 12px 10px;
  text-align: left;
  border-bottom: 1px solid var(--bs-border-color, #e6e9f0);
