  box-shadow: var(--shadow-card);
}

/* .lesson-time — all declarations now Bootstrap utilities in the markup */
.lesson-time b {
  display: block;
  font-size: 13px;
  font-weight: 800;
  color: var(--heading);
}

.lesson-time span {
  font-size: 10px;
  color: var(--muted);
}

.lesson-body b {
  font-size: 13.5px;
  color: var(--heading);
}

.lesson-tags {
  gap: 5px;
  margin-top: 4px;
}

.lesson-tag {
  font-size: 10.5px;
