  padding: 11px 12px;
  border: 1px solid var(--border-soft);
  border-radius: var(--radius-list);
  background: var(--surface);
  transition: transform var(--transition-card), box-shadow var(--transition-card);
}

.info-list-item:hover {
  transform: translateY(-2px);
  box-shadow: var(--shadow-card);
}

.info-list-icon {
  width: 38px;
  height: 38px;
  border-radius: 11px;
  display: grid;
  place-items: center;
  font-size: 18px;
}

.info-list-item-sm {
  padding: 9px;
}

.info-list-item-sm .info-list-icon {
  width: 30px;
  height: 30px;
  border-radius: 9px;
  font-size: 15px;
}

.info-list-avatar {
  width: 38px;
  height: 38px;
  border-radius: 11px;
}

.info-list-body {
  flex: 1;
  min-width: 0;
}

.info-list-body b {
  display: block;
  font-size: 13px;
  color: var(--heading);
}

.info-list-body span {
  font-size: 11.5px;
  color: var(--muted);
}

.info-list-body .un {
  display: -webkit-box;
  -webkit-line-clamp: 1;
  -webkit-box-orient: vertical;
  overflow: hidden;
}

.info-list-end {
  font-size: 11px;
  color: var(--muted);
  gap: 4px;
}

.insight-badge {
  gap: 4px;
  font-size: 10px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  color: var(--tone-purple);
  background: var(--tone-purple-soft);
  padding: 3px 9px;
  border-radius: 999px;
}

.insight-score {
  gap: 14px;
  padding: 14px;
  border-radius: var(--radius-list);
  background: var(--surface);
  border: 1px solid var(--border-soft);
  margin-bottom: 12px;
}

.insight-score .tx b {
  font-size: 15px;
  color: var(--heading);
}

.insight-score .tx p {
  margin: 2px 0 0;
  font-size: 11.5px;
  color: var(--muted);
}

.insight-item {
  gap: 10px;
  padding: 10px 0;
  border-bottom: 1px solid var(--border-soft);
}

.insight-item:last-child {
  border-bottom: 0;
}

.insight-item .ic {
  width: 30px;
  height: 30px;
  border-radius: 9px;
  display: grid;
  place-items: center;
  font-size: 15px;
  flex-shrink: 0;
}

.insight-item .tx b {
  display: block;
  font-size: 12.5px;
  color: var(--heading);
}

.insight-item .tx span {
  font-size: 11px;
  color: var(--muted);
}

/* ---------- TERM LADDER ---------- */
.term-list {
  gap: 6px;
  margin-top: 12px;
  padding-top: 12px;
  border-top: 1px solid var(--border-soft);
}

.term-item {
  display: grid;
  grid-template-columns: 1fr auto auto;
  gap: 8px;
  padding: 7px 10px;
  border-radius: 9px;
  border: 1px solid var(--border-soft);
  border-left-width: 3px;
  background: var(--surface);
}

.term-item .t {
  font-size: 11.5px;
  font-weight: 600;
  color: var(--heading);
}

.term-item .v {
  font-size: 14px;
  font-weight: 800;
  letter-spacing: -0.02em;
  color: var(--heading);
  font-variant-numeric: tabular-nums;
}

/* ---------- SUBJECT ROWS ---------- */
.subject-list {
  gap: 8px;
}

.subject-item {
  display: grid;
  grid-template-columns: 34px 1fr auto;
  gap: 11px;
  padding: 9px 11px;
  border: 1px solid var(--border-soft);
  border-left-width: 3px;
  border-radius: 10px;
  background: var(--surface);
  transition: transform var(--transition-card), box-shadow var(--transition-card);
}

.subject-item:hover {
  transform: translateY(-1px);
  box-shadow: var(--shadow-card);
}

.subject-item > .ic {
  width: 34px;
  height: 34px;
  border-radius: 10px;
  display: grid;
  place-items: center;
  font-size: 17px;
}

.subject-item .mid {
  min-width: 0;
}

.subject-item .top {
  display: flex;
  align-items: baseline;
  gap: 8px;
  margin-bottom: 6px;
}

.subject-item .top b {
  font-size: 12.5px;
  font-weight: 650;
  color: var(--heading);
  white-space: nowrap;
}

.subject-item .top span {
  font-size: 10.5px;
  color: var(--muted);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.subject-item .end {
  display: flex;
  align-items: center;
  gap: 7px;
}

.subject-item .pc {
  font-size: 14px;
  font-weight: 800;
  letter-spacing: -0.02em;
  color: var(--heading);
  font-variant-numeric: tabular-nums;
}

.subject-item .pc small {
  font-size: 10px;
  font-weight: 700;
  color: var(--muted);
}

.subject-item .gr {
  min-width: 30px;
  text-align: center;
  font-size: 10.5px;
  font-weight: 800;
  padding: 3px 5px;
  border-radius: 6px;
}

.subject-item .dl {
  display: inline-flex;
  align-items: center;
  gap: 2px;
  font-size: 10.5px;
  font-weight: 700;
}

.subject-item .dl i {
  font-size: 12px;
}

/* the class-average marker sits on top of the track, so the track cannot clip
   it the way `.progress` does by default; `left` is set inline */
.subject-item .progress {
  position: relative;
  overflow: visible;
}

.subject-item .progress-bar {
  border-radius: inherit;
}

.subject-item .progress .avg {
  position: absolute;
  top: -3px;
  width: 2px;
  height: 14px;
  border-radius: 2px;
  background: var(--heading);
  opacity: 0.55;
}

.subject-legend {
  gap: 6px;
  font-size: 10.5px;
  color: var(--muted);
}

.subject-legend .mk {
  width: 2px;
  height: 12px;
  border-radius: 2px;
  background: var(--heading);
  opacity: 0.55;
}

/* compact variant: name, track, value, tag on a single line */
.subject-item-compact {
  display: grid;
  grid-template-columns: 92px 1fr 38px 50px;
  gap: 10px;
  padding: 0;
  border: 0;
  background: none;
}

.subject-item-compact:hover {
  transform: none;
  box-shadow: none;
}

.subject-item-compact .nm {
  font-size: 12px;
  font-weight: 600;
  color: var(--heading);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.subject-item-compact .pc {
  font-size: 11.5px;
  font-weight: 700;
  text-align: right;
}

.subject-item-compact .gr {
  font-size: 10px;
}

/* ---------- NOTE CALLOUT ---------- */
/* tinted advisory line; the tint comes from a bg-*-transparent utility */
.insight-note {
  gap: 8px;
  padding: 10px 12px;
  border-radius: 10px;
  font-size: 11.5px;
  line-height: 1.5;
}

.insight-note i {
  font-size: 15px;
  flex-shrink: 0;
  margin-top: 1px;
}

.insight-note b {
  color: var(--heading);
}

/* ---------- HIGHLIGHT ROWS ---------- */
.highlight-list {
  gap: 8px;
  margin-top: 14px;
}

.highlight-item {
  gap: 10px;
  padding: 8px 10px;
  border-radius: 10px;
  border: 1px solid var(--border-soft);
  border-left-width: 3px;
  background: var(--surface);
}

.highlight-item .ic {
  width: 30px;
  height: 30px;
  flex-shrink: 0;
  border-radius: 9px;
  display: grid;
  place-items: center;
  font-size: 16px;
}

.highlight-item .tx {
  flex: 1;
  min-width: 0;
}

.highlight-item .tx b {
  display: block;
  font-size: 12px;
  font-weight: 650;
  color: var(--heading);
  line-height: 1.2;
}

.highlight-item .tx span {
  display: block;
  font-size: 10.5px;
  color: var(--muted);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

/* ---------- DETAIL TILES ---------- */
.detail-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 10px;
}

.detail-tile {
  gap: 9px;
  padding: 11px;
  border: 1px solid var(--border-soft);
  border-radius: var(--radius-list);
  background: var(--surface);
  transition: transform var(--transition-card), box-shadow var(--transition-card);
}

.detail-tile:hover {
  transform: translateY(-2px);
  box-shadow: var(--shadow-card);
}

.detail-tile .ic {
  width: 32px;
  height: 32px;
  border-radius: 9px;
  display: grid;
  place-items: center;
  font-size: 16px;
  flex-shrink: 0;
}

.detail-tile b {
  display: block;
  font-size: 13px;
  color: var(--heading);
}

.detail-tile span {
  font-size: 10.5px;
  color: var(--muted);
}

/* ---------- AVATAR STATUS ---------- */
/* .info-list-avatar-wrap — all declarations now Bootstrap utilities in the markup */
.info-list-avatar-wrap .dot {
  position: absolute;
  right: -2px;
  bottom: -2px;
  width: 12px;
  height: 12px;
  border-radius: 50%;
  border: 2px solid var(--surface);
  background: var(--tone-success);
}

.info-list-avatar-wrap .dot.off {
  background: #9aa6c2;
}

@media (max-width: 1399px) {
  .subject-item .top span {
    display: none;
  }
}
@media (max-width: 575px) {
  .subject-item {
    grid-template-columns: 1fr auto;
  }
  .subject-item > .ic {
    display: none;
  }
  .subject-item-compact {
    grid-template-columns: 78px 1fr 34px 30px;
    gap: 7px;
  }
  .detail-grid {
    grid-template-columns: 1fr;
  }
}
/*-----------------
    Stat

    The figure-and-caption pairing that every dashboard repeats: a large value,
    a muted label, and an optional delta showing which way it moved.

        <div class="stat">
            <span class="stat-caption">Enrolment</span>
            <div class="stat-value">1,248</div>
            <span class="stat-label">Active students</span>
            <span class="stat-delta stat-delta-up"><i class="ti ti-arrow-up"></i>3%</span>
        </div>

    The pieces are independent — use `.stat-caption` on its own as a section
    eyebrow, or `.stat-delta` beside any number.
-----------------*/
/*----- uppercase micro-caption, above a value or as a section eyebrow -----*/
.stat-caption {
  display: inline-block;
  font-size: 0.68rem;
  font-weight: 700;
  letter-spacing: 0.09em;
  text-transform: uppercase;
  color: #6A7287;
}

/*----- the figure itself -----*/
.stat-value {
  font-size: 1.85rem;
  font-weight: 800;
  letter-spacing: -0.03em;
  line-height: 1.1;
  color: #202C4B;
}
.stat-value.stat-value-sm {
  font-size: 1.5rem;
}
.stat-value.stat-value-xs {
  font-size: 1.125rem;
}
.stat-value > span,
.stat-value > small {
  font-size: 0.6em;
  font-weight: 500;
  letter-spacing: 0;
  color: #6A7287;
}

/*----- muted caption under or beside the figure -----*/
.stat-label {
  font-size: 0.8rem;
  color: #6A7287;
}
.stat-label.stat-label-sm {
  font-size: 0.74rem;
}

/*----- direction of travel -----*/
.stat-delta {
  display: inline-flex;
  align-items: center;
  gap: 0.125rem;
  font-size: 0.76rem;
  font-weight: 700;
  line-height: 1.3;
}
.stat-delta.stat-delta-sm {
  font-size: 0.72rem;
}
.stat-delta.stat-delta-up {
  color: #1ABE17;
}
.stat-delta.stat-delta-down {
  color: #E82646;
}
.stat-delta.stat-delta-flat {
  color: #838A9B;
}

/*-----------------
    Stat tile

    A bordered box holding one stat, used in KPI strips. It lifts on hover so
    it reads as a target when the whole tile is clickable.
-----------------*/
.stat-tile {
  border: 1px solid #E9EDF4;
  border-radius: 12px;
  padding: 0.7rem 0.8rem;
  height: 100%;
  transition: transform 0.2s ease, border-color 0.2s ease;
}
.stat-tile.stat-tile-hover:hover {
  transform: translateY(-2px);
  border-color: var(--avatar-accent, #3D5EE1);
}
.stat-tile {
  /*----- compact, centred variant for three-up stat grids -----*/
}
.stat-tile.stat-tile-plain {
  text-align: center;
  background: #E9EDF4;
  border: 0;
  border-radius: 5px;
  padding: 0.6rem 0.5rem;
}
.stat-tile {
  /*----- sits on a coloured or photographic panel -----*/
}
.stat-tile.stat-tile-on-media {
  background: rgba(255, 255, 255, 0.15);
  border-color: rgba(255, 255, 255, 0.22);
  backdrop-filter: blur(4px);
  padding: 0.4rem 0.55rem;
  color: #FFF;
}
.stat-tile {
  /*----- accent rule down the leading edge -----*/
}
.stat-tile.stat-tile-accent {
  position: relative;
  overflow: hidden;
}
.stat-tile.stat-tile-accent::before {
  content: "";
  position: absolute;
  inset-inline-start: 0;
  inset-block: 0;
  width: 3px;
  background: var(--avatar-accent, #3D5EE1);
}

/*-----------------
    Stat grid — evenly divided columns of stats inside one card
-----------------*/
.stat-grid {
  display: grid;
  grid-template-columns: repeat(var(--stat-grid-columns, 3), 1fr);
  gap: 0.4rem;
}

/*-----------------
	Dashboard widgets — merged in from the former
	components/_ui-dashboard-widgets.scss. These are generic, reusable
	components; they live with their own kind rather than in a page-shaped file.
-----------------*/
/* ---------- KPI ---------- */
.stats-grid {
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  gap: 12px;
}

.stats-grid.stats-grid-compact {
  grid-template-columns: repeat(auto-fit, minmax(140px, 1fr));
}

.card-stat {
  padding: 14px;
  border: 1px solid var(--border-soft);
  border-radius: var(--radius);
  background: var(--surface);
  box-shadow: var(--shadow-card);
  transition: transform var(--transition-card), box-shadow var(--transition-card);
}

.card-stat:hover {
  transform: translateY(-3px);
  box-shadow: var(--shadow-card-lift);
}

.card-stat-header {
  gap: 8px;
  margin-bottom: 8px;
}

.card-stat-delta {
  font-size: 10.5px;
  font-weight: 700;
  padding: 2px 7px;
  border-radius: 999px;
  gap: 2px;
}

.card-stat-delta.up {
  color: var(--tone-success);
  background: var(--tone-success-soft);
}

.card-stat-delta.down {
  color: var(--tone-danger);
  background: var(--tone-danger-soft);
}

.card-stat-delta.flat {
  color: var(--muted);
  background: var(--surface-soft);
}

.card-stat-value {
  font-size: 24px;
  font-weight: 800;
  color: var(--heading);
  line-height: 1;
}

.card-stat-value small {
  font-size: 12px;
  font-weight: 600;
  color: var(--muted);
}

.card-stat-label {
  font-size: 11px;
  color: var(--muted);
  margin-top: 3px;
}

/* ---------- MY CLASSES ---------- */
.class-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 14px;
}

.award-icon i {
  color: #fff;
}

/* ---------- ACHIEVEMENTS ---------- */
.award-list {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 10px;
}

.award-item {
  padding: 14px 8px;
  border: 1px solid var(--border-soft);
  border-radius: var(--radius-list);
  background: var(--surface);
  transition: transform var(--transition-card);
}

.award-item:hover {
  transform: translateY(-3px);
}

.award-icon {
  width: 52px;
  height: 52px;
  border-radius: 50%;
  margin: 0 auto 8px;
  display: grid;
  place-items: center;
  font-size: 22px;
}
.award-icon i {
  font-size: 22px !important;
}

.award-item b {
  display: block;
  font-size: 12px;
  color: var(--heading);
}

.award-item span {
  font-size: 10px;
  color: var(--muted);
}

@media (max-width: 1199px) {
  .stats-grid {
    grid-template-columns: repeat(3, 1fr);
  }
  .class-grid {
    grid-template-columns: repeat(2, 1fr);
  }
}
@media (max-width: 767px) {
  .stats-grid {
    grid-template-columns: repeat(2, 1fr);
  }
  .class-grid {
    grid-template-columns: 1fr;
  }
  .award-list {
    grid-template-columns: repeat(3, 1fr);
  }
}
@media (max-width: 575px) {
  .stats-grid,
  .card-profile-stats {
    grid-template-columns: 1fr;
  }
}
/* ---------- METRIC TILES ---------- */
