  box-shadow: var(--shadow-card);
}

.metric-tile-value {
  font-size: 22px;
  font-weight: 800;
  letter-spacing: -0.4px;
  color: var(--heading);
  margin: 8px 0 2px;
}

.metric-tile-value small {
  font-size: 11px;
  font-weight: 700;
  color: var(--muted);
}

.metric-tile-label {
  font-size: 11px;
  color: var(--muted);
}

.metric-tile-sm {
  padding: 9px;
}

.metric-tile-sm .metric-tile-value {
