}

.heatstrip span.l3 {
  background: rgba(22, 163, 74, 0.68);
}

.heatstrip span.l4 {
  background: rgba(22, 163, 74, 0.9);
}

.heatstrip span.ab {
  background: rgba(220, 38, 38, 0.55);
}

.heatstrip-legend {
  display: flex;
  align-items: center;
  gap: 5px;
  font-size: 10.5px;
  color: var(--bs-secondary-color);
  margin-top: 8px;
}

.heatstrip-legend i {
  width: 12px;
  height: 12px;
  border-radius: 3px;
  display: inline-block;
  background: var(--bs-secondary-bg);
