@media (max-width: 575.98px) {
  .profile-wrap .frames {
    margin: 0 0 10px 0;
  }
}
.profile-wrap .profile-upload p {
  font-size: 12px;
}

.profile-uploader .btn {
  font-size: 12px;
  margin: 0 0 10px 0;
  padding: 6px 20px;
}

.drag-upload-btn {
  font-size: 12px;
  font-weight: 600;
  background: #FFF;
  border: 1px dashed #E9EDF4;
  border-radius: 5px;
  margin: 0 12px 10px 0;
  padding: 6px 16px;
