}

/*-----------------
    Student profile

    Merged from the former pages/_student-profile.scss — the student module
    keeps one stylesheet, and every reusable block it used (accents, skeleton,
    avatars, badges) now comes from the global component library.
-----------------*/
/* ============================================================
   STUDENT PROFILE page — migrated from app-new.css
   ============================================================ */
/* ===== student-profile.css ===== */
/* ============================================================
   Student 360° Profile — premium enterprise workspace
   Scoped under .student-profile so it never affects sidebar/header/
   layout or the global palette. Inherits Bootstrap --bs-*
   tokens and only adds neutral premium surfaces on top.
   ============================================================ */
/* Match card border / radius / shadow to index2.html (shell-catalyst).
   Scoped to .student-profile so it cannot bleed onto other pages in the merged bundle. */
.student-profile .card {
  border: 1px solid #e8eaed;
  border-radius: 16px;
  box-shadow: 0 1px 2px rgba(15, 23, 42, 0.04), 0 8px 24px rgba(15, 23, 42, 0.06);
}

[data-theme=dark] .student-profile .card,
[data-bs-theme=dark] .student-profile .card {
  border-color: rgba(255, 255, 255, 0.08);
  box-shadow: 0 1px 2px rgba(0, 0, 0, 0.3);
}

.student-profile {
  --avatar-accent: var(--bs-primary);
  --avatar-accent-soft: var(--tint-primary);
}

@media (prefers-reduced-motion: reduce) {
  .student-profile * {
    animation: none !important;
    transition: none !important;
  }
}
/* colour accents */
/* ============================================================
   ACTION BUTTONS (page header)
   ============================================================ */
.profile-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}

.profile-button {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  height: 38px;
  padding: 0 13px;
  border: 1px solid var(--bs-border-color);
  border-radius: var(--radius-sm);
  background: var(--bs-body-bg);
  color: var(--bs-body-color, #1f2937);
  font-size: 13px;
  font-weight: 500;
  line-height: 1;
  cursor: pointer;
  transition: all var(--transition);
  white-space: nowrap;
  text-decoration: none;
}
.profile-button i {
  font-size: 16px;
}
.profile-button:hover {
  background: var(--bs-tertiary-bg);
  border-color: var(--bs-primary);
  color: var(--bs-primary);
  transform: translateY(-1px);
  box-shadow: var(--shadow);
}
.profile-button.profile-icon-button {
  padding: 0;
  width: 38px;
  justify-content: center;
}

.profile-button-primary {
  background: var(--bs-primary);
  border-color: var(--bs-primary);
  color: #fff;
}
.profile-button-primary:hover {
  background: var(--bs-primary);
  border-color: var(--bs-primary);
  color: #fff;
  filter: brightness(1.06);
}

.profile-back {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  width: 38px;
  height: 38px;
  border: 1px solid var(--bs-border-color);
  border-radius: var(--radius-sm);
  background: var(--bs-body-bg);
  color: var(--bs-body-color, #1f2937);
  text-decoration: none;
  transition: all var(--transition);
}
.profile-back i {
  font-size: 18px;
}
.profile-back:hover {
  background: var(--bs-tertiary-bg);
  border-color: var(--bs-primary);
  color: var(--bs-primary);
  transform: translateX(-2px);
  box-shadow: var(--shadow);
}

.student-profile .dropdown-menu {
  min-width: 214px;
  border-radius: 12px;
}

.student-profile .dropdown-head {
  padding: 6px 10px 4px;
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--bs-secondary-color);
}

.student-profile .dropdown-item {
  display: flex;
  align-items: center;
  font-size: 13px;
  padding: 7px 10px;
}
.student-profile .dropdown-item i {
  font-size: 16px;
  color: var(--bs-secondary-color);
}

.student-profile .dropdown-item:hover i,
.student-profile .dropdown-item:focus i {
  color: var(--bs-primary);
}

/* ============================================================
   HERO
   ============================================================ */
.profile-hero {
  position: relative;
  overflow: hidden;
  padding: 24px;
  /* soft brand-tinted background */
  background: radial-gradient(130% 120% at 100% 0%, var(--tint-primary), transparent 55%), linear-gradient(135deg, var(--tint-primary) 0%, rgba(255, 255, 255, 0.4) 45%, var(--bs-secondary-bg) 100%);
}

/* white pattern overlay (dots + diagonal weave) */
.profile-hero::before {
  content: "";
  position: absolute;
  inset: 0;
  background-image: radial-gradient(rgba(255, 255, 255, 0.9) 1.6px, transparent 1.7px), repeating-linear-gradient(45deg, rgba(255, 255, 255, 0.5) 0 1px, transparent 1px 16px), repeating-linear-gradient(-45deg, rgba(255, 255, 255, 0.35) 0 1px, transparent 1px 16px);
  background-size: 20px 20px, auto, auto;
  background-position: 0 0;
  opacity: 0.7;
  pointer-events: none;
  -webkit-mask-image: linear-gradient(115deg, #000 0%, rgba(0, 0, 0, 0.35) 55%, transparent 90%);
  mask-image: linear-gradient(115deg, #000 0%, rgba(0, 0, 0, 0.35) 55%, transparent 90%);
}

/* soft white glow blobs for depth */
.profile-hero::after {
  content: "";
  position: absolute;
  top: -60px;
  right: -40px;
  width: 220px;
  height: 220px;
  border-radius: 50%;
  background: radial-gradient(circle, rgba(255, 255, 255, 0.75), transparent 70%);
  pointer-events: none;
}

[data-bs-theme=dark] .profile-hero {
  background: radial-gradient(130% 120% at 100% 0%, rgba(61, 94, 225, 0.22), transparent 55%), linear-gradient(135deg, rgba(61, 94, 225, 0.16) 0%, var(--bs-body-bg) 55%);
}
[data-bs-theme=dark] .profile-hero::before {
  background-image: radial-gradient(rgba(255, 255, 255, 0.14) 1.4px, transparent 1.5px), repeating-linear-gradient(45deg, rgba(255, 255, 255, 0.08) 0 1px, transparent 1px 16px), repeating-linear-gradient(-45deg, rgba(255, 255, 255, 0.06) 0 1px, transparent 1px 16px);
  background-size: 20px 20px, auto, auto;
  opacity: 1;
}
[data-bs-theme=dark] .profile-hero::after {
  background: radial-gradient(circle, rgba(255, 255, 255, 0.06), transparent 70%);
}

.hero-grid {
  position: relative;
  z-index: 1;
  display: grid;
  grid-template-columns: auto 1fr auto;
  gap: 22px;
  align-items: center;
}
@media (max-width: 1199.98px) {
  .hero-grid {
    grid-template-columns: 1fr;
    gap: 40px;
  }
}

.hero-photo {
  position: relative;
  width: 118px;
  height: 118px;
  border-radius: 20px;
  padding: 4px;
  background: var(--bs-body-bg);
  box-shadow: var(--shadow-lift);
}
.hero-photo img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  border-radius: 16px;
}
.hero-photo .presence {
  position: absolute;
  right: 4px;
  bottom: 4px;
  width: 18px;
  height: 18px;
  border-radius: 50%;
  border: 3px solid var(--bs-body-bg);
  background: #16a34a;
}

.hero-id {
  display: flex;
  flex-direction: column;
  gap: 4px;
  min-width: 0;
}

.hero-name {
  font-size: 24px;
  font-weight: 700;
  color: var(--bs-emphasis-color);
  line-height: 1.1;
  margin: 0;
  display: flex;
  align-items: center;
  gap: 10px;
  flex-wrap: wrap;
}
@media (max-width: 575.98px) {
  .hero-name {
    justify-content: center;
  }
}

.hero-meta {
  display: flex;
  flex-wrap: wrap;
  gap: 8px 16px;
  margin-top: 6px;
}
.hero-meta > span {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  font-size: 12.5px;
  color: var(--bs-secondary-color);
}
.hero-meta i {
  font-size: 15px;
  opacity: 0.8;
}
.hero-meta b {
  color: var(--bs-emphasis-color);
  font-weight: 600;
}

.badges {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  margin-top: 10px;
}

.profile-badge {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  font-size: 11.5px;
  font-weight: 600;
  padding: 4px 10px;
  border-radius: 999px;
  background: var(--accent-soft);
  color: var(--accent);
}
.profile-badge i {
  font-size: 13px;
}
.profile-badge .profile-dot {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: currentColor;
}

.hero-right {
  display: flex;
  align-items: center;
  gap: 22px;
}

/* score rings */
.ring-group {
  display: flex;
  gap: 16px;
}

.profile-ring {
  text-align: center;
}

.ring-track {
  width: 74px;
  height: 74px;
  border-radius: 50%;
  background: conic-gradient(var(--accent) calc(var(--val, 0) * 1%), var(--bs-secondary-bg) 0);
  display: flex;
  align-items: center;
  justify-content: center;
  transition: background 1s ease;
}

.profile-ring-hole {
  width: 56px;
  height: 56px;
  border-radius: 50%;
  background: var(--bs-body-bg);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 16px;
  font-weight: 700;
  color: var(--bs-emphasis-color);
  box-shadow: inset 0 0 0 1px var(--bs-border-color);
}

.ring-lbl {
  font-size: 11px;
  color: var(--bs-secondary-color);
  margin-top: 6px;
  display: block;
}

/* QR + quick contact */
.hero-side {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 10px;
}

.qr-code {
  width: 76px;
  height: 76px;
  border-radius: 12px;
  border: 1px solid var(--bs-border-color);
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--bs-body-bg);
}
.qr-code i {
  font-size: 60px;
  color: var(--bs-emphasis-color);
}

.contact-list {
  display: flex;
  gap: 6px;
}

.profile-contact {
  width: 36px;
  height: 36px;
  border-radius: 50%;
  border: 1px solid var(--bs-border-color);
  background: var(--bs-body-bg);
  color: var(--bs-secondary-color);
  display: inline-flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  transition: all var(--transition);
  text-decoration: none;
}
.profile-contact i {
  font-size: 16px;
}
.profile-contact:hover {
  background: var(--bs-primary);
  border-color: var(--bs-primary);
  color: #fff;
  transform: translateY(-2px);
  box-shadow: var(--shadow-lift);
}
.profile-contact.c-green:hover {
  background: #16a34a;
  border-color: #16a34a;
}
.profile-contact.c-amber:hover {
  background: #d97706;
  border-color: #d97706;
}
.profile-contact.c-whatsapp {
  color: #25d366;
}
.profile-contact.c-whatsapp:hover {
  background: #25d366;
  border-color: #25d366;
  color: #fff;
}

/* profile completion bar in hero */
.complete {
  margin-top: 14px;
}

.complete-top {
  display: flex;
  justify-content: space-between;
  font-size: 12px;
  margin-bottom: 5px;
}
.complete-top b {
  color: var(--bs-emphasis-color);
}

.profile-bar {
  height: 8px;
  border-radius: 999px;
  background: var(--bs-secondary-bg);
  overflow: hidden;
}
.profile-bar > span {
  display: block;
  height: 100%;
  border-radius: 999px;
  background: var(--accent);
  width: 0;
  transition: width 1.1s cubic-bezier(0.4, 0, 0.2, 1);
}

/* ============================================================
   EXECUTIVE OVERVIEW GRID
   ============================================================ */
.profile-overview-grid {
  display: grid;
  grid-template-columns: repeat(5, minmax(0, 1fr));
  gap: 12px;
}
@media (max-width: 575.98px) {
  .profile-overview-grid {
    grid-template-columns: repeat(1, 1fr) !important;
  }
}

.profile-overview {
  position: relative;
  display: grid;
  grid-template-columns: auto 1fr;
  align-items: center;
  column-gap: 12px;
  padding: 12px 14px;
  border: 1px solid var(--bs-border-color);
  border-radius: 14px;
  background: var(--bs-body-bg);
  transition: transform var(--transition), box-shadow var(--transition), border-color var(--transition);
  overflow: hidden;
}

/* corner accent glow */
.profile-overview::before {
  content: "";
  position: absolute;
  top: -34px;
  right: -34px;
  width: 96px;
  height: 96px;
  border-radius: 50%;
  background: var(--accent-soft);
  opacity: 0.55;
  transition: transform var(--transition), opacity var(--transition);
}

/* animated bottom accent bar */
.profile-overview::after {
  content: "";
  position: absolute;
  left: 0;
  right: 0;
  bottom: 0;
  height: 3px;
  background: linear-gradient(90deg, var(--accent), transparent);
  transform: scaleX(0);
  transform-origin: left;
  transition: transform 0.4s var(--transition);
}

.profile-overview:hover {
  transform: translateY(-4px);
  box-shadow: var(--shadow-lift);
  border-color: transparent;
}
.profile-overview:hover::before {
  transform: scale(1.3);
  opacity: 0.75;
}
.profile-overview:hover::after {
  transform: scaleX(1);
}
.profile-overview:hover > .avatar {
  transform: translateY(-2px) rotate(-5deg);
}

.overview-head {
  display: contents;
}

.profile-overview > .avatar {
  grid-column: 1;
  grid-row: 1/span 3;
  align-self: center;
  box-shadow: 0 8px 16px -8px var(--accent-soft), inset 0 1px 0 rgba(255, 255, 255, 0.35);
  transition: transform var(--transition);
}

.overview-lbl {
  grid-column: 2;
  grid-row: 1;
  position: relative;
  z-index: 1;
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.03em;
  text-transform: uppercase;
  color: var(--bs-secondary-color);
}

.overview-val {
  grid-column: 2;
  grid-row: 2;
  position: relative;
  z-index: 1;
  font-size: 20px;
  font-weight: 800;
  color: var(--bs-emphasis-color);
  line-height: 1.1;
  letter-spacing: -0.01em;
}

.overview-sub {
  grid-column: 2;
  grid-row: 3;
  position: relative;
  z-index: 1;
  font-size: 10px;
  font-weight: 600;
  margin-top: 4px;
  display: inline-flex;
  align-items: center;
  gap: 3px;
  width: fit-content;
  padding: 2px 7px;
  border-radius: 999px;
  color: var(--bs-secondary-color);
  background: var(--bs-secondary-bg);
}
.overview-sub i {
  font-size: 12px;
}

.document-upload {
  color: #15803d;
  background: rgba(22, 163, 74, 0.12);
}

.profile-down {
  color: #b91c1c;
  background: rgba(220, 38, 38, 0.12);
}

/* ============================================================
   INFO CARDS / DL rows
   ============================================================ */
.profile-card-title {
  display: flex;
  align-items: center;
  gap: 10px;
  font-size: 15px;
  font-weight: 700;
  color: var(--bs-emphasis-color);
  margin: 0;
}
.profile-card-title .tab-icon {
  width: 34px;
  height: 34px;
  border-radius: 10px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  font-size: 17px;
  color: #fff;
  background: linear-gradient(135deg, rgba(255, 255, 255, 0.28), rgba(255, 255, 255, 0)), var(--accent);
  box-shadow: 0 8px 16px -6px var(--accent-soft), inset 0 1px 0 rgba(255, 255, 255, 0.3);
}

/* Two-column info tiles (Personal Information) */
.definition-list {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 8px;
}
.definition-list > div {
  display: flex;
  flex-direction: column;
  gap: 3px;
  padding: 10px 12px;
  border: 1px solid var(--bs-border-color);
  border-radius: 11px;
  background: var(--bs-secondary-bg);
  transition: transform var(--transition), box-shadow var(--transition), border-color var(--transition), background var(--transition);
}
.definition-list > div:hover {
  transform: translateY(-2px);
  border-color: var(--bs-primary);
  background: var(--bs-body-bg);
  box-shadow: var(--shadow);
}
.definition-list .meta-key {
  font-size: 10.5px;
  color: var(--bs-secondary-color);
  text-transform: uppercase;
  letter-spacing: 0.04em;
  font-weight: 600;
}
.definition-list .value {
  font-size: 13.5px;
  font-weight: 600;
  color: var(--bs-emphasis-color);
  word-break: break-word;
}

/* Single-column key/value rows (Transport,
Hostel,
Medical) */
.definition-list.one-col {
  grid-template-columns: 1fr;
  gap: 0;
}
.definition-list.one-col > div {
  flex-direction: row;
  justify-content: space-between;
  align-items: center;
  gap: 12px;
  padding: 11px 0;
  border: 0;
  border-radius: 0;
  background: transparent;
  transform: none;
  box-shadow: none;
  transition: none;
}
.definition-list.one-col > div:not(:last-child) {
  border-bottom: 1px solid var(--bs-border-color);
}
.definition-list.one-col > div:first-child {
  padding-top: 0;
}
.definition-list.one-col > div:last-child {
  padding-bottom: 0;
}
.definition-list.one-col .meta-key {
  font-size: 12px;
  text-transform: none;
  letter-spacing: 0;
  font-weight: 500;
}
.definition-list.one-col .value {
  text-align: right;
}

.profile-chip-set {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
}

.profile-chip {
  font-size: 12px;
  font-weight: 500;
  padding: 5px 11px;
  border-radius: 999px;
  background: var(--bs-secondary-bg);
  color: var(--bs-emphasis-color);
  border: 1px solid var(--bs-border-color);
  transition: all var(--transition);
}
.profile-chip:hover {
  border-color: var(--bs-primary);
  color: var(--bs-primary);
}
.profile-chip.solid {
  background: var(--tint-primary);
  color: var(--bs-primary);
  border-color: transparent;
}

/* person row (parent/guardian) */
.profile-person {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 14px 0;
  border-bottom: 1px solid var(--bs-border-color);
}
@media (max-width: 575.98px) {
  .profile-person {
    flex-direction: column;
    align-items: flex-start;
    gap: 12px;
  }
}
.profile-person:first-child {
  padding-top: 0;
}
.profile-person:last-child {
  border-bottom: 0;
  padding-bottom: 0;
}
.profile-person img {
  width: 46px;
  height: 46px;
  border-radius: 12px;
  object-fit: cover;
  box-shadow: 0 0 0 3px var(--bs-secondary-bg);
}
.profile-person > .profile-contact {
  background: linear-gradient(135deg, var(--bs-primary), rgba(61, 94, 225, 0.55));
  color: #fff;
  border-color: transparent;
  box-shadow: 0 6px 14px -6px var(--tint-primary);
}
.profile-person .profile-person-name {
  font-weight: 600;
  font-size: 14px;
  color: var(--bs-emphasis-color);
}
.profile-person .person-role {
  font-size: 12px;
  color: var(--bs-secondary-color);
  line-height: 1.55;
}
.profile-person .person-actions {
  margin-left: auto;
  display: flex;
  gap: 6px;
}
@media (max-width: 575.98px) {
  .profile-person .person-actions {
    margin-left: unset;
  }
}

/* ============================================================
   TABS
   ============================================================ */
.tab-list {
  display: flex;
  flex-wrap: wrap;
  gap: 4px;
  padding: 5px;
  margin: 0;
  border: 1px solid var(--bs-border-color);
  border-radius: var(--radius);
  background: var(--bs-secondary-bg);
}

.profile-tab {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  white-space: nowrap;
  flex: 0 0 auto;
  padding: 8px 14px;
  border-radius: 999px;
  border: 0;
  background: transparent;
  color: var(--bs-secondary-color);
  font-size: 13px;
  font-weight: 600;
  cursor: pointer;
  transition: all var(--transition);
}
.profile-tab i {
  font-size: 16px;
}
.profile-tab:hover {
  color: var(--bs-primary);
}
.profile-tab.active {
  background: var(--bs-body-bg);
  color: var(--bs-primary);
  box-shadow: var(--shadow);
}

.tab-pane-block {
  display: none;
  animation: sp-fade 0.35s ease;
}
.tab-pane-block.active {
  display: block;
}

/* mini section heading inside panes */
.block-heading {
  font-size: 13px;
  font-weight: 700;
  color: var(--bs-emphasis-color);
  margin: 0 0 12px;
  display: flex;
  align-items: center;
  gap: 6px;
}
.block-heading i {
  color: var(--bs-primary);
  font-size: 16px;
}

.profile-tile {
  border: 1px solid var(--bs-border-color);
  border-radius: var(--radius-sm);
  padding: 14px;
  background: var(--bs-body-bg);
  transition: all var(--transition);
}
.profile-tile:hover {
  box-shadow: var(--shadow);
}

/* stat mini */
.profile-mini {
  text-align: center;
  padding: 12px;
  border: 1px solid var(--bs-border-color);
  border-radius: var(--radius-sm);
}
.profile-mini .v {
  font-size: 20px;
  font-weight: 700;
  color: var(--bs-emphasis-color);
}
.profile-mini .l {
  font-size: 11.5px;
  color: var(--bs-secondary-color);
  margin-top: 2px;
}

/* ============================================================
   CHARTS (pure CSS/SVG)
   ============================================================ */
/* vertical bars */
.bar-group {
  display: flex;
  align-items: flex-end;
  gap: 8px;
  height: 150px;
  padding-top: 6px;
}
.bar-group .b {
  flex: 1;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 6px;
  height: 100%;
  justify-content: flex-end;
}
.bar-group .b .col {
  width: 70%;
  max-width: 26px;
  border-radius: 6px 6px 0 0;
  background: linear-gradient(180deg, var(--bs-primary), var(--tint-primary));
  height: 0;
  transition: height 1s cubic-bezier(0.4, 0, 0.2, 1);
}
.bar-group .b.alt .col {
  background: linear-gradient(180deg, #16a34a, rgba(22, 163, 74, 0.15));
}
.bar-group .b .cap {
  font-size: 10.5px;
  color: var(--bs-secondary-color);
}
.bar-group .b .val {
  font-size: 10.5px;
  font-weight: 700;
  color: var(--bs-emphasis-color);
}

/* horizontal subject bars */
.histogram-bar {
  margin-bottom: 12px;
}

.histogram-bar-top {
  display: flex;
  justify-content: space-between;
  font-size: 12.5px;
  margin-bottom: 5px;
}
.histogram-bar-top b {
  color: var(--bs-emphasis-color);
}

.histogram-bar-track {
  height: 8px;
  border-radius: 999px;
  background: var(--bs-secondary-bg);
  overflow: hidden;
}

.histogram-bar-fill {
  height: 100%;
  border-radius: 999px;
  width: 0;
  transition: width 1s cubic-bezier(0.4, 0, 0.2, 1);
  background: var(--accent);
}

/* heatmap */
.heatmap-block {
  display: grid;
  grid-template-columns: repeat(7, 1fr);
  gap: 5px;
}
.heatmap-block .d {
  aspect-ratio: 1;
  border-radius: 5px;
  background: var(--bs-secondary-bg);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 10px;
  color: transparent;
}
.heatmap-block .d.l1 {
  background: rgba(22, 163, 74, 0.25);
}
.heatmap-block .d.l2 {
  background: rgba(22, 163, 74, 0.5);
}
.heatmap-block .d.l3 {
  background: rgba(22, 163, 74, 0.75);
}
.heatmap-block .d.l4 {
  background: #16a34a;
}
.heatmap-block .d.absent {
  background: rgba(220, 38, 38, 0.7);
}
.heatmap-block .d.late {
  background: rgba(217, 119, 6, 0.75);
}

.heatmap-block-legend {
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: 11px;
  color: var(--bs-secondary-color);
  margin-top: 10px;
}
.heatmap-block-legend .k {
  width: 12px;
  height: 12px;
  border-radius: 3px;
}

/* donut (svg) */
.profile-donut {
  display: flex;
  align-items: center;
  gap: 16px;
}
.profile-donut svg {
  width: 130px;
  height: 130px;
  transform: rotate(-90deg);
}
.profile-donut circle {
  fill: none;
  stroke-width: 14;
}
.profile-donut .track {
  stroke: var(--bs-secondary-bg);
}

.donut-legend {
  display: flex;
  flex-direction: column;
  gap: 8px;
  font-size: 12.5px;
}
.donut-legend > div {
  display: flex;
  align-items: center;
  gap: 8px;
}
.donut-legend .k {
  width: 12px;
  height: 12px;
  border-radius: 3px;
}
.donut-legend b {
  margin-left: auto;
  color: var(--bs-emphasis-color);
}

/* trend line (svg) */
.profile-trend svg {
  width: 100%;
  height: 120px;
}

.profile-trend .line {
  fill: none;
  stroke: var(--bs-primary);
  stroke-width: 2.5;
  stroke-linecap: round;
  stroke-linejoin: round;
  stroke-dasharray: 600;
  stroke-dashoffset: 600;
  animation: sp-draw 1.4s ease forwards;
}

.profile-trend .area {
  fill: var(--tint-primary);
  opacity: 0.7;
}

.profile-trend .dot {
  fill: var(--bs-primary);
}

/* ranking badge */
.profile-rank {
  display: flex;
  align-items: center;
  gap: 14px;
}

.rank-num {
  font-size: 34px;
  font-weight: 800;
  color: var(--bs-primary);
  line-height: 1;
}
.rank-num small {
  font-size: 15px;
}

/* ============================================================
   TIMELINE
   ============================================================ */
.profile-timeline {
  position: relative;
  padding-left: 30px;
}
.profile-timeline::before {
  content: "";
  position: absolute;
  left: 11px;
  top: 4px;
  bottom: 4px;
  width: 2px;
  background: var(--bs-border-color);
}

.profile-timeline {
  position: relative;
  padding-bottom: 20px;
}
.profile-timeline:last-child {
  padding-bottom: 0;
}
.profile-timeline > .avatar {
  position: absolute;
  left: -30px;
  top: 0;
  box-shadow: 0 0 0 4px var(--bs-body-bg);
}

.profile-timeline-time {
  font-size: 11px;
  color: var(--bs-secondary-color);
}

.timeline-title {
  font-weight: 600;
  color: var(--bs-emphasis-color);
  font-size: 13.5px;
  margin: 2px 0;
}

.timeline-desc {
  font-size: 12.5px;
  color: var(--bs-secondary-color);
}

/* ============================================================
   DOCUMENTS / LISTS
   ============================================================ */
.profile-document-row {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 12px;
  border: 1px solid var(--bs-border-color);
  border-radius: var(--radius-sm);
  transition: all var(--transition);
  background: var(--bs-body-bg);
}
.profile-document-row:hover {
  border-color: var(--bs-primary);
  box-shadow: var(--shadow);
  transform: translateY(-1px);
}
.profile-document-row .document-row-ic {
  width: 40px;
  height: 40px;
  border-radius: 10px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 20px;
  background: var(--accent-soft);
  color: var(--accent);
}
.profile-document-row .document-row-name {
  font-weight: 600;
  color: var(--bs-emphasis-color);
  font-size: 13px;
}
.profile-document-row .document-row-meta {
  font-size: 11.5px;
  color: var(--bs-secondary-color);
}

/* achievement */
.achievement {
  text-align: center;
  padding: 16px 12px;
  border: 1px solid var(--bs-border-color);
  border-radius: var(--radius-sm);
  transition: all var(--transition);
}
.achievement:hover {
  transform: translateY(-3px);
  box-shadow: var(--shadow-lift);
}

.achievement-medal {
  width: 52px;
  height: 52px;
  margin: 0 auto 8px;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 26px;
  background: var(--accent-soft);
  color: var(--accent);
}

.achievement-title {
  font-weight: 600;
  font-size: 12.5px;
  color: var(--bs-emphasis-color);
}

.achievement-sub {
  font-size: 11px;
  color: var(--bs-secondary-color);
}

/* quick actions grid */
.profile-quick-action-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 8px;
}

.profile-quick-action {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 7px;
  padding: 14px 6px;
  border: 1px solid var(--bs-border-color);
  border-radius: var(--radius-sm);
  cursor: pointer;
  background: var(--bs-body-bg);
  color: var(--bs-secondary-color);
  font-size: 11px;
  font-weight: 600;
  text-align: center;
  transition: all var(--transition);
  text-decoration: none;
}
.profile-quick-action i {
  font-size: 20px;
  color: var(--accent);
  transition: transform var(--transition);
}
.profile-quick-action:hover {
  border-color: var(--bs-primary);
  background: var(--bs-tertiary-bg);
  color: var(--bs-emphasis-color);
  transform: translateY(-2px);
  box-shadow: var(--shadow);
}
.profile-quick-action:hover i {
  transform: scale(1.15);
}

/* AI insights widget */
.profile-insight {
  position: relative;
  border-radius: 16px;
  overflow: hidden;
  background: linear-gradient(135deg, rgba(123, 97, 255, 0.16), rgba(61, 94, 225, 0.08) 60%, transparent);
  border: 1px solid rgba(123, 97, 255, 0.22);
  padding: 18px;
}
.profile-insight::before {
  content: "";
  position: absolute;
  top: -50px;
  right: -50px;
  width: 150px;
  height: 150px;
  border-radius: 50%;
  background: radial-gradient(circle, rgba(123, 97, 255, 0.28), transparent 70%);
  pointer-events: none;
}

.insight-head {
  position: relative;
  z-index: 1;
  display: flex;
  align-items: center;
  gap: 10px;
  margin-bottom: 14px;
  padding-bottom: 14px;
  border-bottom: 1px solid rgba(123, 97, 255, 0.18);
}

.profile-insight-badge {
  width: 38px;
  height: 38px;
  border-radius: 11px;
  display: flex;
  align-items: center;
  justify-content: center;
  background: linear-gradient(135deg, #7b61ff, #3d5ee1);
  color: #fff;
  font-size: 19px;
  box-shadow: 0 8px 18px -5px rgba(123, 97, 255, 0.6);
  position: relative;
}
.profile-insight-badge::after {
  content: "";
  position: absolute;
  inset: 0;
  border-radius: 11px;
  background: linear-gradient(135deg, rgba(255, 255, 255, 0.35), transparent 55%);
}

.insight-head h5 {
  margin: 0;
  font-size: 14.5px;
  font-weight: 700;
  color: var(--bs-emphasis-color);
}

.insight-head span {
  font-size: 11px;
  color: var(--bs-secondary-color);
}

.profile-insight-item {
  position: relative;
  z-index: 1;
  background: rgba(255, 255, 255, 0.7);
  border: 1px solid rgba(123, 97, 255, 0.12);
  border-radius: 12px;
  padding: 12px 14px;
  margin-bottom: 8px;
  transition: transform var(--transition), box-shadow var(--transition);
}
.profile-insight-item:hover {
  transform: translateY(-2px);
  box-shadow: 0 8px 20px -8px rgba(123, 97, 255, 0.35);
}
.profile-insight-item:last-child {
  margin-bottom: 0;
}
.profile-insight-item .t {
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: 12px;
  font-weight: 700;
  color: var(--bs-emphasis-color);
}
.profile-insight-item .t i {
  font-size: 15px;
}
.profile-insight-item p {
  margin: 4px 0 0;
  font-size: 12px;
  color: #4b5563;
  line-height: 1.5;
}

.insight-risk {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  font-size: 11px;
  font-weight: 700;
  padding: 2px 8px;
  border-radius: 999px;
}
.insight-risk.low {
  background: rgba(22, 163, 74, 0.15);
  color: #15803d;
}
.insight-risk.med {
  background: rgba(217, 119, 6, 0.15);
  color: #b45309;
}
.insight-risk.high {
  background: rgba(220, 38, 38, 0.15);
  color: #b91c1c;
}

[data-bs-theme=dark] .profile-insight-item {
  background: rgba(255, 255, 255, 0.06);
}
[data-bs-theme=dark] .profile-insight-item p {
  color: #cbd2e0;
}

/* tables inside panes */
.student-profile .table {
  font-size: 13px;
}
.student-profile .table > :not(caption) > * > * {
  padding: 10px 12px;
}

/* status pill reuse */
.profile-pill {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  font-size: 11.5px;
  font-weight: 600;
  font-style: normal;
  padding: 4px 10px;
  border-radius: 999px;
  line-height: 1;
  white-space: nowrap;
}
@media (max-width: 575.98px) {
  .profile-pill {
    margin-left: unset !important;
  }
}
.profile-pill i {
  font-size: 13px;
}
.profile-pill.ok {
  background: rgba(22, 163, 74, 0.12);
  color: #15803d;
}
.profile-pill.warn {
  background: rgba(217, 119, 6, 0.12);
  color: #b45309;
}
.profile-pill.bad {
  background: rgba(220, 38, 38, 0.12);
  color: #b91c1c;
}
.profile-pill.info {
  background: rgba(8, 145, 178, 0.12);
  color: #0e7490;
}
.profile-pill .profile-dot {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: currentColor;
}

/* ============================================================
   COMMUNICATION TAB
   ============================================================ */
.msgs {
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.profile-message {
  display: flex;
  align-items: flex-start;
  gap: 12px;
  padding: 14px;
  border: 1px solid var(--bs-border-color);
  border-radius: 14px;
  background: var(--bs-body-bg);
  transition: transform var(--transition), box-shadow var(--transition), border-color var(--transition);
}
.profile-message:hover {
  transform: translateY(-2px);
  box-shadow: var(--shadow);
  border-color: var(--bs-primary);
}

.message-main {
  flex: 1;
  min-width: 0;
}

.message-top {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 10px;
}

.message-title {
  font-size: 13.5px;
  font-weight: 600;
  color: var(--bs-emphasis-color);
}

.message-date {
  font-size: 11px;
  color: var(--bs-secondary-color);
  flex-shrink: 0;
}

.message-sub {
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: 11.5px;
  color: var(--bs-secondary-color);
  margin: 3px 0 6px;
}

.message-chan {
  font-size: 10px;
  font-weight: 700;
  padding: 1px 7px;
  border-radius: 5px;
}
.message-chan.email {
  background: rgba(37, 99, 235, 0.12);
  color: #2563eb;
}
.message-chan.message {
  background: rgba(22, 163, 74, 0.12);
  color: #16a34a;
}
.message-chan.sms {
  background: rgba(217, 119, 6, 0.12);
  color: #d97706;
}
.message-chan.call {
  background: rgba(13, 148, 136, 0.12);
  color: #0d9488;
}

.message-snippet {
  font-size: 12.5px;
  color: var(--bs-secondary-color);
  line-height: 1.5;
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
}

.profile-message > .profile-pill {
  align-self: flex-start;
  flex-shrink: 0;
}
.profile-message > .profile-pill i {
  font-size: 13px;
}

.announcement {
  position: relative;
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 14px;
  border: 1px solid var(--bs-border-color);
  border-radius: 14px;
  background: var(--bs-body-bg);
  transition: transform var(--transition), box-shadow var(--transition);
}
.announcement:hover {
  transform: translateY(-2px);
  box-shadow: var(--shadow);
}
.announcement.pinned {
  border-color: transparent;
  background: linear-gradient(135deg, var(--tint-primary), transparent 75%);
  box-shadow: inset 0 0 0 1px var(--tint-primary);
}

.announcement-body {
  flex: 1;
  min-width: 0;
}
.announcement-body b {
  font-size: 13px;
  color: var(--bs-emphasis-color);
}

.announcement-pin {
  color: var(--bs-primary);
  font-size: 17px;
  flex-shrink: 0;
}

/* ============================================================
   ACHIEVEMENTS TAB
   ============================================================ */
.profile-award {
  position: relative;
  height: 100%;
  text-align: center;
  padding: 20px 12px;
  border: 1px solid var(--bs-border-color);
  border-radius: 16px;
  background: var(--bs-body-bg);
  overflow: hidden;
  transition: transform var(--transition), box-shadow var(--transition);
}
.profile-award::before {
  content: "";
  position: absolute;
  top: -40px;
  left: 50%;
  transform: translateX(-50%);
  width: 120px;
  height: 80px;
  background: radial-gradient(circle, var(--rib-soft, var(--tint-primary)), transparent 70%);
}
.profile-award:hover {
  transform: translateY(-4px);
  box-shadow: var(--shadow-lift);
}

.award-medal {
  position: relative;
  z-index: 1;
  width: 62px;
  height: 62px;
  border-radius: 50%;
  margin: 0 auto 12px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 30px;
  color: #fff;
}
.award-medal::after {
  content: "";
  position: absolute;
  inset: 0;
  border-radius: 50%;
  background: linear-gradient(135deg, rgba(255, 255, 255, 0.55), transparent 55%);
}

.award-ribbon {
  position: absolute;
  top: 12px;
  right: 12px;
  z-index: 2;
  font-size: 10px;
  font-weight: 800;
  padding: 2px 8px;
  border-radius: 6px;
  color: #fff;
  background: var(--rib, var(--bs-primary));
}

.award-title {
  position: relative;
  z-index: 1;
  font-weight: 600;
  font-size: 13px;
  color: var(--bs-emphasis-color);
  line-height: 1.3;
}

.award-cat {
  position: relative;
  z-index: 1;
  font-size: 11px;
  color: var(--bs-secondary-color);
  margin-top: 3px;
  display: inline-flex;
  align-items: center;
  gap: 4px;
}
.award-cat i {
  font-size: 13px;
}

.profile-award.gold {
  --rib: #d97706;
  --rib-soft: rgba(245, 158, 11, .22);
}
.profile-award.gold .award-medal {
  background: linear-gradient(135deg, #fcd34d, #f59e0b);
  box-shadow: 0 10px 20px -6px rgba(245, 158, 11, 0.55);
}

.profile-award.silver {
  --rib: #6b7280;
  --rib-soft: rgba(148, 163, 184, .22);
}
.profile-award.silver .award-medal {
  background: linear-gradient(135deg, #e5e7eb, #9ca3af);
  box-shadow: 0 10px 20px -6px rgba(148, 163, 184, 0.5);
}

.profile-award.bronze {
  --rib: #b45309;
  --rib-soft: rgba(180, 83, 9, .2);
}
.profile-award.bronze .award-medal {
  background: linear-gradient(135deg, #e0a872, #b45309);
  box-shadow: 0 10px 20px -6px rgba(180, 83, 9, 0.5);
}

.profile-award.blue {
  --rib: #2563eb;
  --rib-soft: rgba(37, 99, 235, .2);
}
.profile-award.blue .award-medal {
  background: linear-gradient(135deg, #60a5fa, #2563eb);
  box-shadow: 0 10px 20px -6px rgba(37, 99, 235, 0.5);
}

/* earned badges */
.badge-alt-group {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 10px;
}

.badge-alt {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: flex-start;
  gap: 8px;
  text-align: center;
  padding: 14px 8px;
  border: 1px solid var(--bs-border-color);
  border-radius: 14px;
  background: var(--bs-body-bg);
  transition: transform var(--transition), box-shadow var(--transition), border-color var(--transition);
}
.badge-alt:hover {
  transform: translateY(-3px);
  box-shadow: var(--shadow);
  border-color: transparent;
}
.badge-alt span {
  display: flex;
  align-items: center;
  justify-content: center;
  min-height: 28px;
  font-size: 10.5px;
  font-weight: 600;
  color: var(--bs-emphasis-color);
  line-height: 1.25;
}

@media (max-width: 400px) {
  .badge-alt-group {
    grid-template-columns: repeat(2, 1fr);
  }
}
/* ============================================================
   DOCUMENTS TAB
   ============================================================ */
.profile-document {
  position: relative;
  height: 100%;
  padding: 16px;
  border: 1px solid var(--bs-border-color);
  border-radius: 14px;
  background: var(--bs-body-bg);
  overflow: hidden;
  transition: transform var(--transition), box-shadow var(--transition), border-color var(--transition);
}
.profile-document::before {
  content: "";
  position: absolute;
  left: 0;
  top: 0;
  right: 0;
  height: 3px;
  background: var(--accent);
  transform: scaleX(0);
  transform-origin: left;
  transition: transform 0.4s var(--transition);
}
.profile-document:hover {
  transform: translateY(-3px);
  box-shadow: var(--shadow-lift);
  border-color: transparent;
}
.profile-document:hover::before {
  transform: scaleX(1);
}

.document-top {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  margin-bottom: 12px;
}

.document-ext {
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.06em;
  padding: 3px 8px;
  border-radius: 6px;
  background: var(--accent-soft);
  color: var(--accent);
}

.document-name {
  font-weight: 600;
  font-size: 13.5px;
  color: var(--bs-emphasis-color);
}

.document-meta {
  font-size: 11px;
  color: var(--bs-secondary-color);
  margin-top: 4px;
  display: flex;
  align-items: center;
  gap: 4px;
  flex-wrap: wrap;
}
.document-meta i {
  font-size: 13px;
}

.document-foot {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  margin-top: 14px;
  padding-top: 12px;
  border-top: 1px solid var(--bs-border-color);
}
.document-foot .profile-pill i {
  font-size: 13px;
}

.document-actions {
  display: flex;
  gap: 6px;
}

/* ============================================================
   LIBRARY TAB
   ============================================================ */
.library-stats {
  grid-template-columns: repeat(4, 1fr);
}

.books {
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.profile-book {
  position: relative;
  display: flex;
  align-items: center;
  gap: 14px;
  padding: 12px 14px;
  border: 1px solid var(--bs-border-color);
  border-radius: 14px;
  background: var(--bs-body-bg);
  overflow: hidden;
  transition: transform var(--transition), box-shadow var(--transition), border-color var(--transition);
}
@media (max-width: 575.98px) {
  .profile-book {
    flex-direction: column;
    align-items: flex-start;
    gap: 12px;
  }
}
.profile-book:hover {
  transform: translateY(-2px);
  box-shadow: var(--shadow);
  border-color: var(--bs-primary);
}
.profile-book.overdue::before {
  content: "";
  position: absolute;
  left: 0;
  top: 0;
  bottom: 0;
  width: 4px;
  background: #dc2626;
}

.book-main {
  flex: 1;
  min-width: 0;
}

.book-title {
  font-weight: 600;
  font-size: 13.5px;
  color: var(--bs-emphasis-color);
}

.book-author {
  font-size: 11.5px;
  color: var(--bs-secondary-color);
}

.book-meta {
  display: flex;
  flex-wrap: wrap;
  gap: 4px 12px;
  margin-top: 5px;
  font-size: 11px;
  color: var(--bs-secondary-color);
}
.book-meta span {
  display: inline-flex;
  align-items: center;
  gap: 3px;
}
.book-meta i {
  font-size: 13px;
}

.book-side {
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  gap: 6px;
  flex-shrink: 0;
}

.profile-button-sm {
  height: 28px;
  padding: 0 10px;
  font-size: 12px;
  border-radius: 8px;
}
.profile-button-sm i {
  font-size: 14px;
}

.profile-queue {
  margin-left: auto;
  flex-shrink: 0;
  font-size: 11px;
  font-weight: 700;
  color: var(--bs-primary);
  background: var(--tint-primary);
  padding: 4px 10px;
  border-radius: 999px;
}
@media (max-width: 575.98px) {
  .profile-queue {
    margin-left: unset;
  }
}

.reading-history {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.reading-mini {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 9px 12px;
  border: 1px solid var(--bs-border-color);
  border-radius: 11px;
  transition: background var(--transition);
}
.reading-mini:hover {
  background: var(--bs-tertiary-bg);
}
.reading-mini b {
  font-size: 13px;
  color: var(--bs-emphasis-color);
}

.star-rating {
  display: flex;
  gap: 1px;
  margin-top: 2px;
}
.star-rating i {
  font-size: 13px;
  color: #f59e0b;
}
.star-rating i.ti-star {
  color: var(--bs-border-color);
}

@media (max-width: 575.98px) {
  .library-stats {
    grid-template-columns: repeat(2, 1fr);
  }
}
/* ============================================================
   ACADEMICS TAB
   ============================================================ */
.profile-kpi {
  position: relative;
  height: 100%;
  padding: 14px 16px;
  border-radius: 16px;
  border: 1px solid var(--bs-border-color);
  background: var(--bs-body-bg);
  overflow: hidden;
  transition: box-shadow var(--transition), transform var(--transition);
}
.profile-kpi::before {
  content: "";
  position: absolute;
  left: 0;
  top: 0;
  right: 0;
  height: 3px;
  background: var(--accent);
  opacity: 0.9;
}
.profile-kpi:hover {
  transform: translateY(-2px);
  box-shadow: var(--shadow);
}
.profile-kpi.grad-primary {
  --accent: var(--accent-indigo);
  --accent-soft: var(--tint-info);
  --avatar-accent: var(--accent);
  --avatar-accent-soft: var(--accent-soft);
}
.profile-kpi.grad-gold {
  --accent: var(--bs-warning);
  --accent-soft: var(--tint-warning);
  --avatar-accent: var(--accent);
  --avatar-accent-soft: var(--accent-soft);
}

.kpi-bg {
  position: absolute;
  right: -10px;
  bottom: -16px;
  font-size: 84px;
  line-height: 1;
  opacity: 0.05;
  color: var(--accent);
}
.kpi-bg i {
  display: block;
}

.kpi-top {
  position: relative;
  z-index: 1;
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 10px;
}

.kpi-tag {
  font-size: 11px;
  font-weight: 700;
  padding: 3px 10px;
  border-radius: 999px;
  background: var(--accent-soft);
  color: var(--accent);
}

.kpi-val {
  position: relative;
  z-index: 1;
  font-size: 28px;
  font-weight: 800;
  line-height: 1;
  color: var(--bs-emphasis-color);
}
.kpi-val small {
  font-size: 14px;
  font-weight: 600;
  color: var(--bs-secondary-color);
}

.kpi-lbl {
  position: relative;
  z-index: 1;
  font-size: 12px;
  margin-top: 4px;
  color: var(--bs-secondary-color);
}

.kpi-bar {
  position: relative;
  z-index: 1;
  height: 6px;
  border-radius: 999px;
  background: var(--bs-secondary-bg);
  overflow: hidden;
  margin-top: 10px;
}
.kpi-bar span {
  display: block;
  height: 100%;
  border-radius: 999px;
  background: var(--accent);
  width: 0;
  transition: width 1.1s cubic-bezier(0.4, 0, 0.2, 1);
}

.trend-x {
  display: flex;
  justify-content: space-between;
  margin-top: 4px;
}
.trend-x span {
  font-size: 9.5px;
  color: var(--bs-secondary-color);
}

.profile-kpi .profile-trend svg {
  height: 58px;
}

/* subject rows */
.subjmarks {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.profile-subject {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 11px 14px;
  border: 1px solid var(--bs-border-color);
  border-radius: 13px;
  background: var(--bs-body-bg);
  transition: transform var(--transition), box-shadow var(--transition);
}
.profile-subject:hover {
  transform: translateY(-2px);
  box-shadow: var(--shadow);
}

.subject-main {
  flex: 1;
  min-width: 0;
}

.subject-top {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-bottom: 7px;
}
.subject-top .name {
  font-weight: 600;
  font-size: 13.5px;
  color: var(--bs-emphasis-color);
}

.subject-pct {
  font-weight: 800;
  font-size: 15px;
  color: var(--bs-emphasis-color);
  width: 46px;
  text-align: right;
}

/* grade badges */
.grade {
  font-size: 11px;
  font-weight: 800;
  padding: 2px 8px;
  border-radius: 6px;
  font-style: normal;
  line-height: 1.5;
}
.grade.a {
  background: rgba(22, 163, 74, 0.14);
  color: #15803d;
}
.grade.b {
  background: rgba(37, 99, 235, 0.14);
  color: #1d4ed8;
}
.grade.c {
  background: rgba(217, 119, 6, 0.14);
  color: #b45309;
}
.grade.d {
  background: rgba(220, 38, 38, 0.14);
  color: #b91c1c;
}

/* exams & results — result banner (distinct from Attendance ring) */
.exam-result {
  display: grid;
  grid-template-columns: auto 1fr auto;
  gap: 18px;
  align-items: stretch;
  padding: 18px;
  border: 1px solid var(--bs-border-color);
  border-radius: var(--radius);
  background: radial-gradient(120% 150% at 100% 0, rgba(79, 70, 229, 0.06), transparent 55%), var(--bs-body-bg);
}
@media (max-width: 1399.98px) {
  .exam-result {
    grid-template-columns: 1fr;
  }
}

.exam-result-grade {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 8px;
  min-width: 116px;
  padding: 14px 18px;
  border-radius: 14px;
  background: linear-gradient(150deg, #4f46e5, #7b61ff);
  color: #fff;
  box-shadow: 0 14px 26px -12px rgba(79, 70, 229, 0.55), inset 0 1px 0 rgba(255, 255, 255, 0.25);
}

.exam-result-letter {
  font-size: 46px;
  font-weight: 800;
  line-height: 1;
  letter-spacing: -1px;
}

.exam-result-band {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  font-size: 11px;
  font-weight: 600;
  padding: 3px 11px;
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.18);
}
.exam-result-band i {
  font-size: 13px;
}

.exam-result-mid {
  display: flex;
  flex-direction: column;
  justify-content: center;
  gap: 12px;
  min-width: 0;
}

.exam-result-scoreline {
  display: flex;
  align-items: center;
  gap: 14px;
  flex-wrap: wrap;
}

.exam-result-pct {
  display: flex;
  align-items: baseline;
  font-weight: 800;
  color: var(--bs-emphasis-color);
  line-height: 1;
}
.exam-result-pct span {
  font-size: 42px;
}
.exam-result-pct i {
  font-size: 20px;
  font-style: normal;
  color: var(--bs-secondary-color);
  margin-left: 2px;
}

.exam-result-cap {
  display: flex;
  flex-direction: column;
}
.exam-result-cap b {
  font-size: 14px;
  color: var(--bs-emphasis-color);
}
.exam-result-cap span {
  font-size: 12px;
  color: var(--bs-secondary-color);
}

.exam-result-trend {
  margin-left: auto;
  display: inline-flex;
  align-items: center;
  gap: 4px;
  font-size: 12px;
  font-weight: 600;
  color: #16a34a;
  background: rgba(22, 163, 74, 0.1);
  padding: 5px 11px;
  border-radius: 999px;
}

.exam-result-meter {
  position: relative;
  display: flex;
  gap: 3px;
  height: 12px;
  margin-top: 2px;
}
.exam-result-meter .seg {
  height: 100%;
  border-radius: 4px;
}
.exam-result-meter .seg.f {
  flex: 40;
  background: rgba(220, 38, 38, 0.28);
}
.exam-result-meter .seg.p {
  flex: 20;
  background: rgba(217, 119, 6, 0.35);
}
.exam-result-meter .seg.m {
  flex: 25;
  background: rgba(8, 145, 178, 0.32);
}
.exam-result-meter .seg.d {
  flex: 15;
  background: rgba(22, 163, 74, 0.45);
}

.exam-result-needle {
  position: absolute;
  top: -4px;
  bottom: -4px;
  left: 0;
  width: 3px;
  border-radius: 3px;
  background: var(--bs-emphasis-color);
  box-shadow: 0 0 0 3px var(--bs-body-bg);
  transition: left 1.1s cubic-bezier(0.22, 1, 0.36, 1);
}
.exam-result-needle::after {
  content: "";
  position: absolute;
  top: -6px;
  left: 50%;
  transform: translateX(-50%);
  width: 11px;
  height: 11px;
  border-radius: 50%;
  background: var(--bs-emphasis-color);
  box-shadow: 0 0 0 3px var(--bs-body-bg);
}

.exam-result-scale {
  display: flex;
  justify-content: space-between;
  font-size: 10.5px;
  color: var(--bs-secondary-color);
}

.exam-result-side {
  display: flex;
  flex-direction: column;
  gap: 8px;
  justify-content: center;
  min-width: 200px;
}

.exam-result-stat {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 8px 12px;
  border: 1px solid var(--bs-border-color);
  border-radius: 12px;
  background: var(--bs-secondary-bg);
  transition: transform var(--transition), box-shadow var(--transition);
}
.exam-result-stat:hover {
  transform: translateY(-1px);
  box-shadow: var(--shadow);
}
.exam-result-stat .ic {
  width: 34px;
  height: 34px;
  border-radius: 9px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  font-size: 17px;
  background: var(--accent-soft);
  color: var(--accent);
  flex-shrink: 0;
}
.exam-result-stat .tx {
  display: flex;
  flex-direction: column;
  line-height: 1.2;
}
.exam-result-stat .tx b {
  font-size: 16px;
  color: var(--bs-emphasis-color);
}
.exam-result-stat .tx span {
  font-size: 11.5px;
  color: var(--bs-secondary-color);
}

@media (max-width: 991px) {
  .exam-result {
    grid-template-columns: 1fr;
  }
  .exam-result-side {
    min-width: 0;
    flex-direction: row;
    flex-wrap: wrap;
  }
  .exam-result-side .exam-result-stat {
    flex: 1 1 30%;
  }
}
@media (max-width: 575px) {
  .exam-result-grade {
    flex-direction: row;
    min-width: 0;
  }
  .exam-result-letter {
    font-size: 34px;
  }
  .exam-result-pct span {
    font-size: 34px;
  }
  .exam-result-side .exam-result-stat {
    flex: 1 1 100%;
  }
}
[data-bs-theme=dark] .exam-result-stat,
[data-theme=dark] .exam-result-stat {
  background: rgba(255, 255, 255, 0.03);
}

/* exam results table */
.exam-table {
  border: 1px solid var(--bs-border-color);
  border-radius: 14px;
  overflow: hidden;
}

.exam-row {
  display: grid;
  grid-template-columns: 1.6fr 1fr 1.4fr 0.7fr 0.8fr;
  align-items: center;
  gap: 10px;
  padding: 12px 14px;
}
.exam-row:not(.head):not(:last-child) {
  border-bottom: 1px solid var(--bs-border-color);
}
.exam-row.head {
  background: var(--bs-secondary-bg);
  font-size: 11px;
  text-transform: uppercase;
  letter-spacing: 0.03em;
  color: var(--bs-secondary-color);
  font-weight: 700;
  padding: 10px 14px;
}
.exam-row:not(.head):hover {
  background: var(--bs-tertiary-bg);
}
.exam-row .ex-name {
  font-weight: 600;
  color: var(--bs-emphasis-color);
  font-size: 13px;
}
.exam-row .ex-date {
  font-size: 12px;
  color: var(--bs-secondary-color);
}
.exam-row .ex-score {
  font-weight: 700;
  color: var(--bs-emphasis-color);
  font-size: 13px;
}
.exam-row .ex-score small {
  font-weight: 500;
  color: var(--bs-secondary-color);
  font-size: 11px;
}

.score-bar {
  display: block;
  height: 4px;
  border-radius: 999px;
  background: var(--bs-secondary-bg);
  margin-top: 5px;
  overflow: hidden;
}
.score-bar b {
  display: block;
  height: 100%;
  border-radius: 999px;
  background: var(--bs-primary);
}

/* teacher remark */
.profile-remark {
  position: relative;
  display: flex;
  gap: 14px;
  padding: 18px;
  border-radius: 16px;
  border: 1px solid var(--bs-border-color);
  background: linear-gradient(135deg, var(--tint-primary), transparent 70%);
}

.remark-quote {
  flex-shrink: 0;
  width: 40px;
  height: 40px;
  border-radius: 12px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  font-size: 22px;
  background: var(--bs-primary);
  color: #fff;
}

.remark-body p {
  margin: 0 0 12px;
  font-size: 13.5px;
  font-style: italic;
  color: var(--bs-emphasis-color);
  line-height: 1.6;
}

.remark-by {
  display: flex;
  align-items: center;
  gap: 10px;
}
@media (max-width: 575.98px) {
  .remark-by {
    flex-wrap: wrap;
  }
}
.remark-by img {
  width: 38px;
  height: 38px;
  border-radius: 50%;
  object-fit: cover;
}
.remark-by b {
  display: block;
  font-size: 13px;
  color: var(--bs-emphasis-color);
}
.remark-by span {
  font-size: 11.5px;
  color: var(--bs-secondary-color);
}

.remark-teal {
  background: linear-gradient(135deg, rgba(13, 148, 136, 0.14), transparent 70%);
}
.remark-teal .remark-quote {
  background: #0d9488;
}

@media (max-width: 575.98px) {
  .exam-row {
    grid-template-columns: 1.4fr 1fr 0.8fr;
  }
  .exam-row .ex-date,
  .exam-row.head span:nth-child(2) {
    display: none;
  }
}
/* ============================================================
   ATTENDANCE TAB
   ============================================================ */
.attendance-ringcard {
  height: 100%;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 14px;
  padding: 20px;
  border: 1px solid var(--bs-border-color);
  border-radius: 14px;
  background: var(--bs-body-bg);
}

.attendance-ring {
  width: 152px;
  height: 152px;
}
.attendance-ring .profile-ring-hole.big {
  width: 120px;
  height: 120px;
  flex-direction: column;
  font-size: 32px;
  font-weight: 800;
  gap: 0;
}
.attendance-ring .profile-ring-hole.big small {
  font-size: 10.5px;
  font-weight: 500;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  color: var(--bs-secondary-color);
  margin-top: 2px;
}

.attendance-ringcap {
  font-size: 12.5px;
  color: var(--bs-secondary-color);
  display: inline-flex;
  align-items: center;
  gap: 5px;
}
.attendance-ringcap i {
  color: #16a34a;
  font-size: 15px;
}
.attendance-ringcap b {
  color: var(--bs-emphasis-color);
}

.attendance-stats {
  height: 100%;
  align-content: center;
}

.profile-tile-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 8px;
  margin-bottom: 14px;
}

.attendance-avg {
  font-size: 11.5px;
  font-weight: 600;
  color: #15803d;
  background: rgba(22, 163, 74, 0.12);
  padding: 4px 10px;
  border-radius: 999px;
  display: inline-flex;
  align-items: center;
  gap: 4px;
}
.attendance-avg i {
  font-size: 14px;
}

.attendance-sub {
  font-size: 11px;
  font-weight: 500;
  color: var(--bs-secondary-color);
  background: var(--bs-secondary-bg);
  padding: 2px 9px;
  border-radius: 999px;
  margin-left: 4px;
}

.bar-group-target {
  position: relative;
}

.heatmap-block-wrap {
  padding: 14px;
  border: 1px solid var(--bs-border-color);
  border-radius: 14px;
  background: var(--bs-body-bg);
}

.heatmap-block-days {
  display: grid;
  grid-template-columns: repeat(7, 1fr);
  gap: 5px;
  margin-bottom: 6px;
}
.heatmap-block-days span {
  text-align: center;
  font-size: 10px;
  font-weight: 600;
  color: var(--bs-secondary-color);
  text-transform: uppercase;
  letter-spacing: 0.02em;
}

.heatmap-block .d {
  cursor: default;
  transition: transform var(--transition);
}
.heatmap-block .d:hover {
  transform: scale(1.15);
}

.heatmap-block-legend {
  flex-wrap: wrap;
}

/* ============================================================
   TIMETABLE TAB
   ============================================================ */
.today-chip {
  font-size: 11px;
  font-weight: 600;
  color: var(--bs-primary);
  background: var(--tint-primary);
  padding: 3px 10px;
  border-radius: 999px;
  margin-left: 6px;
}

/* subject colour tokens */
.sub-blue {
  --sub: #2563eb;
  --sub-soft: rgba(37, 99, 235, .12);
}

.sub-green {
  --sub: #16a34a;
  --sub-soft: rgba(22, 163, 74, .12);
}

.sub-purple {
  --sub: #7b61ff;
  --sub-soft: rgba(123, 97, 255, .12);
}

.sub-teal {
  --sub: #0d9488;
  --sub-soft: rgba(13, 148, 136, .12);
}

.sub-amber {
  --sub: #d97706;
  --sub-soft: rgba(217, 119, 6, .12);
}

.sub-pink {
  --sub: #db2777;
  --sub-soft: rgba(219, 39, 119, .12);
}

/* today's class schedule */
.profile-schedule {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.schedule-item {
  position: relative;
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 12px 14px;
  border: 1px solid var(--bs-border-color);
  border-radius: 13px;
  background: var(--bs-body-bg);
  overflow: hidden;
  transition: transform var(--transition), box-shadow var(--transition), border-color var(--transition);
}
@media (max-width: 575.98px) {
  .schedule-item {
    flex-direction: column;
    align-items: flex-start;
    gap: 12px;
  }
}
.schedule-item::before {
  content: "";
  position: absolute;
  left: 0;
  top: 0;
  bottom: 0;
  width: 4px;
  background: var(--sub, var(--bs-primary));
}
.schedule-item:hover {
  transform: translateX(2px);
  box-shadow: var(--shadow);
}
.schedule-item.now {
  border-color: var(--sub);
  background: var(--sub-soft);
}

.profile-schedule-time {
  width: 58px;
  flex-shrink: 0;
  display: flex;
  flex-direction: column;
  line-height: 1.15;
}
.profile-schedule-time b {
  font-size: 14px;
  color: var(--bs-emphasis-color);
}
.profile-schedule-time span {
  font-size: 11px;
  color: var(--bs-secondary-color);
}

.schedule-body {
  flex: 1;
  min-width: 0;
}

.schedule-subj {
  font-weight: 600;
  font-size: 14px;
  color: var(--bs-emphasis-color);
}

.profile-schedule-meta {
  font-size: 11.5px;
  color: var(--bs-secondary-color);
  display: flex;
  align-items: center;
  gap: 4px;
  flex-wrap: wrap;
}
.profile-schedule-meta i {
  font-size: 13px;
}

.schedule-status {
  font-size: 11px;
  font-weight: 700;
  padding: 4px 10px;
  border-radius: 999px;
  background: var(--bs-secondary-bg);
  color: var(--bs-secondary-color);
  white-space: nowrap;
}
.schedule-status.next {
  background: rgba(8, 145, 178, 0.12);
  color: #0e7490;
}
.schedule-status.now {
  background: var(--sub);
  color: #fff;
  display: inline-flex;
  align-items: center;
  gap: 5px;
}
.schedule-status.now .profile-dot {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: #fff;
  animation: sp-blink 1.2s infinite;
}

/* weekly timetable grid */
.timetable-wrap {
  overflow-x: auto;
}

.profile-timetable {
  width: 100%;
  border-collapse: separate;
  border-spacing: 6px;
  min-width: 580px;
}
.profile-timetable th {
  font-size: 11px;
  color: var(--bs-secondary-color);
  text-transform: uppercase;
  letter-spacing: 0.03em;
  padding: 4px 6px 8px;
  text-align: center;
  font-weight: 700;
}
.profile-timetable thead th span {
  display: block;
  font-size: 9.5px;
  font-weight: 500;
  text-transform: none;
  letter-spacing: 0;
  opacity: 0.7;
  margin-top: 2px;
}
.profile-timetable tbody th {
  text-align: center;
  font-size: 12px;
  font-weight: 700;
  color: var(--bs-emphasis-color);
  background: var(--bs-secondary-bg);
  border-radius: 10px;
  width: 54px;
}
.profile-timetable td {
  text-align: center;
  padding: 3px;
}

.tt-chip {
  display: block;
  padding: 9px 6px;
  border-radius: 10px;
  font-size: 12px;
  font-weight: 600;
  background: var(--sub-soft, var(--bs-secondary-bg));
  color: var(--sub, var(--bs-emphasis-color));
  border: 1px solid transparent;
  transition: transform var(--transition), box-shadow var(--transition);
}
.tt-chip:hover {
  transform: translateY(-2px);
  box-shadow: var(--shadow);
}
.tt-chip.free {
  background: var(--bs-secondary-bg);
  color: var(--bs-secondary-color);
  font-weight: 500;
  border-style: dashed;
  border-color: var(--bs-border-color);
}

/* subject palette (chips + legend keys) */
.s-math {
  --sub: #2563eb;
  --sub-soft: rgba(37, 99, 235, .12);
}

.s-sci {
  --sub: #16a34a;
  --sub-soft: rgba(22, 163, 74, .12);
}

.s-eng {
  --sub: #7b61ff;
  --sub-soft: rgba(123, 97, 255, .12);
}

.s-geo {
  --sub: #0d9488;
  --sub-soft: rgba(13, 148, 136, .12);
}

.s-his {
  --sub: #db2777;
  --sub-soft: rgba(219, 39, 119, .12);
}

.s-pe {
  --sub: #d97706;
  --sub-soft: rgba(217, 119, 6, .12);
}

.s-mus {
  --sub: #4f46e5;
  --sub-soft: rgba(79, 70, 229, .12);
}

.s-art {
  --sub: #0891b2;
  --sub-soft: rgba(8, 145, 178, .12);
}

.s-cs {
  --sub: #475569;
  --sub-soft: rgba(71, 85, 105, .12);
}

.timetable-legend {
  display: flex;
  flex-wrap: wrap;
  gap: 6px 14px;
}
.timetable-legend span {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  font-size: 11.5px;
  color: var(--bs-secondary-color);
}

.tt-key {
  width: 11px;
  height: 11px;
  border-radius: 4px;
  background: var(--sub, var(--bs-primary));
}

/* exam / assignment event tiles */
.profile-event {
  position: relative;
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 12px 14px;
  border: 1px solid var(--bs-border-color);
  border-radius: 13px;
  background: var(--bs-body-bg);
  overflow: hidden;
  transition: transform var(--transition), box-shadow var(--transition);
}
@media (max-width: 575.98px) {
  .profile-event {
    flex-direction: column;
    align-items: flex-start;
  }
}
.profile-event::before {
  content: "";
  position: absolute;
  left: 0;
  top: 0;
  bottom: 0;
  width: 4px;
  background: var(--sub, var(--bs-primary));
}
.profile-event:hover {
  transform: translateY(-2px);
  box-shadow: var(--shadow);
}

.profile-event-date {
  width: 46px;
  height: 46px;
  border-radius: 12px;
  flex-shrink: 0;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  line-height: 1;
  background: var(--sub-soft, var(--tint-primary));
  color: var(--sub, var(--bs-primary));
}
.profile-event-date b {
  font-size: 18px;
  font-weight: 800;
}
.profile-event-date span {
  font-size: 10px;
  text-transform: uppercase;
}

.profile-event-body {
  flex: 1;
  min-width: 0;
}

.event-title {
  font-weight: 600;
  font-size: 13.5px;
  color: var(--bs-emphasis-color);
}

/* ============================================================
   SKELETON
   ============================================================ */
/* the primitive and its shared shapes come from components/_ui-skeleton.scss;
   only this page's own placeholder geometry lives here */
.profile-live {
  display: none;
}

.student-profile.loaded .profile-live {
  display: block;
}

.student-profile .skeleton {
  border-radius: 8px;
}
.student-profile .skeleton-photo {
  width: 118px;
  height: 118px;
  border-radius: 20px;
}
.student-profile .skeleton-ring {
  width: 74px;
  height: 74px;
  border-radius: 50%;
}
.student-profile .skeleton-btn {
  height: 38px;
  width: 120px;
  border-radius: var(--radius-sm);
}
.student-profile .skeleton-card {
  height: 120px;
  border-radius: var(--radius);
}
.student-profile .skeleton-ov {
  height: 92px;
  border-radius: var(--radius-sm);
}
.student-profile .skeleton-chart {
  height: 170px;
