/* ============================================================
   ID CARD (modal) + CONFIRM
   ============================================================ */
.idcard {
  --id-accent: var(--bs-primary);
  position: relative;
  width: 300px;
  margin: 4px auto;
  background: #fff;
  border-radius: 18px;
  overflow: hidden;
  box-shadow: 0 18px 40px -12px rgba(17, 24, 39, 0.38), 0 0 0 1px rgba(17, 24, 39, 0.05);
}

.idcard-head {
  position: relative;
  padding: 22px 18px 40px;
  text-align: center;
  color: #fff;
  background: linear-gradient(135deg, rgba(0, 0, 0, 0), rgba(0, 0, 0, 0.22)), var(--id-accent);
}

.idcard-logo {
  width: 34px;
  height: 34px;
  border-radius: 9px;
  background: rgba(255, 255, 255, 0.18);
  display: inline-flex;
  align-items: center;
  justify-content: center;
  vertical-align: middle;
}
.idcard-logo i {
  font-size: 20px;
  color: #fff;
}

.idcard-brand {
  display: inline-block;
  vertical-align: middle;
  margin-left: 8px;
  text-align: left;
}
.idcard-brand h6 {
  margin: 0;
  font-size: 14px;
  font-weight: 800;
  letter-spacing: 0.04em;
}
.idcard-brand span {
  font-size: 9px;
  text-transform: uppercase;
  letter-spacing: 0.12em;
  opacity: 0.85;
}

.idcard-wave {
  position: absolute;
  left: 0;
  right: 0;
  bottom: -1px;
  height: 30px;
  background: #fff;
  border-radius: 50% 50% 0 0/100% 100% 0 0;
}

.idcard-photo-wrap {
  position: relative;
  width: 88px;
  height: 88px;
  margin: -36px auto 0;
  border-radius: 16px;
  padding: 4px;
  background: #fff;
  box-shadow: 0 8px 18px -6px rgba(17, 24, 39, 0.3);
}
.idcard-photo-wrap img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  border-radius: 12px;
}

.idcard-identity {
  text-align: center;
  margin-top: 8px;
}
.idcard-identity h5 {
  margin: 0;
  font-size: 17px;
  font-weight: 700;
  color: #111827;
}

.idcard-role {
  display: inline-block;
  margin-top: 5px;
  padding: 3px 12px;
  border-radius: 999px;
  background: var(--tint-primary);
  color: var(--id-accent);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.14em;
}

.idcard-info {
  margin: 12px 18px 0;
  border: 1px solid var(--bs-border-color);
  border-radius: 12px;
  overflow: hidden;
}
.idcard-info .idcard-row {
  display: flex;
  justify-content: space-between;
  padding: 8px 12px;
  font-size: 12px;
}
.idcard-info .idcard-row:nth-child(odd) {
  background: var(--bs-secondary-bg);
}
.idcard-info .idcard-row span {
  color: var(--bs-secondary-color);
}
.idcard-info .idcard-row b {
  color: #111827;
}

.idcard-barcode {
  margin: 12px 18px 0;
  text-align: center;
}

.idcard-bars {
  height: 38px;
  border-radius: 4px;
  background-image: repeating-linear-gradient(90deg, #1f2937 0 2px, #fff 2px 4px, #1f2937 4px 7px, #fff 7px 9px, #1f2937 9px 10px, #fff 10px 13px, #1f2937 13px 16px, #fff 16px 17px);
}

.idcard-barcode span {
  display: block;
  margin-top: 4px;
  font-size: 11px;
  letter-spacing: 0.28em;
  color: #374151;
  font-weight: 600;
}

.idcard-foot {
  margin-top: 14px;
  padding: 10px 16px;
  text-align: center;
  font-size: 10.5px;
  color: #fff;
  background: linear-gradient(135deg, rgba(0, 0, 0, 0), rgba(0, 0, 0, 0.22)), var(--id-accent);
}

/* ============================================================
   FEES TAB
   ============================================================ */
.fee-banner {
  display: flex;
  align-items: center;
  gap: 14px;
  padding: 14px 16px;
  margin-bottom: 16px;
  border-radius: 14px;
  border: 1px solid var(--bs-border-color);
  background: radial-gradient(120% 160% at 0% 0%, var(--tint-primary), transparent 60%), linear-gradient(135deg, var(--tint-primary), var(--bs-secondary-bg));
}
@media (max-width: 575.98px) {
  .fee-banner {
    flex-direction: column;
    align-items: start;
  }
}

.fee-banner-txt {
  display: flex;
  flex-direction: column;
  line-height: 1.35;
}
.fee-banner-txt b {
  font-size: 14px;
  color: var(--bs-emphasis-color);
}
.fee-banner-txt span {
  font-size: 12.5px;
  color: var(--bs-secondary-color);
}
.fee-banner-txt strong {
  color: var(--bs-primary);
}

.fee-donut-card {
  border: 1px solid var(--bs-border-color);
  border-radius: 14px;
  padding: 18px;
  height: 100%;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 16px;
  background: var(--bs-body-bg);
}

.fee-donut {
  position: relative;
  width: 150px;
  height: 150px;
}
.fee-donut svg {
  width: 150px;
  height: 150px;
  transform: rotate(-90deg);
}
.fee-donut svg circle {
  fill: none;
  stroke-width: 16;
  stroke-linecap: round;
}
.fee-donut svg .track {
  stroke: var(--bs-secondary-bg);
}

.fee-donut-center {
  position: absolute;
  inset: 0;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
}
.fee-donut-center .pct {
  font-size: 30px;
  font-weight: 800;
  color: var(--bs-emphasis-color);
  line-height: 1;
}
.fee-donut-center .lbl {
  font-size: 11px;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  color: var(--bs-secondary-color);
  margin-top: 3px;
}

.fee-donut-card .donut-legend {
  flex-direction: row;
  flex-wrap: wrap;
  gap: 6px 16px;
  justify-content: center;
}

.fee-stats {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 10px;
}
@media (max-width: 575.98px) {
  .fee-stats {
    grid-template-columns: 1fr;
  }
}

.fee-stat {
  position: relative;
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 14px;
  border: 1px solid var(--bs-border-color);
  border-radius: 14px;
  background: var(--bs-body-bg);
  overflow: hidden;
  transition: transform var(--transition), box-shadow var(--transition);
}
.fee-stat::before {
  content: "";
  position: absolute;
  left: 0;
  top: 0;
  bottom: 0;
  width: 4px;
  background: var(--accent);
}
.fee-stat:hover {
  transform: translateY(-2px);
  box-shadow: var(--shadow-lift);
}

.fee-stat-body {
  flex: 1;
  min-width: 0;
}
.fee-stat-body .v {
  font-size: 19px;
  font-weight: 800;
  color: var(--bs-emphasis-color);
  line-height: 1.1;
}
.fee-stat-body .l {
  font-size: 11.5px;
  color: var(--bs-secondary-color);
}

.fee-mini {
  height: 5px;
  border-radius: 999px;
  background: var(--bs-secondary-bg);
  overflow: hidden;
  margin-top: 6px;
}
.fee-mini span {
  display: block;
  height: 100%;
  border-radius: 999px;
  width: 0;
  transition: width 1s cubic-bezier(0.4, 0, 0.2, 1);
}

.fee-progress {
  margin-top: 12px;
}
.fee-progress .top {
  display: flex;
  justify-content: space-between;
  font-size: 12px;
  color: var(--bs-secondary-color);
  margin-bottom: 6px;
}
.fee-progress .top b {
  color: var(--bs-emphasis-color);
}

/* invoice rows */
.fee-invoices {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.profile-invoice {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 12px 14px;
  border: 1px solid var(--bs-border-color);
  border-radius: 13px;
  background: var(--bs-body-bg);
  transition: transform var(--transition), box-shadow var(--transition), border-color var(--transition);
}
@media (max-width: 575.98px) {
  .profile-invoice {
    flex-direction: column;
    align-items: start;
  }
}
.profile-invoice:hover {
  transform: translateY(-2px);
  box-shadow: var(--shadow);
  border-color: var(--bs-primary);
}

.invoice-main {
  flex: 1;
  min-width: 0;
}

.invoice-title {
  font-weight: 600;
  font-size: 13.5px;
  color: var(--bs-emphasis-color);
}

.invoice-sub {
  font-size: 11.5px;
  color: var(--bs-secondary-color);
}

.invoice-amt {
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  gap: 4px;
  font-weight: 700;
  font-size: 14px;
  color: var(--bs-emphasis-color);
  white-space: nowrap;
}

/* ============================================================
   ANIMATIONS
   ============================================================ */
@keyframes sp-blink {
  0%, 100% {
    opacity: 1;
  }
  50% {
    opacity: 0.3;
  }
}
@keyframes sp-fade {
  from {
    opacity: 0;
    transform: translateY(6px);
  }
  to {
    opacity: 1;
    transform: none;
  }
}
@keyframes sp-draw {
  to {
    stroke-dashoffset: 0;
  }
}
/* ============================================================
   RESPONSIVE
   ============================================================ */
@media (max-width: 1399.98px) {
  .profile-overview-grid {
    grid-template-columns: repeat(3, 1fr);
  }
}
@media (max-width: 991.98px) {
  .hero-grid {
    grid-template-columns: auto 1fr;
  }
  .hero-right {
    grid-column: 1/-1;
    justify-content: space-between;
    margin-top: 6px;
  }
  .profile-overview-grid {
    grid-template-columns: repeat(3, 1fr);
  }
}
@media (max-width: 767.98px) {
  .hero-grid {
    grid-template-columns: 1fr;
    text-align: center;
    justify-items: center;
  }
  .hero-meta,
  .badges {
    justify-content: center;
  }
  .hero-right {
    flex-direction: column;
    gap: 16px;
  }
  .profile-overview-grid {
    grid-template-columns: repeat(2, 1fr);
  }
  .profile-quick-action-grid {
    grid-template-columns: repeat(3, 1fr);
  }
  .definition-list {
    grid-template-columns: 1fr;
  }
}
