}
.record-fact b {
  display: block;
  font-size: 16px;
  font-weight: 800;
  color: var(--bs-emphasis-color);
}
.record-fact span {
  font-size: 10.5px;
  color: var(--bs-secondary-color, #6b7280);
}

/*-----------------
    Skeleton

    The shared skeleton is shaped for the students grid. These rules retrace it
    over this table's eight columns and reduced row height, so the placeholder
    and the loaded rows occupy the same space and nothing jumps on reveal.
-----------------*/
.classes-workspace {
  /* The toolbar sits in .card-header, a sibling of the skeleton rather than a
     child, so it painted straight away with the placeholder stacked under it.
     `:not()` un-matches itself once loaded, so the header needs no counter-rule
     to come back and cannot be stranded hidden. */
  /* The shared component only ever turns the live view ON (`.is-loaded
     .live-content { display: block }`); it never turns it off, and both the header
     and the table are plain divs, so they paint before the reveal. */
}
.classes-workspace:not(.is-loaded) .card-header, .classes-workspace:not(.is-loaded) .live-content {
  display: none;
}
.classes-workspace .skeleton-head {
  padding: 16px 16px 10px;
  border-bottom: 1px solid var(--bs-border-color);
}
.classes-workspace .skeleton-toolbar {
  gap: 8px;
  padding-bottom: 0;
}
.classes-workspace .skeleton-quick {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-wrap: wrap;
  margin-top: 10px;
}
.classes-workspace .skeleton-row {
  grid-template-columns: 34px 30px minmax(210px, 1.6fr) 90px 0.8fr minmax(150px, 1.2fr) 0.5fr 150px;
  gap: 12px;
  padding: 10px 12px;
  border-bottom-color: var(--bs-border-color);
}
.classes-workspace .skeleton-row:last-child {
  border-bottom: 0;
}
.classes-workspace .skeleton-thead {
  padding: 14px 12px;
  background: var(--bs-tertiary-bg);
}
.classes-workspace .skeleton-head {
  height: 9px;
  width: 68%;
  border-radius: 4px;
}
.classes-workspace .skeleton-head-end {
  margin-left: auto;
  width: 46px;
}
.classes-workspace .skeleton-cell {
  display: flex;
  align-items: center;
  gap: 10px;
  min-width: 0;
}
.classes-workspace .skeleton-stack {
  flex: 1;
  min-width: 0;
}
.classes-workspace .skeleton-stack .skeleton-line + .skeleton-line {
  margin-top: 5px;
}
.classes-workspace .skeleton-chev {
  width: 24px;
  height: 24px;
  border-radius: 7px;
}
.classes-workspace .skeleton-check {
  width: 18px;
  height: 18px;
  border-radius: 5px;
}
.classes-workspace .skeleton-avatar {
  width: 38px;
  height: 38px;
  border-radius: 10px;
}
.classes-workspace .skeleton-avatar.skeleton-round {
  border-radius: 50%;
}
.classes-workspace .skeleton-circle {
  width: 28px;
  height: 28px;
}
.classes-workspace .skeleton-line {
  height: 10px;
}
.classes-workspace .skeleton-thin {
  height: 8px;
  width: 65%;
}
.classes-workspace .skeleton-pill {
  height: 20px;
  width: 70px;
}
.classes-workspace .skeleton-foot {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 10px;
  padding: 10px 12px;
}
.classes-workspace .skeleton-foot-info {
  width: 150px;
  height: 10px;
}
.classes-workspace .skeleton-foot-size {
  width: 84px;
  height: 30px;
  border-radius: 8px;
  margin-left: auto;
}
.classes-workspace .skeleton-pager {
  display: flex;
  gap: 3px;
}
.classes-workspace .skeleton-page {
  width: 30px;
  height: 30px;
  border-radius: 8px;
}
.classes-workspace .skeleton-search {
  height: 34px;
  width: 250px;
  border-radius: 8px;
}
.classes-workspace .skeleton-btn {
  height: 34px;
  width: 96px;
  border-radius: 8px;
}
.classes-workspace .skeleton-ico {
  height: 34px;
  width: 34px;
  border-radius: 8px;
}
.classes-workspace .skeleton-density {
  height: 34px;
  width: 96px;
  border-radius: 8px;
}
.classes-workspace .skeleton-chip {
  height: 32px;
  width: 104px;
  border-radius: 999px;
}
.classes-workspace .skeleton-quick .skeleton-btn {
  height: 32px;
  width: 84px;
}

/*-----------------
    Bulk action bar
-----------------*/
.bulk-selection {
  position: sticky;
  bottom: 16px;
  z-index: 20;
  margin-top: 16px;
  display: flex;
  justify-content: center;
  pointer-events: none;
}

.bulk-selection-inner {
  display: flex;
  align-items: center;
  gap: 12px;
  flex-wrap: wrap;
  padding: 10px 14px;
  border-radius: 0;
  background: transparent;
  box-shadow: none;
  pointer-events: auto;
  animation: cls-rise 0.28s cubic-bezier(0.22, 1, 0.36, 1);
}
.bulk-selection-inner .btn {
  background: var(--bs-tertiary-bg);
  border-color: var(--bs-border-color);
  color: var(--heading);
}
.bulk-selection-inner .btn:hover {
  background: var(--bs-primary);
  border-color: var(--bs-primary);
  color: #fff;
}
.bulk-selection-inner .btn.text-danger {
  color: #dc3545 !important;
}

@keyframes cls-rise {
  from {
    opacity: 0;
    transform: translateY(14px);
  }
  to {
    opacity: 1;
    transform: none;
  }
}
.bulk-selection-count {
  font-size: 12px;
  font-weight: 600;
  color: var(--bs-secondary-color, #6b7280);
  white-space: nowrap;
}
.bulk-selection-count b {
  font-size: 14px;
  font-weight: 800;
  color: var(--heading);
}

.bulk-selection-close {
  width: 28px;
  height: 28px;
  border-radius: 50%;
  border: 0;
  background: var(--bs-tertiary-bg);
  color: var(--heading);
  cursor: pointer;
  display: grid;
  place-items: center;
  font-size: 15px;
}
.bulk-selection-close:hover {
  background: var(--bs-primary);
  color: #fff;
}

/*-----------------
    Import drop zone
-----------------*/
.stacked-dropdown {
  position: relative;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 4px;
  padding: 28px 16px;
  border-radius: 12px;
  border: 2px dashed var(--bs-border-color);
  background: var(--bs-tertiary-bg);
  text-align: center;
  transition: all var(--transition);
}
.stacked-dropdown:hover {
  border-color: var(--bs-primary);
}
.stacked-dropdown i {
  font-size: 30px;
  color: var(--bs-primary);
}
.stacked-dropdown b {
  font-size: 13px;
