  flex: 1 1 240px;
  min-width: 180px;
}
.search-field-roles .form-control {
  height: 38px;
  padding-left: 34px;
}
.search-field-roles i {
  position: absolute;
  left: 11px;
  top: 50%;
  transform: translateY(-50%);
  color: var(--bs-secondary-color);
  font-size: 16px;
  pointer-events: none;
}

/* permission module accordion */
.permission-module-list .accordion-item {
  border: 1px solid var(--bs-border-color);
  border-radius: var(--radius-sm) !important;
  margin-bottom: 12px;
  overflow: hidden;
  background: var(--bs-body-bg);
  transition: box-shadow var(--transition);
}
.permission-module-list .accordion-item:hover {
  box-shadow: var(--shadow);
}

.permission-module-list .accordion-button {
  border-radius: var(--radius-sm);
  font-weight: 600;
  padding: 14px 16px;
  background: var(--bs-body-bg);
}
@media (max-width: 575.98px) {
  .permission-module-list .accordion-button {
    flex-wrap: wrap;
    gap: 12px;
  }
}
.permission-module-list .accordion-button:not(.collapsed) {
  color: var(--bs-primary);
  background: var(--tint-primary);
  box-shadow: none;
}
.permission-module-list .accordion-button:focus {
  box-shadow: none;
}

.permission-module-icon {
  width: 34px;
  height: 34px;
  border-radius: 10px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  font-size: 18px;
  margin-right: 12px;
  background: var(--tint-primary);
  color: var(--bs-primary);
}

.permission-module-count {
  margin-left: auto;
  margin-right: 12px;
  font-size: 11.5px;
  font-weight: 600;
  color: var(--bs-secondary-color);
}

/* permission switch grid */
.permission-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(150px, 1fr));
  gap: 10px;
}

.permission-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  padding: 10px 12px;
  border: 1px solid var(--bs-border-color);
  border-radius: 10px;
  background: var(--bs-secondary-bg);
  transition: border-color var(--transition), background var(--transition);
}
.permission-row:hover {
  border-color: var(--bs-primary);
  background: var(--bs-body-bg);
}
.permission-row .form-check {
  margin: 0;
  min-height: auto;
  padding: 0;
}
.permission-row .form-check-input {
  margin: 0;
  cursor: pointer;
}
.permission-row label {
  font-size: 13px;
  font-weight: 500;
  cursor: pointer;
}

/* ============================================================
   USER ASSIGNMENT
   ============================================================ */
.user-row {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 12px 4px;
  border-bottom: 1px solid var(--bs-border-color);
}
.user-row:last-child {
  border-bottom: 0;
}

.user-row-body {
  min-width: 0;
  flex: 1;
}

.user-row-body h6 {
  font-size: 14px;
  font-weight: 600;
  margin: 0;
}

.user-row-body span {
  font-size: 12px;
  color: var(--bs-secondary-color);
}

/* ============================================================
   AUDIT TIMELINE
   ============================================================ */
.roles-timeline {
  position: relative;
  padding-left: 26px;
}

.roles-timeline::before {
  content: "";
  position: absolute;
  left: 8px;
  top: 4px;
  bottom: 4px;
  width: 2px;
  background: var(--bs-border-color);
}

.roles-timeline-item {
  position: relative;
  padding-bottom: 18px;
}

.roles-timeline-item:last-child {
  padding-bottom: 0;
}

.roles-timeline-dot {
  position: absolute;
  left: -26px;
  top: 2px;
  width: 18px;
  height: 18px;
  border-radius: 50%;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  font-size: 11px;
  color: #fff;
  background: var(--bs-primary);
}

.roles-timeline-item p {
  margin: 0;
  font-size: 13px;
  font-weight: 500;
  color: var(--bs-body-color, #1f2937);
}

.roles-timeline-item .roles-timeline-meta {
  font-size: 11.5px;
  color: var(--bs-secondary-color);
}

/* ============================================================
   SECURITY PANEL
   ============================================================ */
.score-block {
  position: relative;
  width: 130px;
  height: 130px;
  margin: 0 auto;
  border-radius: 50%;
  display: grid;
  place-items: center;
  background: radial-gradient(closest-side, var(--bs-body-bg) 78%, transparent 79% 100%), conic-gradient(var(--bs-success) var(--score-block, 82%), var(--bs-border-color) 0);
}

.score-value {
  font-size: 30px;
  font-weight: 800;
  line-height: 1;
  color: var(--bs-heading-color, #111827);
}

.score-label {
  font-size: 11px;
  color: var(--bs-secondary-color);
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

.section-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 11px 0;
  border-bottom: 1px solid var(--bs-border-color);
  font-size: 13px;
}
.section-row:last-child {
  border-bottom: 0;
}
.section-row .section-label {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  color: var(--bs-secondary-color);
}
.section-row .section-label i {
  font-size: 16px;
}

/* ============================================================
   RESPONSIVE
   ============================================================ */
@media (max-width: 991.98px) {
  .directory-list {
    max-height: 360px;
  }
}
/* ============================================================
   DARK MODE
   ============================================================ */
[data-bs-theme=dark] .role-card-name,
[data-bs-theme=dark] .user-row-body h6,
[data-bs-theme=dark] .score-value,
[data-bs-theme=dark] .roles-timeline-item p {
  color: #e9edf5;
}

/* ============================================================
   Delete Account Requests — Account Lifecycle Management
   Adds only the page-specific pieces on top of the shared
   .data-workspace / .data-table / card-* system: an approval
   workflow stepper, a compliance warning panel and the
   truncating reason cell. Never touches sidebar/header/shell.
   ============================================================ */
@media (prefers-reduced-motion: reduce) {
  .closure-page * {
    animation: none !important;
    transition: none !important;
  }
}
/* ---------- Reason cell (truncates with tooltip + view) ---------- */
.closure-reason {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  max-width: 190px;
}
.closure-reason .closure-reason-text {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

/* ============================================================
   APPROVAL WORKFLOW STEPPER
   ============================================================ */
.closure-flow {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}

.closure-step {
  position: relative;
  flex: 1 1 200px;
  min-width: 140px;
  padding: 14px 14px 14px 46px;
  border: 1px solid var(--bs-border-color);
  border-radius: 12px;
  background: var(--bs-body-bg);
  transition: transform var(--transition), box-shadow var(--transition), border-color var(--transition);
}
@media (max-width: 991.98px) {
  .closure-step {
    flex: 1 1 195px;
  }
}
.closure-step:hover {
  transform: translateY(-2px);
  box-shadow: 0 10px 24px rgba(17, 24, 39, 0.08);
}

.closure-step-icon {
  position: absolute;
  left: 12px;
  top: 12px;
  width: 26px;
  height: 26px;
  border-radius: 50%;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  font-size: 14px;
  color: #fff;
  background: var(--bs-secondary-color);
}

.closure-step-title {
  font-size: 13px;
  font-weight: 600;
  margin: 0;
  color: var(--bs-heading-color, #111827);
}

.closure-step-meta {
  font-size: 11px;
  color: var(--bs-secondary-color);
  margin: 2px 0 0;
}

.closure-step-review {
  font-size: 11px;
  color: var(--bs-secondary-color);
  display: inline-flex;
  align-items: center;
  gap: 4px;
  margin-top: 4px;
}

.closure-step-review i {
  font-size: 12px;
}

/* connector line between steps */
.closure-step::after {
  content: "";
  position: absolute;
  right: -8px;
  top: 25px;
  width: 8px;
  height: 2px;
  background: var(--bs-border-color);
}

.closure-step:last-child::after {
  display: none;
}

/* states */
.closure-step.is-done {
  border-color: var(--tint-success);
  background: linear-gradient(135deg, var(--tint-success), transparent 70%), var(--bs-body-bg);
}

.closure-step.is-done .closure-step-icon {
  background: var(--bs-success);
}

.closure-step.is-active {
  border-color: transparent;
  box-shadow: 0 8px 22px var(--tint-primary);
  background: linear-gradient(135deg, var(--tint-primary), transparent 70%), var(--bs-body-bg);
}

.closure-step.is-active .closure-step-icon {
  background: var(--bs-primary);
  animation: dar-pulse 1.8s ease-out infinite;
}

.closure-step.is-pending .closure-step-icon {
  background: #cbd5e1;
}

@keyframes dar-pulse {
  0% {
    box-shadow: 0 0 0 0 var(--tint-primary);
  }
  70% {
    box-shadow: 0 0 0 7px var(--tint-primary);
  }
  100% {
    box-shadow: 0 0 0 0 var(--tint-primary);
  }
}
/* ============================================================
   COMPLIANCE WARNING PANEL
   ============================================================ */
.warning-panel {
  border: 1px solid var(--tint-warning);
  border-radius: 16px;
  background: linear-gradient(135deg, var(--tint-warning), transparent 60%), var(--bs-body-bg);
  overflow: hidden;
}

.warning-panel-head {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 16px;
  border-bottom: 1px solid var(--tint-warning);
}

.warning-panel-icon {
  width: 44px;
  height: 44px;
  flex: 0 0 44px;
  border-radius: 12px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  font-size: 24px;
  color: #fff;
  background: linear-gradient(135deg, #f59e0b, var(--bs-warning));
  box-shadow: 0 6px 16px var(--tint-warning);
}

.warning-panel-list {
  padding: 8px 16px 16px;
  margin: 0;
  list-style: none;
}

.warning-panel-list li {
  display: flex;
  align-items: flex-start;
  gap: 10px;
  padding: 8px 0;
  font-size: 13px;
  color: var(--bs-body-color, #374151);
  border-bottom: 1px solid var(--bs-border-color);
}

.warning-panel-list li:last-child {
  border-bottom: 0;
}

.warning-panel-list li i {
  font-size: 17px;
  margin-top: 1px;
  flex: 0 0 17px;
}

/* ============================================================
   DARK MODE
   ============================================================ */
[data-bs-theme=dark] .closure-step-title {
  color: #e9edf5;
}

[data-bs-theme=dark] .closure-step.is-pending .closure-step-icon {
  background: #3a4252;
}

/* ============================================================
   Membership Plans — Subscription & Billing Management
   Adds the plan-grid, billing toggle, comparison, popularity
   insights and promotion pieces on top of Bootstrap + the
   shared card-* / data-table chrome and stats-card cards. Never
   touches sidebar / header / shell.
   ============================================================ */
@media (prefers-reduced-motion: reduce) {
  .plan-page * {
    animation: none !important;
    transition: none !important;
  }
}
/* Overview metric cards reuse the directory stat component, but the little
   avatar "presence" dot only makes sense on people — hide it here. */
.plan-overview .stats-card-directory .stats-avatar::after {
  content: none;
}

/* ============================================================
   BILLING TOGGLE
   ============================================================ */
.billing-switch {
  display: inline-flex;
  align-items: center;
  gap: 12px;
  padding: 8px 16px;
  border: 1px solid var(--bs-border-color);
  border-radius: 999px;
  background: var(--bs-body-bg);
  box-shadow: var(--shadow);
}
.billing-switch h6 {
  margin: 0;
  font-size: 13.5px;
  font-weight: 600;
  color: var(--bs-secondary-color);
  transition: color var(--transition);
}
.billing-switch .form-check-input {
  cursor: pointer;
}

.plan-page.is-yearly .billing-switch .billing-yearly,
.plan-page:not(.is-yearly) .billing-switch .billing-monthly {
  color: var(--bs-primary);
}

/* price swap driven by the .is-yearly state on .plan-page */
.plan-page .price-yearly {
  display: none;
}

.plan-page.is-yearly .price-monthly {
  display: none;
}

.plan-page.is-yearly .price-yearly {
  display: block;
}

/* ============================================================
   PLAN GRID
   ============================================================ */
.plan-card {
  position: relative;
  display: flex;
  flex-direction: column;
  height: 100%;
  padding: 22px;
  border: 1px solid var(--bs-border-color);
  border-radius: 16px;
  background: linear-gradient(180deg, var(--accent-soft, var(--tint-primary)), transparent 32%), var(--bs-body-bg);
  box-shadow: var(--shadow);
  transition: transform var(--transition), box-shadow var(--transition), border-color var(--transition);
  overflow: hidden;
}
.plan-card::before {
  content: "";
  position: absolute;
  left: 0;
  right: 0;
  top: 0;
  height: 4px;
  background: linear-gradient(90deg, var(--accent, var(--bs-primary)), var(--accent-strong, #7b93ff));
}
.plan-card:hover {
  transform: translateY(-6px);
  box-shadow: var(--shadow-lift);
  border-color: transparent;
}
.plan-card.is-popular {
  border-color: transparent;
  box-shadow: 0 0 0 2px var(--accent, var(--bs-success)), var(--shadow-lift);
}

.plan-card-badge {
  position: absolute;
  top: 14px;
  right: 14px;
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 4px 10px;
  border-radius: 999px;
  font-size: 11px;
  font-weight: 700;
  color: #fff;
  background: linear-gradient(135deg, var(--accent, var(--bs-success)), var(--accent-strong, #4ade80));
  box-shadow: 0 6px 14px var(--accent-soft, var(--tint-success));
}

.plan-card-icon {
  width: 52px;
  height: 52px;
  border-radius: 15px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  font-size: 26px;
  color: #fff;
  background: linear-gradient(135deg, var(--accent, var(--bs-primary)), var(--accent-strong, #7b93ff));
  box-shadow: 0 8px 18px var(--accent-soft, var(--tint-primary));
  margin-bottom: 14px;
}

.plan-card-name {
  font-size: 18px;
  font-weight: 700;
  margin: 0;
  color: var(--bs-heading-color, #111827);
}

.plan-card-desc {
  font-size: 12.5px;
  color: var(--bs-secondary-color);
  margin: 4px 0 0;
  min-height: 34px;
}

.price-block {
  display: flex;
  align-items: baseline;
  gap: 4px;
  margin: 14px 0 2px;
}
.price-block .plan-price-amount {
  font-size: 32px;
  font-weight: 800;
  letter-spacing: -0.02em;
  color: var(--bs-heading-color, #111827);
  line-height: 1;
}
.price-block .plan-price-period {
  font-size: 13px;
  color: var(--bs-secondary-color);
}

.save-badge {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  font-size: 11.5px;
  font-weight: 600;
  color: #15803d;
  background: var(--tint-success);
  border-radius: 999px;
  padding: 2px 9px;
}

/* subscriber + renewal mini-stats */
.plan-card-stats {
  display: flex;
  gap: 8px;
  margin: 16px 0;
}

.plan-card-stat {
  flex: 1;
  padding: 10px;
  border: 1px solid var(--bs-border-color);
  border-radius: 10px;
  background: var(--bs-secondary-bg);
  text-align: center;
}
.plan-card-stat .plan-stat-value {
  font-size: 16px;
  font-weight: 700;
  color: var(--bs-heading-color, #111827);
}
.plan-card-stat .plan-stat-label {
  font-size: 10.5px;
  color: var(--bs-secondary-color);
  text-transform: uppercase;
  letter-spacing: 0.04em;
}

.renew-note {
  height: 6px;
  border-radius: 999px;
  background: var(--bs-secondary-bg);
  overflow: hidden;
  margin-top: 6px;
}
.renew-note > span {
  display: block;
  height: 100%;
  border-radius: 999px;
  background: linear-gradient(90deg, var(--accent, var(--bs-primary)), var(--accent-strong, #7b93ff));
}

/* feature checklist */
.feature-row {
  list-style: none;
  padding: 0;
  margin: 4px 0 18px;
}

.feature-row li {
  display: flex;
  align-items: center;
  gap: 9px;
  padding: 6px 0;
  font-size: 13px;
  color: var(--bs-body-color, #374151);
}
.feature-row li i {
  font-size: 16px;
  flex: 0 0 16px;
}
.feature-row li.off {
  color: var(--bs-secondary-color);
}
.feature-row li.off .feature-text {
  text-decoration: line-through;
  opacity: 0.8;
}

.feature-row .feature-yes {
  color: var(--bs-success);
}

.feature-row .feature-no {
  color: #cbd5e1;
}

/* limits chips */
.limit-list {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 8px;
  padding: 12px;
  border: 1px dashed var(--bs-border-color);
  border-radius: 12px;
  margin-bottom: 18px;
}

.limit-row {
  display: flex;
  flex-direction: column;
}
.limit-row .limit-value {
  font-size: 14px;
  font-weight: 700;
  color: var(--bs-heading-color, #111827);
}
.limit-row .limit-label {
  font-size: 11px;
  color: var(--bs-secondary-color);
}

.plan-card-cta {
  margin-top: auto;
}

/* accent variants */
.plan-accent-slate {
  --accent: #475569;
  --accent-strong: #94a3b8;
  --accent-soft: rgba(71, 85, 105, .28);
}

.plan-accent-primary {
  --accent: var(--bs-primary);
  --accent-strong: #7b93ff;
  --accent-soft: var(--tint-primary);
}

.plan-accent-success {
  --accent: var(--bs-success);
  --accent-strong: #4ade80;
  --accent-soft: var(--tint-success);
}

.plan-accent-purple {
  --accent: var(--accent-purple);
  --accent-strong: #a78bfa;
  --accent-soft: var(--tint-purple);
}

.plan-accent-amber {
  --accent: var(--bs-warning);
  --accent-strong: #fbbf24;
  --accent-soft: var(--tint-warning);
}

.plan-accent-rose {
  --accent: var(--bs-danger);
  --accent-strong: #fb7185;
  --accent-soft: var(--tint-danger);
}

/* ============================================================
   POPULARITY INSIGHTS
   ============================================================ */
.insight-tile {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 12px 0;
  border-bottom: 1px solid var(--bs-border-color);
}
.insight-tile:last-child {
  border-bottom: 0;
}

.insight-tile-icon {
  width: 40px;
  height: 40px;
  flex: 0 0 40px;
  border-radius: 12px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  font-size: 19px;
  background: var(--accent-soft, var(--tint-primary));
  color: var(--accent, var(--bs-primary));
}

.plan-icon-primary {
  --accent: var(--bs-primary);
  --accent-soft: var(--tint-primary);
}

.plan-icon-success {
  --accent: var(--bs-success);
  --accent-soft: var(--tint-success);
}

.plan-icon-purple {
  --accent: var(--accent-purple);
  --accent-soft: var(--tint-purple);
}

.plan-icon-amber {
  --accent: var(--bs-warning);
  --accent-soft: var(--tint-warning);
}

.plan-icon-rose {
  --accent: var(--bs-danger);
  --accent-soft: var(--tint-danger);
}

.insight-tile-body {
  min-width: 0;
  flex: 1;
}

.insight-tile-body p {
  margin: 0;
  font-size: 13.5px;
  font-weight: 600;
  color: var(--bs-heading-color, #111827);
}

.insight-tile-body span {
  font-size: 11.5px;
  color: var(--bs-secondary-color);
}

.insight-tile-value {
  font-size: 15px;
  font-weight: 700;
}

/* ============================================================
   COMPARISON MATRIX (sticky first column)
   ============================================================ */
.compare-table {
  overflow-x: auto;
}

.compare-table table {
  min-width: 720px;
  margin: 0;
}

.compare-table th,
.compare-table td {
  text-align: center;
  padding: 12px 14px;
  border-bottom: 1px solid var(--bs-border-color);
  white-space: nowrap;
}

.compare-table thead th {
  font-size: 13px;
  font-weight: 700;
}

.compare-table tbody th,
.compare-table tbody td:first-child {
  position: sticky;
  left: 0;
  z-index: 2;
  text-align: left;
  background: var(--bs-body-bg);
  font-weight: 500;
  font-size: 13px;
}

.compare-table .compare-yes {
  color: var(--bs-success);
  font-size: 18px;
}

.compare-table .compare-no {
  color: #cbd5e1;
  font-size: 16px;
}

/* ============================================================
   PROMOTIONS + SIDEBAR WIDGETS
   ============================================================ */
.promo-banner {
  display: flex;
  align-items: center;
  gap: 14px;
  padding: 16px;
  border: 1px solid var(--bs-border-color);
  border-radius: 14px;
  background: var(--bs-body-bg);
  height: 100%;
  transition: transform var(--transition), box-shadow var(--transition);
}
.promo-banner:hover {
  transform: translateY(-3px);
  box-shadow: var(--shadow);
}

.promo-banner-icon {
  width: 46px;
  height: 46px;
  flex: 0 0 46px;
  border-radius: 13px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  font-size: 22px;
