/* ============================================================
   Membership Add-ons — Feature Marketplace
   Marketplace cards + bundles for the add-ons page. Reuses the
   mp-* tokens/components (insights, comparison, widgets) — the
   page wraps in `.mp-page` so those variables resolve — and adds
   only the marketplace-specific card and bundle styles here.
   Never touches sidebar / header / shell.
   ============================================================ */
/* ============================================================
   MARKETPLACE CARD
   ============================================================ */
.addon-card {
  position: relative;
  display: flex;
  flex-direction: column;
  height: 100%;
  padding: 18px;
  border: 1px solid var(--bs-border-color);
  border-radius: 16px;
  background: linear-gradient(160deg, var(--accent-soft, var(--tint-primary)), transparent 30%), var(--bs-body-bg);
  box-shadow: var(--shadow);
  transition: transform var(--transition), box-shadow var(--transition), border-color var(--transition);
  width: 100%;
}
.addon-card:hover {
  transform: translateY(-5px);
  box-shadow: var(--shadow-lift);
  border-color: transparent;
}

.addon-card:has(.dropdown-menu.show) {
  z-index: 5;
}

.addon-card .dropdown-menu {
  z-index: 1050;
}

.addon-card-top {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 10px;
  margin-bottom: 12px;
}

.addon-card-icon {
  width: 46px;
  height: 46px;
  flex: 0 0 46px;
  border-radius: 14px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  font-size: 23px;
  color: #fff;
  background: linear-gradient(135deg, var(--accent, var(--bs-primary)), var(--accent-strong, #7b93ff));
  box-shadow: 0 6px 16px var(--accent-soft, var(--tint-primary));
}

.addon-card-popular {
  display: inline-flex;
  align-items: center;
  gap: 3px;
  padding: 3px 9px;
  border-radius: 999px;
  font-size: 10.5px;
  font-weight: 700;
  color: #b45309;
  background: var(--tint-warning);
}

.addon-card-name {
  font-size: 15px;
  font-weight: 700;
  margin: 0;
  color: var(--bs-heading-color, #111827);
  display: flex;
  align-items: center;
  gap: 6px;
}

.addon-card-desc {
  font-size: 12.5px;
  color: var(--bs-secondary-color);
  margin: 5px 0 12px;
  min-height: 36px;
}

.addon-card-tags {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  margin-bottom: 12px;
}

.addon-card-meta {
  display: flex;
  align-items: center;
  gap: 6px 14px;
  flex-wrap: wrap;
  font-size: 11.5px;
  color: var(--bs-secondary-color);
  margin-bottom: 14px;
}
.addon-card-meta span {
  display: inline-flex;
  align-items: center;
  gap: 4px;
}
.addon-card-meta i {
  font-size: 14px;
}

.addon-card-price {
  display: flex;
  align-items: baseline;
  gap: 4px;
  margin-top: auto;
  padding-top: 12px;
  border-top: 1px solid var(--bs-border-color);
}
.addon-card-price .price-amount {
  font-size: 20px;
  font-weight: 800;
  letter-spacing: -0.02em;
  color: var(--bs-heading-color, #111827);
  line-height: 1;
}
.addon-card-price .price-period {
  font-size: 11.5px;
  color: var(--bs-secondary-color);
}
.addon-card-price .price-free {
  font-size: 18px;
  font-weight: 800;
  color: var(--bs-success);
}

.addon-card-cta {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-top: 12px;
}

/* active / installed ribbon corner */
.addon-card.is-installed::before {
  content: "";
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 3px;
  border-radius: 16px 16px 0 0;
  background: linear-gradient(90deg, var(--bs-success), #4ade80);
}

/* ============================================================
   FEATURE BUNDLES
   ============================================================ */
.bundle-card {
  position: relative;
  display: flex;
  flex-direction: column;
  height: 100%;
  padding: 20px;
  border: 1px solid var(--bs-border-color);
  border-radius: 16px;
  background: linear-gradient(135deg, var(--accent-soft, var(--tint-primary)), transparent 45%), var(--bs-body-bg);
  box-shadow: var(--shadow);
  transition: transform var(--transition), box-shadow var(--transition);
  width: 100%;
}
.bundle-card:hover {
  transform: translateY(-4px);
  box-shadow: var(--shadow-lift);
}

.bundle-head {
  display: flex;
  align-items: center;
  gap: 12px;
  margin-bottom: 14px;
}

.bundle-icon {
  width: 48px;
  height: 48px;
  flex: 0 0 48px;
  border-radius: 14px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  font-size: 24px;
  color: #fff;
  background: linear-gradient(135deg, var(--accent, var(--bs-primary)), var(--accent-strong, #7b93ff));
  box-shadow: 0 8px 18px var(--accent-soft, var(--tint-primary));
}

.bundle-name {
  font-size: 16px;
  font-weight: 700;
  margin: 0;
  color: var(--bs-heading-color, #111827);
}

.bundle-sub {
  font-size: 12px;
  color: var(--bs-secondary-color);
}

.bundle-features {
  list-style: none;
  padding: 0;
  margin: 0 0 14px;
}
.bundle-features li {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 5px 0;
  font-size: 13px;
  color: var(--bs-body-color, #374151);
}
.bundle-features li i {
  font-size: 15px;
  color: var(--bs-success);
}

.bundle-foot {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-top: auto;
  padding-top: 14px;
  border-top: 1px solid var(--bs-border-color);
}
@media (max-width: 575.98px) {
  .bundle-foot {
    flex-direction: column;
    align-items: start;
    gap: 12px;
  }
}

.bundle-discount {
  font-size: 20px;
  font-weight: 800;
  color: var(--accent, var(--bs-primary));
  line-height: 1;
}

.bundle-discount small {
  display: block;
  font-size: 11px;
  font-weight: 500;
  color: var(--bs-secondary-color);
}

/* ============================================================
   DARK MODE  (tokens come from .mp-page dark overrides)
   ============================================================ */
[data-bs-theme=dark] .addon-card-name,
[data-bs-theme=dark] .addon-card-price .price-amount,
[data-bs-theme=dark] .bundle-name {
  color: #e9edf5;
}

/* ============================================================
   Class Time Table — Premium Academic Scheduling Workspace
   Adds the scheduling grid, sticky day headers, premium schedule
   cards and hover quick-actions on top of Bootstrap + the shared
   card / toolbar chrome. Reuses the existing bg-transparent-*
   colour system as the subject colour indicator — never touches
   the palette, sidebar, header or page shell.
   ============================================================ */
@media (prefers-reduced-motion: reduce) {
  .timetable-page * {
    transition: none !important;
    animation: none !important;
  }
}
/* ---- Academic header facts ---- */
.stat-fact {
  display: flex;
  align-items: center;
  gap: 10px;
}

.stat-fact-icon {
  width: 38px;
  height: 38px;
  border-radius: 10px;
  flex-shrink: 0;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  font-size: 19px;
}

.stat-fact-value {
  font-weight: 600;
  line-height: 1.1;
  color: var(--bs-heading-color, #1f2937);
}

.stat-fact-label {
  font-size: 0.74rem;
  color: var(--bs-secondary-color);
}

/* ---- Scheduling grid ---- */
.timetable-grid {
  display: flex;
  gap: 14px;
  overflow-x: auto;
  padding-bottom: 8px;
}

.timetable-day {
  flex: 1 0 240px;
  min-width: 240px;
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.timetable-day-head {
  position: sticky;
  top: 0;
  z-index: 3;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 10px 14px;
  border-radius: var(--radius-sm);
  background: var(--bs-tertiary-bg, #f7f8fc);
  border: 1px solid var(--bs-border-color);
  font-weight: 600;
  color: var(--bs-heading-color, #1f2937);
}

.timetable-day-head .timetable-day-count {
  font-size: 0.72rem;
  font-weight: 600;
  color: var(--bs-secondary-color);
  background: var(--bs-card-bg, #fff);
  border-radius: 999px;
  padding: 2px 9px;
}

/* ---- Premium schedule card (colour comes from the reused bg-transparent-* class) ---- */
.timetable-slot {
  position: relative;
  border-radius: var(--radius-sm);
  padding: 14px;
  transition: transform var(--transition), box-shadow var(--transition);
}

.timetable-slot:hover {
  transform: translateY(-3px);
  box-shadow: 0 0.5rem 1.25rem rgba(17, 24, 39, 0.12);
}

.timetable-slot:focus-within {
  box-shadow: 0 0 0 2px rgba(var(--bs-primary-rgb), 0.3);
}

.timetable-slot-icon {
  width: 34px;
  height: 34px;
  border-radius: 9px;
  flex-shrink: 0;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  font-size: 18px;
  background: var(--bs-card-bg, #fff);
}

.timetable-slot-time {
  font-size: 0.74rem;
  font-weight: 600;
  color: var(--bs-heading-color, #1f2937);
}

.timetable-slot-sub {
  font-weight: 600;
  color: var(--bs-heading-color, #1f2937);
  line-height: 1.2;
}

.timetable-slot-meta {
  font-size: 0.74rem;
  color: var(--bs-secondary-color);
}

/* hover / keyboard quick actions */
.toolbar-actions {
  position: absolute;
  top: 10px;
  right: 10px;
  opacity: 0;
  transform: translateY(-4px);
  transition: opacity var(--transition), transform var(--transition);
}

.timetable-slot:hover .toolbar-actions,
.timetable-slot:focus-within .toolbar-actions {
  opacity: 1;
  transform: none;
}

@media (hover: none) {
  .toolbar-actions {
    opacity: 1;
    transform: none;
  }
}
/* teacher chip on a soft card sits on white for contrast */
.timetable-slot-teacher {
  background: var(--bs-card-bg, #fff);
  border-radius: 8px;
}

/* ---- Special period cards ---- */
.timetable-special {
  border: 1px dashed var(--bs-border-color);
  border-radius: var(--radius-sm);
  transition: box-shadow var(--transition), transform var(--transition);
}

.timetable-special:hover {
  transform: translateY(-2px);
  box-shadow: 0 0.35rem 0.9rem rgba(17, 24, 39, 0.08);
}

/* ---- Empty state ---- */
.empty-state-art {
  width: 116px;
  height: 116px;
  margin: 0 auto 18px;
  border-radius: 26px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 52px;
  color: var(--bs-primary);
  background: rgba(var(--bs-primary-rgb), 0.1);
}

/* ---- List view: stack days as full-width rows ---- */
.timetable-grid.timetable-list {
  flex-direction: column;
}

.timetable-grid.timetable-list .timetable-day {
  min-width: 100%;
}

.timetable-grid.timetable-list .timetable-day-head {
  position: static;
}

/* ---- Responsive: stack days as full-width schedule cards on mobile ---- */
@media (max-width: 767.98px) {
  .timetable-grid {
    flex-direction: column;
  }
  .timetable-day {
    min-width: 100%;
  }
  .timetable-day-head {
    position: static;
  }
}
/* ============================================================
   Curriculum — Premium Academic Curriculum Management Workspace
   Three-panel layout helpers. Everything visual that Bootstrap
   utilities + existing PreSkool components already cover is NOT
   redefined here — this partial only adds the sticky panels,
   the nav rail, the animated progress and a couple of tiles.
   ============================================================ */
.curriculum-page {
  /* ---- Sticky side panels (desktop only) ---- */
}
@media (min-width: 992px) {
  .curriculum-page .curriculum-sticky {
    position: sticky;
    top: 1rem;
    max-height: calc(100vh - 9rem);
    overflow-y: auto;
    overflow-x: hidden;
  }
}
.curriculum-page {
  /* thin, unobtrusive scrollbar for the rails */
}
.curriculum-page .curriculum-sticky::-webkit-scrollbar {
  width: 6px;
}
.curriculum-page .curriculum-sticky::-webkit-scrollbar-thumb {
  background: rgba(0, 0, 0, 0.12);
  border-radius: 20px;
}
.curriculum-page {
  /* ---- Left navigation rail ---- */
}
.curriculum-page .curriculum-nav-title {
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.04em;
  text-transform: uppercase;
}
.curriculum-page .curriculum-nav .list-group-item {
  border: 0;
  padding: 0.45rem 0.65rem;
  border-radius: 0.5rem;
  font-size: 13px;
  cursor: pointer;
  transition: background-color 0.2s ease, color 0.2s ease;
}
.curriculum-page .curriculum-nav .list-group-item .curriculum-nav-icon {
  width: 18px;
  text-align: center;
}
.curriculum-page {
  /* ---- Explorer cards ---- */
}
.curriculum-page .curriculum-card {
  cursor: pointer;
  transition: transform 0.2s ease, box-shadow 0.2s ease, border-color 0.2s ease;
}
.curriculum-page .curriculum-card.active {
  border-color: var(--bs-primary);
  box-shadow: 0 0 0 1px var(--bs-primary);
}
.curriculum-page .curriculum-card .curriculum-card-extra {
  transition: max-height 0.25s ease, opacity 0.2s ease;
}
.curriculum-page {
  /* Grid / list view of the explorer */
}
.curriculum-page .curriculum-explorer.is-list .col-cur {
  width: 100%;
  flex: 0 0 100%;
  max-width: 100%;
}
.curriculum-page .curriculum-explorer.is-list .curriculum-card .card-body {
  display: flex;
  align-items: center;
  gap: 1rem;
  flex-wrap: wrap;
}
.curriculum-page .curriculum-explorer.is-list .curriculum-card .curriculum-card-extra {
  display: none !important;
}
.curriculum-page {
  /* ---- Animated progress ---- */
}
.curriculum-page .curriculum-progress .progress-bar {
  transition: width 1s cubic-bezier(0.25, 0.8, 0.25, 1);
}
.curriculum-page {
  /* ---- Resource tile ---- */
}
.curriculum-page .resource-row {
  transition: border-color 0.2s ease, background-color 0.2s ease;
}
.curriculum-page .resource-row:hover {
  border-color: var(--bs-primary) !important;
}
.curriculum-page .resource-row .resource-actions {
  opacity: 0;
  transition: opacity 0.2s ease;
}
.curriculum-page .resource-row:hover .resource-actions {
  opacity: 1;
}
@media (max-width: 767.98px) {
  .curriculum-page .resource-row .resource-actions {
    opacity: 1;
  }
}
.curriculum-page {
  /* ---- Structure accordion progress ---- */
}
.curriculum-page .structure-row .accordion-button {
  font-size: 13px;
  font-weight: 600;
}
.curriculum-page .structure-row .accordion-button:not(.collapsed) {
  background: var(--bs-primary-bg-subtle, rgba(63, 81, 181, 0.08));
}
.curriculum-page .structure-row .structure-meta {
  font-size: 12px;
}
.curriculum-page {
  /* ---- Empty state ---- */
}
.curriculum-page .curriculum-empty {
  padding: 3rem 1rem;
}
.curriculum-page .curriculum-empty .curriculum-empty-icon {
  width: 84px;
  height: 84px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border-radius: 50%;
}

/* ---- Dark theme niceties ---- */
[data-theme=dark] .curriculum-page .curriculum-sticky::-webkit-scrollbar-thumb {
  background: rgba(255, 255, 255, 0.16);
}

