/* ===== parent-portal.css ===== */
/* ============================================================
   PARENT PORTAL — 2026 SaaS executive experience (.parent-portal)
   Inspired by Linear / Stripe / Notion / Vercel.
   Scoped & self-contained. Does not touch sidebar/header/global card.
   ============================================================ */
.parent-portal {
  color: var(--bs-body-color);
  font-feature-settings: "tnum" 1, "ss01" 1;
}

/* ...but a section that merely opens a row's column is NOT the top of the page —
   without this it collapses to 4px and the row collides with the block above
   (e.g. Assignment Board → Fee Timeline). Restore the normal rhythm. */
.parent-portal .row > [class*=col-] > .portal-section:first-child {
  margin-top: 26px;
}

.parent-live-flag {
  gap: 5px;
  font-size: 10.5px;
  font-weight: 700;
  letter-spacing: 0.04em;
  color: var(--bs-danger);
}

.parent-live-flag::before {
  content: "";
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: var(--bs-danger);
  box-shadow: 0 0 0 0 rgba(225, 29, 72, 0.5);
  animation: px-pulse 1.4s infinite;
}

@keyframes px-pulse {
  0% {
    box-shadow: 0 0 0 0 rgba(225, 29, 72, 0.5);
  }
  100% {
    box-shadow: 0 0 0 6px rgba(225, 29, 72, 0);
  }
}
/* ---------- COMMAND HERO ---------- */
.portal-command-bar {
  display: grid;
  grid-template-columns: 1.25fr 1fr;
  gap: 16px;
}

.portal-command-bar-left {
  border: 1px solid var(--bs-border-color);
  border-radius: var(--radius);
  background: radial-gradient(120% 140% at 100% 0, rgba(61, 94, 225, 0.06), transparent 46%), linear-gradient(180deg, var(--bs-body-bg), var(--bs-secondary-bg));
  padding: 20px;
}

.parent-identity {
  gap: 14px;
}

.parent-identity-avatar {
  position: relative;
  width: 58px;
  height: 58px;
}

.parent-identity-avatar img {
  width: 100%;
  height: 100%;
  border-radius: 16px;
  object-fit: cover;
}

.parent-identity-verified {
  position: absolute;
  right: -4px;
  bottom: -4px;
  width: 20px;
  height: 20px;
  border-radius: 50%;
  background: var(--bs-primary);
  color: #fff;
  display: grid;
  place-items: center;
  font-size: 11px;
  border: 2px solid var(--bs-body-bg);
}

.parent-identity-head {
  font-size: 11px;
  color: var(--bs-secondary-color);
}

.parent-identity-name {
  font-size: 20px;
  font-weight: 750;
  letter-spacing: -0.02em;
  color: var(--bs-emphasis-color);
  line-height: 1.1;
}

.parent-identity-meta {
  gap: 6px;
  margin-top: 5px;
}

/* active-child context strip (bridges the header switcher to the hero) */
.child-context {
  gap: 14px;
  margin-top: 16px;
  padding: 12px 14px;
  border: 1px solid var(--bs-border-color);
  border-radius: var(--radius-sm);
  background: var(--bs-tertiary-bg);
}

.child-context-name {
  gap: 10px;
  min-width: 0;
}

.child-context-avatar {
  position: relative;
}

.child-context-avatar img {
  width: 38px;
  height: 38px;
  border-radius: 11px;
  object-fit: cover;
  box-shadow: 0 0 0 2px var(--bs-body-bg), 0 0 0 3px var(--bs-primary);
}

.child-context-status-dot {
  position: absolute;
  right: -2px;
  bottom: -2px;
  width: 11px;
  height: 11px;
  border-radius: 50%;
  background: var(--bs-success);
  border: 2px solid var(--bs-tertiary-bg);
}

.child-context-id {
  min-width: 0;
}

.child-context-title {
  font-size: 12px;
  color: var(--bs-secondary-color);
  line-height: 1.25;
}

.child-context-title b {
  font-size: 14px;
  font-weight: 700;
  color: var(--bs-emphasis-color);
}

.child-context-subtitle {
  font-size: 11px;
  color: var(--bs-tertiary-color);
}

.child-context-facts {
  gap: 8px;
}

.child-context-fact {
  display: inline-flex;
  gap: 8px;
  padding: 6px 11px;
  border: 1px solid var(--bs-border-color);
  border-radius: var(--radius-xs);
  background: var(--bs-body-bg);
}

.child-context-fact > i {
  font-size: 16px;
  color: var(--bs-primary);
}

.child-context-fact > span {
  display: flex;
  flex-direction: column;
  line-height: 1.2;
}

.child-context-fact-value {
  font-size: 12px;
  font-weight: 650;
  color: var(--bs-emphasis-color);
  white-space: nowrap;
}

.child-context-fact-label {
  font-size: 10px;
  color: var(--bs-tertiary-color);
}

@media (max-width: 991.98px) {
  .child-context-facts {
    width: 100%;
  }
  .child-context-fact {
    flex: 1;
  }
}
/* child switcher cards */
.switch-control {
  flex: 1;
  min-width: 150px;
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 10px;
  border: 1px solid var(--bs-border-color);
  border-radius: var(--radius-sm);
  background: var(--bs-body-bg);
  cursor: pointer;
  transition: all var(--transition);
  text-align: left;
}

.switch-control:hover {
  transform: translateY(-2px);
  box-shadow: var(--shadow-lift);
}

.switch-control img {
  width: 40px;
  height: 40px;
  border-radius: 11px;
  object-fit: cover;
}

.switch-control-name {
  font-size: 13px;
  font-weight: 650;
  color: var(--bs-emphasis-color);
  line-height: 1.15;
  padding-right: 4px;
}

.switch-control-class {
  font-size: 11px;
  color: var(--bs-secondary-color);
}

.switch-control.active {
  border-color: transparent;
  background: linear-gradient(135deg, var(--bs-emphasis-color), #2b2f3a);
  color: #fff;
}

.switch-control.active .switch-control-name {
  color: #fff;
}

.switch-control.active .switch-control-class {
  color: rgba(255, 255, 255, 0.65);
}

.switch-control.active img {
  box-shadow: 0 0 0 2px rgba(255, 255, 255, 0.4);
}

/* --- Compact child switcher in the page-header / breadcrumb bar --- */
.child-switcher {
  display: flex;
  align-items: center;
  gap: 10px;
}
@media (max-width: 575.98px) {
  .child-switcher {
    flex-wrap: wrap;
  }
}

.child-switcher-label {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--bs-secondary-color);
  white-space: nowrap;
}

.child-switcher-label i {
  font-size: 15px;
  color: var(--bs-tertiary-color);
}

.child-switcher-option {
  display: flex;
  align-items: center;
  gap: 4px;
  padding: 4px;
  border: 1px solid var(--bs-border-color);
  border-radius: 999px;
  background: var(--bs-tertiary-bg);
}

.switch-control-sm {
  flex: 0 0 auto;
  min-width: 0;
  gap: 8px;
  padding: 4px 12px 4px 4px;
  border: 1px solid transparent;
  border-radius: 999px;
  background: transparent;
}

.switch-control-sm:hover {
  transform: none;
  box-shadow: none;
  background: var(--bs-body-bg);
}

.switch-control-sm img {
  width: 30px;
  height: 30px;
  border-radius: 999px;
}

.switch-control-sm .switch-control-name {
