/* ============================================================
   Membership Transactions — Billing & Transaction Management
   Page-scoped styles for membership-transactions.html (.mt-* / .pay-badge).
   Relocated here from _parent-portal.scss (migration artifact).
   ============================================================ */
:root {
  --mt-line: #e9edf5;
  --mt-soft: #f6f7fb;
  --mt-ink: #1b2559;
  --mt-mut: var(--bs-secondary-color);
}

[data-bs-theme=dark] {
  --mt-line: rgba(255,255,255,.09);
  --mt-soft: rgba(255,255,255,.04);
  --mt-ink: #e6e9f5;
  --mt-mut: #9aa3b8;
}

/* ---------- Financial insights strip (KPI mini widgets) ---------- */
.mt-kpis {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 14px;
}

.mt-kpi {
  position: relative;
  background: var(--bs-card-bg, var(--bs-body-bg));
  border: 1px solid var(--mt-line);
  border-radius: 14px;
  padding: 14px 16px;
  display: flex;
  flex-direction: column;
  gap: 8px;
  overflow: hidden;
  transition: transform 0.18s ease, box-shadow 0.18s ease, border-color 0.18s ease;
}

.mt-kpi:hover {
  transform: translateY(-3px);
  box-shadow: 0 12px 26px rgba(30, 41, 89, 0.09);
  border-color: transparent;
}

.mt-kpi-top {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
}

.mt-kpi-lbl {
  font-size: 12px;
  font-weight: 600;
  color: var(--mt-mut);
  letter-spacing: 0.01em;
}

.mt-kpi-ic {
  width: 30px;
  height: 30px;
  border-radius: 9px;
  display: grid;
  place-items: center;
  font-size: 16px;
  flex: none;
}

.mt-kpi-val {
  font-size: 20px;
  font-weight: 700;
  line-height: 1.1;
  color: var(--mt-ink);
  margin: 0;
}

.mt-kpi-foot {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  font-size: 11.5px;
  font-weight: 600;
}

.mt-trend {
  display: inline-flex;
  align-items: center;
  gap: 3px;
}

.mt-trend.up {
  color: #16b364;
}

.mt-trend.down {
  color: #f04438;
}

.mt-trend.flat {
