}

.aix-eyebrow {
  display: block;
  margin: 0 0 2px;
  font-size: 11px;
  font-weight: 500;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--bs-primary);
}

.aix-label {
  display: block;
  margin: 0;
  font-size: 11px;
  font-weight: 500;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  color: var(--bs-secondary-color);
}

/* ============================================================
   3. STATUS INDICATORS + AI BADGES
   ============================================================ */
.aix-status {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 5px 12px;
  border-radius: 999px;
  font-size: 12px;
  font-weight: 500;
  background: var(--bs-secondary-bg);
  color: var(--bs-secondary-color);
}

.aix-dot {
  position: relative;
  display: inline-block;
  width: 8px;
  height: 8px;
  flex-shrink: 0;
  border-radius: 50%;
  background: currentColor;
}
.aix-dot.aix-dot-live::after {
  content: "";
  position: absolute;
  inset: 0;
  border-radius: 50%;
  background: inherit;
  animation: aix-pulse 1.8s ease-out infinite;
}

@keyframes aix-pulse {
  from {
    opacity: 0.6;
    scale: 1;
  }
  to {
    opacity: 0;
    scale: 2.8;
  }
}
.aix-badge, .aix-sev {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 4px 10px;
  border-radius: 999px;
  font-size: 11px;
  font-weight: 500;
  background: var(--bs-secondary-bg);
  color: var(--bs-secondary-color);
  white-space: nowrap;
}
.aix-badge.is-ai, .is-ai.aix-sev {
  background: var(--tint-primary);
  color: var(--bs-primary);
}
.aix-badge.is-critical, .is-critical.aix-sev {
  background: #FDE9ED;
  color: #E82646;
}
.aix-badge.is-high, .is-high.aix-sev {
  background: #FEF8EA;
  color: rgb(162.6, 124.3820512821, 0);
}
.aix-badge.is-medium, .is-medium.aix-sev {
  background: #E7F1FC;
  color: #0F65CD;
}
.aix-badge.is-positive, .is-positive.aix-sev {
  background: #E8F9E8;
  color: #1ABE17;
}

/* severity pill with a leading dot */
.aix-sev::before {
  content: "";
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: currentColor;
  flex-shrink: 0;
}

/* ============================================================
   4. CONFIDENCE + PROGRESS INDICATORS
   ============================================================ */
.aix-conf {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  min-width: 116px;
}

.aix-conf-track {
  position: relative;
  flex: 1 1 auto;
  height: 5px;
  border-radius: 999px;
  background: var(--bs-tertiary-bg);
  overflow: hidden;
}

.aix-conf-fill {
  position: absolute;
  inset: 0 auto 0 0;
  width: calc(var(--p, 0) * 1%);
  border-radius: inherit;
  background: linear-gradient(90deg, var(--bs-primary), #6FCCD8);
}

.aix-conf-val {
  font-size: 12px;
  font-weight: 600;
  color: var(--bs-emphasis-color);
  font-variant-numeric: tabular-nums;
}

/* circular confidence badge */
.aix-conf-ring {
  position: relative;
  display: grid;
  place-items: center;
  width: 56px;
  height: 56px;
  flex-shrink: 0;
  border-radius: 50%;
  background: conic-gradient(var(--bs-primary) calc(var(--p, 0) * 1%), var(--bs-tertiary-bg) 0);
}
.aix-conf-ring::before {
  content: "";
  position: absolute;
  inset: 5px;
  border-radius: 50%;
  background: var(--bs-body-bg);
}
.aix-conf-ring.aix-conf-ring-lg {
  width: 92px;
  height: 92px;
}
.aix-conf-ring.aix-conf-ring-lg::before {
  inset: 8px;
}

.aix-conf-ring-in {
  position: relative;
  font-size: 13px;
  font-weight: 700;
  color: var(--bs-emphasis-color);
  font-variant-numeric: tabular-nums;
}

.aix-prog {
  position: relative;
  height: 6px;
  border-radius: 999px;
  background: var(--bs-tertiary-bg);
  overflow: hidden;
}

.aix-prog-fill {
  position: absolute;
  inset: 0 auto 0 0;
  width: calc(var(--p, 0) * 1%);
  border-radius: inherit;
  background: var(--bs-primary);
  transition: width var(--transition);
}
.aix-prog-fill.is-critical {
  background: #E82646;
}
.aix-prog-fill.is-high {
  background: #EAB300;
}
.aix-prog-fill.is-medium {
  background: #0F65CD;
}
.aix-prog-fill.is-positive {
  background: #1ABE17;
}

/* ============================================================
   5. HERO WORKSPACE
   ============================================================ */
.aix-hero {
  position: relative;
  border: 1px solid var(--bs-border-color);
  border-radius: var(--radius);
  background: radial-gradient(90% 120% at 88% 0%, rgba(61, 94, 225, 0.1) 0%, rgba(255, 255, 255, 0) 60%), radial-gradient(70% 90% at 0% 100%, rgba(111, 204, 216, 0.1) 0%, rgba(255, 255, 255, 0) 60%), var(--bs-body-bg);
  box-shadow: var(--shadow);
  overflow: hidden;
}

.aix-hero-body {
  position: relative;
  padding: 24px;
}
@media (min-width: 1400px) {
  .aix-hero-body {
    padding: 28px 32px;
  }
}
@media (max-width: 575.98px) {
  .aix-hero-body {
    padding: 20px;
  }
}

.aix-hero-title {
  margin: 0 0 8px;
  font-size: 28px;
  font-weight: 700;
  line-height: 1.2;
  letter-spacing: -0.02em;
  color: var(--bs-emphasis-color);
}
@media (max-width: 991.98px) {
  .aix-hero-title {
    font-size: 23px;
  }
}

/* stat rail — figures, not KPI cards: no boxes, no icons, hairline dividers */
.aix-hero-rail {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 18px;
  padding-top: 18px;
  margin-top: 18px;
  border-top: 1px solid var(--bs-border-color);
}
@media (max-width: 767.98px) {
  .aix-hero-rail {
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 20px;
  }
}

.aix-hero-stat {
  min-width: 0;
}
.aix-hero-stat + .aix-hero-stat {
  padding-left: 18px;
  border-left: 1px solid var(--bs-border-color);
}
@media (max-width: 767.98px) {
  .aix-hero-stat + .aix-hero-stat {
    padding-left: 0;
    border-left: 0;
  }
}

.aix-hero-val {
  display: flex;
  align-items: baseline;
  gap: 5px;
  margin: 2px 0 0;
  font-size: 21px;
  font-weight: 700;
  line-height: 1.2;
  color: var(--bs-emphasis-color);
}
.aix-hero-val small {
  font-size: 12px;
  font-weight: 400;
  color: var(--bs-secondary-color);
}

/* illustration column */
.aix-hero-art {
  position: relative;
  display: grid;
  place-items: center;
  min-height: 196px;
  height: 100%;
  border-radius: var(--radius);
  background: linear-gradient(160deg, var(--tint-primary) 0%, var(--bs-body-bg) 70%);
  border: 1px solid var(--bs-border-color);
  overflow: hidden;
}

.aix-hero-art-core {
  position: relative;
  display: grid;
  place-items: center;
  width: 78px;
  height: 78px;
  border-radius: 50%;
  background: var(--bs-body-bg);
  box-shadow: var(--aix-glow);
  color: var(--bs-primary);
  font-size: 32px;
  z-index: 1;
}

/* concentric scanning rings behind the core */
.aix-hero-art-ring {
  position: absolute;
  border: 1px solid rgba(61, 94, 225, 0.18);
  border-radius: 50%;
}
.aix-hero-art-ring.r1 {
  width: 124px;
  height: 124px;
}
.aix-hero-art-ring.r2 {
  width: 170px;
  height: 170px;
  border-style: dashed;
  animation: aix-spin 34s linear infinite;
}
.aix-hero-art-ring.r3 {
  width: 218px;
  height: 218px;
  border-color: rgba(61, 94, 225, 0.1);
}

@keyframes aix-spin {
  to {
    rotate: 360deg;
  }
}
/* small chips that sit on the rings */
.aix-hero-chip {
  position: absolute;
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 6px 12px;
  border-radius: 999px;
  background: var(--bs-body-bg);
  border: 1px solid var(--bs-border-color);
  box-shadow: var(--shadow);
  font-size: 11px;
  font-weight: 500;
  color: var(--bs-emphasis-color);
  white-space: nowrap;
  z-index: 2;
}
.aix-hero-chip.c1 {
