  left: 3%;
}
.aix-hero-chip.c2 {
  bottom: 11%;
  right: 3%;
}
.aix-hero-chip.c3 {
  top: 11%;
  right: 5%;
}

/* ---- workflow stepper: the page's own table of contents ---- */
.aix-wf {
  padding: 16px 24px 20px;
  border-top: 1px solid var(--bs-border-color);
  background: var(--bs-secondary-bg);
}
@media (max-width: 575.98px) {
  .aix-wf {
    padding: 16px 20px;
  }
}

.aix-wf-title {
  margin-bottom: 12px;
}

.aix-wf-rail {
  display: grid;
  grid-template-columns: repeat(5, minmax(0, 1fr));
  gap: 8px;
}
@media (max-width: 1199.98px) {
  .aix-wf-rail {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }
}
@media (max-width: 575.98px) {
  .aix-wf-rail {
    grid-template-columns: minmax(0, 1fr);
  }
}

.aix-wf-step {
  position: relative;
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 10px 12px;
  border: 1px solid var(--bs-border-color);
  border-radius: var(--radius-sm);
  background: var(--bs-body-bg);
  transition: border-color var(--transition), box-shadow var(--transition);
  /* connector between stages */
}
.aix-wf-step:not(:last-child)::after {
  content: "";
  position: absolute;
  top: 50%;
  right: -8px;
  width: 8px;
  height: 8px;
  border-top: 1.5px solid var(--bs-border-color);
  border-right: 1.5px solid var(--bs-border-color);
  rotate: 45deg;
  translate: 0 -50%;
}
@media (max-width: 1199.98px) {
  .aix-wf-step:not(:last-child)::after {
    display: none;
  }
}
.aix-wf-step:hover, .aix-wf-step:focus-visible {
  border-color: var(--bs-primary);
  box-shadow: var(--shadow);
}
.aix-wf-step:hover .aix-wf-ic, .aix-wf-step:focus-visible .aix-wf-ic {
  background: var(--tint-primary);
  color: var(--bs-primary);
}

.aix-wf-ic {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 34px;
  height: 34px;
  flex-shrink: 0;
  border-radius: var(--radius-sm);
  background: var(--bs-secondary-bg);
  color: var(--bs-emphasis-color);
  font-size: 16px;
  transition: background var(--transition), color var(--transition);
}

.aix-wf-txt {
  display: flex;
  flex-direction: column;
  min-width: 0;
}

.aix-wf-step-n {
  font-size: 10px;
  font-weight: 500;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--bs-primary);
}

.aix-wf-lbl {
  font-size: 13px;
  font-weight: 600;
  line-height: 1.3;
  color: var(--bs-emphasis-color);
}

.aix-wf-sub {
  font-size: 11px;
  color: var(--bs-secondary-color);
}

/* ============================================================
   6. EXPLAINABLE AI PANEL + SIGNAL CHAIN
   ============================================================ */
.aix-explain {
  position: relative;
  height: 100%;
  border: 1px solid var(--bs-border-color);
  border-radius: var(--radius);
  background: var(--bs-body-bg);
  box-shadow: var(--shadow);
  overflow: hidden;
  transition: box-shadow var(--transition), border-color var(--transition);
}
.aix-explain:hover {
  border-color: rgba(61, 94, 225, 0.35);
  box-shadow: var(--shadow-lift);
}

/* severity reads from the top edge, so the card is scannable before it is read */
.aix-explain-accent::before {
  content: "";
  position: absolute;
  inset: 0 0 auto 0;
  height: 3px;
  z-index: 1;
  background: var(--bs-tertiary-bg);
}
.aix-explain-accent.is-critical::before {
  background: #E82646;
}
.aix-explain-accent.is-high::before {
  background: #EAB300;
}
.aix-explain-accent.is-medium::before {
  background: #0F65CD;
}

.aix-explain-head {
  display: flex;
  align-items: flex-start;
  gap: 12px;
  padding: 16px 18px;
  background: linear-gradient(180deg, var(--tint-primary) 0%, var(--bs-body-bg) 100%);
  border-bottom: 1px solid var(--bs-border-color);
}

.aix-explain-body {
  padding: 18px;
}

.aix-explain-obs {
  margin: 0 0 6px;
  font-size: 16px;
  font-weight: 600;
  line-height: 1.4;
  letter-spacing: -0.01em;
  color: var(--bs-emphasis-color);
}

/* the reasoning block — quoted, so it reads as generated text */
.aix-why {
  position: relative;
  padding: 12px 14px 12px 16px;
  border-radius: var(--radius-sm);
  background: var(--bs-secondary-bg);
  font-size: 13px;
  line-height: 1.6;
  color: var(--bs-secondary-color);
}
.aix-why::before {
  content: "";
  position: absolute;
  inset: 10px auto 10px 0;
  width: 3px;
  border-radius: 999px;
  background: var(--bs-primary);
  opacity: 0.5;
}

/* ---- supporting signals as a dense grid, not a stacked chain ----
   Four signals in two rows instead of four, which is most of the height
   the explanation card used to spend. */
.aix-sig-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 8px;
}

.aix-sig {
  display: flex;
  align-items: center;
  gap: 9px;
  min-width: 0;
  padding: 9px 10px;
  border: 1px solid var(--bs-border-color);
  border-radius: var(--radius-sm);
  background: var(--bs-body-bg);
  transition: border-color var(--transition), background var(--transition);
}
.aix-sig:hover {
  background: var(--bs-secondary-bg);
  border-color: rgba(61, 94, 225, 0.28);
}

.aix-sig-ic {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 26px;
  height: 26px;
  flex-shrink: 0;
  border-radius: 50%;
  background: var(--bs-secondary-bg);
  color: var(--bs-secondary-color);
  font-size: 13px;
}
.aix-sig-ic.is-critical {
  background: #FDE9ED;
  color: #E82646;
}
.aix-sig-ic.is-high {
  background: #FEF8EA;
  color: rgb(162.6, 124.3820512821, 0);
}
.aix-sig-ic.is-medium {
  background: #E7F1FC;
  color: #0F65CD;
}
.aix-sig-ic.is-positive {
  background: #E8F9E8;
  color: #1ABE17;
}

.aix-sig-txt {
  min-width: 0;
}

.aix-sig-lbl {
  display: block;
  font-size: 10px;
  font-weight: 500;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  color: var(--bs-secondary-color);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.aix-sig-val {
  display: block;
  font-size: 12.5px;
  font-weight: 600;
  line-height: 1.35;
  color: var(--bs-emphasis-color);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

/* the suggested action, inline rather than as its own labelled block */
.aix-act-line {
  display: flex;
  align-items: flex-start;
  gap: 9px;
  padding: 11px 12px;
  border-radius: var(--radius-sm);
  background: var(--tint-primary);
  font-size: 13px;
  line-height: 1.55;
  color: var(--bs-emphasis-color);
}

/* small confidence ring that sits in the card head */
.aix-conf-ring-sm {
  width: 44px;
  height: 44px;
}
.aix-conf-ring-sm::before {
  inset: 4px;
}
.aix-conf-ring-sm .aix-conf-ring-in {
  font-size: 11px;
}

/* supporting signals as a vertical chain with connectors */
.aix-chain {
  display: flex;
  flex-direction: column;
  gap: 0;
}

.aix-chain-step {
  position: relative;
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 9px 0;
}
.aix-chain-step:not(:last-child)::after {
  content: "";
  position: absolute;
  top: 34px;
  left: 13px;
  bottom: -4px;
  width: 1px;
  background: var(--bs-border-color);
}

.aix-chain-ic {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 28px;
  height: 28px;
  flex-shrink: 0;
  border-radius: 50%;
  background: var(--bs-secondary-bg);
  color: var(--bs-secondary-color);
  font-size: 14px;
  z-index: 1;
}
.aix-chain-ic.is-critical {
  background: #FDE9ED;
  color: #E82646;
}
.aix-chain-ic.is-high {
  background: #FEF8EA;
  color: rgb(162.6, 124.3820512821, 0);
}
.aix-chain-ic.is-medium {
  background: #E7F1FC;
  color: #0F65CD;
}

.aix-chain-txt {
  flex: 1 1 auto;
  min-width: 0;
  font-size: 13px;
  color: var(--bs-emphasis-color);
}

.aix-chain-val {
  font-size: 12px;
  font-weight: 600;
  color: var(--bs-secondary-color);
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
}

/* outcome strip at the foot of an explanation */
.aix-outcome {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 14px 20px;
  border-top: 1px solid var(--bs-border-color);
  background: var(--bs-secondary-bg);
}

/* ============================================================
   7. INSIGHT CARDS
   ============================================================ */
.aix-insight {
  position: relative;
  height: 100%;
  padding: 20px;
  border: 1px solid var(--bs-border-color);
  border-radius: var(--radius);
  background: var(--bs-body-bg);
  box-shadow: var(--shadow);
  transition: transform var(--transition), box-shadow var(--transition);
}
.aix-insight:hover {
  transform: translateY(-2px);
  box-shadow: var(--shadow-lift);
}

.aix-insight-top {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  margin-bottom: 14px;
}

.aix-insight-ic {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 38px;
  height: 38px;
  flex-shrink: 0;
  border-radius: var(--radius-sm);
  background: var(--bs-secondary-bg);
  color: var(--bs-emphasis-color);
  font-size: 18px;
}

.aix-insight-txt {
  margin: 0;
  font-size: 14px;
  line-height: 1.65;
  color: var(--bs-emphasis-color);
}
.aix-insight-txt b {
  font-weight: 600;
}

.aix-insight-foot {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  margin-top: 16px;
  padding-top: 14px;
  border-top: 1px solid var(--bs-border-color);
}

/* ============================================================
   8. RECOMMENDATION CARDS
   ============================================================ */
.aix-rec {
  position: relative;
  display: flex;
  flex-direction: column;
  height: 100%;
  border: 1px solid var(--bs-border-color);
  border-radius: var(--radius);
  background: var(--bs-body-bg);
  box-shadow: var(--shadow);
  overflow: hidden;
  transition: transform var(--transition), box-shadow var(--transition);
}
.aix-rec::before {
  content: "";
  position: absolute;
  inset: 0 0 auto 0;
  height: 3px;
  background: var(--bs-primary);
  opacity: 0;
  transition: opacity var(--transition);
}
.aix-rec:hover {
  transform: translateY(-2px);
  box-shadow: var(--shadow-lift);
}
.aix-rec:hover::before {
  opacity: 1;
}

.aix-rec-head {
  display: flex;
  align-items: flex-start;
  gap: 12px;
  padding: 16px 16px 0;
}

.aix-rec-body {
  flex: 1 1 auto;
  padding: 12px 16px 16px;
}

.aix-rec-title {
  margin: 0 0 4px;
  font-size: 15px;
  font-weight: 600;
  line-height: 1.35;
  color: var(--bs-emphasis-color);
}

/* Impact and timeline sit on one line with a hairline between them.
   This replaces a three-cell bordered grid that cost ~110px in a card
   only 300px wide. */
.aix-rec-stats {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  margin-top: 12px;
  border: 1px solid var(--bs-border-color);
  border-radius: var(--radius-sm);
  overflow: hidden;
}

.aix-rec-stat {
  display: flex;
  align-items: center;
  gap: 8px;
  min-width: 0;
  padding: 9px 11px;
  background: var(--bs-body-bg);
}
.aix-rec-stat + .aix-rec-stat {
  border-left: 1px solid var(--bs-border-color);
}
.aix-rec-stat i {
  flex-shrink: 0;
  font-size: 15px;
  color: var(--bs-secondary-color);
}

.aix-rec-stat-txt {
  min-width: 0;
}

.aix-rec-stat-lbl {
  display: block;
  font-size: 10px;
  font-weight: 500;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  color: var(--bs-secondary-color);
  white-space: nowrap;
}

.aix-rec-stat-val {
  display: block;
  font-size: 12.5px;
  font-weight: 600;
  line-height: 1.35;
  color: var(--bs-emphasis-color);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.aix-rec-foot {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 12px 16px;
  border-top: 1px solid var(--bs-border-color);
  background: var(--bs-secondary-bg);
}

/* ============================================================
   9. STUDENT INTELLIGENCE (PROFILE) CARDS
   ============================================================ */
.aix-profile {
  position: relative;
  display: grid;
  grid-template-columns: 268px minmax(0, 1fr) 232px;
  border: 1px solid var(--bs-border-color);
  border-radius: var(--radius);
  background: var(--bs-body-bg);
  box-shadow: var(--shadow);
  overflow: hidden;
  transition: box-shadow var(--transition), border-color var(--transition);
}
.aix-profile:hover {
  border-color: rgba(61, 94, 225, 0.3);
  box-shadow: var(--shadow-lift);
}
@media (max-width: 1399.98px) {
  .aix-profile {
    grid-template-columns: 248px minmax(0, 1fr);
  }
}
@media (max-width: 767.98px) {
  .aix-profile {
    grid-template-columns: minmax(0, 1fr);
  }
}

.aix-profile-media {
  display: flex;
  flex-direction: column;
  gap: 14px;
  padding: 20px;
  background: linear-gradient(180deg, var(--tint-primary) 0%, var(--bs-body-bg) 100%);
  border-right: 1px solid var(--bs-border-color);
}
@media (max-width: 767.98px) {
  .aix-profile-media {
    border-right: 0;
    border-bottom: 1px solid var(--bs-border-color);
  }
}

.aix-profile-main {
  padding: 20px;
  min-width: 0;
}

.aix-profile-side {
  display: flex;
  flex-direction: column;
  gap: 10px;
  padding: 20px;
  background: var(--bs-secondary-bg);
  border-left: 1px solid var(--bs-border-color);
}
@media (max-width: 1399.98px) {
  .aix-profile-side {
    grid-column: 1/-1;
    flex-direction: row;
    flex-wrap: wrap;
    border-left: 0;
    border-top: 1px solid var(--bs-border-color);
  }
}

.aix-profile-name {
  margin: 0;
  font-size: 17px;
  font-weight: 600;
  letter-spacing: -0.01em;
  color: var(--bs-emphasis-color);
}

/* the risk score readout */
.aix-score {
  display: flex;
  align-items: baseline;
  gap: 4px;
  font-size: 30px;
  font-weight: 700;
  line-height: 1;
  color: var(--bs-emphasis-color);
}
.aix-score small {
  font-size: 12px;
  font-weight: 400;
  color: var(--bs-secondary-color);
}

/* compact horizontal risk timeline built from bars */
.aix-mini {
  display: flex;
  align-items: flex-end;
  gap: 3px;
  height: 34px;
}

.aix-mini i {
  flex: 1 1 auto;
  min-width: 4px;
  height: calc(var(--v, 30) * 1%);
  border-radius: 2px;
  background: var(--bs-tertiary-bg);
}
.aix-mini i.is-critical {
  background: #E82646;
}
.aix-mini i.is-high {
  background: #EAB300;
}
.aix-mini i.is-medium {
  background: #0F65CD;
}
.aix-mini i.is-positive {
  background: #1ABE17;
}

/* a labelled fact row used inside profile and side panels */
.aix-fact {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 8px 0;
}
.aix-fact + .aix-fact {
  border-top: 1px solid var(--bs-border-color);
}

/* ---- case status strip ----
   The lifecycle facts of a case (age, stage, next review). Deliberately not
   built from .aix-fact: three space-between rows sitting side by side read as
   a second copy of the owners row above and leave a ragged gap between each
   label and its value. This is one enclosed bar with hairline dividers, so it
   reads as case metadata rather than as more content. */
.aix-caseline {
  display: flex;
  flex-wrap: wrap;
  align-items: stretch;
  border: 1px solid var(--bs-border-color);
  border-radius: var(--radius-sm);
  background: var(--bs-secondary-bg);
  overflow: hidden;
}

.aix-caseline-item {
  display: flex;
  align-items: center;
  gap: 10px;
  flex: 1 1 0;
  min-width: 148px;
  padding: 10px 14px;
}
.aix-caseline-item + .aix-caseline-item {
  border-left: 1px solid var(--bs-border-color);
}
.aix-caseline-item i {
  flex-shrink: 0;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 28px;
  height: 28px;
  border-radius: 50%;
  background: var(--bs-body-bg);
  border: 1px solid var(--bs-border-color);
  color: var(--bs-primary);
  font-size: 15px;
}

.aix-caseline-txt {
  display: flex;
  flex-direction: column;
  min-width: 0;
  line-height: 1.35;
}
.aix-caseline-txt span:first-child {
  font-size: 11px;
  font-weight: 500;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  color: var(--bs-secondary-color);
}
.aix-caseline-txt span:last-child {
  font-size: 13px;
  font-weight: 500;
  color: var(--bs-emphasis-color);
}

@media (max-width: 575.98px) {
  .aix-caseline-item + .aix-caseline-item {
    border-left: 0;
    border-top: 1px solid var(--bs-border-color);
  }
}
.aix-person {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  min-width: 0;
}

/* ---- secondary actions inside the profile action rail ----
   The rail is a fixed column while the middle drives the height, so it
   almost always has room left over. These fill it with the actions that
   belong to the case rather than with padding. */
.aix-quick-grid {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 8px;
  /* the tooltip wrapper each button sits in */
}
.aix-quick-grid > span {
  display: inline-flex;
}

.aix-quick-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 40px;
  height: 40px;
  flex-shrink: 0;
  border: 1px solid var(--bs-border-color);
  border-radius: 50%;
  background: var(--bs-body-bg);
  color: var(--bs-emphasis-color);
  font-size: 17px;
  transition: border-color var(--transition), background var(--transition), color var(--transition);
}
.aix-quick-btn:hover, .aix-quick-btn:focus-visible {
  border-color: rgba(61, 94, 225, 0.35);
  background: var(--tint-primary);
  color: var(--bs-primary);
}

/* case status, pinned to the foot of the rail */
.aix-side-foot {
  margin-top: auto;
  padding-top: 12px;
  border-top: 1px solid var(--bs-border-color);
}
@media (max-width: 1399.98px) {
  .aix-side-foot {
    flex: 1 1 100%;
    margin-top: 0;
  }
}

/* ============================================================
   10. WORKFLOW CARDS
   ============================================================ */
.aix-flow {
  position: relative;
  border: 1px solid var(--bs-border-color);
  border-radius: var(--radius);
  background: var(--bs-body-bg);
  box-shadow: var(--shadow);
  overflow: hidden;
}

.aix-flow-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 14px;
  padding: 18px 20px;
  border-bottom: 1px solid var(--bs-border-color);
}

.aix-flow-body {
  padding: 20px;
}

/* horizontal stage rail with connectors */
.aix-steps {
  display: grid;
  grid-template-columns: repeat(7, minmax(0, 1fr));
  gap: 8px;
}
@media (max-width: 1199.98px) {
  .aix-steps {
    grid-template-columns: repeat(4, minmax(0, 1fr));
  }
}
@media (max-width: 575.98px) {
  .aix-steps {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}

.aix-step {
  position: relative;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 8px;
  padding: 14px 10px;
  border-radius: var(--radius-sm);
  background: var(--bs-secondary-bg);
  text-align: center;
  transition: background var(--transition);
}
.aix-step:hover {
  background: var(--bs-tertiary-bg);
}
.aix-step {
  /* connector */
}
.aix-step:not(:last-child)::after {
  content: "";
  position: absolute;
  top: 31px;
  right: -8px;
  width: 8px;
  height: 1px;
  background: var(--bs-border-color);
}
@media (max-width: 1199.98px) {
  .aix-step:not(:last-child)::after {
    display: none;
  }
}
.aix-step.is-done {
  background: #E8F9E8;
}
.aix-step.is-active {
  background: var(--tint-primary);
  box-shadow: inset 0 0 0 1px rgba(61, 94, 225, 0.28);
}

.aix-step-ic {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 34px;
  height: 34px;
  border-radius: 50%;
  background: var(--bs-body-bg);
  color: var(--bs-secondary-color);
  font-size: 16px;
}
.is-done .aix-step-ic {
  color: #1ABE17;
}
.is-active .aix-step-ic {
  color: var(--bs-primary);
}

.aix-step-lbl {
  margin: 0;
  font-size: 12px;
  font-weight: 500;
  line-height: 1.35;
  color: var(--bs-emphasis-color);
}

.aix-step-sub {
  margin: 0;
  font-size: 11px;
  color: var(--bs-secondary-color);
}

/* ============================================================
   11. ACTIVITY TIMELINE
   ============================================================ */
.aix-tl {
  position: relative;
  margin: 0;
  padding: 0;
  list-style: none;
}

.aix-tl-item {
  position: relative;
  display: grid;
  grid-template-columns: 36px minmax(0, 1fr);
  gap: 14px;
  padding-bottom: 22px;
}
.aix-tl-item:last-child {
  padding-bottom: 0;
}
.aix-tl-item {
  /* the rail */
}
.aix-tl-item:not(:last-child)::before {
  content: "";
  position: absolute;
  top: 38px;
  left: 17px;
  bottom: 0;
  width: 1px;
  background: var(--bs-border-color);
}

.aix-tl-dot {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 36px;
  height: 36px;
  border-radius: 50%;
  background: var(--bs-secondary-bg);
  color: var(--bs-secondary-color);
  font-size: 16px;
  z-index: 1;
}
.aix-tl-dot.is-done {
  background: #E8F9E8;
  color: #1ABE17;
}
.aix-tl-dot.is-active {
  background: var(--tint-primary);
  color: var(--bs-primary);
  box-shadow: 0 0 0 4px rgba(61, 94, 225, 0.1);
}

.aix-tl-title {
  margin: 0 0 2px;
  font-size: 14px;
  font-weight: 600;
  color: var(--bs-emphasis-color);
}

/* ============================================================
   12. ACTION CENTER
   ============================================================ */
.aix-action {
  display: flex;
  align-items: flex-start;
  gap: 14px;
  padding: 14px;
  border: 1px solid var(--bs-border-color);
  border-radius: var(--radius-sm);
  background: var(--bs-body-bg);
  transition: background var(--transition), border-color var(--transition);
}
.aix-action:hover {
  background: var(--bs-tertiary-bg);
  border-color: rgba(61, 94, 225, 0.28);
}
.aix-action + .aix-action {
  margin-top: 12px;
}

.aix-action-ic {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 38px;
  height: 38px;
  flex-shrink: 0;
  border-radius: var(--radius-sm);
  background: var(--bs-secondary-bg);
  color: var(--bs-emphasis-color);
}

/* ============================================================
   13. RESOURCE CARDS
   ============================================================ */
.aix-res {
  display: flex;
  align-items: flex-start;
  gap: 14px;
  height: 100%;
  padding: 18px;
  border: 1px solid var(--bs-border-color);
  border-radius: var(--radius);
  background: var(--bs-body-bg);
  box-shadow: var(--shadow);
  cursor: pointer;
  transition: transform var(--transition), box-shadow var(--transition);
}
.aix-res:hover {
  transform: translateY(-2px);
  box-shadow: var(--shadow-lift);
}
.aix-res:hover .aix-res-go {
  color: var(--bs-primary);
  translate: 2px 0;
}

.aix-res-go {
  color: var(--bs-secondary-color);
  transition: color var(--transition), translate var(--transition);
}

/* ============================================================
   14. COPILOT WORKSPACE
   ============================================================ */
.aix-copilot {
  position: relative;
  border: 1px solid var(--bs-border-color);
  border-radius: var(--radius);
  background: radial-gradient(80% 120% at 100% 0%, rgba(61, 94, 225, 0.1) 0%, rgba(255, 255, 255, 0) 60%), var(--bs-body-bg);
  box-shadow: var(--shadow);
  overflow: hidden;
}

.aix-copilot-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 16px;
  padding: 22px 24px;
  border-bottom: 1px solid var(--bs-border-color);
}

.aix-copilot-body {
  padding: 24px;
}

.aix-act {
  display: flex;
  flex-direction: column;
  gap: 10px;
  height: 100%;
  padding: 16px;
  border: 1px solid var(--bs-border-color);
  border-radius: var(--radius-sm);
  background: var(--bs-body-bg);
  text-align: left;
  transition: transform var(--transition), box-shadow var(--transition), border-color var(--transition);
}
.aix-act:hover {
  transform: translateY(-2px);
  border-color: rgba(61, 94, 225, 0.3);
  box-shadow: var(--shadow-lift);
}

.aix-act-ic {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 36px;
  height: 36px;
  border-radius: var(--radius-sm);
  background: var(--tint-primary);
  color: var(--bs-primary);
  font-size: 17px;
}

/* ============================================================
   15. PREMIUM ACCORDION / OFFCANVAS / MODAL
   ============================================================ */
.aix-acc {
  border: 1px solid var(--bs-border-color);
  border-radius: var(--radius);
  overflow: hidden;
}
.aix-acc .accordion-item {
  border: 0;
  border-bottom: 1px solid var(--bs-border-color);
  background: transparent;
}
.aix-acc .accordion-item:last-child {
  border-bottom: 0;
}
.aix-acc .accordion-button {
  padding: 14px 16px;
  font-size: 14px;
  font-weight: 500;
  color: var(--bs-emphasis-color);
  background: var(--bs-body-bg);
  box-shadow: none;
}
.aix-acc .accordion-button:not(.collapsed) {
  background: var(--tint-primary);
  color: var(--bs-primary);
}
.aix-acc .accordion-button:focus {
  box-shadow: none;
}
.aix-acc .accordion-body {
  padding: 16px;
  font-size: 13px;
  line-height: 1.7;
  color: var(--bs-secondary-color);
  background: var(--bs-body-bg);
}

.aix-canvas .offcanvas-header {
  padding: 20px;
  background: linear-gradient(180deg, var(--tint-primary) 0%, var(--bs-body-bg) 100%);
  border-bottom: 1px solid var(--bs-border-color);
}
.aix-canvas .offcanvas-body {
  padding: 20px;
}
.aix-canvas .offcanvas-footer {
  padding: 16px 20px;
  border-top: 1px solid var(--bs-border-color);
  background: var(--bs-secondary-bg);
}

.aix-modal .modal-content {
  border: 1px solid var(--bs-border-color);
  border-radius: var(--radius);
  overflow: hidden;
}
.aix-modal .modal-header {
  padding: 20px;
  background: linear-gradient(180deg, var(--tint-primary) 0%, var(--bs-body-bg) 100%);
  border-bottom: 1px solid var(--bs-border-color);
}
.aix-modal .modal-body {
  padding: 20px;
}
.aix-modal .modal-footer {
  padding: 16px 20px;
  background: var(--bs-secondary-bg);
}

/* ============================================================
   16. CASE QUEUE + CASE WORKSPACE
   The scalable pattern: the page lists cases, the workspace holds the
   detail. One offcanvas serves every case, so the page length is the same
   whether the engine flags 10 students or 500.
   ============================================================ */
/* ---- the workspace shell ---- */
/* The case workspace needs most of the viewport. The theme already sets
   `.offcanvas.offcanvas-end { width: auto !important }`, which is two classes
   and !important, so a single-class rule cannot win however it is written.
   Matching all three classes outranks it without editing the shared partial. */
.offcanvas.offcanvas-end.aix-canvas-xl {
  width: 88% !important;
  max-width: 1440px !important;
}
@media (max-width: 991.98px) {
  .offcanvas.offcanvas-end.aix-canvas-xl {
    width: 100% !important;
  }
}

/* record highlights panel, the Salesforce-style header */
.aix-record {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 16px;
  padding: 18px 24px;
  background: linear-gradient(180deg, var(--tint-primary) 0%, var(--bs-body-bg) 100%);
  border-bottom: 1px solid var(--bs-border-color);
}

.aix-record-stats {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 0;
  border: 1px solid var(--bs-border-color);
  border-radius: var(--radius-sm);
  background: var(--bs-body-bg);
  overflow: hidden;
}
@media (max-width: 767.98px) {
  .aix-record-stats {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}

.aix-record-stat {
  padding: 9px 14px;
  min-width: 0;
}
.aix-record-stat + .aix-record-stat {
  border-left: 1px solid var(--bs-border-color);
}
@media (max-width: 767.98px) {
  .aix-record-stat:nth-child(3) {
    border-left: 0;
  }
}

/* ---- horizontal stepper ---- */
.aix-stepper {
  display: grid;
  grid-template-columns: repeat(5, minmax(0, 1fr));
  gap: 8px;
  padding: 14px 24px;
  background: var(--bs-secondary-bg);
  border-bottom: 1px solid var(--bs-border-color);
  list-style: none;
  margin: 0;
}
@media (max-width: 991.98px) {
  .aix-stepper {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }
}
@media (max-width: 575.98px) {
  .aix-stepper {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}

.aix-stepper-btn {
  position: relative;
  display: flex;
  align-items: center;
  gap: 10px;
  width: 100%;
  padding: 10px 12px;
  border: 1px solid var(--bs-border-color);
  border-radius: var(--radius-sm);
  background: var(--bs-body-bg);
  text-align: left;
  transition: border-color var(--transition), background var(--transition), box-shadow var(--transition);
  /* connector between steps */
}
.aix-stepper-btn::after {
  content: "";
  position: absolute;
  top: 50%;
  right: -8px;
  width: 8px;
  height: 8px;
  border-top: 1.5px solid var(--bs-border-color);
  border-right: 1.5px solid var(--bs-border-color);
  rotate: 45deg;
  translate: 0 -50%;
}
@media (max-width: 991.98px) {
  .aix-stepper-btn::after {
    display: none;
  }
}
.aix-stepper-btn:hover {
  border-color: rgba(61, 94, 225, 0.35);
}
.aix-stepper-btn.active {
  border-color: var(--bs-primary);
  background: var(--bs-body-bg);
  box-shadow: inset 0 0 0 1px var(--bs-primary);
}
.aix-stepper-btn.active .aix-stepper-ic {
  background: var(--bs-primary);
  color: #fff;
}
.aix-stepper-btn.active .aix-stepper-lbl {
  color: var(--bs-primary);
}

.nav-item:last-child .aix-stepper-btn::after {
  display: none;
}

.aix-stepper-ic {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 30px;
  height: 30px;
  flex-shrink: 0;
  border-radius: 50%;
  background: var(--bs-secondary-bg);
  color: var(--bs-secondary-color);
  font-size: 14px;
  font-weight: 600;
  transition: background var(--transition), color var(--transition);
}

.aix-stepper-txt {
  display: flex;
  flex-direction: column;
  min-width: 0;
}

.aix-stepper-n {
  font-size: 10px;
  font-weight: 500;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--bs-secondary-color);
}

.aix-stepper-lbl {
  font-size: 13px;
  font-weight: 600;
  line-height: 1.3;
  color: var(--bs-emphasis-color);
  transition: color var(--transition);
}

/* ---- panes ---- */
.aix-pane-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 12px;
  margin-bottom: 16px;
  padding-bottom: 12px;
  border-bottom: 1px solid var(--bs-border-color);
}

/* a plain bordered block used throughout the panes */
.aix-block {
  border: 1px solid var(--bs-border-color);
  border-radius: var(--radius);
  background: var(--bs-body-bg);
  overflow: hidden;
  height: 100%;
}

.aix-block-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 12px 16px;
  border-bottom: 1px solid var(--bs-border-color);
  background: var(--bs-secondary-bg);
}

.aix-block-body {
  padding: 16px;
}

/* ============================================================
   17. EMPTY STATES
   ============================================================ */
.aix-empty {
  display: flex;
  flex-direction: column;
  align-items: center;
  text-align: center;
  padding: 36px 24px;
  border: 1px dashed var(--bs-border-color);
  border-radius: var(--radius);
  background: var(--bs-secondary-bg);
}

.aix-empty-art {
  position: relative;
  display: grid;
  place-items: center;
  width: 64px;
  height: 64px;
  margin-bottom: 14px;
  border-radius: 50%;
  background: var(--bs-body-bg);
  border: 1px solid var(--bs-border-color);
  color: var(--bs-primary);
  font-size: 26px;
}
.aix-empty-art::after {
  content: "";
  position: absolute;
  inset: -8px;
  border: 1px dashed var(--bs-border-color);
  border-radius: 50%;
}

.aix-empty-title {
  margin: 0 0 4px;
  font-size: 15px;
  font-weight: 600;
  color: var(--bs-emphasis-color);
}

/* ============================================================
   17. ATTENDANCE INTELLIGENCE  —  prefix `atn-`

   A second component family in the same library, sharing the tokens above
   but with a deliberately different visual language from the `aix-` family:

     aix-  enclosed cards, hairline dividers, chevron steppers, left rails
     atn-  banded surfaces, a vertical signal spine, square heat cells,
           numbered rail steps and arc gauges

   Nothing here overrides an `aix-` rule, so the two can coexist on a page
   without either winning by accident.
   ============================================================ */
@media (prefers-reduced-motion: reduce) {
  [class*=atn-],
  [class*=atn-]::before,
  [class*=atn-]::after {
    animation: none !important;
    transition: none !important;
  }
}
/* ---- section framing ---------------------------------------------------
   Sections announce themselves with a rule and a number rather than with
   an icon tile, so the page reads as a document of findings. */
.atn-sec {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 16px;
  padding-bottom: 14px;
  margin-bottom: 24px;
  border-bottom: 2px solid var(--bs-emphasis-color);
}

.atn-sec-n {
  display: block;
  margin-bottom: 6px;
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  color: var(--bs-primary);
}

.atn-sec-title {
  margin: 0;
  font-size: 20px;
  font-weight: 600;
  color: var(--bs-emphasis-color);
}

.atn-sec-sub {
  margin: 4px 0 0;
  font-size: 13px;
  color: var(--bs-secondary-color);
  max-width: 620px;
}

/* small caps label, used inside every atn component */
.atn-lbl {
  display: block;
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--bs-secondary-color);
}

/* ---- confidence chip ---------------------------------------------------
   Reads as a measurement, not a badge: monospaced-feel figure with a rule
   under it that fills to the value carried by `.aix-p-*`. */
.atn-conf {
  display: inline-flex;
  flex-direction: column;
  gap: 4px;
  min-width: 62px;
}
.atn-conf b {
  font-size: 14px;
  font-weight: 600;
  font-variant-numeric: tabular-nums;
  color: var(--bs-emphasis-color);
  line-height: 1;
}
.atn-conf::after {
  content: "";
  display: block;
  height: 3px;
  border-radius: 2px;
  background: linear-gradient(90deg, var(--bs-primary) 0 calc(var(--p, 0) * 1%), var(--bs-tertiary-bg) calc(var(--p, 0) * 1%) 100%);
}

/* ---- severity / status pills ------------------------------------------- */
.atn-pill {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 3px 10px;
  border-radius: 999px;
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.02em;
  border: 1px solid transparent;
  white-space: nowrap;
}
.atn-pill i {
  font-size: 13px;
}
.atn-pill.is-critical {
  color: #E82646;
  background: #FDE9ED;
  border-color: #FAD4DA;
}
.atn-pill.is-high {
  color: #EAB300;
  background: #FEF8EA;
  border-color: #FDF1D6;
}
.atn-pill.is-watch {
  color: #0F65CD;
  background: #E7F1FC;
  border-color: #CFE2FA;
}
.atn-pill.is-good {
  color: #1ABE17;
  background: #E8F9E8;
  border-color: #D1F2D1;
}
.atn-pill.is-ai {
  color: var(--bs-primary);
  background: var(--tint-primary);
  border-color: rgba(61, 94, 225, 0.22);
}

/* live status dot */
.atn-live {
  position: relative;
  display: inline-block;
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: #1ABE17;
}
.atn-live::after {
  content: "";
  position: absolute;
  inset: -4px;
  border-radius: 50%;
  border: 1px solid #1ABE17;
  opacity: 0;
  animation: atn-ping 2.4s ease-out infinite;
}

@keyframes atn-ping {
  0% {
    transform: scale(0.6);
    opacity: 0.9;
  }
  100% {
    transform: scale(1.5);
    opacity: 0;
  }
}
/* ============================================================
   HERO — split workspace: gauge on the left, live feed on the right
   ============================================================ */
.atn-hero {
  position: relative;
  overflow: hidden;
  border-radius: var(--radius);
  background: radial-gradient(120% 140% at 0% 0%, rgba(61, 94, 225, 0.1) 0%, rgba(61, 94, 225, 0) 55%), radial-gradient(100% 120% at 100% 0%, rgba(2, 168, 181, 0.1) 0%, rgba(2, 168, 181, 0) 50%), var(--bs-body-bg);
  border: 1px solid var(--bs-border-color);
  box-shadow: var(--shadow);
}

/* a faint grid so the surface reads as an instrument panel */
.atn-hero::before {
  content: "";
  position: absolute;
  inset: 0;
  background-image: linear-gradient(var(--bs-border-color) 1px, transparent 1px), linear-gradient(90deg, var(--bs-border-color) 1px, transparent 1px);
  background-size: 46px 46px;
  opacity: 0.35;
  mask-image: radial-gradient(120% 100% at 50% 0%, #000 0%, transparent 75%);
  pointer-events: none;
}

.atn-hero-inner {
  position: relative;
  display: grid;
  grid-template-columns: minmax(0, 1fr) 336px;
  gap: 32px;
  padding: 26px 28px;
}
@media (max-width: 1199.98px) {
  .atn-hero-inner {
    grid-template-columns: minmax(0, 1fr);
    gap: 24px;
  }
}
@media (max-width: 575.98px) {
  .atn-hero-inner {
    padding: 20px;
  }
}

.atn-hero-eyebrow {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 5px 12px 5px 8px;
  border-radius: 999px;
  background: var(--bs-body-bg);
  border: 1px solid var(--bs-border-color);
  box-shadow: var(--shadow);
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--bs-emphasis-color);
}

.atn-hero-title {
  margin: 14px 0 8px;
  font-size: 30px;
  line-height: 1.22;
  font-weight: 600;
  letter-spacing: -0.02em;
  color: var(--bs-emphasis-color);
}
.atn-hero-title em {
  font-style: normal;
  background: linear-gradient(90deg, var(--bs-primary), #02a8b5);
  -webkit-background-clip: text;
  background-clip: text;
  -webkit-text-fill-color: transparent;
}
@media (max-width: 767.98px) {
  .atn-hero-title {
    font-size: 24px;
  }
}

/* health meter — one continuous band, not four stat boxes */
.atn-meter {
  margin-top: 20px;
  padding: 16px 18px;
  border-radius: var(--radius);
  background: var(--bs-body-bg);
  border: 1px solid var(--bs-border-color);
}

.atn-meter-head {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 12px;
  margin-bottom: 12px;
}
.atn-meter-head b {
  font-size: 24px;
  font-weight: 600;
  font-variant-numeric: tabular-nums;
  color: var(--bs-emphasis-color);
}
.atn-meter-head b small {
  font-size: 13px;
  font-weight: 500;
  color: var(--bs-secondary-color);
}

.atn-meter-band {
  display: flex;
  gap: 3px;
  height: 26px;
}
.atn-meter-band span {
  flex: 1 1 0;
  border-radius: 3px;
  background: var(--bs-tertiary-bg);
  transition: var(--transition);
}
.atn-meter-band span.is-on {
  background: linear-gradient(180deg, var(--bs-primary), rgba(61, 94, 225, 0.72));
}
.atn-meter-band span.is-warn {
  background: #EAB300;
}
.atn-meter-band span.is-bad {
  background: #E82646;
}

.atn-meter-scale {
  display: flex;
  justify-content: space-between;
  margin-top: 8px;
  font-size: 11px;
  color: var(--bs-secondary-color);
}

/* hero figures sit on a single inline row, divided by dots not boxes */
.atn-hero-facts {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 8px 20px;
  margin-top: 18px;
  font-size: 13px;
  color: var(--bs-secondary-color);
}
.atn-hero-facts span b {
  font-weight: 600;
  color: var(--bs-emphasis-color);
}

/* ---- right column: gauge + live feed ---- */
.atn-hero-panel {
  display: flex;
  flex-direction: column;
  gap: 14px;
  padding: 18px;
  border-radius: var(--radius);
  background: var(--bs-body-bg);
  border: 1px solid var(--bs-border-color);
  box-shadow: var(--aix-glow);
}

.atn-gauge {
  position: relative;
  width: 168px;
  height: 92px;
  margin: 4px auto 0;
  overflow: hidden;
}

/* The dial is a conic sweep starting at 9 o'clock, so a half turn (180deg)
   is a full reading and `--p` maps to degrees at 1.8 per percent. The hole is
   cut with a radial mask rather than an overlaid disc, so the hero's tinted
   background shows through the middle. */
.atn-gauge::before {
  content: "";
  position: absolute;
  left: 0;
  top: 0;
  width: 168px;
  height: 168px;
  border-radius: 50%;
  background: conic-gradient(from 270deg, var(--bs-primary) 0deg calc(var(--p, 0) * 1.8deg), var(--bs-tertiary-bg) calc(var(--p, 0) * 1.8deg) 180deg, transparent 180deg 360deg);
  -webkit-mask: radial-gradient(farthest-side, transparent calc(100% - 14px), #000 calc(100% - 14px));
  mask: radial-gradient(farthest-side, transparent calc(100% - 14px), #000 calc(100% - 14px));
}

.atn-gauge-val {
  position: absolute;
  left: 0;
  right: 0;
  bottom: 2px;
  text-align: center;
  font-size: 26px;
  font-weight: 600;
  font-variant-numeric: tabular-nums;
  color: var(--bs-emphasis-color);
  line-height: 1;
}
.atn-gauge-val small {
  display: block;
  margin-top: 4px;
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--bs-secondary-color);
}

/* live prediction feed — ticker rows, each with a leading time */
.atn-feed {
  display: flex;
  flex-direction: column;
  border-top: 1px solid var(--bs-border-color);
}

.atn-feed-row {
  display: flex;
  align-items: flex-start;
  gap: 10px;
  padding: 9px 0;
  font-size: 12px;
}
.atn-feed-row + .atn-feed-row {
  border-top: 1px dashed var(--bs-border-color);
}
.atn-feed-row time {
  flex-shrink: 0;
  width: 42px;
  font-variant-numeric: tabular-nums;
  color: var(--bs-secondary-color);
}
.atn-feed-row p {
  margin: 0;
  color: var(--bs-emphasis-color);
}

/* ============================================================
   CASE CARDS — compact 3-up grid with a delta band and heat strip
   ============================================================ */
.atn-case {
  display: flex;
  flex-direction: column;
  height: 100%;
  border-radius: var(--radius);
  background: var(--bs-body-bg);
  border: 1px solid var(--bs-border-color);
  overflow: hidden;
  transition: var(--transition);
}
.atn-case:hover {
  border-color: rgba(61, 94, 225, 0.3);
  box-shadow: var(--shadow-lift);
}

/* the delta band is the card's identity: current -> predicted, in colour */
.atn-case-band {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 12px 16px;
  color: #fff;
  background: linear-gradient(90deg, #202C4B, rgba(32, 44, 75, 0.82));
}
.atn-case-band.is-critical {
  background: linear-gradient(90deg, #E82646, rgba(232, 38, 70, 0.8));
}
.atn-case-band.is-high {
  background: linear-gradient(90deg, #EAB300, rgba(234, 179, 0, 0.8));
}
.atn-case-band.is-watch {
  background: linear-gradient(90deg, #0F65CD, rgba(15, 101, 205, 0.8));
}

.atn-case-delta {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 18px;
  font-weight: 600;
  font-variant-numeric: tabular-nums;
  line-height: 1;
}
.atn-case-delta i {
  font-size: 16px;
  opacity: 0.85;
}
.atn-case-delta small {
  font-size: 11px;
  font-weight: 500;
  opacity: 0.85;
}

.atn-case-body {
  display: flex;
  flex-direction: column;
  gap: 14px;
  flex: 1 1 auto;
  padding: 16px;
}

.atn-case-name {
  margin: 0;
  font-size: 15px;
  font-weight: 600;
  color: var(--bs-emphasis-color);
}

/* 12-week heat strip — square cells, four intensities */
.atn-heat {
  display: flex;
  gap: 3px;
}
.atn-heat i {
  flex: 1 1 0;
  height: 18px;
  border-radius: 3px;
  background: var(--bs-tertiary-bg);
}
.atn-heat i.h1 {
  background: rgba(61, 94, 225, 0.22);
}
.atn-heat i.h2 {
  background: rgba(61, 94, 225, 0.45);
}
.atn-heat i.h3 {
  background: rgba(61, 94, 225, 0.7);
}
.atn-heat i.h4 {
  background: var(--bs-primary);
}
.atn-heat i.m1 {
  background: #FDE9ED;
}
.atn-heat i.m2 {
  background: #F8BEC8;
}
.atn-heat i.m3 {
  background: #E82646;
}

.atn-case-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 12px;
  padding: 12px 0;
  border-top: 1px solid var(--bs-border-color);
  border-bottom: 1px solid var(--bs-border-color);
}

.atn-case-foot {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 12px 16px;
  background: var(--bs-secondary-bg);
  border-top: 1px solid var(--bs-border-color);
}

/* round icon-only secondary actions */
.atn-ico-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 34px;
  height: 34px;
  flex-shrink: 0;
  border-radius: 50%;
  background: var(--bs-body-bg);
  border: 1px solid var(--bs-border-color);
  color: var(--bs-secondary-color);
  font-size: 16px;
  transition: var(--transition);
}
.atn-ico-btn:hover {
  color: var(--bs-primary);
  border-color: var(--bs-primary);
  background: var(--tint-primary);
}

/* ============================================================
   SIGNAL SPINE — the explainable-AI cascade
   A vertical chain of nodes joined by a drawn line, so the causal
   order the AI followed is the layout itself.
   ============================================================ */
.atn-spine {
  position: relative;
  padding-left: 34px;
}
.atn-spine::before {
  content: "";
  position: absolute;
  left: 13px;
  top: 10px;
  bottom: 10px;
  width: 2px;
  background: linear-gradient(180deg, var(--bs-primary), rgba(61, 94, 225, 0.12));
}

.atn-node {
  position: relative;
  padding: 14px 16px;
  border-radius: var(--radius);
  background: var(--bs-body-bg);
  border: 1px solid var(--bs-border-color);
  transition: var(--transition);
}
.atn-node + .atn-node {
  margin-top: 14px;
}
.atn-node:hover {
  border-color: rgba(61, 94, 225, 0.3);
  box-shadow: var(--shadow);
}
.atn-node {
  /* the marker sits on the spine */
}
.atn-node::before {
  content: "";
  position: absolute;
  left: -27px;
  top: 20px;
  width: 12px;
  height: 12px;
  border-radius: 50%;
  background: var(--bs-body-bg);
  border: 3px solid var(--bs-primary);
}
.atn-node.is-critical::before {
  border-color: #E82646;
}
.atn-node.is-high::before {
  border-color: #EAB300;
}
.atn-node.is-watch::before {
  border-color: #0F65CD;
}

.atn-node-obs {
  margin: 0 0 6px;
  font-size: 15px;
  font-weight: 600;
  color: var(--bs-emphasis-color);
}

.atn-node-why {
  margin: 0 0 12px;
  font-size: 13px;
  line-height: 1.6;
  color: var(--bs-secondary-color);
}

/* supporting signals read as inline evidence tags */
.atn-sigs {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
}
.atn-sigs span {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  padding: 4px 10px;
  border-radius: var(--radius-sm);
  background: var(--bs-secondary-bg);
  border: 1px solid var(--bs-border-color);
  font-size: 12px;
  color: var(--bs-emphasis-color);
}
.atn-sigs span i {
  font-size: 13px;
  color: var(--bs-secondary-color);
}

.atn-node-foot {
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 12px;
  margin-top: 12px;
  padding-top: 12px;
  border-top: 1px dashed var(--bs-border-color);
}

/* expected improvement figure */
.atn-gain {
  display: inline-flex;
  align-items: baseline;
  gap: 4px;
  font-size: 15px;
  font-weight: 600;
  font-variant-numeric: tabular-nums;
  color: #1ABE17;
}
.atn-gain small {
  font-size: 11px;
  font-weight: 500;
  color: var(--bs-secondary-color);
}

/* ============================================================
   RECOMMENDATIONS — priority-ranked rows with a leading rank number
   ============================================================ */
.atn-rec {
  display: flex;
  align-items: flex-start;
  gap: 14px;
  height: 100%;
  padding: 16px;
  border-radius: var(--radius);
  background: var(--bs-body-bg);
  border: 1px solid var(--bs-border-color);
  transition: var(--transition);
}
.atn-rec:hover {
  border-color: rgba(61, 94, 225, 0.3);
  box-shadow: var(--shadow-lift);
}

.atn-rec-rank {
  flex-shrink: 0;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 38px;
  height: 38px;
  border-radius: var(--radius-sm);
  background: var(--tint-primary);
  color: var(--bs-primary);
  font-size: 14px;
  font-weight: 700;
  font-variant-numeric: tabular-nums;
}

.atn-rec-title {
  margin: 0 0 4px;
  font-size: 14px;
  font-weight: 600;
  color: var(--bs-emphasis-color);
}

.atn-rec-meta {
  display: flex;
  flex-wrap: wrap;
  gap: 6px 16px;
  margin-top: 10px;
  font-size: 12px;
  color: var(--bs-secondary-color);
}
.atn-rec-meta b {
  font-weight: 600;
  color: var(--bs-emphasis-color);
}

/* ============================================================
   RECOVERY RAIL — 7 numbered stations on a drawn track
   ============================================================ */
.atn-rail {
  position: relative;
  display: grid;
  grid-template-columns: repeat(7, minmax(0, 1fr));
  gap: 8px;
}
@media (max-width: 1199.98px) {
  .atn-rail {
    grid-template-columns: repeat(4, minmax(0, 1fr));
    row-gap: 22px;
  }
}
@media (max-width: 575.98px) {
  .atn-rail {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}

.atn-station {
  position: relative;
  text-align: center;
  padding-top: 42px;
  /* the track segment */
}
.atn-station::before {
  content: "";
  position: absolute;
  left: 50%;
  right: -50%;
  top: 16px;
  height: 2px;
  background: var(--bs-tertiary-bg);
}
.atn-station:last-child::before {
  display: none;
}
.atn-station.is-done::before {
  background: #1ABE17;
}
.atn-station {
  /* the station marker */
}
.atn-station::after {
  content: attr(data-n);
  position: absolute;
  left: 50%;
  top: 0;
  transform: translateX(-50%);
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 34px;
  height: 34px;
  border-radius: 50%;
  background: var(--bs-body-bg);
  border: 2px solid var(--bs-tertiary-bg);
  color: var(--bs-secondary-color);
  font-size: 12px;
  font-weight: 700;
  font-variant-numeric: tabular-nums;
}
.atn-station.is-done::after {
  background: #1ABE17;
  border-color: #1ABE17;
  color: #fff;
}
.atn-station.is-now::after {
  border-color: var(--bs-primary);
  color: var(--bs-primary);
  box-shadow: 0 0 0 4px var(--tint-primary);
}
@media (max-width: 1199.98px) {
  .atn-station::before {
    display: none;
  }
}

.atn-station-lbl {
  display: block;
  font-size: 13px;
  font-weight: 600;
  color: var(--bs-emphasis-color);
}

.atn-station-sub {
  display: block;
  margin-top: 2px;
  font-size: 11px;
  color: var(--bs-secondary-color);
}

/* ============================================================
   COPILOT LAUNCHER — six large action tiles
   ============================================================ */
.atn-launch {
  position: relative;
  display: flex;
  flex-direction: column;
  gap: 10px;
  height: 100%;
  padding: 18px;
  border-radius: var(--radius);
  background: var(--bs-body-bg);
  border: 1px solid var(--bs-border-color);
  overflow: hidden;
  transition: var(--transition);
}
.atn-launch::after {
  content: "";
  position: absolute;
  right: -32px;
  top: -32px;
  width: 96px;
  height: 96px;
  border-radius: 50%;
  background: var(--tint-primary);
  opacity: 0;
  transition: var(--transition);
}
.atn-launch:hover {
  border-color: rgba(61, 94, 225, 0.3);
  box-shadow: var(--shadow-lift);
}
.atn-launch:hover::after {
  opacity: 1;
}
.atn-launch:hover .atn-launch-ic {
  color: #fff;
  background: var(--bs-primary);
  border-color: var(--bs-primary);
}

.atn-launch-ic {
  position: relative;
  z-index: 1;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 42px;
  height: 42px;
  border-radius: var(--radius-sm);
  background: var(--tint-primary);
  border: 1px solid transparent;
  color: var(--bs-primary);
  font-size: 20px;
  transition: var(--transition);
}

.atn-launch-title {
  position: relative;
  z-index: 1;
  margin: 0;
  font-size: 14px;
  font-weight: 600;
  color: var(--bs-emphasis-color);
}

/* ============================================================
   INTELLIGENCE NOTES — findings written as quoted AI statements
   ============================================================ */
.atn-note {
  height: 100%;
  padding: 18px;
  border-radius: var(--radius);
  background: var(--bs-body-bg);
  border: 1px solid var(--bs-border-color);
  border-left: 3px solid var(--bs-primary);
  transition: var(--transition);
}
.atn-note:hover {
  box-shadow: var(--shadow-lift);
}
.atn-note.is-good {
  border-left-color: #1ABE17;
}
.atn-note.is-warn {
  border-left-color: #EAB300;
}
.atn-note.is-bad {
  border-left-color: #E82646;
}

.atn-note-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  margin-bottom: 10px;
}

.atn-note-fig {
  display: block;
  margin-bottom: 6px;
  font-size: 26px;
  font-weight: 600;
  font-variant-numeric: tabular-nums;
  line-height: 1;
  color: var(--bs-emphasis-color);
}

.atn-note-txt {
  margin: 0;
  font-size: 13px;
  line-height: 1.6;
  color: var(--bs-secondary-color);
}

/* ============================================================
   SUCCESS CARDS — celebratory, tinted, avatar-led
   ============================================================ */
.atn-win {
  position: relative;
  height: 100%;
  padding: 18px;
  border-radius: var(--radius);
  background: linear-gradient(160deg, #E8F9E8 0%, var(--bs-body-bg) 62%);
  border: 1px solid var(--bs-border-color);
  overflow: hidden;
}

.atn-win-ic {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 38px;
  height: 38px;
  margin-bottom: 12px;
  border-radius: 50%;
  background: var(--bs-body-bg);
  border: 1px solid var(--bs-border-color);
  color: #1ABE17;
  font-size: 18px;
}

.atn-win-fig {
  display: block;
  font-size: 24px;
  font-weight: 600;
  font-variant-numeric: tabular-nums;
  line-height: 1;
  color: var(--bs-emphasis-color);
}

/* ============================================================
   AUDIT TIMELINE — alternating, centred on a rule
   ============================================================ */
.atn-tl {
  position: relative;
  padding: 4px 0;
}
.atn-tl::before {
  content: "";
  position: absolute;
  left: 50%;
  top: 0;
  bottom: 0;
  width: 2px;
  margin-left: -1px;
  background: var(--bs-border-color);
}
@media (max-width: 767.98px) {
  .atn-tl::before {
    left: 11px;
    margin-left: 0;
  }
}

.atn-tl-item {
  position: relative;
  width: 50%;
  padding-right: 40px;
  margin-bottom: 20px;
}
.atn-tl-item:nth-child(even) {
  margin-left: 50%;
  padding-right: 0;
  padding-left: 40px;
  text-align: left;
}
.atn-tl-item:nth-child(odd) {
  text-align: right;
}
.atn-tl-item {
  /* the knot on the centre rule */
}
.atn-tl-item::before {
  content: "";
  position: absolute;
  top: 16px;
  width: 13px;
  height: 13px;
  border-radius: 50%;
  background: var(--bs-body-bg);
  border: 3px solid var(--bs-primary);
  z-index: 1;
}
.atn-tl-item:nth-child(odd)::before {
  right: -6px;
}
.atn-tl-item:nth-child(even)::before {
  left: -7px;
}
.atn-tl-item.is-good::before {
  border-color: #1ABE17;
}
.atn-tl-item.is-warn::before {
  border-color: #EAB300;
}
.atn-tl-item.is-bad::before {
  border-color: #E82646;
}
@media (max-width: 767.98px) {
  .atn-tl-item {
    width: 100%;
    margin-left: 0 !important;
    padding-left: 40px !important;
    padding-right: 0 !important;
    text-align: left !important;
  }
  .atn-tl-item::before {
    left: 5px !important;
    right: auto !important;
  }
}

.atn-tl-card {
  display: inline-block;
  text-align: left;
  padding: 14px 16px;
  border-radius: var(--radius);
  background: var(--bs-body-bg);
  border: 1px solid var(--bs-border-color);
  transition: var(--transition);
}
.atn-tl-card:hover {
  box-shadow: var(--shadow);
}

.atn-tl-title {
  margin: 0 0 3px;
  font-size: 14px;
  font-weight: 600;
  color: var(--bs-emphasis-color);
}

/* ============================================================
   RESOURCE TILES — link rows with a trailing arrow
   ============================================================ */
.atn-res {
  display: flex;
  align-items: center;
  gap: 14px;
  height: 100%;
  padding: 16px;
  border-radius: var(--radius);
  background: var(--bs-body-bg);
  border: 1px solid var(--bs-border-color);
  transition: var(--transition);
}
.atn-res:hover {
  border-color: rgba(61, 94, 225, 0.3);
  background: var(--bs-secondary-bg);
}
.atn-res:hover .atn-res-go {
  transform: translateX(3px);
  color: var(--bs-primary);
}

.atn-res-ic {
  flex-shrink: 0;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 40px;
  height: 40px;
  border-radius: var(--radius-sm);
  background: var(--bs-secondary-bg);
  border: 1px solid var(--bs-border-color);
  color: var(--bs-primary);
  font-size: 19px;
}

.atn-res-go {
  flex-shrink: 0;
  color: var(--bs-secondary-color);
  font-size: 17px;
  transition: var(--transition);
}

/* ============================================================
   WORKSPACE OFFCANVAS — numbered stepper with a progress rule
   ============================================================ */
.offcanvas.offcanvas-end.atn-ws {
  width: 88% !important;
  max-width: 1400px !important;
}
@media (max-width: 991.98px) {
  .offcanvas.offcanvas-end.atn-ws {
    width: 100% !important;
  }
}
.offcanvas.offcanvas-end.atn-ws .offcanvas-body {
  padding: 22px;
}

.atn-ws-head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 18px;
  padding: 20px 22px;
  background: linear-gradient(180deg, var(--tint-primary) 0%, var(--bs-body-bg) 100%);
  border-bottom: 1px solid var(--bs-border-color);
}

.atn-ws-figs {
  display: flex;
  flex-wrap: wrap;
  gap: 10px 28px;
}

/* the stepper: numbers on a rule, panes below */
.atn-steps {
  position: relative;
  display: grid;
  grid-template-columns: repeat(5, minmax(0, 1fr));
  gap: 6px;
  padding: 18px 22px 20px;
  border-bottom: 1px solid var(--bs-border-color);
  background: var(--bs-secondary-bg);
  list-style: none;
  margin: 0;
}
@media (max-width: 767.98px) {
  .atn-steps {
    grid-template-columns: repeat(2, minmax(0, 1fr));
    row-gap: 14px;
  }
}

.atn-step {
  position: relative;
  display: flex;
  align-items: center;
  gap: 10px;
  width: 100%;
  padding: 8px 10px;
  border: 0;
  border-radius: var(--radius-sm);
  background: transparent;
  text-align: left;
  transition: var(--transition);
}
.atn-step:hover {
  background: var(--bs-body-bg);
}
.atn-step {
  /* connector between numbers */
}
.atn-step::after {
  content: "";
  position: absolute;
  left: calc(100% + 3px);
  top: 50%;
  width: 6px;
  height: 2px;
  background: var(--bs-border-color);
}
.atn-step.is-last::after {
  display: none;
}
@media (max-width: 767.98px) {
  .atn-step::after {
    display: none;
  }
}

.atn-step-n {
  flex-shrink: 0;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 30px;
  height: 30px;
  border-radius: 50%;
  background: var(--bs-body-bg);
  border: 1px solid var(--bs-border-color);
  color: var(--bs-secondary-color);
  font-size: 12px;
  font-weight: 700;
  font-variant-numeric: tabular-nums;
  transition: var(--transition);
}

.atn-step-txt {
  display: flex;
  flex-direction: column;
  min-width: 0;
  line-height: 1.3;
}
.atn-step-txt span:first-child {
  font-size: 10px;
  font-weight: 600;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--bs-secondary-color);
}
.atn-step-txt span:last-child {
  font-size: 13px;
  font-weight: 600;
  color: var(--bs-emphasis-color);
}

.atn-step.active {
  background: var(--bs-body-bg);
  box-shadow: var(--shadow);
}
.atn-step.active .atn-step-n {
  background: var(--bs-primary);
  border-color: var(--bs-primary);
  color: #fff;
}

/* panels inside the workspace */
.atn-panel {
  height: 100%;
  border-radius: var(--radius);
  background: var(--bs-body-bg);
  border: 1px solid var(--bs-border-color);
  overflow: hidden;
}

.atn-panel-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 13px 16px;
  background: var(--bs-secondary-bg);
  border-bottom: 1px solid var(--bs-border-color);
}
.atn-panel-head h6 {
  margin: 0;
  font-size: 13px;
  font-weight: 600;
  color: var(--bs-emphasis-color);
}

.atn-panel-body {
  padding: 16px;
}

/* a plain labelled figure used across the panels */
.atn-fig {
  display: flex;
  flex-direction: column;
  gap: 2px;
  line-height: 1.3;
}
.atn-fig span:first-child {
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--bs-secondary-color);
}
.atn-fig span:last-child {
  font-size: 14px;
  font-weight: 600;
  font-variant-numeric: tabular-nums;
  color: var(--bs-emphasis-color);
}

/* attendance history — weekly columns, pure CSS */
.atn-cols {
  display: flex;
  align-items: flex-end;
  gap: 6px;
  height: 108px;
}
.atn-cols i {
  flex: 1 1 0;
  border-radius: 4px 4px 0 0;
  background: linear-gradient(180deg, var(--bs-primary), rgba(61, 94, 225, 0.45));
  height: calc(var(--p, 0) * 1%);
  min-height: 4px;
}
.atn-cols i.is-low {
  background: linear-gradient(180deg, #E82646, #F8BEC8);
}

/* checklist of completed actions */
.atn-check {
  display: flex;
  align-items: flex-start;
  gap: 10px;
  padding: 9px 0;
  font-size: 13px;
  color: var(--bs-emphasis-color);
}
.atn-check + .atn-check {
  border-top: 1px dashed var(--bs-border-color);
}
.atn-check i {
  flex-shrink: 0;
  margin-top: 1px;
  font-size: 16px;
  color: #1ABE17;
}
.atn-check.is-pending i {
  color: var(--bs-secondary-color);
}

/* ============================================================
   PREMIUM ALERT + EMPTY STATE
   ============================================================ */
.atn-alert {
  display: flex;
  align-items: flex-start;
  gap: 14px;
  padding: 16px 18px;
  border-radius: var(--radius);
  background: linear-gradient(90deg, var(--tint-primary), var(--bs-body-bg) 70%);
  border: 1px solid var(--bs-border-color);
  border-left: 3px solid var(--bs-primary);
}

.atn-alert-ic {
  flex-shrink: 0;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 38px;
  height: 38px;
  border-radius: 50%;
  background: var(--bs-body-bg);
  border: 1px solid var(--bs-border-color);
  color: var(--bs-primary);
  font-size: 18px;
}

.atn-empty {
  padding: 40px 24px;
  text-align: center;
  border-radius: var(--radius);
  background: var(--bs-secondary-bg);
  border: 1px dashed var(--bs-border-color);
}

.atn-empty-ic {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 56px;
  height: 56px;
  margin-bottom: 14px;
  border-radius: 50%;
  background: var(--bs-body-bg);
  border: 1px solid var(--bs-border-color);
  color: var(--bs-primary);
  font-size: 24px;
}

/* ============================================================
   18. STUDENT DIGITAL TWIN  —  prefix `sdt-`

   The third family in this library. Where the others are instruments,
   this one is a dossier: a document about one person.

     aix-  enclosed cards, hairline dividers, chevron steppers
     atn-  banded surfaces, a vertical spine, stations, arc gauges
     sdt-  a portrait medallion, outlined chapter numerals, a date
           gutter, qualitative dot scales and tinted borderless panels

   Nothing here overrides an `aix-` or `atn-` rule.
   ============================================================ */
@media (prefers-reduced-motion: reduce) {
  [class*=sdt-],
  [class*=sdt-]::before,
  [class*=sdt-]::after {
    animation: none !important;
    transition: none !important;
  }
}
/* ---- chapter headings --------------------------------------------------
   A large outlined numeral rather than a rule or an icon tile, so the page
   reads as a bound document with chapters. */
.sdt-chapter {
  display: flex;
  align-items: center;
  gap: 18px;
  margin-bottom: 26px;
}

.sdt-chapter-n {
  flex-shrink: 0;
  font-size: 46px;
  font-weight: 700;
  line-height: 1;
  letter-spacing: -0.03em;
  color: transparent;
  -webkit-text-stroke: 1.5px var(--bs-border-color);
}
@media (max-width: 575.98px) {
  .sdt-chapter-n {
    font-size: 34px;
  }
}

.sdt-chapter-title {
  margin: 0;
  font-size: 21px;
  font-weight: 600;
  letter-spacing: -0.01em;
  color: var(--bs-emphasis-color);
}

.sdt-chapter-sub {
  margin: 3px 0 0;
  font-size: 13px;
  color: var(--bs-secondary-color);
  max-width: 680px;
}

/* ---- shared small pieces ---------------------------------------------- */
.sdt-lbl {
  display: block;
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.07em;
  text-transform: uppercase;
  color: var(--bs-secondary-color);
}

.sdt-tag {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  padding: 4px 11px;
  border-radius: 6px;
  font-size: 11px;
  font-weight: 600;
  background: var(--bs-secondary-bg);
  color: var(--bs-emphasis-color);
  border: 1px solid var(--bs-border-color);
}
.sdt-tag i {
  font-size: 13px;
}
.sdt-tag.is-ai {
  background: var(--tint-primary);
  border-color: rgba(61, 94, 225, 0.2);
  color: var(--bs-primary);
}
.sdt-tag.is-up {
  background: #E8F9E8;
  border-color: #D1F2D1;
  color: #1ABE17;
}
.sdt-tag.is-flat {
  background: #E7F1FC;
  border-color: #CFE2FA;
  color: #0F65CD;
}
.sdt-tag.is-down {
  background: #FEF8EA;
  border-color: #FDF1D6;
  color: #EAB300;
}
.sdt-tag.is-alert {
  background: #FDE9ED;
  border-color: #FAD4DA;
  color: #E82646;
}

/* qualitative scale — five dots, no numbers */
.sdt-dots {
  display: inline-flex;
  gap: 4px;
}
.sdt-dots i {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--bs-tertiary-bg);
}
.sdt-dots i.on {
  background: var(--bs-primary);
}
.sdt-dots.is-up i.on {
  background: #1ABE17;
}
.sdt-dots.is-down i.on {
  background: #EAB300;
}

/* ============================================================
   HERO — a dossier: portrait medallion, identity, vertical score column
   ============================================================ */
.sdt-hero {
  position: relative;
  overflow: hidden;
  border-radius: var(--radius);
  background: linear-gradient(115deg, #F2F5FF 0%, var(--bs-body-bg) 46%, var(--bs-body-bg) 100%);
  border: 1px solid var(--bs-border-color);
  box-shadow: var(--shadow);
}

/* a soft diagonal wash across the right side, no image needed */
.sdt-hero::after {
  content: "";
  position: absolute;
  right: -120px;
  top: -140px;
  width: 420px;
  height: 420px;
  border-radius: 50%;
  background: radial-gradient(circle, rgba(2, 168, 181, 0.12) 0%, rgba(2, 168, 181, 0) 68%);
  pointer-events: none;
}

.sdt-hero-inner {
  position: relative;
  display: grid;
  grid-template-columns: 186px minmax(0, 1fr) 172px;
  gap: 30px;
  padding: 28px;
}
@media (max-width: 1199.98px) {
  .sdt-hero-inner {
    grid-template-columns: 152px minmax(0, 1fr);
  }
}
@media (max-width: 767.98px) {
  .sdt-hero-inner {
    grid-template-columns: minmax(0, 1fr);
    gap: 24px;
    padding: 22px;
  }
}

/* portrait medallion with an orbiting trait ring */
.sdt-medallion {
  position: relative;
  width: 152px;
  height: 152px;
  margin: 0 auto;
}
.sdt-medallion img {
  position: absolute;
  inset: 16px;
  width: calc(100% - 32px);
  height: calc(100% - 32px);
  border-radius: 50%;
  object-fit: cover;
  border: 3px solid var(--bs-body-bg);
  box-shadow: var(--shadow-lift);
}
.sdt-medallion {
  /* the ring */
}
.sdt-medallion::before {
  content: "";
  position: absolute;
  inset: 0;
  border-radius: 50%;
  background: conic-gradient(from 200deg, var(--bs-primary) 0deg calc(var(--p, 0) * 3.6deg), var(--bs-tertiary-bg) calc(var(--p, 0) * 3.6deg) 360deg);
  -webkit-mask: radial-gradient(farthest-side, transparent calc(100% - 5px), #000 calc(100% - 5px));
  mask: radial-gradient(farthest-side, transparent calc(100% - 5px), #000 calc(100% - 5px));
}
@media (max-width: 1199.98px) {
  .sdt-medallion {
    width: 132px;
    height: 132px;
  }
}

.sdt-medallion-badge {
  position: absolute;
  left: 50%;
  bottom: -10px;
  transform: translateX(-50%);
  display: inline-flex;
  align-items: center;
  gap: 5px;
  padding: 4px 11px;
  border-radius: 999px;
  background: var(--bs-body-bg);
  border: 1px solid var(--bs-border-color);
  box-shadow: var(--shadow);
  font-size: 11px;
  font-weight: 600;
  white-space: nowrap;
  color: var(--bs-primary);
}

.sdt-hero-name {
  margin: 0 0 4px;
  font-size: 30px;
  font-weight: 600;
  letter-spacing: -0.02em;
  line-height: 1.2;
  color: var(--bs-emphasis-color);
}
@media (max-width: 767.98px) {
  .sdt-hero-name {
    font-size: 24px;
  }
}

.sdt-hero-lede {
  margin: 14px 0 0;
  font-size: 14px;
  line-height: 1.65;
  color: var(--bs-secondary-color);
}
.sdt-hero-lede b {
  font-weight: 600;
  color: var(--bs-emphasis-color);
}

/* the facts sit as a definition strip, no boxes */
.sdt-hero-strip {
  display: flex;
  flex-wrap: wrap;
  gap: 18px 30px;
  margin-top: 18px;
  padding-top: 16px;
  border-top: 1px solid var(--bs-border-color);
}

.sdt-hero-fact {
  display: flex;
  flex-direction: column;
  gap: 3px;
  line-height: 1.3;
}
.sdt-hero-fact span:last-child {
  font-size: 14px;
  font-weight: 600;
  color: var(--bs-emphasis-color);
}

/* vertical intelligence score column */
.sdt-score {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 12px;
  padding: 18px 14px;
  border-radius: var(--radius);
  background: var(--bs-body-bg);
  border: 1px solid var(--bs-border-color);
  box-shadow: var(--aix-glow);
}
@media (max-width: 1199.98px) {
  .sdt-score {
    grid-column: 1/-1;
    flex-direction: row;
    align-items: center;
    justify-content: space-between;
  }
}

.sdt-score-val {
  font-size: 34px;
  font-weight: 700;
  line-height: 1;
  font-variant-numeric: tabular-nums;
  letter-spacing: -0.02em;
  color: var(--bs-emphasis-color);
}
.sdt-score-val small {
  font-size: 13px;
  font-weight: 500;
  color: var(--bs-secondary-color);
}

/* stacked segments, filled from the bottom */
.sdt-score-col {
  display: flex;
  flex-direction: column-reverse;
  gap: 4px;
  width: 34px;
  height: 132px;
}
.sdt-score-col i {
  flex: 1 1 0;
  border-radius: 3px;
  background: var(--bs-tertiary-bg);
}
.sdt-score-col i.on {
  background: linear-gradient(90deg, var(--bs-primary), rgba(61, 94, 225, 0.6));
}
@media (max-width: 1199.98px) {
  .sdt-score-col {
    flex-direction: row;
    width: auto;
    flex: 1 1 auto;
    height: 26px;
    margin: 0 18px;
  }
}

/* ============================================================
   DIGITAL TWIN — trait tiles with a strand of dots
   ============================================================ */
.sdt-dna {
  position: relative;
  display: flex;
  gap: 14px;
  height: 100%;
  padding: 16px;
  border-radius: var(--radius);
  background: var(--bs-secondary-bg);
  border: 1px solid transparent;
  transition: var(--transition);
}
.sdt-dna:hover {
  background: var(--bs-body-bg);
  border-color: rgba(61, 94, 225, 0.28);
  box-shadow: var(--shadow-lift);
}

/* the strand: a vertical run of dots down the left edge */
.sdt-strand {
  flex-shrink: 0;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 5px;
  padding-top: 4px;
}
.sdt-strand i {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: var(--bs-tertiary-bg);
}
.sdt-strand i.on {
  background: var(--bs-primary);
}
.sdt-strand.is-up i.on {
  background: #1ABE17;
}
.sdt-strand.is-down i.on {
  background: #EAB300;
}
.sdt-strand.is-alert i.on {
  background: #E82646;
}

.sdt-dna-title {
  margin: 0 0 3px;
  font-size: 14px;
  font-weight: 600;
  color: var(--bs-emphasis-color);
}

.sdt-dna-val {
  display: block;
  margin-bottom: 7px;
  font-size: 15px;
  font-weight: 600;
  color: var(--bs-primary);
}

.sdt-dna-txt {
  margin: 0;
  font-size: 12.5px;
  line-height: 1.6;
  color: var(--bs-secondary-color);
}

/* ============================================================
   LENS — explainable AI as a two-column reading panel
   ============================================================ */
.sdt-lens {
  display: grid;
  grid-template-columns: 232px minmax(0, 1fr);
  height: 100%;
  border-radius: var(--radius);
  background: var(--bs-body-bg);
  border: 1px solid var(--bs-border-color);
  overflow: hidden;
  transition: var(--transition);
}
.sdt-lens:hover {
  box-shadow: var(--shadow-lift);
}
@media (max-width: 767.98px) {
  .sdt-lens {
    grid-template-columns: minmax(0, 1fr);
  }
}

/* left face carries the observation and its direction */
.sdt-lens-face {
  display: flex;
  flex-direction: column;
  justify-content: center;
  gap: 10px;
  padding: 20px;
  background: var(--bs-secondary-bg);
  border-right: 1px solid var(--bs-border-color);
}
@media (max-width: 767.98px) {
  .sdt-lens-face {
    border-right: 0;
    border-bottom: 1px solid var(--bs-border-color);
  }
}

.sdt-lens-ic {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 44px;
  height: 44px;
  border-radius: var(--radius-sm);
  background: var(--bs-body-bg);
  border: 1px solid var(--bs-border-color);
  font-size: 21px;
  color: var(--bs-primary);
}
.sdt-lens-ic.is-up {
  color: #1ABE17;
}
.sdt-lens-ic.is-down {
  color: #EAB300;
}
.sdt-lens-ic.is-alert {
  color: #E82646;
}

.sdt-lens-obs {
  margin: 0;
  font-size: 16px;
  font-weight: 600;
  line-height: 1.35;
  color: var(--bs-emphasis-color);
}

.sdt-lens-body {
  padding: 20px;
}

.sdt-lens-why {
  margin: 0 0 14px;
  font-size: 13.5px;
  line-height: 1.68;
  color: var(--bs-secondary-color);
}

/* evidence reads as a short cited list */
.sdt-ev {
  display: flex;
  align-items: flex-start;
  gap: 9px;
  padding: 7px 0;
  font-size: 12.5px;
  color: var(--bs-emphasis-color);
}
.sdt-ev + .sdt-ev {
  border-top: 1px dashed var(--bs-border-color);
}
.sdt-ev i {
  flex-shrink: 0;
  margin-top: 2px;
  font-size: 14px;
  color: var(--bs-secondary-color);
}

.sdt-lens-foot {
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 14px;
  margin-top: 16px;
  padding-top: 14px;
  border-top: 1px solid var(--bs-border-color);
}

/* ============================================================
   JOURNEY — a wide date gutter with the line between
   ============================================================ */
.sdt-journey {
  position: relative;
}

.sdt-leg {
  position: relative;
  display: grid;
  grid-template-columns: 116px 34px minmax(0, 1fr);
  gap: 0;
}
@media (max-width: 575.98px) {
  .sdt-leg {
    grid-template-columns: 0 30px minmax(0, 1fr);
  }
}

.sdt-leg-date {
  padding: 16px 16px 16px 0;
  text-align: right;
  line-height: 1.35;
}
.sdt-leg-date span:first-child {
  display: block;
  font-size: 13px;
  font-weight: 600;
  color: var(--bs-emphasis-color);
}
.sdt-leg-date span:last-child {
  display: block;
  font-size: 11px;
  color: var(--bs-secondary-color);
}
@media (max-width: 575.98px) {
  .sdt-leg-date {
    display: none;
  }
}

/* the rule and its knot live in the middle column */
.sdt-leg-rule {
  position: relative;
}
.sdt-leg-rule::before {
  content: "";
  position: absolute;
  left: 50%;
  top: 0;
  bottom: 0;
  width: 2px;
  margin-left: -1px;
  background: var(--bs-border-color);
}
.sdt-leg-rule::after {
  content: "";
  position: absolute;
  left: 50%;
  top: 22px;
  transform: translateX(-50%);
  width: 13px;
  height: 13px;
  border-radius: 50%;
  background: var(--bs-body-bg);
  border: 3px solid var(--bs-primary);
}

.sdt-leg:first-child .sdt-leg-rule::before {
  top: 22px;
}

.sdt-leg:last-child .sdt-leg-rule::before {
  bottom: calc(100% - 22px);
}

.sdt-leg.is-good .sdt-leg-rule::after {
  border-color: #1ABE17;
}

.sdt-leg.is-warn .sdt-leg-rule::after {
  border-color: #EAB300;
}

.sdt-leg.is-alert .sdt-leg-rule::after {
  border-color: #E82646;
}

.sdt-leg.is-now .sdt-leg-rule::after {
  box-shadow: 0 0 0 4px var(--tint-primary);
}

.sdt-leg-card {
  margin: 8px 0 8px 16px;
  padding: 14px 16px;
  border-radius: var(--radius);
  background: var(--bs-secondary-bg);
  border: 1px solid transparent;
  transition: var(--transition);
}
.sdt-leg-card:hover {
  background: var(--bs-body-bg);
  border-color: var(--bs-border-color);
  box-shadow: var(--shadow);
}

.sdt-leg-title {
  margin: 0 0 3px;
  font-size: 14px;
  font-weight: 600;
  color: var(--bs-emphasis-color);
}

/* ============================================================
   LEARNING INTELLIGENCE — words, not figures
   ============================================================ */
.sdt-learn {
  height: 100%;
  padding: 18px;
  border-radius: var(--radius);
  background: var(--bs-body-bg);
  border: 1px solid var(--bs-border-color);
  transition: var(--transition);
}
.sdt-learn:hover {
  border-color: rgba(61, 94, 225, 0.28);
  box-shadow: var(--shadow-lift);
}

.sdt-learn-head {
  display: flex;
  align-items: center;
  gap: 11px;
  margin-bottom: 12px;
}

.sdt-learn-ic {
  flex-shrink: 0;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 36px;
  height: 36px;
  border-radius: 50%;
  background: var(--tint-primary);
  color: var(--bs-primary);
  font-size: 17px;
}

.sdt-learn-title {
  margin: 0;
  font-size: 14px;
  font-weight: 600;
  color: var(--bs-emphasis-color);
}

.sdt-learn-verdict {
  display: block;
  margin-bottom: 8px;
  font-size: 18px;
  font-weight: 600;
  letter-spacing: -0.01em;
  color: var(--bs-emphasis-color);
}

.sdt-learn-txt {
  margin: 0 0 14px;
  font-size: 12.5px;
  line-height: 1.6;
  color: var(--bs-secondary-color);
}

/* ============================================================
   RECOMMENDATIONS — a ribbon down the left edge
   ============================================================ */
.sdt-rec {
  position: relative;
  height: 100%;
  padding: 18px 18px 18px 24px;
  border-radius: var(--radius);
  background: var(--bs-body-bg);
  border: 1px solid var(--bs-border-color);
  overflow: hidden;
  transition: var(--transition);
}
.sdt-rec::before {
  content: "";
  position: absolute;
  left: 0;
  top: 0;
  bottom: 0;
  width: 5px;
  background: var(--bs-primary);
}
.sdt-rec.is-critical::before {
  background: #E82646;
}
.sdt-rec.is-high::before {
  background: #EAB300;
}
.sdt-rec.is-normal::before {
  background: #0F65CD;
}
.sdt-rec:hover {
  box-shadow: var(--shadow-lift);
}

.sdt-rec-title {
  margin: 0 0 5px;
  font-size: 15px;
  font-weight: 600;
  color: var(--bs-emphasis-color);
}

.sdt-rec-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 12px;
  margin: 14px 0;
  padding: 12px 0;
  border-top: 1px solid var(--bs-border-color);
  border-bottom: 1px solid var(--bs-border-color);
}
@media (max-width: 575.98px) {
  .sdt-rec-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}

.sdt-cell {
  display: flex;
  flex-direction: column;
  gap: 3px;
  line-height: 1.3;
}
.sdt-cell span:last-child {
  font-size: 13px;
  font-weight: 600;
  color: var(--bs-emphasis-color);
}

/* ============================================================
   GROWTH STORY — quoted narrative cards
   ============================================================ */
.sdt-story {
  position: relative;
  height: 100%;
  padding: 20px 20px 20px 22px;
  border-radius: var(--radius);
  background: linear-gradient(165deg, var(--tint-primary) 0%, var(--bs-body-bg) 58%);
  border: 1px solid var(--bs-border-color);
  overflow: hidden;
  /* an opening quotation mark set in the corner */
}
.sdt-story::before {
  content: "“";
  position: absolute;
  right: 12px;
  top: -14px;
  font-size: 88px;
  line-height: 1;
  font-weight: 700;
  color: var(--bs-border-color);
  pointer-events: none;
}
.sdt-story.is-good {
  background: linear-gradient(165deg, #E8F9E8 0%, var(--bs-body-bg) 58%);
}
.sdt-story.is-warn {
  background: linear-gradient(165deg, #FEF8EA 0%, var(--bs-body-bg) 58%);
}

.sdt-story-title {
  position: relative;
  margin: 0 0 10px;
  font-size: 15px;
  font-weight: 600;
  color: var(--bs-emphasis-color);
}

.sdt-story-txt {
  position: relative;
  margin: 0;
  font-size: 13px;
  line-height: 1.68;
  color: var(--bs-secondary-color);
}

/* ============================================================
   COPILOT — launcher rows with a trailing arrow
   ============================================================ */
.sdt-do {
  display: flex;
  align-items: center;
  gap: 14px;
  height: 100%;
  padding: 15px 16px;
  border-radius: var(--radius);
  background: var(--bs-body-bg);
  border: 1px solid var(--bs-border-color);
  transition: var(--transition);
}
.sdt-do:hover {
  border-color: rgba(61, 94, 225, 0.3);
  box-shadow: var(--aix-glow);
}
.sdt-do:hover .sdt-do-ic {
  background: var(--bs-primary);
  border-color: var(--bs-primary);
  color: #fff;
}
.sdt-do:hover .sdt-do-go {
  transform: translateX(3px);
  color: var(--bs-primary);
}

.sdt-do-ic {
  flex-shrink: 0;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 40px;
  height: 40px;
  border-radius: var(--radius-sm);
  background: var(--tint-primary);
  border: 1px solid transparent;
  color: var(--bs-primary);
  font-size: 19px;
  transition: var(--transition);
}

.sdt-do-go {
  flex-shrink: 0;
  font-size: 17px;
  color: var(--bs-secondary-color);
  transition: var(--transition);
}

/* ============================================================
   FEED — a time gutter down the left
   ============================================================ */
.sdt-feed {
  border-radius: var(--radius);
  background: var(--bs-body-bg);
  border: 1px solid var(--bs-border-color);
  overflow: hidden;
}

.sdt-feed-row {
  display: grid;
  grid-template-columns: 96px 40px minmax(0, 1fr);
  align-items: center;
  transition: var(--transition);
}
.sdt-feed-row + .sdt-feed-row {
  border-top: 1px solid var(--bs-border-color);
}
.sdt-feed-row:hover {
  background: var(--bs-secondary-bg);
}
@media (max-width: 575.98px) {
  .sdt-feed-row {
    grid-template-columns: 64px 36px minmax(0, 1fr);
  }
}

.sdt-feed-when {
  padding: 14px 12px;
  text-align: right;
  font-size: 11.5px;
  line-height: 1.35;
  color: var(--bs-secondary-color);
  border-right: 1px solid var(--bs-border-color);
}
.sdt-feed-when b {
  display: block;
  font-weight: 600;
  color: var(--bs-emphasis-color);
}

.sdt-feed-ic {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 28px;
  height: 28px;
  margin: 0 auto;
  border-radius: 50%;
  background: var(--tint-primary);
  color: var(--bs-primary);
  font-size: 14px;
}
.sdt-feed-ic.is-good {
  background: #E8F9E8;
  color: #1ABE17;
}
.sdt-feed-ic.is-warn {
  background: #FEF8EA;
  color: #EAB300;
}

.sdt-feed-txt {
  padding: 13px 16px;
}
.sdt-feed-txt p {
  margin: 0;
  font-size: 13px;
  color: var(--bs-emphasis-color);
}
.sdt-feed-txt small {
  display: block;
  margin-top: 2px;
  font-size: 12px;
  color: var(--bs-secondary-color);
}

/* ============================================================
   OPPORTUNITIES — poster tiles with a tinted cap
   ============================================================ */
.sdt-opp {
  display: flex;
  flex-direction: column;
  height: 100%;
  border-radius: var(--radius);
  background: var(--bs-body-bg);
  border: 1px solid var(--bs-border-color);
  overflow: hidden;
  transition: var(--transition);
}
.sdt-opp:hover {
  transform: translateY(-3px);
  box-shadow: var(--shadow-lift);
}

.sdt-opp-cap {
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
  height: 74px;
  background: linear-gradient(135deg, var(--bs-primary), rgba(61, 94, 225, 0.62));
  color: #fff;
  font-size: 28px;
  /* a faint ring behind the glyph */
}
.sdt-opp-cap::before {
  content: "";
  position: absolute;
  width: 68px;
  height: 68px;
  border-radius: 50%;
  border: 1px solid rgba(255, 255, 255, 0.25);
}
.sdt-opp-cap.is-teal {
  background: linear-gradient(135deg, #02a8b5, rgba(2, 168, 181, 0.62));
}
.sdt-opp-cap.is-amber {
  background: linear-gradient(135deg, #EAB300, rgba(234, 179, 0, 0.62));
}
.sdt-opp-cap.is-green {
  background: linear-gradient(135deg, #1ABE17, rgba(26, 190, 23, 0.62));
}

.sdt-opp-body {
  display: flex;
  flex-direction: column;
  flex: 1 1 auto;
  padding: 16px;
}

.sdt-opp-title {
  margin: 0 0 5px;
  font-size: 14px;
  font-weight: 600;
  color: var(--bs-emphasis-color);
}

/* ============================================================
   WORKSPACE OFFCANVAS — ribbon stepper with an underline indicator
   ============================================================ */
.offcanvas.offcanvas-end.sdt-ws {
  width: 85% !important;
  max-width: 1380px !important;
}
@media (max-width: 991.98px) {
  .offcanvas.offcanvas-end.sdt-ws {
    width: 100% !important;
  }
}
.offcanvas.offcanvas-end.sdt-ws .offcanvas-body {
  padding: 22px;
}

.sdt-ws-head {
  display: flex;
  align-items: center;
  gap: 18px;
  flex-wrap: wrap;
  padding: 20px 22px;
  background: linear-gradient(115deg, #F2F5FF 0%, var(--bs-body-bg) 60%);
  border-bottom: 1px solid var(--bs-border-color);
}

.sdt-ribbon {
  display: grid;
  grid-template-columns: repeat(5, minmax(0, 1fr));
  list-style: none;
  margin: 0;
  padding: 0 22px;
  background: var(--bs-body-bg);
  border-bottom: 1px solid var(--bs-border-color);
}
@media (max-width: 767.98px) {
  .sdt-ribbon {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}

.sdt-rib {
  position: relative;
  display: block;
  width: 100%;
  padding: 14px 10px;
  border: 0;
  background: transparent;
  text-align: left;
  transition: var(--transition);
  /* the underline indicator */
}
.sdt-rib::after {
  content: "";
  position: absolute;
  left: 10px;
  right: 10px;
  bottom: -1px;
  height: 2px;
  background: transparent;
  transition: var(--transition);
}
.sdt-rib span:first-child {
  display: block;
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--bs-secondary-color);
}
.sdt-rib span:last-child {
  display: block;
  margin-top: 2px;
  font-size: 14px;
  font-weight: 600;
  color: var(--bs-secondary-color);
}
.sdt-rib:hover span:last-child {
  color: var(--bs-emphasis-color);
}
.sdt-rib.active::after {
  background: var(--bs-primary);
}
.sdt-rib.active span:first-child {
  color: var(--bs-primary);
}
.sdt-rib.active span:last-child {
  color: var(--bs-emphasis-color);
}

/* panels inside the workspace */
.sdt-box {
  height: 100%;
  padding: 18px;
  border-radius: var(--radius);
  background: var(--bs-body-bg);
  border: 1px solid var(--bs-border-color);
}

.sdt-box-title {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  margin: 0 0 14px;
  font-size: 13px;
  font-weight: 600;
  letter-spacing: 0.05em;
  text-transform: uppercase;
  color: var(--bs-secondary-color);
}

/* a labelled line used throughout the workspace */
.sdt-line {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 9px 0;
  font-size: 13px;
  color: var(--bs-emphasis-color);
}
.sdt-line + .sdt-line {
  border-top: 1px dashed var(--bs-border-color);
}
.sdt-line b {
  font-weight: 600;
}

/* thin labelled meter */
.sdt-meter {
  display: block;
  height: 6px;
  border-radius: 3px;
  background: linear-gradient(90deg, var(--bs-primary) 0 calc(var(--p, 0) * 1%), var(--bs-tertiary-bg) calc(var(--p, 0) * 1%) 100%);
}
.sdt-meter.is-good {
  background: linear-gradient(90deg, #1ABE17 0 calc(var(--p, 0) * 1%), var(--bs-tertiary-bg) calc(var(--p, 0) * 1%) 100%);
}

/* ============================================================
   PREMIUM ACCORDION + EMPTY STATE
   ============================================================ */
.sdt-acc .accordion-item {
  margin-bottom: 12px;
  border: 1px solid var(--bs-border-color);
  border-radius: var(--radius) !important;
  overflow: hidden;
  background: var(--bs-body-bg);
}
.sdt-acc .accordion-button {
  padding: 15px 18px;
  font-size: 14px;
  font-weight: 600;
  color: var(--bs-emphasis-color);
  background: var(--bs-body-bg);
  box-shadow: none;
}
.sdt-acc .accordion-button:not(.collapsed) {
  background: var(--tint-primary);
  color: var(--bs-primary);
}
.sdt-acc .accordion-button:focus {
  box-shadow: none;
}
.sdt-acc .accordion-body {
  padding: 16px 18px;
  font-size: 13px;
  line-height: 1.65;
  color: var(--bs-secondary-color);
}

.sdt-empty {
  padding: 44px 24px;
  text-align: center;
  border-radius: var(--radius);
  background: radial-gradient(80% 100% at 50% 0%, var(--tint-primary) 0%, transparent 70%), var(--bs-body-bg);
  border: 1px dashed var(--bs-border-color);
}

.sdt-empty-ic {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 58px;
  height: 58px;
  margin-bottom: 14px;
  border-radius: 18px;
  background: var(--bs-body-bg);
  border: 1px solid var(--bs-border-color);
  box-shadow: var(--shadow);
  color: var(--bs-primary);
  font-size: 25px;
}

/* ============================================================
   19. TIMETABLE OPTIMIZATION  —  prefix `tto-`

   The fourth family. Its subject is a grid of time, so its language is
   built from slots, tracks and segments rather than from cards about people.

     aix-  enclosed cards, hairline dividers, chevron steppers
     atn-  banded surfaces, a vertical spine, stations, arc gauges
     sdt-  portrait medallion, chapter numerals, date gutter, dot scales
     tto-  slot grids, bracketed section marks, before/after bars,
           collision headers, a horizontal track and segmented steppers

   Nothing here overrides a rule from the families above.
   ============================================================ */
@media (prefers-reduced-motion: reduce) {
  [class*=tto-],
  [class*=tto-]::before,
  [class*=tto-]::after {
    animation: none !important;
    transition: none !important;
  }
}
/* ---- section marks ----------------------------------------------------
   A bracketed number set inline with the title and a rule running to the
   right edge, so sections read like console headings. */
.tto-mark {
  display: flex;
  align-items: center;
  gap: 16px;
  margin-bottom: 24px;
}
@media (max-width: 767.98px) {
  .tto-mark {
    flex-wrap: wrap;
  }
}

.tto-mark-n {
  flex-shrink: 0;
  padding: 5px 11px;
  border-radius: 6px;
  background: var(--bs-emphasis-color);
  color: #fff;
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.14em;
  font-variant-numeric: tabular-nums;
}

.tto-mark-title {
  margin: 0;
  font-size: 20px;
  font-weight: 600;
  letter-spacing: -0.01em;
  color: var(--bs-emphasis-color);
  white-space: nowrap;
}

.tto-mark-rule {
  flex: 1 1 auto;
  height: 1px;
  background: var(--bs-border-color);
}
@media (max-width: 767.98px) {
  .tto-mark-rule {
    display: none;
  }
}

.tto-mark-sub {
  margin: -16px 0 24px;
  font-size: 13px;
  color: var(--bs-secondary-color);
  max-width: 700px;
}

/* ---- shared pieces ----------------------------------------------------- */
.tto-lbl {
  display: block;
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.07em;
  text-transform: uppercase;
  color: var(--bs-secondary-color);
}

.tto-chip {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  padding: 4px 10px;
  border-radius: 5px;
  font-size: 11px;
  font-weight: 600;
  background: var(--bs-secondary-bg);
  border: 1px solid var(--bs-border-color);
  color: var(--bs-emphasis-color);
  white-space: nowrap;
}
.tto-chip i {
  font-size: 13px;
}
.tto-chip.is-ai {
  background: var(--tint-primary);
  border-color: rgba(61, 94, 225, 0.2);
  color: var(--bs-primary);
}
.tto-chip.is-crit {
  background: #FDE9ED;
  border-color: #FAD4DA;
  color: #E82646;
}
.tto-chip.is-warn {
  background: #FEF8EA;
  border-color: #FDF1D6;
  color: #EAB300;
}
.tto-chip.is-info {
  background: #E7F1FC;
  border-color: #CFE2FA;
  color: #0F65CD;
}
.tto-chip.is-ok {
  background: #E8F9E8;
  border-color: #D1F2D1;
  color: #1ABE17;
}

/* confidence readout: figure with a filled rule beneath */
.tto-conf {
  display: inline-flex;
  flex-direction: column;
  gap: 4px;
  min-width: 58px;
}
.tto-conf b {
  font-size: 14px;
  font-weight: 600;
  font-variant-numeric: tabular-nums;
  color: var(--bs-emphasis-color);
  line-height: 1;
}
.tto-conf::after {
  content: "";
  height: 3px;
  border-radius: 2px;
  background: linear-gradient(90deg, var(--bs-primary) 0 calc(var(--p, 0) * 1%), var(--bs-tertiary-bg) calc(var(--p, 0) * 1%) 100%);
}

/* ============================================================
   HERO — copy on the left, a live slot grid on the right
   ============================================================ */
.tto-hero {
  position: relative;
  overflow: hidden;
  border-radius: var(--radius);
  background: linear-gradient(135deg, var(--bs-body-bg) 0%, var(--bs-body-bg) 52%, #F2F5FF 100%);
  border: 1px solid var(--bs-border-color);
  box-shadow: var(--shadow);
}

/* a faint ruled backdrop, like a period grid seen through paper */
.tto-hero::before {
  content: "";
  position: absolute;
  inset: 0;
  background-image: repeating-linear-gradient(90deg, var(--bs-border-color) 0 1px, transparent 1px 84px);
  opacity: 0.5;
  mask-image: linear-gradient(180deg, #000 0%, transparent 80%);
  pointer-events: none;
}

.tto-hero-inner {
  position: relative;
  display: grid;
  grid-template-columns: minmax(0, 1fr) 380px;
  gap: 34px;
  padding: 28px;
}
@media (max-width: 1299.98px) {
  .tto-hero-inner {
    grid-template-columns: minmax(0, 1fr);
    gap: 26px;
  }
}
@media (max-width: 575.98px) {
  .tto-hero-inner {
    padding: 22px;
  }
}

.tto-hero-badge {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 5px 12px;
  border-radius: 6px;
  background: var(--bs-emphasis-color);
  color: #fff;
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.1em;
  text-transform: uppercase;
}

.tto-hero-title {
  margin: 14px 0 10px;
  font-size: 30px;
  line-height: 1.22;
  font-weight: 600;
  letter-spacing: -0.02em;
  color: var(--bs-emphasis-color);
}
.tto-hero-title em {
  font-style: normal;
  background: linear-gradient(90deg, var(--bs-primary), #02a8b5);
  -webkit-background-clip: text;
  background-clip: text;
  -webkit-text-fill-color: transparent;
}
@media (max-width: 767.98px) {
  .tto-hero-title {
    font-size: 24px;
  }
}

/* status readouts on one ruled line, no boxes */
.tto-hero-read {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 16px;
  margin-top: 20px;
  padding: 16px 0;
  border-top: 1px solid var(--bs-border-color);
  border-bottom: 1px solid var(--bs-border-color);
}
@media (max-width: 767.98px) {
  .tto-hero-read {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}

.tto-read {
  display: flex;
  flex-direction: column;
  gap: 4px;
  line-height: 1.25;
}
.tto-read b {
  font-size: 19px;
  font-weight: 600;
  font-variant-numeric: tabular-nums;
  color: var(--bs-emphasis-color);
}
.tto-read b small {
  font-size: 12px;
  font-weight: 500;
  color: var(--bs-secondary-color);
}

/* ---- the illustration: a slot grid with conflicts lit up ---- */
.tto-grid-art {
  display: flex;
  flex-direction: column;
  gap: 14px;
  padding: 18px;
  border-radius: var(--radius);
  background: var(--bs-body-bg);
  border: 1px solid var(--bs-border-color);
  box-shadow: var(--aix-glow);
}

.tto-slots {
  display: grid;
  grid-template-columns: repeat(8, minmax(0, 1fr));
  gap: 5px;
}
.tto-slots i {
  aspect-ratio: 1;
  border-radius: 4px;
  background: var(--bs-secondary-bg);
  border: 1px solid var(--bs-border-color);
}
.tto-slots i.f {
  background: var(--tint-primary);
  border-color: rgba(61, 94, 225, 0.22);
}
.tto-slots i.g {
  background: rgba(61, 94, 225, 0.55);
  border-color: transparent;
}
.tto-slots i.x {
  background: #E82646;
  border-color: transparent;
  animation: tto-flash 2.6s ease-in-out infinite;
}
.tto-slots i.w {
  background: #EAB300;
  border-color: transparent;
}
.tto-slots i.o {
  background: #1ABE17;
  border-color: transparent;
}

@keyframes tto-flash {
  0%, 100% {
    opacity: 1;
  }
  50% {
    opacity: 0.45;
  }
}
.tto-legend {
  display: flex;
  flex-wrap: wrap;
  gap: 6px 14px;
  font-size: 11px;
  color: var(--bs-secondary-color);
}
.tto-legend span {
  display: inline-flex;
  align-items: center;
  gap: 5px;
}
.tto-legend i {
  width: 9px;
  height: 9px;
  border-radius: 2px;
  background: var(--bs-tertiary-bg);
}
.tto-legend i.f {
  background: var(--tint-primary);
}
.tto-legend i.g {
  background: rgba(61, 94, 225, 0.55);
}
.tto-legend i.x {
  background: #E82646;
}
.tto-legend i.o {
  background: #1ABE17;
}

/* ============================================================
   OPTIMIZATION CARDS — a before/after pair of bars
   ============================================================ */
.tto-opt {
  display: flex;
  flex-direction: column;
  height: 100%;
  padding: 18px;
  border-radius: var(--radius);
  background: var(--bs-body-bg);
  border: 1px solid var(--bs-border-color);
  transition: var(--transition);
}
.tto-opt:hover {
  border-color: rgba(61, 94, 225, 0.28);
  box-shadow: var(--shadow-lift);
}

.tto-opt-title {
  margin: 0;
  font-size: 15px;
  font-weight: 600;
  color: var(--bs-emphasis-color);
}

/* two stacked bars, current then optimized, on a shared scale */
.tto-ba {
  display: flex;
  flex-direction: column;
  gap: 9px;
  margin: 14px 0;
  padding: 14px;
  border-radius: var(--radius-sm);
  background: var(--bs-secondary-bg);
}

.tto-ba-row {
  display: grid;
  grid-template-columns: 68px minmax(0, 1fr) 44px;
  align-items: center;
  gap: 10px;
  font-size: 11px;
  color: var(--bs-secondary-color);
}
.tto-ba-row b {
  text-align: right;
  font-size: 12px;
  font-weight: 600;
  font-variant-numeric: tabular-nums;
  color: var(--bs-emphasis-color);
}

.tto-bar {
  height: 8px;
  border-radius: 4px;
  background: var(--bs-tertiary-bg);
  overflow: hidden;
}
.tto-bar::before {
  content: "";
  display: block;
  height: 100%;
  width: calc(var(--p, 0) * 1%);
  border-radius: 4px;
  background: #D1D6DE;
}
.tto-bar.is-after::before {
  background: linear-gradient(90deg, var(--bs-primary), #02a8b5);
}

.tto-opt-foot {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 12px;
  margin-top: auto;
  padding-top: 14px;
  border-top: 1px solid var(--bs-border-color);
}

.tto-gain {
  display: inline-flex;
  align-items: baseline;
  gap: 4px;
  font-size: 19px;
  font-weight: 600;
  font-variant-numeric: tabular-nums;
  color: #1ABE17;
}
.tto-gain small {
  font-size: 11px;
  font-weight: 500;
  color: var(--bs-secondary-color);
}

/* ============================================================
   EXPLAINABLE AI — a premium accordion
   ============================================================ */
.tto-acc .accordion-item {
  margin-bottom: 12px;
  background: var(--bs-body-bg);
  border: 1px solid var(--bs-border-color);
  border-radius: var(--radius) !important;
  overflow: hidden;
  transition: var(--transition);
}
.tto-acc .accordion-item:has(.accordion-button:not(.collapsed)) {
  border-color: rgba(61, 94, 225, 0.3);
  box-shadow: var(--shadow-lift);
}
.tto-acc .accordion-button {
  display: flex;
  align-items: center;
  gap: 14px;
  padding: 16px 18px;
  font-size: 15px;
  font-weight: 600;
  color: var(--bs-emphasis-color);
  background: var(--bs-body-bg);
  box-shadow: none;
}
.tto-acc .accordion-button:not(.collapsed) {
  background: var(--bs-secondary-bg);
  color: var(--bs-emphasis-color);
}
.tto-acc .accordion-button:focus {
  box-shadow: none;
}
.tto-acc .accordion-button::after {
  margin-left: 0;
  flex-shrink: 0;
}
.tto-acc .accordion-body {
  padding: 18px;
  border-top: 1px solid var(--bs-border-color);
}

/* the severity square that leads each accordion row */
.tto-acc-ic {
  flex-shrink: 0;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 36px;
  height: 36px;
  border-radius: var(--radius-sm);
  background: var(--tint-primary);
  color: var(--bs-primary);
  font-size: 18px;
}
.tto-acc-ic.is-crit {
  background: #FDE9ED;
  color: #E82646;
}
.tto-acc-ic.is-warn {
  background: #FEF8EA;
  color: #EAB300;
}
.tto-acc-ic.is-info {
  background: #E7F1FC;
  color: #0F65CD;
}

/* evidence lines inside the accordion body */
.tto-ev {
  display: flex;
  align-items: flex-start;
  gap: 9px;
  padding: 8px 0;
  font-size: 13px;
  color: var(--bs-emphasis-color);
}
.tto-ev + .tto-ev {
  border-top: 1px dashed var(--bs-border-color);
}
.tto-ev i {
  flex-shrink: 0;
  margin-top: 2px;
  font-size: 15px;
  color: var(--bs-secondary-color);
}

/* a boxed conclusion inside the body */
.tto-fix {
  display: flex;
  align-items: flex-start;
  gap: 12px;
  padding: 14px;
  border-radius: var(--radius-sm);
  background: var(--tint-primary);
  border: 1px solid rgba(61, 94, 225, 0.18);
}
.tto-fix i {
  flex-shrink: 0;
  margin-top: 1px;
  font-size: 18px;
  color: var(--bs-primary);
}

/* ============================================================
   CONFLICT CARDS — a collision header, two sides meeting
   ============================================================ */
.tto-clash {
  display: flex;
  flex-direction: column;
  height: 100%;
  border-radius: var(--radius);
  background: var(--bs-body-bg);
  border: 1px solid var(--bs-border-color);
  overflow: hidden;
  transition: var(--transition);
}
.tto-clash:hover {
  box-shadow: var(--shadow-lift);
}

.tto-clash-head {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 40px minmax(0, 1fr);
  align-items: center;
  gap: 8px;
  padding: 16px;
  background: var(--bs-secondary-bg);
  border-bottom: 1px solid var(--bs-border-color);
}

.tto-side {
  min-width: 0;
  padding: 10px 12px;
  border-radius: var(--radius-sm);
  background: var(--bs-body-bg);
  border: 1px solid var(--bs-border-color);
  text-align: center;
}
.tto-side span:first-child {
  display: block;
  font-size: 10px;
  font-weight: 600;
  letter-spacing: 0.07em;
  text-transform: uppercase;
  color: var(--bs-secondary-color);
}
.tto-side span:last-child {
  display: block;
  margin-top: 2px;
  font-size: 13px;
  font-weight: 600;
  color: var(--bs-emphasis-color);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

/* the collision glyph between the two sides */
.tto-vs {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 34px;
  height: 34px;
  margin: 0 auto;
  border-radius: 50%;
  background: #FDE9ED;
  border: 1px solid #FAD4DA;
  color: #E82646;
  font-size: 17px;
}
.tto-vs.is-warn {
  background: #FEF8EA;
  border-color: #FDF1D6;
  color: #EAB300;
}

.tto-clash-body {
  display: flex;
  flex-direction: column;
  gap: 12px;
  flex: 1 1 auto;
  padding: 16px;
}

.tto-clash-foot {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 12px 16px;
  background: var(--bs-secondary-bg);
  border-top: 1px solid var(--bs-border-color);
}

/* ============================================================
   OPPORTUNITY ROWS — a figure on the right, a slim gauge under
   ============================================================ */
.tto-opp {
  display: flex;
  align-items: center;
  gap: 14px;
  height: 100%;
  padding: 15px 16px;
  border-radius: var(--radius);
  background: var(--bs-body-bg);
  border: 1px solid var(--bs-border-color);
  transition: var(--transition);
}
.tto-opp:hover {
  border-color: rgba(61, 94, 225, 0.28);
  background: var(--bs-secondary-bg);
}

.tto-opp-ic {
  flex-shrink: 0;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 38px;
  height: 38px;
  border-radius: var(--radius-sm);
  background: var(--tint-primary);
  color: var(--bs-primary);
  font-size: 18px;
}

.tto-opp-fig {
  flex-shrink: 0;
  text-align: right;
}
.tto-opp-fig b {
  display: block;
  font-size: 17px;
  font-weight: 600;
  font-variant-numeric: tabular-nums;
  line-height: 1;
  color: #1ABE17;
}
.tto-opp-fig span {
  display: block;
  margin-top: 3px;
  font-size: 10px;
  font-weight: 600;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--bs-secondary-color);
}

/* ============================================================
   SCHEDULE INTELLIGENCE — one feature panel, then compact rows
   ============================================================ */
.tto-feature {
  position: relative;
  height: 100%;
  padding: 24px;
  border-radius: var(--radius);
  background: radial-gradient(120% 100% at 100% 0%, rgba(2, 168, 181, 0.14) 0%, transparent 60%), linear-gradient(160deg, var(--bs-primary) 0%, #202C4B 100%);
  color: #fff;
  overflow: hidden;
}

.tto-feature::after {
  content: "";
  position: absolute;
  right: -60px;
  bottom: -60px;
  width: 200px;
  height: 200px;
  border-radius: 50%;
  border: 1px solid rgba(255, 255, 255, 0.16);
}

.tto-feature-fig {
  display: block;
  margin: 14px 0 8px;
  font-size: 40px;
  font-weight: 700;
  line-height: 1;
  letter-spacing: -0.02em;
  font-variant-numeric: tabular-nums;
}

.tto-note {
  display: flex;
  align-items: flex-start;
  gap: 12px;
  height: 100%;
  padding: 15px 16px;
  border-radius: var(--radius);
  background: var(--bs-body-bg);
  border: 1px solid var(--bs-border-color);
  transition: var(--transition);
}
.tto-note:hover {
  box-shadow: var(--shadow);
}
.tto-note i {
  flex-shrink: 0;
  margin-top: 2px;
  font-size: 17px;
  color: var(--bs-primary);
}

.tto-note-title {
  margin: 0 0 3px;
  font-size: 13.5px;
  font-weight: 600;
  color: var(--bs-emphasis-color);
}

/* ============================================================
   COPILOT — action bars with a trailing shortcut chip
   ============================================================ */
.tto-do {
  display: flex;
  align-items: center;
  gap: 14px;
  width: 100%;
  padding: 14px 16px;
  border-radius: var(--radius);
  background: var(--bs-body-bg);
  border: 1px solid var(--bs-border-color);
  transition: var(--transition);
}
.tto-do + .tto-do {
  margin-top: 10px;
}
.tto-do:hover {
  border-color: rgba(61, 94, 225, 0.3);
  box-shadow: var(--aix-glow);
}
.tto-do:hover .tto-do-ic {
  background: var(--bs-primary);
  color: #fff;
}

.tto-do-ic {
  flex-shrink: 0;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 38px;
  height: 38px;
  border-radius: var(--radius-sm);
  background: var(--tint-primary);
  color: var(--bs-primary);
  font-size: 18px;
  transition: var(--transition);
}

/* keyboard-style shortcut mark */
.tto-key {
  flex-shrink: 0;
  padding: 3px 8px;
  border-radius: 5px;
  background: var(--bs-secondary-bg);
  border: 1px solid var(--bs-border-color);
  border-bottom-width: 2px;
  font-size: 11px;
  font-weight: 600;
  color: var(--bs-secondary-color);
}

/* ============================================================
   HORIZONTAL TIMELINE — a track running left to right
   ============================================================ */
.tto-track {
  display: grid;
  grid-template-columns: repeat(7, minmax(0, 1fr));
  gap: 10px;
}
@media (max-width: 1199.98px) {
  .tto-track {
    grid-template-columns: repeat(4, minmax(0, 1fr));
  }
}
@media (max-width: 767.98px) {
  .tto-track {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}
@media (max-width: 480px) {
  .tto-track {
    grid-template-columns: minmax(0, 1fr);
  }
}

.tto-stop {
  position: relative;
  padding-top: 40px;
  /* the rail segment reaching to the next stop */
}
.tto-stop::before {
  content: "";
  position: absolute;
  left: calc(50% + 16px);
  right: calc(-50% + 16px);
  top: 15px;
  height: 2px;
  background: var(--bs-tertiary-bg);
}
.tto-stop:last-child::before {
  display: none;
}
.tto-stop.is-done::before {
  background: #1ABE17;
}
.tto-stop {
  /* the node */
}
.tto-stop::after {
  content: "";
  position: absolute;
  left: 50%;
  top: 0;
  transform: translateX(-50%);
  width: 32px;
  height: 32px;
  border-radius: 50%;
  background: var(--bs-body-bg);
  border: 2px solid var(--bs-tertiary-bg);
}
.tto-stop.is-done::after {
  background: #1ABE17;
  border-color: #1ABE17;
}
.tto-stop.is-now::after {
  border-color: var(--bs-primary);
  box-shadow: 0 0 0 4px var(--tint-primary);
}
@media (max-width: 1199.98px) {
  .tto-stop::before {
    display: none;
  }
}

/* the glyph sits inside the node */
.tto-stop-ic {
  position: absolute;
  left: 50%;
  top: 0;
  transform: translateX(-50%);
  z-index: 1;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 32px;
  height: 32px;
  font-size: 15px;
  color: var(--bs-secondary-color);
}

.tto-stop.is-done .tto-stop-ic {
  color: #fff;
}

.tto-stop.is-now .tto-stop-ic {
  color: var(--bs-primary);
}

.tto-stop-card {
  padding: 13px 14px;
  border-radius: var(--radius);
  background: var(--bs-secondary-bg);
  border: 1px solid transparent;
  transition: var(--transition);
}
.tto-stop-card:hover {
  background: var(--bs-body-bg);
  border-color: var(--bs-border-color);
  box-shadow: var(--shadow);
}

.tto-stop-title {
  margin: 0 0 3px;
  font-size: 13px;
  font-weight: 600;
  color: var(--bs-emphasis-color);
}

/* ============================================================
   RESOURCE ROWS — a segmented availability strip
   ============================================================ */
.tto-res {
  display: grid;
  grid-template-columns: 210px minmax(0, 1fr) 116px;
  align-items: center;
  gap: 18px;
  padding: 14px 16px;
  transition: var(--transition);
}
.tto-res + .tto-res {
  border-top: 1px solid var(--bs-border-color);
}
.tto-res:hover {
  background: var(--bs-secondary-bg);
}
@media (max-width: 991.98px) {
  .tto-res {
    grid-template-columns: minmax(0, 1fr);
    gap: 10px;
  }
}

.tto-res-name {
  display: flex;
  align-items: center;
  gap: 11px;
}
.tto-res-name i {
  flex-shrink: 0;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 34px;
  height: 34px;
  border-radius: var(--radius-sm);
  background: var(--bs-secondary-bg);
  border: 1px solid var(--bs-border-color);
  color: var(--bs-primary);
  font-size: 16px;
}

/* eight periods across, coloured by load */
.tto-strip {
  display: flex;
  gap: 3px;
}
.tto-strip i {
  flex: 1 1 0;
  height: 22px;
  border-radius: 3px;
  background: var(--bs-secondary-bg);
  border: 1px solid var(--bs-border-color);
}
.tto-strip i.l1 {
  background: var(--tint-primary);
  border-color: transparent;
}
.tto-strip i.l2 {
  background: rgba(61, 94, 225, 0.45);
  border-color: transparent;
}
.tto-strip i.l3 {
  background: var(--bs-primary);
  border-color: transparent;
}
.tto-strip i.ov {
  background: #E82646;
  border-color: transparent;
}
.tto-strip i.fr {
  background: #E8F9E8;
  border-color: #D1F2D1;
}

/* ============================================================
   RECOMMENDATIONS — rank chip, body, apply footer
   ============================================================ */
.tto-rec {
  display: flex;
  flex-direction: column;
  height: 100%;
  border-radius: var(--radius);
  background: var(--bs-body-bg);
  border: 1px solid var(--bs-border-color);
  overflow: hidden;
  transition: var(--transition);
}
.tto-rec:hover {
  border-color: rgba(61, 94, 225, 0.28);
  box-shadow: var(--shadow-lift);
}

.tto-rec-head {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 14px 16px;
  border-bottom: 1px solid var(--bs-border-color);
}

.tto-rec-rank {
  flex-shrink: 0;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 30px;
  height: 30px;
  border-radius: 6px;
  background: var(--bs-emphasis-color);
  color: #fff;
  font-size: 12px;
  font-weight: 700;
  font-variant-numeric: tabular-nums;
}

.tto-rec-title {
  margin: 0;
  font-size: 14px;
  font-weight: 600;
  color: var(--bs-emphasis-color);
}

.tto-rec-body {
  flex: 1 1 auto;
  padding: 16px;
}

.tto-rec-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 12px;
  margin-top: 14px;
  padding-top: 14px;
  border-top: 1px dashed var(--bs-border-color);
}

.tto-cell {
  display: flex;
  flex-direction: column;
  gap: 3px;
  line-height: 1.3;
}
.tto-cell span:last-child {
  font-size: 13px;
  font-weight: 600;
  color: var(--bs-emphasis-color);
}

/* ============================================================
   WORKSPACE OFFCANVAS — a segmented stepper that reads as progress
   ============================================================ */
.offcanvas.offcanvas-end.tto-ws {
  width: 90% !important;
  max-width: 1460px !important;
}
@media (max-width: 991.98px) {
  .offcanvas.offcanvas-end.tto-ws {
    width: 100% !important;
  }
}
.offcanvas.offcanvas-end.tto-ws .offcanvas-body {
  padding: 22px;
}

.tto-ws-head {
  display: flex;
  align-items: center;
  gap: 18px;
  flex-wrap: wrap;
  padding: 20px 22px;
  background: linear-gradient(135deg, var(--bs-body-bg) 0%, #F2F5FF 100%);
  border-bottom: 1px solid var(--bs-border-color);
}

.tto-ws-ic {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 52px;
  height: 52px;
  flex-shrink: 0;
  border-radius: var(--radius);
  background: var(--bs-body-bg);
  border: 1px solid var(--bs-border-color);
  box-shadow: var(--shadow);
  color: var(--bs-primary);
  font-size: 24px;
}

/* the stepper is one continuous bar cut into five segments */
.tto-seg {
  display: grid;
  grid-template-columns: repeat(5, minmax(0, 1fr));
  gap: 4px;
  list-style: none;
  margin: 0;
  padding: 16px 22px;
  background: var(--bs-secondary-bg);
  border-bottom: 1px solid var(--bs-border-color);
}
@media (max-width: 767.98px) {
  .tto-seg {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}

.tto-segbtn {
  position: relative;
  display: flex;
  align-items: center;
  gap: 10px;
  width: 100%;
  padding: 10px 14px;
  border: 1px solid transparent;
  border-radius: var(--radius-sm);
  background: var(--bs-body-bg);
  text-align: left;
  transition: var(--transition);
  /* the fill rule along the bottom edge */
}
.tto-segbtn::after {
  content: "";
  position: absolute;
  left: 14px;
  right: 14px;
  bottom: 6px;
  height: 2px;
  border-radius: 1px;
  background: var(--bs-tertiary-bg);
  transition: var(--transition);
}
.tto-segbtn:hover {
  border-color: var(--bs-border-color);
}
.tto-segbtn.active {
  border-color: rgba(61, 94, 225, 0.3);
  box-shadow: var(--shadow);
}
.tto-segbtn.active::after {
  background: var(--bs-primary);
}
.tto-segbtn.active .tto-segbtn-n {
  background: var(--bs-primary);
  border-color: var(--bs-primary);
  color: #fff;
}

.tto-segbtn-n {
  flex-shrink: 0;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 28px;
  height: 28px;
  border-radius: 6px;
  background: var(--bs-secondary-bg);
  border: 1px solid var(--bs-border-color);
  color: var(--bs-secondary-color);
  font-size: 11px;
  font-weight: 700;
  font-variant-numeric: tabular-nums;
  transition: var(--transition);
}

.tto-segbtn-txt {
  display: flex;
  flex-direction: column;
  min-width: 0;
  padding-bottom: 6px;
  line-height: 1.25;
}
.tto-segbtn-txt span:first-child {
  font-size: 10px;
  font-weight: 600;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--bs-secondary-color);
}
.tto-segbtn-txt span:last-child {
  font-size: 13px;
  font-weight: 600;
  color: var(--bs-emphasis-color);
}

/* panels inside the workspace */
.tto-panel {
  height: 100%;
  border-radius: var(--radius);
  background: var(--bs-body-bg);
  border: 1px solid var(--bs-border-color);
  overflow: hidden;
}

.tto-panel-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 13px 16px;
  background: var(--bs-secondary-bg);
  border-bottom: 1px solid var(--bs-border-color);
}
.tto-panel-head h6 {
  margin: 0;
  font-size: 13px;
  font-weight: 600;
  color: var(--bs-emphasis-color);
}

.tto-panel-body {
  padding: 16px;
}

.tto-line {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 9px 0;
  font-size: 13px;
  color: var(--bs-emphasis-color);
}
.tto-line + .tto-line {
  border-top: 1px dashed var(--bs-border-color);
}
.tto-line b {
  font-weight: 600;
}

/* ============================================================
   EMPTY STATE
   ============================================================ */
.tto-empty {
  padding: 42px 24px;
  text-align: center;
  border-radius: var(--radius);
  background: var(--bs-body-bg);
  border: 1px dashed var(--bs-border-color);
}

.tto-empty-ic {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 56px;
  height: 56px;
  margin-bottom: 14px;
  border-radius: var(--radius);
  background: var(--tint-primary);
  color: var(--bs-primary);
  font-size: 25px;
}

/* ============================================================
   20. HOMEWORK EVALUATION  —  prefix `hwk-`

   The fifth family. Its subject is marked work, so its language is drawn
   from the physical review studio: ruled paper, margin bars, grade seals,
   rubric strips and hanging annotation markers.

     aix-  enclosed cards, hairline dividers, chevron steppers
     atn-  banded surfaces, a vertical spine, stations, arc gauges
     sdt-  portrait medallion, chapter numerals, date gutter, dot scales
     tto-  slot grids, bracketed marks, before/after bars, a horizontal track
     hwk-  paper sheets, margin rules, grade seals, rubric strips,
           highlighted headings and hanging annotation markers

   Nothing here overrides a rule from the families above.
   ============================================================ */
@media (prefers-reduced-motion: reduce) {
  [class*=hwk-],
  [class*=hwk-]::before,
  [class*=hwk-]::after {
    animation: none !important;
    transition: none !important;
  }
}
/* ---- section headings -------------------------------------------------
   A kicker above and a marker highlight sitting behind the last line of
   the title, the way a reviewer would underline a heading. */
.hwk-head {
  margin-bottom: 26px;
}

.hwk-kicker {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  margin-bottom: 8px;
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: var(--bs-primary);
}
.hwk-kicker::before {
  content: "";
  width: 22px;
  height: 2px;
  background: var(--bs-primary);
}

.hwk-title {
  position: relative;
  display: inline;
  margin: 0;
  font-size: 21px;
  font-weight: 600;
  letter-spacing: -0.01em;
  color: var(--bs-emphasis-color);
  background-image: linear-gradient(180deg, transparent 62%, var(--tint-primary) 62%);
  background-repeat: no-repeat;
  box-decoration-break: clone;
  -webkit-box-decoration-break: clone;
}

.hwk-sub {
  margin: 10px 0 0;
  font-size: 13px;
  color: var(--bs-secondary-color);
  max-width: 700px;
}

/* ---- shared pieces ----------------------------------------------------- */
.hwk-lbl {
  display: block;
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.07em;
  text-transform: uppercase;
  color: var(--bs-secondary-color);
}

.hwk-tag {
  /* geometry, typography and surface come from the shared badge component */
}
.hwk-tag i {
  font-size: 13px;
}
.hwk-tag.is-ai {
  background: var(--tint-primary);
  border-color: rgba(61, 94, 225, 0.2);
  color: var(--bs-primary);
}
.hwk-tag.is-strong {
  background: #E8F9E8;
  border-color: #D1F2D1;
  color: #1ABE17;
}
.hwk-tag.is-weak {
  background: #FDE9ED;
  border-color: #FAD4DA;
  color: #E82646;
}
.hwk-tag.is-mid {
  background: #FEF8EA;
  border-color: #FDF1D6;
  color: #EAB300;
}
.hwk-tag.is-note {
  background: #E7F1FC;
  border-color: #CFE2FA;
  color: #0F65CD;
}

/* the grade seal — a stamped circle */
.hwk-seal {
  display: inline-flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  width: 54px;
  height: 54px;
  flex-shrink: 0;
  border-radius: 50%;
  background: var(--bs-body-bg);
  border: 2px solid var(--bs-primary);
  color: var(--bs-primary);
  line-height: 1;
}
.hwk-seal b {
  font-size: 18px;
  font-weight: 700;
  font-variant-numeric: tabular-nums;
}
.hwk-seal span {
  margin-top: 2px;
  font-size: 8px;
  font-weight: 700;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  opacity: 0.7;
}
.hwk-seal.is-strong {
  border-color: #1ABE17;
  color: #1ABE17;
}
.hwk-seal.is-mid {
  border-color: #EAB300;
  color: #EAB300;
}
.hwk-seal.is-weak {
  border-color: #E82646;
  color: #E82646;
}

/* rubric strip — five criteria, filled by quality */
.hwk-rubric {
  display: flex;
  gap: 4px;
}
.hwk-rubric i {
  flex: 1 1 0;
  height: 5px;
  border-radius: 3px;
  background: var(--bs-tertiary-bg);
}
.hwk-rubric i.on {
  background: var(--bs-primary);
}
.hwk-rubric i.mid {
  background: #EAB300;
}
.hwk-rubric i.low {
  background: #E82646;
}

/* confidence readout */
.hwk-conf {
  display: inline-flex;
  flex-direction: column;
  gap: 4px;
  min-width: 56px;
}
.hwk-conf b {
  font-size: 14px;
  font-weight: 600;
  font-variant-numeric: tabular-nums;
  color: var(--bs-emphasis-color);
  line-height: 1;
}
.hwk-conf::after {
  content: "";
  height: 3px;
  border-radius: 2px;
  background: linear-gradient(90deg, var(--bs-primary) 0 calc(var(--p, 0) * 1%), var(--bs-tertiary-bg) calc(var(--p, 0) * 1%) 100%);
}

/* ============================================================
   HERO — a review desk: ruled sheet on the left, paper stack on the right
   ============================================================ */
.hwk-studio {
  position: relative;
  overflow: hidden;
  border-radius: var(--radius);
  background: linear-gradient(180deg, #F2F5FF 0%, var(--bs-body-bg) 34%), var(--bs-body-bg);
  border: 1px solid var(--bs-border-color);
  box-shadow: var(--shadow);
}

/* ruled lines, faint, like the page underneath */
.hwk-studio::before {
  content: "";
  position: absolute;
  inset: 0;
  background-image: repeating-linear-gradient(180deg, transparent 0 33px, var(--bs-border-color) 33px 34px);
  opacity: 0.45;
  mask-image: linear-gradient(90deg, transparent 0%, #000 40%);
  pointer-events: none;
}

.hwk-studio-inner {
  position: relative;
  display: grid;
  grid-template-columns: minmax(0, 1fr) 330px;
  gap: 34px;
  padding: 28px 28px 28px 34px;
  /* the margin rule down the left edge */
}
.hwk-studio-inner::before {
  content: "";
  position: absolute;
  left: 16px;
  top: 20px;
  bottom: 20px;
  width: 2px;
  border-radius: 1px;
  background: #F8BEC8;
}
@media (max-width: 1299.98px) {
  .hwk-studio-inner {
    grid-template-columns: minmax(0, 1fr);
    gap: 26px;
  }
}
@media (max-width: 575.98px) {
  .hwk-studio-inner {
    padding: 22px 20px 22px 28px;
  }
}

.hwk-studio-badge {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 5px 12px;
  border-radius: 999px;
  background: var(--bs-body-bg);
  border: 1px solid var(--bs-border-color);
  box-shadow: var(--shadow);
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--bs-emphasis-color);
}

.hwk-studio-title {
  margin: 14px 0 10px;
  font-size: 30px;
  line-height: 1.22;
  font-weight: 600;
  letter-spacing: -0.02em;
  color: var(--bs-emphasis-color);
}
.hwk-studio-title em {
  font-style: normal;
  background: linear-gradient(90deg, var(--bs-primary), #02a8b5);
  -webkit-background-clip: text;
  background-clip: text;
  -webkit-text-fill-color: transparent;
}
@media (max-width: 767.98px) {
  .hwk-studio-title {
    font-size: 24px;
  }
}

/* the status line reads as a marking record, divided by upright rules */
.hwk-record {
  display: flex;
  flex-wrap: wrap;
  margin-top: 20px;
  border: 1px solid var(--bs-border-color);
  border-radius: var(--radius);
  background: var(--bs-body-bg);
  overflow: hidden;
}

.hwk-record-cell {
  flex: 1 1 130px;
  padding: 13px 16px;
  line-height: 1.3;
}
.hwk-record-cell + .hwk-record-cell {
  border-left: 1px solid var(--bs-border-color);
}
.hwk-record-cell b {
  display: block;
  margin-top: 3px;
  font-size: 19px;
  font-weight: 600;
  font-variant-numeric: tabular-nums;
  color: var(--bs-emphasis-color);
}
.hwk-record-cell b small {
  font-size: 12px;
  font-weight: 500;
  color: var(--bs-secondary-color);
}
@media (max-width: 575.98px) {
  .hwk-record-cell {
    flex-basis: 50%;
  }
  .hwk-record-cell:nth-child(odd) {
    border-left: 0;
  }
  .hwk-record-cell:nth-child(n+3) {
    border-top: 1px solid var(--bs-border-color);
  }
}

/* ---- illustration: a stack of marked sheets ---- */
.hwk-stack {
  position: relative;
  display: flex;
  flex-direction: column;
  gap: 14px;
  padding: 20px;
  border-radius: var(--radius);
  background: var(--bs-body-bg);
  border: 1px solid var(--bs-border-color);
  box-shadow: var(--aix-glow);
}

.hwk-sheets {
  position: relative;
  height: 148px;
}

/* three offset sheets, the front one carrying the seal */
.hwk-sheet {
  position: absolute;
  inset: 0;
  border-radius: var(--radius-sm);
  background: var(--bs-body-bg);
  border: 1px solid var(--bs-border-color);
  box-shadow: var(--shadow);
}
.hwk-sheet.s1 {
  transform: rotate(-5deg) translateY(6px);
  opacity: 0.55;
}
.hwk-sheet.s2 {
  transform: rotate(3deg) translateY(3px);
  opacity: 0.8;
}
.hwk-sheet.s3 {
  display: flex;
  flex-direction: column;
  justify-content: center;
  gap: 8px;
  padding: 18px;
}

/* skeleton lines standing in for written work */
.hwk-ruled {
  display: block;
  height: 6px;
  border-radius: 3px;
  background: var(--bs-tertiary-bg);
  width: calc(var(--p, 100) * 1%);
}
.hwk-ruled.is-mark {
  background: var(--tint-primary);
}

.hwk-sheet-seal {
  position: absolute;
  right: -10px;
  top: -12px;
  transform: rotate(-12deg);
  box-shadow: var(--shadow);
}

/* ============================================================
   SUBMISSION CARDS — a paper head, a rubric strip, an action foot
   ============================================================ */
.hwk-sub {
  display: flex;
  flex-direction: column;
  height: 100%;
  border-radius: var(--radius);
  background: var(--bs-body-bg);
  border: 1px solid var(--bs-border-color);
  overflow: hidden;
  transition: var(--transition);
}
.hwk-sub:hover {
  border-color: rgba(61, 94, 225, 0.28);
  box-shadow: var(--shadow-lift);
}

/* the head is the sheet: ruled, with the seal stamped at the right */
.hwk-sub-head {
  position: relative;
  display: flex;
  align-items: center;
  gap: 14px;
  padding: 16px;
  background: repeating-linear-gradient(180deg, transparent 0 21px, var(--bs-border-color) 21px 22px), var(--bs-secondary-bg);
  border-bottom: 1px solid var(--bs-border-color);
  /* margin rule */
}
.hwk-sub-head::before {
  content: "";
  position: absolute;
  left: 8px;
  top: 10px;
  bottom: 10px;
  width: 2px;
  border-radius: 1px;
  background: #F8BEC8;
}

.hwk-sub-title {
  margin: 0 0 2px;
  font-size: 14px;
  font-weight: 600;
  color: var(--bs-emphasis-color);
}

.hwk-sub-body {
  display: flex;
  flex-direction: column;
  gap: 13px;
  flex: 1 1 auto;
  padding: 16px;
}

.hwk-sub-meta {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 12px;
  padding: 12px 0;
  border-top: 1px solid var(--bs-border-color);
  border-bottom: 1px solid var(--bs-border-color);
}

.hwk-cell {
  display: flex;
  flex-direction: column;
  gap: 3px;
  line-height: 1.3;
  min-width: 0;
}
.hwk-cell span:last-child {
  font-size: 13px;
  font-weight: 600;
  color: var(--bs-emphasis-color);
}

.hwk-sub-foot {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 12px 16px;
  background: var(--bs-secondary-bg);
  border-top: 1px solid var(--bs-border-color);
}

.hwk-ico {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 34px;
  height: 34px;
  flex-shrink: 0;
  border-radius: 50%;
  background: var(--bs-body-bg);
  border: 1px solid var(--bs-border-color);
  color: var(--bs-secondary-color);
  font-size: 16px;
  transition: var(--transition);
}
.hwk-ico:hover {
  color: var(--bs-primary);
  border-color: var(--bs-primary);
  background: var(--tint-primary);
}

/* ============================================================
   ANNOTATION CARDS — explainable AI as a marked-up page
   A hanging marker in the margin, then three reading columns.
   ============================================================ */
.hwk-note {
  position: relative;
  padding: 20px 20px 20px 26px;
  border-radius: var(--radius);
  background: var(--bs-body-bg);
  border: 1px solid var(--bs-border-color);
  transition: var(--transition);
}
.hwk-note + .hwk-note {
  margin-top: 16px;
}
.hwk-note {
  /* the coloured margin bar */
}
.hwk-note::before {
  content: "";
  position: absolute;
  left: 10px;
  top: 20px;
  bottom: 20px;
  width: 3px;
  border-radius: 2px;
  background: var(--bs-primary);
}
.hwk-note.is-strong::before {
  background: #1ABE17;
}
.hwk-note.is-mid::before {
  background: #EAB300;
}
.hwk-note.is-weak::before {
  background: #E82646;
}
.hwk-note:hover {
  box-shadow: var(--shadow-lift);
}

.hwk-note-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 12px;
  padding-bottom: 14px;
  margin-bottom: 16px;
  border-bottom: 1px solid var(--bs-border-color);
}

.hwk-note-obs {
  margin: 0;
  font-size: 16px;
  font-weight: 600;
  color: var(--bs-emphasis-color);
}

/* three reading columns inside the note */
.hwk-cols {
  display: grid;
  grid-template-columns: 1.25fr 1fr 1fr;
  gap: 24px;
}
@media (max-width: 991.98px) {
  .hwk-cols {
    grid-template-columns: minmax(0, 1fr);
    gap: 18px;
  }
}

@media (min-width: 992px) {
  .hwk-col-rule {
    padding-left: 24px;
    border-left: 1px dashed var(--bs-border-color);
  }
}

.hwk-ev {
  display: flex;
  align-items: flex-start;
  gap: 9px;
  padding: 7px 0;
  font-size: 12.5px;
  color: var(--bs-emphasis-color);
}
.hwk-ev + .hwk-ev {
  border-top: 1px dashed var(--bs-border-color);
}
.hwk-ev i {
  flex-shrink: 0;
  margin-top: 2px;
  font-size: 14px;
  color: var(--bs-secondary-color);
}

/* ============================================================
   LEARNING GAP — a four-rung priority ladder
   ============================================================ */
.hwk-gap {
  display: flex;
  flex-direction: column;
  height: 100%;
  padding: 18px;
  border-radius: var(--radius);
  background: var(--bs-body-bg);
  border: 1px solid var(--bs-border-color);
  transition: var(--transition);
}
.hwk-gap:hover {
  border-color: rgba(61, 94, 225, 0.28);
  box-shadow: var(--shadow-lift);
}

.hwk-gap-title {
  margin: 0;
  font-size: 15px;
  font-weight: 600;
  color: var(--bs-emphasis-color);
}

/* the ladder: four rungs, filled to the priority level */
.hwk-ladder {
  display: flex;
  align-items: flex-end;
  gap: 4px;
  height: 26px;
}
.hwk-ladder i {
  flex: 1 1 0;
  border-radius: 2px 2px 0 0;
  background: var(--bs-tertiary-bg);
}
.hwk-ladder i:nth-child(1) {
  height: 40%;
}
.hwk-ladder i:nth-child(2) {
  height: 60%;
}
.hwk-ladder i:nth-child(3) {
  height: 80%;
}
.hwk-ladder i:nth-child(4) {
  height: 100%;
}
.hwk-ladder i.on {
  background: var(--bs-primary);
}
.hwk-ladder i.on.is-mid {
  background: #EAB300;
}
.hwk-ladder i.on.is-weak {
  background: #E82646;
}

/* ============================================================
   FEEDBACK TILES — a priority ribbon across the top
   ============================================================ */
.hwk-fb {
  display: flex;
  flex-direction: column;
  height: 100%;
  border-radius: var(--radius);
  background: var(--bs-body-bg);
  border: 1px solid var(--bs-border-color);
  overflow: hidden;
  transition: var(--transition);
}
.hwk-fb:hover {
  box-shadow: var(--shadow-lift);
}

.hwk-fb-ribbon {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  padding: 8px 14px;
  background: var(--bs-primary);
  color: #fff;
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}
.hwk-fb-ribbon.is-weak {
  background: #E82646;
}
.hwk-fb-ribbon.is-mid {
  background: #EAB300;
}
.hwk-fb-ribbon.is-note {
  background: #0F65CD;
}

.hwk-fb-body {
  display: flex;
  flex-direction: column;
  gap: 10px;
  flex: 1 1 auto;
  padding: 16px;
}

.hwk-fb-ic {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 40px;
  height: 40px;
  border-radius: var(--radius-sm);
  background: var(--tint-primary);
  color: var(--bs-primary);
  font-size: 19px;
}

/* ============================================================
   QUALITY TILES — a letter grade beside a written verdict
   ============================================================ */
.hwk-q {
  display: flex;
  gap: 14px;
  height: 100%;
  padding: 16px;
  border-radius: var(--radius);
  background: var(--bs-secondary-bg);
  border: 1px solid transparent;
  transition: var(--transition);
}
.hwk-q:hover {
  background: var(--bs-body-bg);
  border-color: var(--bs-border-color);
  box-shadow: var(--shadow);
}

.hwk-q-grade {
  flex-shrink: 0;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 42px;
  height: 42px;
  border-radius: var(--radius-sm);
  background: var(--bs-body-bg);
  border: 1px solid var(--bs-border-color);
  color: var(--bs-primary);
  font-size: 17px;
  font-weight: 700;
}
.hwk-q-grade.is-strong {
  color: #1ABE17;
}
.hwk-q-grade.is-mid {
  color: #EAB300;
}
.hwk-q-grade.is-weak {
  color: #E82646;
}

.hwk-q-title {
  margin: 0 0 3px;
  font-size: 13.5px;
  font-weight: 600;
  color: var(--bs-emphasis-color);
}

/* ============================================================
   COPILOT — draft tiles showing a skeleton of the document
   ============================================================ */
.hwk-draft {
  display: flex;
  flex-direction: column;
  gap: 12px;
  height: 100%;
  padding: 18px;
  border-radius: var(--radius);
  background: var(--bs-body-bg);
  border: 1px solid var(--bs-border-color);
  transition: var(--transition);
}
.hwk-draft:hover {
  border-color: rgba(61, 94, 225, 0.3);
  box-shadow: var(--aix-glow);
}
.hwk-draft:hover .hwk-draft-ic {
  background: var(--bs-primary);
  color: #fff;
}
.hwk-draft:hover .hwk-ruled.is-mark {
  background: rgba(61, 94, 225, 0.32);
}

.hwk-draft-ic {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 38px;
  height: 38px;
  border-radius: var(--radius-sm);
  background: var(--tint-primary);
  color: var(--bs-primary);
  font-size: 18px;
  transition: var(--transition);
}

.hwk-draft-title {
  margin: 0;
  font-size: 14px;
  font-weight: 600;
  color: var(--bs-emphasis-color);
}

/* the preview skeleton at the foot of each draft tile */
.hwk-preview {
  display: flex;
  flex-direction: column;
  gap: 6px;
  margin-top: auto;
  padding-top: 14px;
  border-top: 1px dashed var(--bs-border-color);
}

/* ============================================================
   EVALUATION TIMELINE — dashed connector, step number in the corner
   ============================================================ */
.hwk-flow {
  position: relative;
  padding-left: 26px;
}
.hwk-flow::before {
  content: "";
  position: absolute;
  left: 0;
  top: 12px;
  bottom: 12px;
  border-left: 2px dashed var(--bs-border-color);
}

.hwk-step {
  position: relative;
  padding: 16px 18px;
  border-radius: var(--radius);
  background: var(--bs-body-bg);
  border: 1px solid var(--bs-border-color);
  transition: var(--transition);
}
.hwk-step + .hwk-step {
  margin-top: 14px;
}
.hwk-step:hover {
  box-shadow: var(--shadow);
}
.hwk-step {
  /* the numbered knot sitting on the dashed line */
}
.hwk-step::before {
  content: attr(data-n);
  position: absolute;
  left: -26px;
  top: 18px;
  transform: translateX(-50%);
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 26px;
  height: 26px;
  border-radius: 50%;
  background: var(--bs-body-bg);
  border: 2px solid var(--bs-tertiary-bg);
  color: var(--bs-secondary-color);
  font-size: 10px;
  font-weight: 700;
  font-variant-numeric: tabular-nums;
}
.hwk-step.is-done::before {
  background: #1ABE17;
  border-color: #1ABE17;
  color: #fff;
}
.hwk-step.is-now::before {
  border-color: var(--bs-primary);
  color: var(--bs-primary);
  box-shadow: 0 0 0 4px var(--tint-primary);
}

.hwk-step-title {
  margin: 0 0 3px;
  font-size: 14px;
  font-weight: 600;
  color: var(--bs-emphasis-color);
}

/* ============================================================
   OPPORTUNITY SHELF — dashed tiles, things you add to a plan
   ============================================================ */
.hwk-shelf {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 10px;
  height: 100%;
  padding: 18px;
  border-radius: var(--radius);
  background: var(--bs-body-bg);
  border: 1px dashed var(--bs-border-color);
  transition: var(--transition);
}
.hwk-shelf:hover {
  border-style: solid;
  border-color: rgba(61, 94, 225, 0.35);
  background: var(--tint-primary);
}
.hwk-shelf:hover .hwk-shelf-add {
  color: var(--bs-primary);
}

.hwk-shelf-ic {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 40px;
  height: 40px;
  border-radius: 50%;
  background: var(--bs-secondary-bg);
  border: 1px solid var(--bs-border-color);
  color: var(--bs-primary);
  font-size: 19px;
}

.hwk-shelf-title {
  margin: 0;
  font-size: 14px;
  font-weight: 600;
  color: var(--bs-emphasis-color);
}

.hwk-shelf-add {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  margin-top: auto;
  font-size: 12px;
  font-weight: 600;
  color: var(--bs-secondary-color);
  transition: var(--transition);
}

/* ============================================================
   INSIGHT LIST — hanging numbers, no boxes, typographic
   ============================================================ */
.hwk-insight {
  display: flex;
  align-items: flex-start;
  gap: 16px;
  padding: 16px 0;
  border-top: 1px solid var(--bs-border-color);
}
.hwk-insight:last-child {
  border-bottom: 1px solid var(--bs-border-color);
}

.hwk-insight-n {
  flex-shrink: 0;
  width: 30px;
  font-size: 15px;
  font-weight: 700;
  font-variant-numeric: tabular-nums;
  line-height: 1.4;
  color: transparent;
  -webkit-text-stroke: 1px var(--bs-primary);
}

.hwk-insight-title {
  margin: 0 0 4px;
  font-size: 14px;
  font-weight: 600;
  color: var(--bs-emphasis-color);
}

/* ============================================================
   WORKSPACE OFFCANVAS — circular stepper, labels below, dashed links
   ============================================================ */
.offcanvas.offcanvas-end.hwk-ws {
  width: 88% !important;
  max-width: 1420px !important;
}
@media (max-width: 991.98px) {
  .offcanvas.offcanvas-end.hwk-ws {
    width: 100% !important;
  }
}
.offcanvas.offcanvas-end.hwk-ws .offcanvas-body {
  padding: 22px;
}

.hwk-ws-head {
  display: flex;
  align-items: center;
  gap: 18px;
  flex-wrap: wrap;
  padding: 20px 22px;
  background: linear-gradient(180deg, #F2F5FF 0%, var(--bs-body-bg) 100%);
  border-bottom: 1px solid var(--bs-border-color);
}

.hwk-dots {
  display: grid;
  grid-template-columns: repeat(5, minmax(0, 1fr));
  list-style: none;
  margin: 0;
  padding: 20px 22px 18px;
  background: var(--bs-body-bg);
  border-bottom: 1px solid var(--bs-border-color);
}
@media (max-width: 767.98px) {
  .hwk-dots {
    grid-template-columns: repeat(2, minmax(0, 1fr));
    row-gap: 16px;
  }
}

.hwk-dot {
  position: relative;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 8px;
  width: 100%;
  padding: 0 6px;
  border: 0;
  background: transparent;
  transition: var(--transition);
  /* dashed link to the next dot */
}
.hwk-dot::before {
  content: "";
  position: absolute;
  left: calc(50% + 20px);
  right: calc(-50% + 20px);
  top: 17px;
  border-top: 2px dashed var(--bs-border-color);
}
.hwk-dot.is-last::before {
  display: none;
}
@media (max-width: 767.98px) {
  .hwk-dot::before {
    display: none;
  }
}

.hwk-dot-n {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 36px;
  height: 36px;
  border-radius: 50%;
  background: var(--bs-body-bg);
  border: 2px solid var(--bs-border-color);
  color: var(--bs-secondary-color);
  font-size: 12px;
  font-weight: 700;
  font-variant-numeric: tabular-nums;
  transition: var(--transition);
}

.hwk-dot-txt {
  display: flex;
  flex-direction: column;
  align-items: center;
  line-height: 1.3;
}
.hwk-dot-txt span:first-child {
  font-size: 10px;
  font-weight: 600;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--bs-secondary-color);
}
.hwk-dot-txt span:last-child {
  font-size: 13px;
  font-weight: 600;
  color: var(--bs-secondary-color);
}

.hwk-dot:hover .hwk-dot-n {
  border-color: var(--bs-primary);
  color: var(--bs-primary);
}

.hwk-dot.active .hwk-dot-n {
  background: var(--bs-primary);
  border-color: var(--bs-primary);
  color: #fff;
  box-shadow: 0 0 0 4px var(--tint-primary);
}
.hwk-dot.active .hwk-dot-txt span:first-child {
  color: var(--bs-primary);
}
.hwk-dot.active .hwk-dot-txt span:last-child {
  color: var(--bs-emphasis-color);
}

/* panels inside the workspace */
.hwk-panel {
  height: 100%;
  border-radius: var(--radius);
  background: var(--bs-body-bg);
  border: 1px solid var(--bs-border-color);
  overflow: hidden;
}

.hwk-panel-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 13px 16px;
  background: var(--bs-secondary-bg);
  border-bottom: 1px solid var(--bs-border-color);
}
.hwk-panel-head h6 {
  margin: 0;
  font-size: 13px;
  font-weight: 600;
  color: var(--bs-emphasis-color);
}

.hwk-panel-body {
  padding: 16px;
}

.hwk-line {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 9px 0;
  font-size: 13px;
  color: var(--bs-emphasis-color);
}
.hwk-line + .hwk-line {
  border-top: 1px dashed var(--bs-border-color);
}
.hwk-line b {
  font-weight: 600;
}

/* a quoted feedback block, as the teacher would write it */
.hwk-quote {
  padding: 14px 16px;
  border-radius: var(--radius-sm);
  background: var(--bs-secondary-bg);
  border-left: 3px solid var(--bs-primary);
  font-size: 13px;
  line-height: 1.68;
  color: var(--bs-emphasis-color);
}

/* ============================================================
   PREMIUM ACCORDION + EMPTY STATE
   ============================================================ */
.hwk-acc .accordion-item {
  margin-bottom: 10px;
  background: var(--bs-body-bg);
  border: 1px solid var(--bs-border-color);
  border-radius: var(--radius) !important;
  overflow: hidden;
}
.hwk-acc .accordion-button {
  padding: 14px 16px;
  font-size: 13.5px;
  font-weight: 600;
  color: var(--bs-emphasis-color);
  background: var(--bs-body-bg);
  box-shadow: none;
}
.hwk-acc .accordion-button:not(.collapsed) {
  background: var(--tint-primary);
  color: var(--bs-primary);
}
.hwk-acc .accordion-button:focus {
  box-shadow: none;
}
.hwk-acc .accordion-body {
  padding: 15px 16px;
  font-size: 13px;
  line-height: 1.65;
  color: var(--bs-secondary-color);
  border-top: 1px solid var(--bs-border-color);
}

.hwk-empty {
  padding: 40px 24px;
  text-align: center;
  border-radius: var(--radius);
  background: var(--bs-body-bg);
  border: 1px dashed var(--bs-border-color);
}

.hwk-empty-ic {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 56px;
  height: 56px;
  margin-bottom: 14px;
  border-radius: 50%;
  background: var(--tint-primary);
  color: var(--bs-primary);
  font-size: 25px;
}

/* ============================================================
   21. TEACHING INTELLIGENCE  —  prefix `tch-`

   The sixth family. Its subject is a practitioner's craft, so its language
   is drawn from appraisal and credentialing: facet bars, definition rows,
   an engagement waveform, credential badges and folded-corner notes.

     aix-  enclosed cards, hairline dividers, chevron steppers
     atn-  banded surfaces, a vertical spine, stations, arc gauges
     sdt-  portrait medallion, chapter numerals, date gutter, dot scales
     tto-  slot grids, bracketed marks, before/after bars, a horizontal track
     hwk-  paper sheets, margin rules, grade seals, rubric strips
     tch-  tinted heading bands, facet bars, definition rows, a waveform,
           credential badges, folded corners and an arrow breadcrumb

   Nothing here overrides a rule from the families above.
   ============================================================ */
@media (prefers-reduced-motion: reduce) {
  [class*=tch-],
  [class*=tch-]::before,
  [class*=tch-]::after {
    animation: none !important;
    transition: none !important;
  }
}
/* ---- section heading: a tinted band, not a rule or a numeral --------- */
.tch-band {
  display: flex;
  align-items: center;
  gap: 16px;
  padding: 16px 20px;
  margin-bottom: 24px;
  border-radius: var(--radius);
  background: linear-gradient(90deg, var(--tint-primary) 0%, var(--bs-secondary-bg) 60%, var(--bs-body-bg) 100%);
  border: 1px solid var(--bs-border-color);
}
@media (max-width: 767.98px) {
  .tch-band {
    flex-wrap: wrap;
  }
}

.tch-band-n {
  flex-shrink: 0;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 42px;
  height: 42px;
  border-radius: var(--radius-sm);
  background: var(--bs-body-bg);
  border: 1px solid var(--bs-border-color);
  box-shadow: var(--shadow);
  color: var(--bs-primary);
  font-size: 14px;
  font-weight: 700;
  font-variant-numeric: tabular-nums;
}

.tch-band-title {
  margin: 0;
  font-size: 19px;
  font-weight: 600;
  letter-spacing: -0.01em;
  color: var(--bs-emphasis-color);
}

.tch-band-sub {
  margin: 2px 0 0;
  font-size: 13px;
  color: var(--bs-secondary-color);
}

/* ---- shared pieces ---------------------------------------------------- */
.tch-lbl {
  display: block;
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.07em;
  text-transform: uppercase;
  color: var(--bs-secondary-color);
}

.tch-pill {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  padding: 4px 10px;
  border-radius: 6px;
  font-size: 11px;
  font-weight: 600;
  background: var(--bs-secondary-bg);
  border: 1px solid var(--bs-border-color);
  color: var(--bs-emphasis-color);
  white-space: nowrap;
}
.tch-pill i {
  font-size: 13px;
}
.tch-pill.is-ai {
  background: var(--tint-primary);
  border-color: rgba(61, 94, 225, 0.2);
  color: var(--bs-primary);
}
.tch-pill.is-high {
  background: #E8F9E8;
  border-color: #D1F2D1;
  color: #1ABE17;
}
.tch-pill.is-mid {
  background: #FEF8EA;
  border-color: #FDF1D6;
  color: #EAB300;
}
.tch-pill.is-low {
  background: #FDE9ED;
  border-color: #FAD4DA;
  color: #E82646;
}
.tch-pill.is-note {
  background: #E7F1FC;
  border-color: #CFE2FA;
  color: #0F65CD;
}

/* ---- facet bars: the family's signature readout ----------------------
   A label, a slim track and a figure on one line. Several stacked read as
   a profile of a practitioner rather than as a chart. */
.tch-facet {
  display: grid;
  grid-template-columns: 104px minmax(0, 1fr) 38px;
  align-items: center;
  gap: 10px;
  padding: 6px 0;
  font-size: 11.5px;
  color: var(--bs-secondary-color);
}
.tch-facet b {
  text-align: right;
  font-size: 12px;
  font-weight: 600;
  font-variant-numeric: tabular-nums;
  color: var(--bs-emphasis-color);
}

.tch-facet-bar {
  height: 6px;
  border-radius: 3px;
  background: linear-gradient(90deg, var(--bs-primary) 0 calc(var(--p, 0) * 1%), var(--bs-tertiary-bg) calc(var(--p, 0) * 1%) 100%);
}
.tch-facet-bar.is-high {
  background: linear-gradient(90deg, #1ABE17 0 calc(var(--p, 0) * 1%), var(--bs-tertiary-bg) calc(var(--p, 0) * 1%) 100%);
}
.tch-facet-bar.is-mid {
  background: linear-gradient(90deg, #EAB300 0 calc(var(--p, 0) * 1%), var(--bs-tertiary-bg) calc(var(--p, 0) * 1%) 100%);
}
.tch-facet-bar.is-low {
  background: linear-gradient(90deg, #E82646 0 calc(var(--p, 0) * 1%), var(--bs-tertiary-bg) calc(var(--p, 0) * 1%) 100%);
}

/* ============================================================
   HERO — copy on the left, an engagement waveform on the right
   ============================================================ */
.tch-stage {
  position: relative;
  overflow: hidden;
  border-radius: var(--radius);
  background: radial-gradient(90% 120% at 100% 100%, rgba(2, 168, 181, 0.12) 0%, transparent 58%), linear-gradient(160deg, #F2F5FF 0%, var(--bs-body-bg) 44%), var(--bs-body-bg);
  border: 1px solid var(--bs-border-color);
  box-shadow: var(--shadow);
}

.tch-stage-inner {
  position: relative;
  display: grid;
  grid-template-columns: minmax(0, 1fr) 372px;
  gap: 34px;
  padding: 28px;
}
@media (max-width: 1299.98px) {
  .tch-stage-inner {
    grid-template-columns: minmax(0, 1fr);
    gap: 26px;
  }
}
@media (max-width: 575.98px) {
  .tch-stage-inner {
    padding: 22px;
  }
}

.tch-stage-badge {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 5px 12px 5px 6px;
  border-radius: 999px;
  background: var(--bs-body-bg);
  border: 1px solid var(--bs-border-color);
  box-shadow: var(--shadow);
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--bs-emphasis-color);
}
.tch-stage-badge i {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 22px;
  height: 22px;
  border-radius: 50%;
  background: var(--bs-primary);
  color: #fff;
  font-size: 13px;
}

.tch-stage-title {
  margin: 14px 0 10px;
  font-size: 30px;
  line-height: 1.22;
  font-weight: 600;
  letter-spacing: -0.02em;
  color: var(--bs-emphasis-color);
}
.tch-stage-title em {
  font-style: normal;
  background: linear-gradient(90deg, var(--bs-primary), #02a8b5);
  -webkit-background-clip: text;
  background-clip: text;
  -webkit-text-fill-color: transparent;
}
@media (max-width: 767.98px) {
  .tch-stage-title {
    font-size: 24px;
  }
}

/* status readouts as a wrapped definition strip */
.tch-stage-strip {
  display: flex;
  flex-wrap: wrap;
  gap: 18px 32px;
  margin-top: 20px;
  padding-top: 18px;
  border-top: 1px solid var(--bs-border-color);
}

.tch-stat {
  display: flex;
  flex-direction: column;
  gap: 4px;
  line-height: 1.25;
}
.tch-stat b {
  font-size: 19px;
  font-weight: 600;
  font-variant-numeric: tabular-nums;
  color: var(--bs-emphasis-color);
}
.tch-stat b small {
  font-size: 12px;
  font-weight: 500;
  color: var(--bs-secondary-color);
}

/* ---- the illustration: an engagement waveform ---- */
.tch-panel {
  display: flex;
  flex-direction: column;
  gap: 16px;
  padding: 20px;
  border-radius: var(--radius);
  background: var(--bs-body-bg);
  border: 1px solid var(--bs-border-color);
  box-shadow: var(--aix-glow);
}

.tch-wave {
  display: flex;
  align-items: center;
  gap: 3px;
  height: 96px;
}
.tch-wave i {
  flex: 1 1 0;
  min-height: 4px;
  height: calc(var(--p, 10) * 1%);
  border-radius: 2px;
  background: linear-gradient(180deg, var(--bs-primary), rgba(61, 94, 225, 0.38));
}
.tch-wave i.is-peak {
  background: linear-gradient(180deg, #02a8b5, rgba(2, 168, 181, 0.4));
}
.tch-wave i.is-dip {
  background: linear-gradient(180deg, #EAB300, rgba(234, 179, 0, 0.4));
}

.tch-wave-axis {
  display: flex;
  justify-content: space-between;
  font-size: 11px;
  color: var(--bs-secondary-color);
}

/* ============================================================
   TEACHER CARDS — a tinted corner, a portrait, then facet bars
   ============================================================ */
.tch-card {
  position: relative;
  display: flex;
  flex-direction: column;
  height: 100%;
  border-radius: var(--radius);
  background: var(--bs-body-bg);
  border: 1px solid var(--bs-border-color);
  overflow: hidden;
  transition: var(--transition);
}
.tch-card:hover {
  border-color: rgba(61, 94, 225, 0.28);
  box-shadow: var(--shadow-lift);
}
.tch-card {
  /* the diagonal tinted corner behind the portrait */
}
.tch-card::before {
  content: "";
  position: absolute;
  left: 0;
  top: 0;
  width: 100%;
  height: 96px;
  background: linear-gradient(120deg, var(--tint-primary) 0%, var(--bs-secondary-bg) 70%, transparent 100%);
}

.tch-card-head {
  position: relative;
  display: flex;
  align-items: center;
  gap: 14px;
  padding: 18px 18px 14px;
}

.tch-card-name {
  margin: 0 0 2px;
  font-size: 15px;
  font-weight: 600;
  color: var(--bs-emphasis-color);
}

/* the score reads as a mark out of 100, set beside the portrait */
.tch-card-score {
  margin-left: auto;
  text-align: right;
  line-height: 1;
}
.tch-card-score b {
  font-size: 23px;
  font-weight: 700;
  font-variant-numeric: tabular-nums;
  color: var(--bs-emphasis-color);
}
.tch-card-score b small {
  font-size: 12px;
  font-weight: 500;
  color: var(--bs-secondary-color);
}

.tch-card-body {
  display: flex;
  flex-direction: column;
  gap: 14px;
  flex: 1 1 auto;
  padding: 0 18px 16px;
}

.tch-card-foot {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 12px 18px;
  background: var(--bs-secondary-bg);
  border-top: 1px solid var(--bs-border-color);
}

.tch-ico {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 34px;
  height: 34px;
  flex-shrink: 0;
  border-radius: var(--radius-sm);
  background: var(--bs-body-bg);
  border: 1px solid var(--bs-border-color);
  color: var(--bs-secondary-color);
  font-size: 16px;
  transition: var(--transition);
}
.tch-ico:hover {
  color: var(--bs-primary);
  border-color: var(--bs-primary);
  background: var(--tint-primary);
}

/* ============================================================
   DEFINITION ROWS — explainable AI read as an appraisal record
   ============================================================ */
.tch-record {
  position: relative;
  padding: 20px 22px;
  border-radius: var(--radius);
  background: var(--bs-body-bg);
  border: 1px solid var(--bs-border-color);
  border-left: 4px solid var(--bs-primary);
  transition: var(--transition);
}
.tch-record + .tch-record {
  margin-top: 16px;
}
.tch-record.is-high {
  border-left-color: #1ABE17;
}
.tch-record.is-mid {
  border-left-color: #EAB300;
}
.tch-record.is-low {
  border-left-color: #E82646;
}
.tch-record:hover {
  box-shadow: var(--shadow-lift);
}

.tch-record-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 12px;
  padding-bottom: 14px;
  margin-bottom: 4px;
  border-bottom: 1px solid var(--bs-border-color);
}

.tch-record-obs {
  margin: 0;
  font-size: 16px;
  font-weight: 600;
  color: var(--bs-emphasis-color);
}

/* label on the left, value on the right, ruled between */
.tch-dl {
  display: grid;
  grid-template-columns: 172px minmax(0, 1fr);
  gap: 0 24px;
}
@media (max-width: 767.98px) {
  .tch-dl {
    grid-template-columns: minmax(0, 1fr);
    gap: 0;
  }
}

.tch-dt {
  padding: 13px 0 13px;
  border-bottom: 1px dashed var(--bs-border-color);
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.07em;
  text-transform: uppercase;
  color: var(--bs-secondary-color);
}
@media (max-width: 767.98px) {
  .tch-dt {
    padding-bottom: 0;
    border-bottom: 0;
  }
}

.tch-dd {
  margin: 0;
  padding: 13px 0;
  border-bottom: 1px dashed var(--bs-border-color);
  font-size: 13px;
  line-height: 1.65;
  color: var(--bs-emphasis-color);
}
.tch-dd:last-child {
  border-bottom: 0;
}
@media (max-width: 767.98px) {
  .tch-dd {
    padding-top: 4px;
  }
}

.tch-ev {
  display: flex;
  align-items: flex-start;
  gap: 8px;
  padding: 3px 0;
  font-size: 12.5px;
  color: var(--bs-secondary-color);
}
.tch-ev i {
  flex-shrink: 0;
  margin-top: 2px;
  font-size: 14px;
  color: var(--bs-primary);
}

/* ============================================================
   FACET CARDS — a ringed badge above a written finding
   ============================================================ */
.tch-facet-card {
  height: 100%;
  padding: 18px;
  border-radius: var(--radius);
  background: var(--bs-body-bg);
  border: 1px solid var(--bs-border-color);
  transition: var(--transition);
}
.tch-facet-card:hover {
  border-color: rgba(61, 94, 225, 0.28);
  box-shadow: var(--shadow-lift);
}

.tch-ring {
  position: relative;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 52px;
  height: 52px;
  margin-bottom: 12px;
  border-radius: 50%;
  background: var(--bs-body-bg);
  color: var(--bs-primary);
  font-size: 21px;
  /* the ring itself is a conic sweep set by --p */
}
.tch-ring::before {
  content: "";
  position: absolute;
  inset: 0;
  border-radius: 50%;
  background: conic-gradient(var(--bs-primary) 0deg calc(var(--p, 0) * 3.6deg), var(--bs-tertiary-bg) calc(var(--p, 0) * 3.6deg) 360deg);
  -webkit-mask: radial-gradient(farthest-side, transparent calc(100% - 3px), #000 calc(100% - 3px));
  mask: radial-gradient(farthest-side, transparent calc(100% - 3px), #000 calc(100% - 3px));
}
.tch-ring.is-high {
  color: #1ABE17;
}
.tch-ring.is-high::before {
  background: conic-gradient(#1ABE17 0deg calc(var(--p, 0) * 3.6deg), var(--bs-tertiary-bg) calc(var(--p, 0) * 3.6deg) 360deg);
}
.tch-ring.is-mid {
  color: #EAB300;
}
.tch-ring.is-mid::before {
  background: conic-gradient(#EAB300 0deg calc(var(--p, 0) * 3.6deg), var(--bs-tertiary-bg) calc(var(--p, 0) * 3.6deg) 360deg);
}
.tch-ring.is-low {
  color: #E82646;
}
.tch-ring.is-low::before {
  background: conic-gradient(#E82646 0deg calc(var(--p, 0) * 3.6deg), var(--bs-tertiary-bg) calc(var(--p, 0) * 3.6deg) 360deg);
}

.tch-facet-title {
  margin: 0 0 10px;
  font-size: 15px;
  font-weight: 600;
  color: var(--bs-emphasis-color);
}

.tch-mini {
  margin-bottom: 10px;
}
.tch-mini span:first-child {
  display: block;
  margin-bottom: 2px;
  font-size: 10.5px;
  font-weight: 600;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--bs-secondary-color);
}
.tch-mini span:last-child {
  display: block;
  font-size: 12.5px;
  line-height: 1.55;
  color: var(--bs-emphasis-color);
}

/* ============================================================
   COACHING CARDS — a dashed schedule strip along the foot
   ============================================================ */
.tch-coach {
  display: flex;
  flex-direction: column;
  height: 100%;
  padding: 18px;
  border-radius: var(--radius);
  background: var(--bs-body-bg);
  border: 1px solid var(--bs-border-color);
  transition: var(--transition);
}
.tch-coach:hover {
  box-shadow: var(--shadow-lift);
}

.tch-coach-ic {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 40px;
  height: 40px;
  margin-bottom: 12px;
  border-radius: var(--radius-sm);
  background: var(--tint-primary);
  color: var(--bs-primary);
  font-size: 19px;
}
.tch-coach-ic.is-low {
  background: #FDE9ED;
  color: #E82646;
}
.tch-coach-ic.is-mid {
  background: #FEF8EA;
  color: #EAB300;
}
.tch-coach-ic.is-note {
  background: #E7F1FC;
  color: #0F65CD;
}

.tch-coach-title {
  margin: 0 0 6px;
  font-size: 15px;
  font-weight: 600;
  color: var(--bs-emphasis-color);
}

.tch-coach-foot {
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 10px;
  margin-top: auto;
  padding-top: 14px;
  border-top: 1px dashed var(--bs-border-color);
}

/* ============================================================
   CLASSROOM TILES — icon set into the top-right corner
   ============================================================ */
.tch-tile {
  position: relative;
  height: 100%;
  padding: 18px;
  border-radius: var(--radius);
  background: var(--bs-secondary-bg);
  border: 1px solid transparent;
  overflow: hidden;
  transition: var(--transition);
}
.tch-tile:hover {
  background: var(--bs-body-bg);
  border-color: var(--bs-border-color);
  box-shadow: var(--shadow);
}

.tch-tile-ic {
  position: absolute;
  right: 14px;
  top: 14px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 34px;
  height: 34px;
  border-radius: 50%;
  background: var(--bs-body-bg);
  border: 1px solid var(--bs-border-color);
  color: var(--bs-primary);
  font-size: 16px;
}

.tch-tile-title {
  margin: 0 0 8px;
  padding-right: 44px;
  font-size: 14px;
  font-weight: 600;
  color: var(--bs-emphasis-color);
}

/* ============================================================
   COPILOT — numbered wide bars
   ============================================================ */
.tch-do {
  display: flex;
  align-items: center;
  gap: 14px;
  width: 100%;
  padding: 15px 18px;
  border-radius: var(--radius);
  background: var(--bs-body-bg);
  border: 1px solid var(--bs-border-color);
  transition: var(--transition);
}
.tch-do:hover {
  border-color: rgba(61, 94, 225, 0.3);
  box-shadow: var(--aix-glow);
}
.tch-do:hover .tch-do-n {
  background: var(--bs-primary);
  border-color: var(--bs-primary);
  color: #fff;
}
.tch-do:hover .tch-do-go {
  transform: translateX(3px);
  color: var(--bs-primary);
}

.tch-do-n {
  flex-shrink: 0;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 34px;
  height: 34px;
  border-radius: 50%;
  background: var(--bs-secondary-bg);
  border: 1px solid var(--bs-border-color);
  color: var(--bs-secondary-color);
  font-size: 12px;
  font-weight: 700;
  font-variant-numeric: tabular-nums;
  transition: var(--transition);
}

.tch-do-go {
  flex-shrink: 0;
  font-size: 17px;
  color: var(--bs-secondary-color);
  transition: var(--transition);
}

/* ============================================================
   JOURNEY — a numeral gutter, no connecting line
   ============================================================ */
.tch-path {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.tch-leg {
  display: grid;
  grid-template-columns: 62px minmax(0, 1fr);
  align-items: stretch;
  gap: 16px;
  padding: 16px 18px;
  border-radius: var(--radius);
  background: var(--bs-secondary-bg);
  border: 1px solid transparent;
  transition: var(--transition);
}
.tch-leg:hover {
  background: var(--bs-body-bg);
  border-color: var(--bs-border-color);
  box-shadow: var(--shadow);
}
.tch-leg.is-now {
  background: var(--bs-body-bg);
  border-color: rgba(61, 94, 225, 0.3);
  box-shadow: var(--shadow);
}
@media (max-width: 575.98px) {
  .tch-leg {
    grid-template-columns: minmax(0, 1fr);
    gap: 8px;
  }
}

/* the big outlined numeral in the gutter */
.tch-leg-n {
  display: flex;
  align-items: flex-start;
  justify-content: center;
  font-size: 32px;
  font-weight: 700;
  line-height: 1;
  font-variant-numeric: tabular-nums;
  color: transparent;
  -webkit-text-stroke: 1.5px var(--bs-border-color);
}
.tch-leg.is-done .tch-leg-n {
  -webkit-text-stroke-color: #1ABE17;
}
.tch-leg.is-now .tch-leg-n {
  -webkit-text-stroke-color: var(--bs-primary);
}
@media (max-width: 575.98px) {
  .tch-leg-n {
    justify-content: flex-start;
    font-size: 24px;
  }
}

.tch-leg-title {
  margin: 0 0 3px;
  font-size: 14px;
  font-weight: 600;
  color: var(--bs-emphasis-color);
}

/* ============================================================
   CREDENTIAL BADGES — professional growth
   ============================================================ */
.tch-badge {
  display: flex;
  flex-direction: column;
  align-items: center;
  text-align: center;
  height: 100%;
  padding: 20px 16px;
  border-radius: var(--radius);
  background: var(--bs-body-bg);
  border: 1px solid var(--bs-border-color);
  transition: var(--transition);
}
.tch-badge:hover {
  border-color: rgba(61, 94, 225, 0.28);
  box-shadow: var(--shadow-lift);
}

/* a ringed medal with a small tick set at the foot */
.tch-medal {
  position: relative;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 56px;
  height: 56px;
  margin-bottom: 14px;
  border-radius: 50%;
  background: var(--tint-primary);
  color: var(--bs-primary);
  font-size: 24px;
}
.tch-medal::after {
  content: "";
  position: absolute;
  inset: -5px;
  border-radius: 50%;
  border: 1px dashed var(--bs-border-color);
}
.tch-medal.is-high {
  background: #E8F9E8;
  color: #1ABE17;
}
.tch-medal.is-mid {
  background: #FEF8EA;
  color: #EAB300;
}
.tch-medal.is-note {
  background: #E7F1FC;
  color: #0F65CD;
}

.tch-badge-fig {
  display: block;
  font-size: 22px;
  font-weight: 700;
  line-height: 1;
  font-variant-numeric: tabular-nums;
  color: var(--bs-emphasis-color);
}

.tch-badge-title {
  margin: 8px 0 4px;
  font-size: 13.5px;
  font-weight: 600;
  color: var(--bs-emphasis-color);
}

/* ============================================================
   INSIGHT NOTES — a folded top-right corner
   ============================================================ */
.tch-note {
  position: relative;
  height: 100%;
  padding: 18px;
  border-radius: var(--radius);
  background: var(--bs-body-bg);
  border: 1px solid var(--bs-border-color);
  transition: var(--transition);
}
.tch-note:hover {
  box-shadow: var(--shadow-lift);
}
.tch-note {
  /* the fold */
}
.tch-note::before {
  content: "";
  position: absolute;
  right: 0;
  top: 0;
  border-width: 0 22px 22px 0;
  border-style: solid;
  border-color: var(--bs-secondary-bg) var(--bs-secondary-bg) var(--bs-border-color) var(--bs-border-color);
  border-top-right-radius: var(--radius);
}

.tch-note-title {
  margin: 0 0 6px;
  padding-right: 26px;
  font-size: 14px;
  font-weight: 600;
  color: var(--bs-emphasis-color);
}

/* ============================================================
   WORKSPACE OFFCANVAS — an arrow breadcrumb stepper
   ============================================================ */
.offcanvas.offcanvas-end.tch-ws {
  width: 88% !important;
  max-width: 1440px !important;
}
@media (max-width: 991.98px) {
  .offcanvas.offcanvas-end.tch-ws {
    width: 100% !important;
  }
}
.offcanvas.offcanvas-end.tch-ws .offcanvas-body {
  padding: 22px;
}

.tch-ws-head {
  display: flex;
  align-items: center;
  gap: 18px;
  flex-wrap: wrap;
  padding: 20px 22px;
  background: linear-gradient(160deg, #F2F5FF 0%, var(--bs-body-bg) 60%);
  border-bottom: 1px solid var(--bs-border-color);
}

.tch-crumbs {
  display: grid;
  grid-template-columns: repeat(5, minmax(0, 1fr));
  gap: 2px;
  list-style: none;
  margin: 0;
  padding: 0;
  background: var(--bs-secondary-bg);
  border-bottom: 1px solid var(--bs-border-color);
}
@media (max-width: 767.98px) {
  .tch-crumbs {
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 1px;
  }
}

/* each step is notched into the next, like a process breadcrumb */
.tch-crumb {
  position: relative;
  display: flex;
  align-items: center;
  gap: 10px;
  width: 100%;
  padding: 14px 18px 14px 26px;
  border: 0;
  background: var(--bs-body-bg);
  text-align: left;
  clip-path: polygon(0 0, calc(100% - 12px) 0, 100% 50%, calc(100% - 12px) 100%, 0 100%, 12px 50%);
  transition: var(--transition);
}
.tch-crumb:first-child {
  clip-path: polygon(0 0, calc(100% - 12px) 0, 100% 50%, calc(100% - 12px) 100%, 0 100%);
  padding-left: 18px;
}
.tch-crumb:last-child {
  clip-path: polygon(0 0, 100% 0, 100% 100%, 0 100%, 12px 50%);
}
.tch-crumb:hover {
  background: var(--bs-tertiary-bg);
}
.tch-crumb.active {
  background: var(--bs-primary);
}
.tch-crumb.active .tch-crumb-n {
  background: rgba(255, 255, 255, 0.22);
  color: #fff;
}
.tch-crumb.active .tch-crumb-txt span:first-child {
  color: rgba(255, 255, 255, 0.78);
}
.tch-crumb.active .tch-crumb-txt span:last-child {
  color: #fff;
}
@media (max-width: 767.98px) {
  .tch-crumb {
    clip-path: none !important;
    padding: 12px 14px !important;
  }
}

.tch-crumb-n {
  flex-shrink: 0;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 28px;
  height: 28px;
  border-radius: 50%;
  background: var(--bs-secondary-bg);
  color: var(--bs-secondary-color);
  font-size: 11px;
  font-weight: 700;
  font-variant-numeric: tabular-nums;
  transition: var(--transition);
}

.tch-crumb-txt {
  display: flex;
  flex-direction: column;
  min-width: 0;
  line-height: 1.25;
}
.tch-crumb-txt span:first-child {
  font-size: 10px;
  font-weight: 600;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--bs-secondary-color);
}
.tch-crumb-txt span:last-child {
  font-size: 13px;
  font-weight: 600;
  color: var(--bs-emphasis-color);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

/* panels inside the workspace */
.tch-box {
  height: 100%;
  border-radius: var(--radius);
  background: var(--bs-body-bg);
  border: 1px solid var(--bs-border-color);
  overflow: hidden;
}

.tch-box-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 13px 16px;
  background: var(--bs-secondary-bg);
  border-bottom: 1px solid var(--bs-border-color);
}
.tch-box-head h6 {
  margin: 0;
  font-size: 13px;
  font-weight: 600;
  color: var(--bs-emphasis-color);
}

.tch-box-body {
  padding: 16px;
}

.tch-line {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 9px 0;
  font-size: 13px;
  color: var(--bs-emphasis-color);
}
.tch-line + .tch-line {
  border-top: 1px dashed var(--bs-border-color);
}
.tch-line b {
  font-weight: 600;
}

/* a quoted observation, as a reviewer would write it */
.tch-quote {
  padding: 14px 16px;
  border-radius: var(--radius-sm);
  background: var(--bs-secondary-bg);
  border-left: 3px solid var(--bs-primary);
  font-size: 13px;
  line-height: 1.68;
  color: var(--bs-emphasis-color);
}

/* ============================================================
   PREMIUM ACCORDION + EMPTY STATE
   ============================================================ */
.tch-acc .accordion-item {
  margin-bottom: 10px;
  background: var(--bs-body-bg);
  border: 1px solid var(--bs-border-color);
  border-radius: var(--radius) !important;
  overflow: hidden;
}
.tch-acc .accordion-button {
  padding: 14px 16px;
  font-size: 13.5px;
  font-weight: 600;
  color: var(--bs-emphasis-color);
  background: var(--bs-body-bg);
  box-shadow: none;
}
.tch-acc .accordion-button:not(.collapsed) {
  background: var(--tint-primary);
  color: var(--bs-primary);
}
.tch-acc .accordion-button:focus {
  box-shadow: none;
}
.tch-acc .accordion-body {
  padding: 15px 16px;
  font-size: 13px;
  line-height: 1.65;
  color: var(--bs-secondary-color);
  border-top: 1px solid var(--bs-border-color);
}

.tch-empty {
  padding: 40px 24px;
  text-align: center;
  border-radius: var(--radius);
  background: var(--bs-secondary-bg);
  border: 1px solid var(--bs-border-color);
}

.tch-empty-ic {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 56px;
  height: 56px;
  margin-bottom: 14px;
  border-radius: 50%;
  background: var(--bs-body-bg);
  border: 1px solid var(--bs-border-color);
  box-shadow: var(--shadow);
  color: var(--bs-primary);
  font-size: 25px;
}

/* ============================================================
   22. FAMILY ENGAGEMENT  —  prefix `fam-`

   The seventh family. Its subject is a relationship between two parties,
   so its language is drawn from correspondence: paired avatars joined by a
   connector, message threads, composed letters and drop capitals.

     aix-  enclosed cards, hairline dividers, chevron steppers
     atn-  banded surfaces, a vertical spine, stations, arc gauges
     sdt-  portrait medallion, chapter numerals, date gutter, dot scales
     tto-  slot grids, bracketed marks, before/after bars, a horizontal track
     hwk-  paper sheets, margin rules, grade seals, rubric strips
     tch-  tinted bands, facet bars, definition rows, medals, folded corners
     fam-  paired avatars, message threads, drop capitals, calendar chips
           and a single continuous progress stepper

   Nothing here overrides a rule from the families above.
   ============================================================ */
@media (prefers-reduced-motion: reduce) {
  [class*=fam-],
  [class*=fam-]::before,
  [class*=fam-]::after {
    animation: none !important;
    transition: none !important;
  }
}
/* ---- section heading: a thick rounded accent at the left -------------- */
.fam-hd {
  display: flex;
  align-items: flex-start;
  gap: 16px;
  margin-bottom: 24px;
}
.fam-hd::before {
  content: "";
  flex-shrink: 0;
  width: 5px;
  align-self: stretch;
  min-height: 46px;
  border-radius: 3px;
  background: linear-gradient(180deg, var(--bs-primary), #02a8b5);
}

.fam-hd-title {
  margin: 0;
  font-size: 20px;
  font-weight: 600;
  letter-spacing: -0.01em;
  color: var(--bs-emphasis-color);
}

.fam-hd-sub {
  margin: 5px 0 0;
  font-size: 13px;
  color: var(--bs-secondary-color);
  max-width: 700px;
}

/* ---- shared pieces ---------------------------------------------------- */
.fam-lbl {
  display: block;
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.07em;
  text-transform: uppercase;
  color: var(--bs-secondary-color);
}

.fam-chip {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  padding: 4px 11px;
  border-radius: 999px;
  font-size: 11px;
  font-weight: 600;
  background: var(--bs-secondary-bg);
  border: 1px solid var(--bs-border-color);
  color: var(--bs-emphasis-color);
  white-space: nowrap;
}
.fam-chip i {
  font-size: 13px;
}
.fam-chip.is-ai {
  background: var(--tint-primary);
  border-color: rgba(61, 94, 225, 0.2);
  color: var(--bs-primary);
}
.fam-chip.is-warm {
  background: #E8F9E8;
  border-color: #D1F2D1;
  color: #1ABE17;
}
.fam-chip.is-cool {
  background: #E7F1FC;
  border-color: #CFE2FA;
  color: #0F65CD;
}
.fam-chip.is-fading {
  background: #FEF8EA;
  border-color: #FDF1D6;
  color: #EAB300;
}
.fam-chip.is-cold {
  background: #FDE9ED;
  border-color: #FAD4DA;
  color: #E82646;
}
html[data-theme=dark] .fam-chip.is-warm {
  background: rgba(26, 190, 23, 0.16);
  border-color: rgba(26, 190, 23, 0.32);
  color: color-mix(in srgb, #1ABE17 60%, white);
}
html[data-theme=dark] .fam-chip.is-cool {
  background: rgba(15, 101, 205, 0.16);
  border-color: rgba(15, 101, 205, 0.32);
  color: color-mix(in srgb, #0F65CD 60%, white);
}
html[data-theme=dark] .fam-chip.is-fading {
  background: rgba(234, 179, 0, 0.16);
  border-color: rgba(234, 179, 0, 0.32);
  color: color-mix(in srgb, #EAB300 60%, white);
}
html[data-theme=dark] .fam-chip.is-cold {
  background: rgba(232, 38, 70, 0.16);
  border-color: rgba(232, 38, 70, 0.32);
  color: color-mix(in srgb, #E82646 60%, white);
}

/* engagement level: five linked rings, filled to level */
.fam-level {
  display: inline-flex;
  align-items: center;
  gap: 3px;
}
.fam-level i {
  width: 9px;
  height: 9px;
  border-radius: 50%;
  border: 1.5px solid var(--bs-tertiary-bg);
}
.fam-level i.on {
  background: var(--bs-primary);
  border-color: var(--bs-primary);
}
.fam-level.is-warm i.on {
  background: #1ABE17;
  border-color: #1ABE17;
}
.fam-level.is-fading i.on {
  background: #EAB300;
  border-color: #EAB300;
}
.fam-level.is-cold i.on {
  background: #E82646;
  border-color: #E82646;
}

/* ============================================================
   HERO — copy on the left, a conversation thread on the right
   ============================================================ */
.fam-hero {
  position: relative;
  overflow: hidden;
  border-radius: var(--radius);
  background: radial-gradient(80% 120% at 0% 100%, rgba(2, 168, 181, 0.12) 0%, transparent 55%), linear-gradient(200deg, #F2F5FF 0%, var(--bs-body-bg) 46%), var(--bs-body-bg);
  border: 1px solid var(--bs-border-color);
  box-shadow: var(--shadow);
}

.fam-hero-inner {
  position: relative;
  display: grid;
  grid-template-columns: minmax(0, 1fr) 372px;
  gap: 34px;
  padding: 28px;
}
@media (max-width: 1299.98px) {
  .fam-hero-inner {
    grid-template-columns: minmax(0, 1fr);
    gap: 26px;
  }
}
@media (max-width: 575.98px) {
  .fam-hero-inner {
    padding: 22px;
  }
}

.fam-hero-badge {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 5px 13px;
  border-radius: 999px;
  background: var(--bs-body-bg);
  border: 1px solid var(--bs-border-color);
  box-shadow: var(--shadow);
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--bs-emphasis-color);
}

.fam-hero-title {
  margin: 14px 0 10px;
  font-size: 30px;
  line-height: 1.22;
  font-weight: 600;
  letter-spacing: -0.02em;
  color: var(--bs-emphasis-color);
}
.fam-hero-title em {
  font-style: normal;
  background: linear-gradient(90deg, var(--bs-primary), #02a8b5);
  -webkit-background-clip: text;
  background-clip: text;
  -webkit-text-fill-color: transparent;
}
@media (max-width: 767.98px) {
  .fam-hero-title {
    font-size: 24px;
  }
}

/* readouts on a soft rounded strip rather than in boxes */
.fam-hero-strip {
  display: flex;
  flex-wrap: wrap;
  gap: 14px 30px;
  margin-top: 20px;
  padding: 16px 18px;
  border-radius: var(--radius);
  background: var(--bs-body-bg);
  border: 1px solid var(--bs-border-color);
}

.fam-stat {
  display: flex;
  flex-direction: column;
  gap: 3px;
  line-height: 1.25;
}
.fam-stat b {
  font-size: 18px;
  font-weight: 600;
  font-variant-numeric: tabular-nums;
  color: var(--bs-emphasis-color);
}
.fam-stat b small {
  font-size: 12px;
  font-weight: 500;
  color: var(--bs-secondary-color);
}

/* ---- the illustration: a conversation thread ---- */
.fam-thread-panel {
  display: flex;
  flex-direction: column;
  gap: 14px;
  padding: 20px;
  border-radius: var(--radius);
  background: var(--bs-body-bg);
  border: 1px solid var(--bs-border-color);
  box-shadow: var(--aix-glow);
}

.fam-bubbles {
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.fam-bubble {
  position: relative;
  max-width: 86%;
  padding: 11px 14px;
  border-radius: 14px 14px 14px 4px;
  background: var(--bs-secondary-bg);
  border: 1px solid var(--bs-border-color);
  font-size: 12.5px;
  line-height: 1.55;
  color: var(--bs-emphasis-color);
}
.fam-bubble small {
  display: block;
  margin-top: 4px;
  font-size: 10.5px;
  color: var(--bs-secondary-color);
}
.fam-bubble {
  /* the school's side sits right, tinted */
}
.fam-bubble.is-school {
  align-self: flex-end;
  border-radius: 14px 14px 4px 14px;
  background: var(--tint-primary);
  border-color: rgba(61, 94, 225, 0.18);
}
.fam-bubble.is-ai {
  align-self: stretch;
  max-width: 100%;
  border-style: dashed;
  background: var(--bs-body-bg);
  border-radius: var(--radius);
}

/* ============================================================
   FAMILY CARDS — two avatars joined by a connector
   ============================================================ */
.fam-card {
  display: flex;
  flex-direction: column;
  height: 100%;
  border-radius: var(--radius);
  background: var(--bs-body-bg);
  border: 1px solid var(--bs-border-color);
  overflow: hidden;
  transition: var(--transition);
}
.fam-card:hover {
  border-color: rgba(61, 94, 225, 0.28);
  box-shadow: var(--shadow-lift);
}

.fam-card-head {
  display: flex;
  align-items: center;
  gap: 14px;
  padding: 18px;
  background: linear-gradient(180deg, var(--bs-secondary-bg), var(--bs-body-bg));
  border-bottom: 1px solid var(--bs-border-color);
}

/* the pair: parent and student, linked by a small drawn tie */
.fam-pair {
  position: relative;
  display: inline-flex;
  align-items: center;
  flex-shrink: 0;
  padding-right: 6px;
}
.fam-pair .avatar + .avatar {
  margin-left: -12px;
}
.fam-pair {
  /* the tie sits under the join */
}
.fam-pair::after {
  content: "";
  position: absolute;
  left: 50%;
  bottom: -5px;
  transform: translateX(-50%);
  width: 22px;
  height: 3px;
  border-radius: 2px;
  background: var(--bs-primary);
}

.fam-card-name {
  margin: 0 0 2px;
  font-size: 15px;
  font-weight: 600;
  color: var(--bs-emphasis-color);
}

.fam-card-body {
  display: flex;
  flex-direction: column;
  gap: 13px;
  flex: 1 1 auto;
  padding: 16px 18px;
}

.fam-facts {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 12px;
  padding: 12px 0;
  border-top: 1px solid var(--bs-border-color);
  border-bottom: 1px solid var(--bs-border-color);
}

.fam-cell {
  display: flex;
  flex-direction: column;
  gap: 3px;
  min-width: 0;
  line-height: 1.3;
}
.fam-cell span:last-child {
  font-size: 13px;
  font-weight: 600;
  color: var(--bs-emphasis-color);
}

.fam-card-foot {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 12px 18px;
  background: var(--bs-secondary-bg);
  border-top: 1px solid var(--bs-border-color);
}

.fam-ico {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 34px;
  height: 34px;
  flex-shrink: 0;
  border-radius: 50%;
  background: var(--bs-body-bg);
  border: 1px solid var(--bs-border-color);
  color: var(--bs-secondary-color);
  font-size: 16px;
  transition: var(--transition);
}
.fam-ico:hover {
  color: var(--bs-primary);
  border-color: var(--bs-primary);
  background: var(--tint-primary);
}

/* ============================================================
   EXPLAINABLE AI — written as a thread of exchanges
   ============================================================ */
.fam-note {
  padding: 20px;
  border-radius: var(--radius);
  background: var(--bs-body-bg);
  border: 1px solid var(--bs-border-color);
  transition: var(--transition);
}
.fam-note:hover {
  box-shadow: var(--shadow-lift);
}

.fam-note-head {
  display: flex;
  align-items: flex-start;
  gap: 12px;
  padding-bottom: 14px;
  margin-bottom: 16px;
  border-bottom: 1px solid var(--bs-border-color);
}

.fam-note-ic {
  flex-shrink: 0;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 38px;
  height: 38px;
  border-radius: 12px;
  background: var(--tint-primary);
  color: var(--bs-primary);
  font-size: 18px;
}
.fam-note-ic.is-warm {
  background: #E8F9E8;
  color: #1ABE17;
}
.fam-note-ic.is-fading {
  background: #FEF8EA;
  color: #EAB300;
}
.fam-note-ic.is-cold {
  background: #FDE9ED;
  color: #E82646;
}

.fam-note-obs {
  margin: 0;
  font-size: 15px;
  font-weight: 600;
  color: var(--bs-emphasis-color);
}

/* each part of the explanation is an indented exchange */
.fam-turn {
  position: relative;
  padding: 0 0 14px 22px;
}
.fam-turn:last-child {
  padding-bottom: 0;
}
.fam-turn {
  /* the connecting rail */
}
.fam-turn::before {
  content: "";
  position: absolute;
  left: 4px;
  top: 14px;
  bottom: 0;
  width: 1px;
  background: var(--bs-border-color);
}
.fam-turn:last-child::before {
  display: none;
}
.fam-turn {
  /* the marker */
}
.fam-turn::after {
  content: "";
  position: absolute;
  left: 0;
  top: 6px;
  width: 9px;
  height: 9px;
  border-radius: 50%;
  background: var(--bs-body-bg);
  border: 2px solid var(--bs-primary);
}

.fam-turn-lbl {
  display: block;
  margin-bottom: 4px;
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.07em;
  text-transform: uppercase;
  color: var(--bs-secondary-color);
}

.fam-ev {
  display: flex;
  align-items: flex-start;
  gap: 8px;
  padding: 4px 0;
  font-size: 12.5px;
  color: var(--bs-secondary-color);
}
.fam-ev i {
  flex-shrink: 0;
  margin-top: 3px;
  font-size: 6px;
  color: var(--bs-primary);
}

/* ============================================================
   ENGAGEMENT CARDS — a two-tone split
   ============================================================ */
.fam-eng {
  display: flex;
  flex-direction: column;
  height: 100%;
  border-radius: var(--radius);
  background: var(--bs-body-bg);
  border: 1px solid var(--bs-border-color);
  overflow: hidden;
  transition: var(--transition);
}
.fam-eng:hover {
  box-shadow: var(--shadow-lift);
}

.fam-eng-top {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 16px 18px;
  background: var(--tint-primary);
}
.fam-eng-top.is-warm {
  background: #E8F9E8;
}
.fam-eng-top.is-fading {
  background: #FEF8EA;
}
.fam-eng-top.is-cold {
  background: #FDE9ED;
}
.fam-eng-top.is-cool {
  background: #E7F1FC;
}

.fam-eng-ic {
  flex-shrink: 0;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 38px;
  height: 38px;
  border-radius: 50%;
  background: var(--bs-body-bg);
  color: var(--bs-primary);
  font-size: 18px;
}

.fam-eng-title {
  margin: 0;
  font-size: 14.5px;
  font-weight: 600;
  color: var(--bs-emphasis-color);
}

.fam-eng-body {
  flex: 1 1 auto;
  padding: 16px 18px;
}

.fam-kv {
  margin-bottom: 12px;
}
.fam-kv span:first-child {
  display: block;
  margin-bottom: 2px;
  font-size: 10.5px;
  font-weight: 600;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--bs-secondary-color);
}
.fam-kv span:last-child {
  display: block;
  font-size: 12.5px;
  line-height: 1.55;
  color: var(--bs-emphasis-color);
}

/* ============================================================
   RECOMMENDATION CARDS — a send strip along the bottom edge
   ============================================================ */
.fam-rec {
  display: flex;
  flex-direction: column;
  height: 100%;
  border-radius: var(--radius);
  background: var(--bs-body-bg);
  border: 1px solid var(--bs-border-color);
  overflow: hidden;
  transition: var(--transition);
}
.fam-rec:hover {
  border-color: rgba(61, 94, 225, 0.3);
  box-shadow: var(--shadow-lift);
}

.fam-rec-body {
  display: flex;
  flex-direction: column;
  gap: 10px;
  flex: 1 1 auto;
  padding: 18px;
}

.fam-rec-title {
  margin: 0;
  font-size: 14.5px;
  font-weight: 600;
  color: var(--bs-emphasis-color);
}

.fam-rec-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 10px;
  margin-top: auto;
  padding-top: 14px;
  border-top: 1px dashed var(--bs-border-color);
}

/* the strip is the action: full bleed, coloured by priority */
.fam-send {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 7px;
  padding: 12px;
  background: var(--bs-primary);
  color: #fff;
  font-size: 13px;
  font-weight: 600;
  transition: var(--transition);
}
.fam-send.is-cold {
  background: #E82646;
}
.fam-send.is-fading {
  background: #EAB300;
}
.fam-send.is-cool {
  background: #0F65CD;
}
.fam-send:hover {
  filter: brightness(0.94);
  color: #fff;
}

/* ============================================================
   STORY CARDS — a drop capital opens each narrative
   ============================================================ */
.fam-story {
  position: relative;
  height: 100%;
  padding: 20px;
  border-radius: var(--radius);
  background: var(--bs-body-bg);
  border: 1px solid var(--bs-border-color);
  /* a second hairline inset, like a bound page */
  box-shadow: inset 0 0 0 4px var(--bs-body-bg), inset 0 0 0 5px var(--bs-border-color);
  transition: var(--transition);
}
.fam-story:hover {
  box-shadow: inset 0 0 0 4px var(--bs-body-bg), inset 0 0 0 5px rgba(61, 94, 225, 0.28), var(--shadow-lift);
}

.fam-story-title {
  margin: 0 0 10px;
  font-size: 14px;
  font-weight: 600;
  letter-spacing: 0.02em;
  color: var(--bs-emphasis-color);
}

.fam-story-txt {
  margin: 0;
  font-size: 13px;
  line-height: 1.7;
  color: var(--bs-secondary-color);
  /* the drop capital */
}
.fam-story-txt::first-letter {
  float: left;
  margin: 4px 8px 0 0;
  font-size: 34px;
  line-height: 0.8;
  font-weight: 700;
  color: var(--bs-primary);
}

/* ============================================================
   COPILOT — composer tiles with an addressee line
   ============================================================ */
.fam-compose {
  display: flex;
  flex-direction: column;
  gap: 12px;
  height: 100%;
  padding: 18px;
  border-radius: var(--radius);
  background: var(--bs-body-bg);
  border: 1px solid var(--bs-border-color);
  transition: var(--transition);
}
.fam-compose:hover {
  border-color: rgba(61, 94, 225, 0.3);
  box-shadow: var(--aix-glow);
}
.fam-compose:hover .fam-compose-ic {
  background: var(--bs-primary);
  color: #fff;
}

.fam-compose-ic {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 38px;
  height: 38px;
  border-radius: 12px;
  background: var(--tint-primary);
  color: var(--bs-primary);
  font-size: 18px;
  transition: var(--transition);
}

.fam-compose-title {
  margin: 0;
  font-size: 14px;
  font-weight: 600;
  color: var(--bs-emphasis-color);
}

/* the addressee line, like the head of a letter */
.fam-to {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-top: auto;
  padding-top: 12px;
  border-top: 1px dashed var(--bs-border-color);
  font-size: 11.5px;
  color: var(--bs-secondary-color);
}
.fam-to b {
  font-weight: 600;
  color: var(--bs-emphasis-color);
}

/* ============================================================
   PARTNERSHIP TIMELINE — faces on the line
   ============================================================ */
.fam-line {
  position: relative;
  padding-left: 54px;
}
.fam-line::before {
  content: "";
  position: absolute;
  left: 19px;
  top: 16px;
  bottom: 16px;
  width: 2px;
  background: linear-gradient(180deg, var(--bs-primary), rgba(61, 94, 225, 0.14));
}

.fam-mark {
  position: relative;
  padding: 15px 18px;
  border-radius: var(--radius);
  background: var(--bs-secondary-bg);
  border: 1px solid transparent;
  transition: var(--transition);
}
.fam-mark + .fam-mark {
  margin-top: 14px;
}
.fam-mark:hover {
  background: var(--bs-body-bg);
  border-color: var(--bs-border-color);
  box-shadow: var(--shadow);
}
.fam-mark {
  /* the node is an avatar, sat on the line */
}
.fam-mark .fam-mark-face {
  position: absolute;
  left: -54px;
  top: 14px;
  width: 40px;
  height: 40px;
  border-radius: 50%;
  border: 2px solid var(--bs-body-bg);
  box-shadow: var(--shadow);
  object-fit: cover;
}
.fam-mark .fam-mark-ic {
  position: absolute;
  left: -54px;
  top: 14px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 40px;
  height: 40px;
  border-radius: 50%;
  background: var(--bs-body-bg);
  border: 2px solid var(--bs-border-color);
  color: var(--bs-primary);
  font-size: 17px;
}
.fam-mark.is-now .fam-mark-ic {
  border-color: var(--bs-primary);
  box-shadow: 0 0 0 4px var(--tint-primary);
}

.fam-mark-title {
  margin: 0 0 3px;
  font-size: 14px;
  font-weight: 600;
  color: var(--bs-emphasis-color);
}

/* ============================================================
   OPPORTUNITY CARDS — a calendar chip at the left
   ============================================================ */
.fam-opp {
  display: flex;
  align-items: flex-start;
  gap: 14px;
  height: 100%;
  padding: 16px;
  border-radius: var(--radius);
  background: var(--bs-body-bg);
  border: 1px solid var(--bs-border-color);
  transition: var(--transition);
}
.fam-opp:hover {
  border-color: rgba(61, 94, 225, 0.28);
  box-shadow: var(--shadow-lift);
}
.fam-opp:hover .fam-date {
  background: var(--bs-primary);
  border-color: var(--bs-primary);
  color: #fff;
}

/* a torn-off calendar leaf */
.fam-date {
  flex-shrink: 0;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  width: 50px;
  height: 54px;
  border-radius: var(--radius-sm);
  background: var(--bs-secondary-bg);
  border: 1px solid var(--bs-border-color);
  color: var(--bs-emphasis-color);
  line-height: 1;
  transition: var(--transition);
}
.fam-date b {
  font-size: 19px;
  font-weight: 700;
  font-variant-numeric: tabular-nums;
}
.fam-date span {
  margin-top: 3px;
  font-size: 10px;
  font-weight: 600;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  opacity: 0.75;
}

.fam-opp-title {
  margin: 0 0 3px;
  font-size: 14px;
  font-weight: 600;
  color: var(--bs-emphasis-color);
}

/* ============================================================
   INSIGHT ROWS — a soft tinted band with a leading glyph
   ============================================================ */
.fam-ins {
  display: flex;
  align-items: flex-start;
  gap: 14px;
  height: 100%;
  padding: 16px 18px;
  border-radius: var(--radius);
  background: var(--bs-secondary-bg);
  border: 1px solid transparent;
  transition: var(--transition);
}
.fam-ins:hover {
  background: var(--bs-body-bg);
  border-color: var(--bs-border-color);
  box-shadow: var(--shadow);
}

.fam-ins-ic {
  flex-shrink: 0;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 40px;
  height: 40px;
  border-radius: 12px;
  background: var(--bs-body-bg);
  border: 1px solid var(--bs-border-color);
  color: var(--bs-primary);
  font-size: 18px;
}

.fam-ins-title {
  margin: 0 0 4px;
  font-size: 14px;
  font-weight: 600;
  color: var(--bs-emphasis-color);
}

/* ============================================================
   WORKSPACE OFFCANVAS — one continuous progress rule
   ============================================================ */
.offcanvas.offcanvas-end.fam-ws {
  width: 88% !important;
  max-width: 1420px !important;
}
@media (max-width: 991.98px) {
  .offcanvas.offcanvas-end.fam-ws {
    width: 100% !important;
  }
}
.offcanvas.offcanvas-end.fam-ws .offcanvas-body {
  padding: 22px;
}

.fam-ws-head {
  display: flex;
  align-items: center;
  gap: 18px;
  flex-wrap: wrap;
  padding: 20px 22px;
  background: linear-gradient(200deg, #F2F5FF 0%, var(--bs-body-bg) 58%);
  border-bottom: 1px solid var(--bs-border-color);
}

/* the stepper: five labels above one rule that fills to the active stage */
.fam-steps {
  position: relative;
  display: grid;
  grid-template-columns: repeat(5, minmax(0, 1fr));
  gap: 0;
  list-style: none;
  margin: 0;
  padding: 18px 22px 0;
  background: var(--bs-body-bg);
  border-bottom: 1px solid var(--bs-border-color);
  /* the continuous track sits under every step */
}
.fam-steps::after {
  content: "";
  position: absolute;
  left: 22px;
  right: 22px;
  bottom: 0;
  height: 3px;
  border-radius: 2px;
  background: var(--bs-tertiary-bg);
}
@media (max-width: 767.98px) {
  .fam-steps {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
  .fam-steps::after {
    display: none;
  }
}

.fam-step {
  position: relative;
  z-index: 1;
  display: flex;
  align-items: center;
  gap: 10px;
  width: 100%;
  padding: 10px 12px 16px;
  border: 0;
  background: transparent;
  text-align: left;
  transition: var(--transition);
  /* the filled portion of the rule, per step */
}
.fam-step::after {
  content: "";
  position: absolute;
  left: 0;
  right: 0;
  bottom: -1px;
  height: 3px;
  border-radius: 2px;
  background: transparent;
  transition: var(--transition);
}
.fam-step:hover .fam-step-n {
  border-color: var(--bs-primary);
  color: var(--bs-primary);
}
.fam-step.active::after {
  background: var(--bs-primary);
}
.fam-step.active .fam-step-n {
  background: var(--bs-primary);
  border-color: var(--bs-primary);
  color: #fff;
}
.fam-step.active .fam-step-txt span:last-child {
  color: var(--bs-emphasis-color);
}
@media (max-width: 767.98px) {
  .fam-step {
    padding-bottom: 10px;
  }
  .fam-step::after {
    display: none;
  }
}

.fam-step-n {
  flex-shrink: 0;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 30px;
  height: 30px;
  border-radius: 10px;
  background: var(--bs-body-bg);
  border: 1.5px solid var(--bs-border-color);
  color: var(--bs-secondary-color);
  font-size: 11px;
  font-weight: 700;
  font-variant-numeric: tabular-nums;
  transition: var(--transition);
}

.fam-step-txt {
  display: flex;
  flex-direction: column;
  min-width: 0;
  line-height: 1.25;
}
.fam-step-txt span:first-child {
  font-size: 10px;
  font-weight: 600;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--bs-secondary-color);
}
.fam-step-txt span:last-child {
  font-size: 13px;
  font-weight: 600;
  color: var(--bs-secondary-color);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

/* panels inside the workspace */
.fam-box {
  height: 100%;
  border-radius: var(--radius);
  background: var(--bs-body-bg);
  border: 1px solid var(--bs-border-color);
  overflow: hidden;
}

.fam-box-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 13px 16px;
  background: var(--bs-secondary-bg);
  border-bottom: 1px solid var(--bs-border-color);
}
.fam-box-head h6 {
  margin: 0;
  font-size: 13px;
  font-weight: 600;
  color: var(--bs-emphasis-color);
}

.fam-box-body {
  padding: 16px;
}

.fam-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 9px 0;
  font-size: 13px;
  color: var(--bs-emphasis-color);
}
.fam-row + .fam-row {
  border-top: 1px dashed var(--bs-border-color);
}
.fam-row b {
  font-weight: 600;
}

/* ============================================================
   PREMIUM ACCORDION + EMPTY STATE
   ============================================================ */
.fam-acc .accordion-item {
  margin-bottom: 10px;
  background: var(--bs-body-bg);
  border: 1px solid var(--bs-border-color);
  border-radius: var(--radius) !important;
  overflow: hidden;
}
.fam-acc .accordion-button {
  padding: 14px 16px;
  font-size: 13.5px;
  font-weight: 600;
  color: var(--bs-emphasis-color);
  background: var(--bs-body-bg);
  box-shadow: none;
}
.fam-acc .accordion-button:not(.collapsed) {
  background: var(--tint-primary);
  color: var(--bs-primary);
}
.fam-acc .accordion-button:focus {
  box-shadow: none;
}
.fam-acc .accordion-body {
  padding: 15px 16px;
  font-size: 13px;
  line-height: 1.65;
  color: var(--bs-secondary-color);
  border-top: 1px solid var(--bs-border-color);
}

.fam-empty {
  padding: 40px 24px;
  text-align: center;
  border-radius: var(--radius);
  background: var(--bs-secondary-bg);
  border: 1px solid var(--bs-border-color);
}

.fam-empty-ic {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 56px;
  height: 56px;
  margin-bottom: 14px;
  border-radius: 18px;
  background: var(--bs-body-bg);
  border: 1px solid var(--bs-border-color);
  box-shadow: var(--shadow);
  color: var(--bs-primary);
  font-size: 25px;
}

/* ============================================================
   23. REVENUE INTELLIGENCE  —  prefix `rev-`

   The eighth family. Its subject is money and likelihood, so its language
   comes from the ledger: dotted leaders running to an amount, tabular
   figures, segmented probability blocks and a forecast cone.

     aix-  enclosed cards, hairline dividers, chevron steppers
     atn-  banded surfaces, a vertical spine, stations, arc gauges
     sdt-  portrait medallion, chapter numerals, date gutter, dot scales
     tto-  slot grids, bracketed marks, before/after bars, a horizontal track
     hwk-  paper sheets, margin rules, grade seals, rubric strips
     tch-  tinted bands, facet bars, definition rows, medals, folded corners
     fam-  paired avatars, message threads, drop capitals, calendar chips
     rev-  dotted leaders, tabular amounts, probability blocks, impact rails
           and a forecast cone

   Nothing here overrides a rule from the families above.
   ============================================================ */
@media (prefers-reduced-motion: reduce) {
  [class*=rev-],
  [class*=rev-]::before,
  [class*=rev-]::after {
    animation: none !important;
    transition: none !important;
  }
}
/* ---- section heading: title, dotted leader, figure --------------------
   Reads like a line in a statement rather than like a page heading. */
.rev-hd {
  margin-bottom: 24px;
}

.rev-hd-line {
  display: flex;
  align-items: baseline;
  gap: 12px;
}

.rev-hd-title {
  margin: 0;
  flex-shrink: 0;
  font-size: 20px;
  font-weight: 600;
  letter-spacing: -0.01em;
  color: var(--bs-emphasis-color);
}

/* the leader itself */
.rev-leader {
  flex: 1 1 auto;
  min-width: 24px;
  height: 1px;
  align-self: center;
  background-image: linear-gradient(90deg, var(--bs-border-color) 33%, transparent 0);
  background-size: 6px 1px;
  background-repeat: repeat-x;
}

.rev-hd-fig {
  flex-shrink: 0;
  font-size: 15px;
  font-weight: 700;
  font-variant-numeric: tabular-nums;
  color: var(--bs-primary);
}

.rev-hd-sub {
  margin: 8px 0 0;
  font-size: 13px;
  color: var(--bs-secondary-color);
  max-width: 700px;
}

/* ---- shared pieces ---------------------------------------------------- */
.rev-lbl {
  display: block;
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.07em;
  text-transform: uppercase;
  color: var(--bs-secondary-color);
}

/* every amount on the page is set in tabular figures */
.rev-amt {
  font-variant-numeric: tabular-nums;
  font-weight: 700;
  letter-spacing: -0.01em;
  color: var(--bs-emphasis-color);
}
.rev-amt.is-lg {
  font-size: 24px;
}
.rev-amt.is-md {
  font-size: 17px;
}
.rev-amt.is-in {
  color: #1ABE17;
}
.rev-amt.is-out {
  color: #E82646;
}

.rev-tag {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  padding: 4px 10px;
  border-radius: 4px;
  font-size: 11px;
  font-weight: 600;
  background: var(--bs-secondary-bg);
  border: 1px solid var(--bs-border-color);
  color: var(--bs-emphasis-color);
  white-space: nowrap;
}
.rev-tag i {
  font-size: 13px;
}
.rev-tag.is-ai {
  background: var(--tint-primary);
  border-color: rgba(61, 94, 225, 0.2);
  color: var(--bs-primary);
}
.rev-tag.is-likely {
  background: #E8F9E8;
  border-color: #D1F2D1;
  color: #1ABE17;
}
.rev-tag.is-watch {
  background: #E7F1FC;
  border-color: #CFE2FA;
  color: #0F65CD;
}
.rev-tag.is-slow {
  background: #FEF8EA;
  border-color: #FDF1D6;
  color: #EAB300;
}
.rev-tag.is-risk {
  background: #FDE9ED;
  border-color: #FAD4DA;
  color: #E82646;
}

/* Dark mode - these status tags used solid light pastel backgrounds
   (#E8F9E8/#E7F1FC/#FEF8EA/#FDE9ED), which read as flat white/near-white
   chips floating on a dark card. Swapped for translucent washes of the
   same brand color, with the label brightened for contrast - the same
   treatment .ops-chip's dark variant already used for its "is-live"
   state, extended to every status color. */
html[data-theme=dark] .rev-tag.is-likely {
  background: rgba(26, 190, 23, 0.16);
  border-color: rgba(26, 190, 23, 0.32);
  color: color-mix(in srgb, #1ABE17 60%, white);
}
html[data-theme=dark] .rev-tag.is-watch {
  background: rgba(15, 101, 205, 0.16);
  border-color: rgba(15, 101, 205, 0.32);
  color: color-mix(in srgb, #0F65CD 60%, white);
}
html[data-theme=dark] .rev-tag.is-slow {
  background: rgba(234, 179, 0, 0.16);
  border-color: rgba(234, 179, 0, 0.32);
  color: color-mix(in srgb, #EAB300 60%, white);
}
html[data-theme=dark] .rev-tag.is-risk {
  background: rgba(232, 38, 70, 0.16);
  border-color: rgba(232, 38, 70, 0.32);
  color: color-mix(in srgb, #E82646 60%, white);
}

/* ---- probability blocks: the family's signature readout ---------------
   Ten discrete blocks, filled to the likelihood. Discrete rather than a
   continuous bar, because a forecast is a count of outcomes, not a level. */
.rev-prob {
  display: flex;
  gap: 3px;
}
.rev-prob i {
  flex: 1 1 0;
  height: 14px;
  border-radius: 2px;
  background: var(--bs-tertiary-bg);
}
.rev-prob i.on {
  background: var(--bs-primary);
}
.rev-prob.is-likely i.on {
  background: #1ABE17;
}
.rev-prob.is-slow i.on {
  background: #EAB300;
}
.rev-prob.is-risk i.on {
  background: #E82646;
}
.rev-prob.is-sm i {
  height: 8px;
}

/* a ledger row: label, leader, value */
.rev-row {
  display: flex;
  align-items: baseline;
  gap: 10px;
  padding: 8px 0;
  font-size: 13px;
}
.rev-row + .rev-row {
  border-top: 1px solid var(--bs-border-color);
}
.rev-row > span:first-child {
  flex-shrink: 0;
  color: var(--bs-secondary-color);
}
.rev-row > b {
  flex-shrink: 0;
  font-weight: 600;
  font-variant-numeric: tabular-nums;
  color: var(--bs-emphasis-color);
}

/* ============================================================
   HERO — copy on the left, a forecast cone on the right
   ============================================================ */
.rev-hero {
  position: relative;
  overflow: hidden;
  border-radius: var(--radius);
  background: linear-gradient(105deg, var(--bs-body-bg) 0%, var(--bs-body-bg) 50%, #E8F9E8 100%), var(--bs-body-bg);
  border: 1px solid var(--bs-border-color);
  box-shadow: var(--shadow);
}

/* a faint ledger rule across the whole panel */
.rev-hero::before {
  content: "";
  position: absolute;
  inset: 0;
  background-image: repeating-linear-gradient(180deg, transparent 0 39px, var(--bs-border-color) 39px 40px);
  opacity: 0.4;
  mask-image: linear-gradient(180deg, transparent, #000 60%);
  pointer-events: none;
}

.rev-hero-inner {
  position: relative;
  display: grid;
  grid-template-columns: minmax(0, 1fr) 380px;
  gap: 34px;
  padding: 28px;
}
@media (max-width: 1299.98px) {
  .rev-hero-inner {
    grid-template-columns: minmax(0, 1fr);
    gap: 26px;
  }
}
@media (max-width: 575.98px) {
  .rev-hero-inner {
    padding: 22px;
  }
}

.rev-hero-badge {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 5px 12px;
  border-radius: 4px;
  background: var(--bs-emphasis-color);
  color: #fff;
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.1em;
  text-transform: uppercase;
}

.rev-hero-title {
  margin: 14px 0 10px;
  font-size: 30px;
  line-height: 1.22;
  font-weight: 600;
  letter-spacing: -0.02em;
  color: var(--bs-emphasis-color);
}
.rev-hero-title em {
  font-style: normal;
  font-variant-numeric: tabular-nums;
  background: linear-gradient(90deg, var(--bs-primary), #02a8b5);
  -webkit-background-clip: text;
  background-clip: text;
  -webkit-text-fill-color: transparent;
}
@media (max-width: 767.98px) {
  .rev-hero-title {
    font-size: 24px;
  }
}

/* the status block is a short statement, ruled like one */
.rev-hero-stmt {
  margin-top: 20px;
  padding: 4px 18px;
  border-radius: var(--radius);
  background: var(--bs-body-bg);
  border: 1px solid var(--bs-border-color);
}

/* ---- illustration: the forecast cone ---- */
.rev-cone-panel {
  display: flex;
  flex-direction: column;
  gap: 16px;
  padding: 20px;
  border-radius: var(--radius);
  background: var(--bs-body-bg);
  border: 1px solid var(--bs-border-color);
  box-shadow: var(--aix-glow);
}

/* three nested bands widening to the right: the range of outcomes */
.rev-cone {
  position: relative;
  height: 132px;
}

.rev-cone-band {
  position: absolute;
  inset: 0;
  border-radius: 6px;
}
.rev-cone-band.b1 {
  background: linear-gradient(90deg, rgba(61, 94, 225, 0.05), rgba(61, 94, 225, 0.16));
  clip-path: polygon(0 46%, 100% 4%, 100% 96%, 0 54%);
}
.rev-cone-band.b2 {
  background: linear-gradient(90deg, rgba(61, 94, 225, 0.1), rgba(61, 94, 225, 0.3));
  clip-path: polygon(0 47%, 100% 24%, 100% 76%, 0 53%);
}
.rev-cone-band {
  /* the expected line runs through the middle */
}
.rev-cone-band.b3 {
  background: linear-gradient(90deg, var(--bs-primary), #02a8b5);
  clip-path: polygon(0 48%, 100% 46%, 100% 54%, 0 52%);
}

.rev-cone-pin {
  position: absolute;
  right: 0;
  top: 50%;
  transform: translate(50%, -50%);
  width: 12px;
  height: 12px;
  border-radius: 50%;
  background: var(--bs-body-bg);
  border: 3px solid var(--bs-primary);
  box-shadow: var(--shadow);
}

.rev-cone-axis {
  display: flex;
  justify-content: space-between;
  font-size: 11px;
  color: var(--bs-secondary-color);
}

/* ============================================================
   REVENUE CASE CARDS — statement head, amount, probability
   ============================================================ */
.rev-case {
  display: flex;
  flex-direction: column;
  height: 100%;
  border-radius: var(--radius);
  background: var(--bs-body-bg);
  border: 1px solid var(--bs-border-color);
  overflow: hidden;
  transition: var(--transition);
}
.rev-case:hover {
  border-color: rgba(61, 94, 225, 0.28);
  box-shadow: var(--shadow-lift);
}

.rev-case-head {
  display: flex;
  align-items: center;
  gap: 13px;
  padding: 16px 18px;
  border-bottom: 1px dashed var(--bs-border-color);
}

.rev-case-name {
  margin: 0 0 2px;
  font-size: 14.5px;
  font-weight: 600;
  color: var(--bs-emphasis-color);
}

/* the outstanding amount sits alone on a tinted shelf */
.rev-shelf {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 12px;
  padding: 14px 18px;
  background: var(--bs-secondary-bg);
}

.rev-case-body {
  display: flex;
  flex-direction: column;
  gap: 13px;
  flex: 1 1 auto;
  padding: 16px 18px;
}

.rev-case-foot {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 12px 18px;
  border-top: 1px solid var(--bs-border-color);
}

.rev-ico {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 34px;
  height: 34px;
  flex-shrink: 0;
  border-radius: 6px;
  background: var(--bs-secondary-bg);
  border: 1px solid var(--bs-border-color);
  color: var(--bs-secondary-color);
  font-size: 16px;
  transition: var(--transition);
}
.rev-ico:hover {
  color: var(--bs-primary);
  border-color: var(--bs-primary);
  background: var(--tint-primary);
}

/* ============================================================
   EXPLAINABLE AI — content left, a tinted impact rail right
   ============================================================ */
.rev-note {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 232px;
  height: 100%;
  border-radius: var(--radius);
  background: var(--bs-body-bg);
  border: 1px solid var(--bs-border-color);
  overflow: hidden;
  transition: var(--transition);
}
.rev-note:hover {
  box-shadow: var(--shadow-lift);
}
@media (max-width: 991.98px) {
  .rev-note {
    grid-template-columns: minmax(0, 1fr);
  }
}

.rev-note-body {
  padding: 20px;
}

.rev-note-obs {
  margin: 0 0 12px;
  font-size: 15.5px;
  font-weight: 600;
  color: var(--bs-emphasis-color);
}

.rev-ev {
  display: flex;
  align-items: baseline;
  gap: 10px;
  padding: 7px 0;
  font-size: 12.5px;
}
.rev-ev + .rev-ev {
  border-top: 1px dotted var(--bs-border-color);
}
.rev-ev > span:first-child {
  flex-shrink: 0;
  color: var(--bs-secondary-color);
}
.rev-ev > b {
  flex-shrink: 0;
  font-weight: 600;
  font-variant-numeric: tabular-nums;
  color: var(--bs-emphasis-color);
}

/* the rail carries the money view of the same finding */
.rev-rail {
  display: flex;
  flex-direction: column;
  gap: 14px;
  padding: 20px;
  background: linear-gradient(180deg, var(--tint-primary), var(--bs-secondary-bg));
  border-left: 1px solid var(--bs-border-color);
}
.rev-rail.is-likely {
  background: linear-gradient(180deg, #E8F9E8, var(--bs-secondary-bg));
}
.rev-rail.is-slow {
  background: linear-gradient(180deg, #FEF8EA, var(--bs-secondary-bg));
}
.rev-rail.is-risk {
  background: linear-gradient(180deg, #FDE9ED, var(--bs-secondary-bg));
}
@media (max-width: 991.98px) {
  .rev-rail {
    border-left: 0;
    border-top: 1px solid var(--bs-border-color);
  }
}

/* ============================================================
   INTELLIGENCE CARDS — an amount block beside the finding
   ============================================================ */
.rev-int {
  display: flex;
  height: 100%;
  border-radius: var(--radius);
  background: var(--bs-body-bg);
  border: 1px solid var(--bs-border-color);
  overflow: hidden;
  transition: var(--transition);
}
.rev-int:hover {
  border-color: rgba(61, 94, 225, 0.28);
  box-shadow: var(--shadow-lift);
}

.rev-int-fig {
  flex-shrink: 0;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 6px;
  width: 108px;
  padding: 16px 10px;
  text-align: center;
  background: var(--bs-secondary-bg);
  border-right: 1px solid var(--bs-border-color);
}
.rev-int-fig i {
  font-size: 19px;
  color: var(--bs-primary);
}

.rev-int-body {
  padding: 16px 18px;
}

.rev-int-title {
  margin: 0 0 10px;
  font-size: 14.5px;
  font-weight: 600;
  color: var(--bs-emphasis-color);
}

.rev-kv {
  margin-bottom: 10px;
}
.rev-kv span:first-child {
  display: block;
  margin-bottom: 2px;
  font-size: 10.5px;
  font-weight: 600;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--bs-secondary-color);
}
.rev-kv span:last-child {
  display: block;
  font-size: 12.5px;
  line-height: 1.55;
  color: var(--bs-emphasis-color);
}

/* ============================================================
   COLLECTION CARDS — probability blocks across the top
   ============================================================ */
.rev-rec {
  display: flex;
  flex-direction: column;
  height: 100%;
  border-radius: var(--radius);
  background: var(--bs-body-bg);
  border: 1px solid var(--bs-border-color);
  overflow: hidden;
  transition: var(--transition);
}
.rev-rec:hover {
  box-shadow: var(--shadow-lift);
}

.rev-rec-top {
  padding: 14px 16px 12px;
  border-bottom: 1px solid var(--bs-border-color);
}

.rev-rec-body {
  display: flex;
  flex-direction: column;
  gap: 10px;
  flex: 1 1 auto;
  padding: 16px;
}

.rev-rec-title {
  margin: 0;
  font-size: 14.5px;
  font-weight: 600;
  color: var(--bs-emphasis-color);
}

.rev-rec-foot {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  margin-top: auto;
  padding-top: 12px;
  border-top: 1px dashed var(--bs-border-color);
}

/* ============================================================
   OPPORTUNITY TILES — a corner amount badge
   ============================================================ */
.rev-opp {
  position: relative;
  height: 100%;
  padding: 18px;
  border-radius: var(--radius);
  background: var(--bs-body-bg);
  border: 1px solid var(--bs-border-color);
  transition: var(--transition);
}
.rev-opp:hover {
  border-color: rgba(61, 94, 225, 0.28);
  box-shadow: var(--shadow-lift);
}

.rev-opp-badge {
  position: absolute;
  right: 16px;
  top: 16px;
  padding: 4px 9px;
  border-radius: 4px;
  background: var(--tint-primary);
  color: var(--bs-primary);
  font-size: 12px;
  font-weight: 700;
  font-variant-numeric: tabular-nums;
}
.rev-opp-badge.is-likely {
  background: #E8F9E8;
  color: #1ABE17;
}
.rev-opp-badge.is-slow {
  background: #FEF8EA;
  color: #EAB300;
}
.rev-opp-badge.is-risk {
  background: #FDE9ED;
  color: #E82646;
}
html[data-theme=dark] .rev-opp-badge.is-likely {
  background: rgba(26, 190, 23, 0.16);
  color: color-mix(in srgb, #1ABE17 60%, white);
}
html[data-theme=dark] .rev-opp-badge.is-slow {
  background: rgba(234, 179, 0, 0.16);
  color: color-mix(in srgb, #EAB300 60%, white);
}
html[data-theme=dark] .rev-opp-badge.is-risk {
  background: rgba(232, 38, 70, 0.16);
  color: color-mix(in srgb, #E82646 60%, white);
}

.rev-opp-title {
  margin: 0 0 8px;
  padding-right: 84px;
  font-size: 14px;
  font-weight: 600;
  color: var(--bs-emphasis-color);
}

/* ============================================================
   COPILOT — indexed rows with a run chip
   ============================================================ */
.rev-do {
  display: flex;
  align-items: center;
  gap: 14px;
  width: 100%;
  padding: 14px 16px;
  border-radius: var(--radius);
  background: var(--bs-body-bg);
  border: 1px solid var(--bs-border-color);
  transition: var(--transition);
}
.rev-do:hover {
  border-color: rgba(61, 94, 225, 0.3);
  box-shadow: var(--aix-glow);
}
.rev-do:hover .rev-do-run {
  background: var(--bs-primary);
  border-color: var(--bs-primary);
  color: #fff;
}

.rev-do-ix {
  flex-shrink: 0;
  width: 34px;
  font-size: 12px;
  font-weight: 700;
  font-variant-numeric: tabular-nums;
  letter-spacing: 0.04em;
  color: var(--bs-secondary-color);
}

.rev-do-run {
  flex-shrink: 0;
  display: inline-flex;
  align-items: center;
  gap: 5px;
  padding: 5px 11px;
  border-radius: 4px;
  background: var(--bs-secondary-bg);
  border: 1px solid var(--bs-border-color);
  color: var(--bs-secondary-color);
  font-size: 11px;
  font-weight: 600;
  transition: var(--transition);
}

/* ============================================================
   REVENUE JOURNEY — squares on a dotted rail, amounts at the right
   ============================================================ */
.rev-journey {
  position: relative;
  padding-left: 30px;
}
.rev-journey::before {
  content: "";
  position: absolute;
  left: 8px;
  top: 14px;
  bottom: 14px;
  border-left: 2px dotted var(--bs-border-color);
}

.rev-stop {
  position: relative;
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 12px;
  padding: 14px 16px;
  border-radius: var(--radius);
  background: var(--bs-secondary-bg);
  border: 1px solid transparent;
  transition: var(--transition);
}
.rev-stop + .rev-stop {
  margin-top: 12px;
}
.rev-stop:hover {
  background: var(--bs-body-bg);
  border-color: var(--bs-border-color);
  box-shadow: var(--shadow);
}
.rev-stop {
  /* a small square sat on the dotted rail */
}
.rev-stop::before {
  content: "";
  position: absolute;
  left: -27px;
  top: 22px;
  width: 12px;
  height: 12px;
  border-radius: 3px;
  background: var(--bs-body-bg);
  border: 2px solid var(--bs-tertiary-bg);
}
.rev-stop.is-done::before {
  background: #1ABE17;
  border-color: #1ABE17;
}
.rev-stop.is-now {
  background: var(--bs-body-bg);
  border-color: rgba(61, 94, 225, 0.3);
}
.rev-stop.is-now::before {
  border-color: var(--bs-primary);
  box-shadow: 0 0 0 4px var(--tint-primary);
}

.rev-stop-title {
  margin: 0 0 3px;
  font-size: 14px;
  font-weight: 600;
  color: var(--bs-emphasis-color);
}

/* ============================================================
   FINANCIAL OPPORTUNITY — a dotted-leader stat foot
   ============================================================ */
.rev-fin {
  display: flex;
  flex-direction: column;
  height: 100%;
  padding: 18px;
  border-radius: var(--radius);
  background: var(--bs-body-bg);
  border: 1px solid var(--bs-border-color);
  transition: var(--transition);
}
.rev-fin:hover {
  border-color: rgba(61, 94, 225, 0.28);
  box-shadow: var(--shadow-lift);
}

.rev-fin-ic {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 40px;
  height: 40px;
  margin-bottom: 12px;
  border-radius: 8px;
  background: var(--tint-primary);
  color: var(--bs-primary);
  font-size: 19px;
}

.rev-fin-title {
  margin: 0 0 6px;
  font-size: 14px;
  font-weight: 600;
  color: var(--bs-emphasis-color);
}

.rev-fin-foot {
  margin-top: auto;
  padding-top: 14px;
  border-top: 1px solid var(--bs-border-color);
}

/* ============================================================
   INSIGHT ROWS — a large figure leading the line
   ============================================================ */
.rev-ins {
  display: flex;
  align-items: flex-start;
  gap: 16px;
  height: 100%;
  padding: 16px 18px;
  border-radius: var(--radius);
  background: var(--bs-body-bg);
  border: 1px solid var(--bs-border-color);
  transition: var(--transition);
}
.rev-ins:hover {
  box-shadow: var(--shadow);
}

.rev-ins-fig {
  flex-shrink: 0;
  min-width: 78px;
  font-size: 21px;
  font-weight: 700;
  line-height: 1.2;
  font-variant-numeric: tabular-nums;
  letter-spacing: -0.02em;
  color: var(--bs-primary);
}
.rev-ins-fig.is-in {
  color: #1ABE17;
}
.rev-ins-fig.is-out {
  color: #E82646;
}

.rev-ins-title {
  margin: 0 0 4px;
  font-size: 14px;
  font-weight: 600;
  color: var(--bs-emphasis-color);
}

/* ============================================================
   WORKSPACE OFFCANVAS — boxed steps with a filling top edge
   ============================================================ */
.offcanvas.offcanvas-end.rev-ws {
  width: 88% !important;
  max-width: 1440px !important;
}
@media (max-width: 991.98px) {
  .offcanvas.offcanvas-end.rev-ws {
    width: 100% !important;
  }
}
.offcanvas.offcanvas-end.rev-ws .offcanvas-body {
  padding: 22px;
}

.rev-ws-head {
  display: flex;
  align-items: center;
  gap: 18px;
  flex-wrap: wrap;
  padding: 20px 22px;
  background: linear-gradient(105deg, var(--bs-body-bg) 0%, #E8F9E8 100%);
  border-bottom: 1px solid var(--bs-border-color);
}

.rev-steps {
  display: grid;
  grid-template-columns: repeat(5, minmax(0, 1fr));
  gap: 10px;
  list-style: none;
  margin: 0;
  padding: 16px 22px;
  background: var(--bs-secondary-bg);
  border-bottom: 1px solid var(--bs-border-color);
}
@media (max-width: 767.98px) {
  .rev-steps {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}

.rev-step {
  position: relative;
  display: flex;
  align-items: center;
  gap: 10px;
  width: 100%;
  padding: 12px 14px;
  border: 1px solid var(--bs-border-color);
  border-radius: var(--radius-sm);
  background: var(--bs-body-bg);
  text-align: left;
  transition: var(--transition);
  /* the top edge fills when active */
}
.rev-step::before {
  content: "";
  position: absolute;
  left: -1px;
  right: -1px;
  top: -1px;
  height: 3px;
  border-radius: var(--radius-sm) var(--radius-sm) 0 0;
  background: transparent;
  transition: var(--transition);
}
.rev-step {
  /* the caret linking to the next step */
}
.rev-step::after {
  content: "";
  position: absolute;
  left: calc(100% + 1px);
  top: 50%;
  transform: translateY(-50%);
  border-width: 5px 0 5px 6px;
  border-style: solid;
  border-color: transparent transparent transparent var(--bs-border-color);
}
.rev-step.is-last::after {
  display: none;
}
.rev-step:hover {
  border-color: rgba(61, 94, 225, 0.3);
}
.rev-step.active {
  border-color: rgba(61, 94, 225, 0.35);
  box-shadow: var(--shadow);
}
.rev-step.active::before {
  background: var(--bs-primary);
}
.rev-step.active .rev-step-n {
  background: var(--bs-primary);
  border-color: var(--bs-primary);
  color: #fff;
}
.rev-step.active .rev-step-txt span:last-child {
  color: var(--bs-emphasis-color);
}
@media (max-width: 767.98px) {
  .rev-step::after {
    display: none;
  }
}

.rev-step-n {
  flex-shrink: 0;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 28px;
  height: 28px;
  border-radius: 5px;
  background: var(--bs-secondary-bg);
  border: 1px solid var(--bs-border-color);
  color: var(--bs-secondary-color);
  font-size: 11px;
  font-weight: 700;
  font-variant-numeric: tabular-nums;
  transition: var(--transition);
}

.rev-step-txt {
  display: flex;
  flex-direction: column;
  min-width: 0;
  line-height: 1.25;
}
.rev-step-txt span:first-child {
  font-size: 10px;
  font-weight: 600;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--bs-secondary-color);
}
.rev-step-txt span:last-child {
  font-size: 13px;
  font-weight: 600;
  color: var(--bs-secondary-color);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

/* panels inside the workspace */
.rev-box {
  height: 100%;
  border-radius: var(--radius);
  background: var(--bs-body-bg);
  border: 1px solid var(--bs-border-color);
  overflow: hidden;
}

.rev-box-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 13px 16px;
  background: var(--bs-secondary-bg);
  border-bottom: 1px solid var(--bs-border-color);
}
.rev-box-head h6 {
  margin: 0;
  font-size: 13px;
  font-weight: 600;
  color: var(--bs-emphasis-color);
}

.rev-box-body {
  padding: 16px;
}

/* a quoted note from the finance team */
.rev-quote {
  padding: 14px 16px;
  border-radius: var(--radius-sm);
  background: var(--bs-secondary-bg);
  border-left: 3px solid var(--bs-primary);
  font-size: 13px;
  line-height: 1.68;
  color: var(--bs-emphasis-color);
}

/* ============================================================
   PREMIUM ACCORDION + EMPTY STATE
   ============================================================ */
.rev-acc .accordion-item {
  margin-bottom: 10px;
  background: var(--bs-body-bg);
  border: 1px solid var(--bs-border-color);
  border-radius: var(--radius) !important;
  overflow: hidden;
}
.rev-acc .accordion-button {
  padding: 14px 16px;
  font-size: 13.5px;
  font-weight: 600;
  color: var(--bs-emphasis-color);
  background: var(--bs-body-bg);
  box-shadow: none;
}
.rev-acc .accordion-button:not(.collapsed) {
  background: var(--tint-primary);
  color: var(--bs-primary);
}
.rev-acc .accordion-button:focus {
  box-shadow: none;
}
.rev-acc .accordion-body {
  padding: 15px 16px;
  font-size: 13px;
  line-height: 1.65;
  color: var(--bs-secondary-color);
  border-top: 1px solid var(--bs-border-color);
}

.rev-empty {
  padding: 40px 24px;
  text-align: center;
  border-radius: var(--radius);
  background: var(--bs-body-bg);
  border: 1px dashed var(--bs-border-color);
}

.rev-empty-ic {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 56px;
  height: 56px;
  margin-bottom: 14px;
  border-radius: 8px;
  background: var(--tint-primary);
  color: var(--bs-primary);
  font-size: 25px;
}

/* ============================================================
   24. AI OPERATING CENTER  —  prefix `ops-`

   The ninth family, and the one that defines the module. Every other AI
   page is a single application; this one is the surface they all launch
   from, so it is the only family that goes dark and cinematic.

     aix-  enclosed cards, hairline dividers, chevron steppers
     atn-  banded surfaces, a vertical spine, stations, arc gauges
     sdt-  portrait medallion, chapter numerals, date gutter, dot scales
     tto-  slot grids, bracketed marks, before/after bars, a horizontal track
     hwk-  paper sheets, margin rules, grade seals, rubric strips
     tch-  tinted bands, facet bars, definition rows, medals, folded corners
     fam-  paired avatars, message threads, drop capitals, calendar chips
     rev-  dotted leaders, tabular amounts, probability blocks, forecast cone
     ops-  a dark mission surface, glass panels, bento spans, telemetry rails
           and a glowing pipeline

   Nothing here overrides a rule from the families above.
   ============================================================ */
/* dark surface tokens, scoped to this family only */
@media (prefers-reduced-motion: reduce) {
  [class*=ops-],
  [class*=ops-]::before,
  [class*=ops-]::after {
    animation: none !important;
    transition: none !important;
  }
}
/* ---- section heading: an eyebrow, a title, a hairline to the edge ---- */
.ops-hd {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 16px;
  margin-bottom: 24px;
}

.ops-eyebrow {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  margin-bottom: 8px;
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  color: var(--bs-primary);
}
.ops-eyebrow::before {
  content: "";
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: var(--bs-primary);
  box-shadow: 0 0 0 3px var(--tint-primary);
}

.ops-hd-title {
  margin: 0;
  font-size: 22px;
  font-weight: 600;
  letter-spacing: -0.02em;
  color: var(--bs-emphasis-color);
}

.ops-hd-sub {
  margin: 5px 0 0;
  font-size: 13px;
  color: var(--bs-secondary-color);
  max-width: 720px;
}

/* ---- shared pieces ---------------------------------------------------- */
.ops-lbl {
  display: block;
  font-size: 10.5px;
  font-weight: 600;
  letter-spacing: 0.09em;
  text-transform: uppercase;
  color: var(--bs-secondary-color);
}

.ops-chip {
  /* geometry, typography and surface come from the shared badge component */
}
.ops-chip i {
  font-size: 12px;
}
.ops-chip.is-ai {
  background: var(--tint-primary);
  border-color: rgba(61, 94, 225, 0.2);
  color: var(--bs-primary);
}
.ops-chip.is-live {
  background: #E8F9E8;
  border-color: #D1F2D1;
  color: #1ABE17;
}
.ops-chip.is-idle {
  background: #E7F1FC;
  border-color: #CFE2FA;
  color: #0F65CD;
}
.ops-chip.is-queued {
  background: #FEF8EA;
  border-color: #FDF1D6;
  color: #EAB300;
}
.ops-chip.is-off {
  background: #FDE9ED;
  border-color: #FAD4DA;
  color: #E82646;
}
.ops-chip {
  /* on the dark surface the chip becomes glass */
}
.ops-dark .ops-chip {
  background: rgba(255, 255, 255, 0.07);
  border-color: var(--bs-border-color);
  color: var(--bs-emphasis-color);
}
.ops-dark .ops-chip.is-live {
  background: rgba(26, 190, 23, 0.16);
  border-color: rgba(26, 190, 23, 0.3);
  color: #7BE87A;
}
.ops-dark .ops-chip.is-ai {
  background: rgba(108, 139, 255, 0.16);
  border-color: rgba(108, 139, 255, 0.32);
  color: #A9BCFF;
}
/* Site dark mode - .ops-dark above only covers chips inside this page's
   permanently-dark "glass" panels; chips elsewhere on the page still sat
   on solid light pastel backgrounds when the whole site switched to dark
   mode. Same translucent-wash treatment as .ops-dark, so a chip looks the
   same whether it's in a glass panel or on an ordinary dark-mode card. */
html[data-theme=dark] .ops-chip.is-live {
  background: rgba(26, 190, 23, 0.16);
  border-color: rgba(26, 190, 23, 0.32);
  color: color-mix(in srgb, #1ABE17 60%, white);
}
html[data-theme=dark] .ops-chip.is-idle {
  background: rgba(15, 101, 205, 0.16);
  border-color: rgba(15, 101, 205, 0.32);
  color: color-mix(in srgb, #0F65CD 60%, white);
}
html[data-theme=dark] .ops-chip.is-queued {
  background: rgba(234, 179, 0, 0.16);
  border-color: rgba(234, 179, 0, 0.32);
  color: color-mix(in srgb, #EAB300 60%, white);
}
html[data-theme=dark] .ops-chip.is-off {
  background: rgba(232, 38, 70, 0.16);
  border-color: rgba(232, 38, 70, 0.32);
  color: color-mix(in srgb, #E82646 60%, white);
}

/* a live pulsing dot, used for service status */
.ops-dot {
  position: relative;
  display: inline-block;
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: #1ABE17;
  flex-shrink: 0;
}
.ops-dot::after {
  content: "";
  position: absolute;
  inset: -4px;
  border-radius: 50%;
  border: 1px solid currentColor;
  color: #1ABE17;
  opacity: 0;
  animation: ops-pulse 2.4s ease-out infinite;
}
.ops-dot.is-idle {
  background: #0F65CD;
}
.ops-dot.is-idle::after {
  color: #0F65CD;
}
.ops-dot.is-queued {
  background: #EAB300;
}
.ops-dot.is-queued::after {
  color: #EAB300;
}
.ops-dot.is-off {
  background: #E82646;
}
.ops-dot.is-off::after {
  animation: none;
}

@keyframes ops-pulse {
  0% {
    transform: scale(0.6);
    opacity: 0.9;
  }
  100% {
    transform: scale(1.9);
    opacity: 0;
  }
}
/* health meter — four segments */
.ops-health {
  display: inline-flex;
  gap: 3px;
}
.ops-health i {
  width: 14px;
  height: 4px;
  border-radius: 2px;
  background: var(--bs-tertiary-bg);
}
.ops-health i.on {
  background: #1ABE17;
}
.ops-health.is-warn i.on {
  background: #EAB300;
}
.ops-health.is-bad i.on {
  background: #E82646;
}
.ops-dark .ops-health i {
  background: rgba(255, 255, 255, 0.16);
}

/* ============================================================
   1. MISSION CONTROL — the dark cinematic hero
   ============================================================ */
.ops-mission {
  position: relative;
  overflow: hidden;
  border-radius: 20px;
  background: radial-gradient(90% 120% at 10% 0%, rgba(108, 139, 255, 0.28) 0%, transparent 55%), radial-gradient(70% 100% at 100% 100%, rgba(53, 214, 229, 0.2) 0%, transparent 58%), linear-gradient(160deg, var(--bs-secondary-color) 0%, var(--bs-emphasis-color) 100%);
  color: var(--bs-body-color);
  box-shadow: 0 24px 60px rgba(14, 21, 38, 0.28);
}

/* a fine grid, faded out toward the foot — the mission surface */
.ops-mission::before {
  content: "";
  position: absolute;
  inset: 0;
  background-image: linear-gradient(var(--bs-border-color) 1px, transparent 1px), linear-gradient(90deg, var(--bs-border-color) 1px, transparent 1px);
  background-size: 54px 54px;
  mask-image: radial-gradient(120% 90% at 50% 0%, #000 0%, transparent 78%);
  pointer-events: none;
}

/* a slow sweep of light across the surface */
.ops-mission::after {
  content: "";
  position: absolute;
  top: -40%;
  left: -30%;
  width: 60%;
  height: 180%;
  background: linear-gradient(90deg, transparent, rgba(255, 255, 255, 0.05), transparent);
  transform: rotate(18deg);
  animation: ops-sweep 9s ease-in-out infinite;
  pointer-events: none;
}

@keyframes ops-sweep {
  0%, 100% {
    transform: translateX(-10%) rotate(18deg);
    opacity: 0;
  }
  50% {
    transform: translateX(120%) rotate(18deg);
    opacity: 1;
  }
}
.ops-mission-inner {
  position: relative;
  display: grid;
  grid-template-columns: minmax(0, 1fr) 392px;
  gap: 40px;
  padding: 40px;
}
@media (max-width: 1299.98px) {
  .ops-mission-inner {
    grid-template-columns: minmax(0, 1fr);
    gap: 30px;
    padding: 32px;
  }
}
@media (max-width: 575.98px) {
  .ops-mission-inner {
    padding: 24px;
  }
}

.ops-mission-badge {
  display: inline-flex;
  align-items: center;
  gap: 9px;
  padding: 6px 14px 6px 8px;
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.07);
  border: 1px solid var(--bs-border-color);
  backdrop-filter: blur(8px);
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--bs-emphasis-color);
}
.ops-mission-badge i {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 24px;
  height: 24px;
  border-radius: 50%;
  background: linear-gradient(135deg, var(--bs-primary), var(--accent-strong));
  color: #0E1526;
  font-size: 14px;
}

.ops-mission-title {
  margin: 20px 0 14px;
  font-size: 42px;
  line-height: 1.12;
  font-weight: 600;
  letter-spacing: -0.03em;
  color: var(--bs-emphasis-color);
}
.ops-mission-title em {
  font-style: normal;
  background: linear-gradient(90deg, var(--bs-primary), var(--accent-strong));
  -webkit-background-clip: text;
  background-clip: text;
  -webkit-text-fill-color: transparent;
}
@media (max-width: 991.98px) {
  .ops-mission-title {
    font-size: 32px;
  }
}
@media (max-width: 575.98px) {
  .ops-mission-title {
    font-size: 26px;
  }
}

.ops-mission-lead {
  margin: 0;
  max-width: 640px;
  font-size: 15px;
  line-height: 1.7;
  color: var(--bs-body-color);
}

/* telemetry rail: figures on the dark surface, divided by hairlines */
.ops-rail {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 1px;
  margin-top: 30px;
  background: var(--bs-border-color);
  border: 1px solid var(--bs-border-color);
  border-radius: var(--radius);
  overflow: hidden;
}
@media (max-width: 575.98px) {
  .ops-rail {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}

.ops-rail-cell {
  padding: 15px 18px;
  background: rgba(255, 255, 255, 0.02);
  line-height: 1.3;
}
.ops-rail-cell b {
  display: block;
  margin-top: 5px;
  font-size: 21px;
  font-weight: 600;
  font-variant-numeric: tabular-nums;
  color: var(--bs-emphasis-color);
}
.ops-rail-cell b small {
  font-size: 12px;
  font-weight: 500;
  color: var(--bs-body-color);
}
.ops-rail-cell span:first-child {
  font-size: 10.5px;
  font-weight: 600;
  letter-spacing: 0.09em;
  text-transform: uppercase;
  color: rgba(255, 255, 255, 0.5);
}

/* primary actions on the dark surface */
.ops-btn {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  padding: 11px 20px;
  border-radius: 10px;
  border: 1px solid var(--bs-border-color);
  background: rgba(255, 255, 255, 0.07);
  color: var(--bs-emphasis-color);
  font-size: 14px;
  font-weight: 600;
  backdrop-filter: blur(8px);
  transition: var(--transition);
}
.ops-btn:hover {
  background: rgba(255, 255, 255, 0.13);
  color: var(--bs-emphasis-color);
  transform: translateY(-1px);
}
.ops-btn.is-primary {
  background: linear-gradient(135deg, var(--bs-primary), #4C6BE8);
  border-color: transparent;
  box-shadow: 0 8px 24px rgba(76, 107, 232, 0.4);
}
.ops-btn.is-primary:hover {
  box-shadow: 0 12px 30px rgba(76, 107, 232, 0.5);
}

/* ---- the glass mission panel on the right ---- */
.ops-glass {
  position: relative;
  display: flex;
  flex-direction: column;
  gap: 16px;
  padding: 22px;
  border-radius: 16px;
  background: rgba(255, 255, 255, 0.06);
  border: 1px solid var(--bs-border-color);
  backdrop-filter: blur(14px);
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.08);
}

/* a floating orb behind the glass */
.ops-orb {
  position: absolute;
  border-radius: 50%;
  filter: blur(30px);
  pointer-events: none;
}
.ops-orb.o1 {
  width: 160px;
  height: 160px;
  right: -40px;
  top: -50px;
  background: rgba(108, 139, 255, 0.5);
  animation: ops-drift 14s ease-in-out infinite;
}
.ops-orb.o2 {
  width: 120px;
  height: 120px;
  left: -30px;
  bottom: -40px;
  background: rgba(53, 214, 229, 0.38);
  animation: ops-drift 18s ease-in-out infinite reverse;
}

@keyframes ops-drift {
  0%, 100% {
    transform: translate(0, 0);
  }
  50% {
    transform: translate(-16px, 20px);
  }
}
/* the mission list inside the glass */
.ops-mission-row {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 11px 0;
  font-size: 13px;
  color: var(--bs-body-color);
}
.ops-mission-row + .ops-mission-row {
  border-top: 1px solid var(--bs-border-color);
}
.ops-mission-row b {
  display: block;
  font-weight: 600;
  color: var(--bs-emphasis-color);
}
.ops-mission-row time {
  flex-shrink: 0;
  font-size: 11px;
  font-variant-numeric: tabular-nums;
  color: rgba(255, 255, 255, 0.45);
}

.ops-mission-ic {
  flex-shrink: 0;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 34px;
  height: 34px;
  border-radius: 10px;
  background: rgba(255, 255, 255, 0.08);
  border: 1px solid var(--bs-border-color);
  color: var(--bs-emphasis-color);
  font-size: 16px;
}

/* ============================================================
   2. BENTO — the capability hub
   ============================================================ */
.ops-bento {
  display: grid;
  grid-template-columns: repeat(6, minmax(0, 1fr));
  gap: 16px;
}
@media (max-width: 1199.98px) {
  .ops-bento {
    grid-template-columns: repeat(4, minmax(0, 1fr));
  }
}
@media (max-width: 767.98px) {
  .ops-bento {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}

/* spans, so the grid reads as a bento rather than as a row of equals */
.ops-span-2 {
  grid-column: span 2;
}

.ops-span-3 {
  grid-column: span 3;
}

.ops-span-4 {
  grid-column: span 4;
}

@media (max-width: 1199.98px) {
  .ops-span-3, .ops-span-4 {
    grid-column: span 4;
  }
}
@media (max-width: 767.98px) {
  .ops-span-2, .ops-span-3, .ops-span-4 {
    grid-column: span 2;
  }
}
.ops-tile {
  position: relative;
  display: flex;
  flex-direction: column;
  gap: 12px;
  min-height: 168px;
  padding: 20px;
  border-radius: 16px;
  background: var(--bs-body-bg);
  border: 1px solid var(--bs-border-color);
  overflow: hidden;
  transition: var(--transition);
  /* a corner glow that arrives on hover */
}
.ops-tile::after {
  content: "";
  position: absolute;
  right: -50px;
  top: -50px;
  width: 150px;
  height: 150px;
  border-radius: 50%;
  background: radial-gradient(circle, var(--tint-primary) 0%, transparent 70%);
  opacity: 0;
  transition: var(--transition);
}
.ops-tile:hover {
  border-color: rgba(61, 94, 225, 0.32);
  box-shadow: var(--shadow-lift);
  transform: translateY(-2px);
}
.ops-tile:hover::after {
  opacity: 1;
}
.ops-tile:hover .ops-tile-ic {
  background: linear-gradient(135deg, var(--bs-primary), #02a8b5);
  border-color: transparent;
  color: #fff;
}
.ops-tile {
  /* the feature tile carries the dark treatment */
}
.ops-tile.is-feature {
  background: radial-gradient(80% 120% at 100% 0%, rgba(53, 214, 229, 0.18) 0%, transparent 60%), linear-gradient(150deg, #3D5EE1 0%, #202C4B 100%);
  border-color: transparent;
  color: rgba(255, 255, 255, 0.78);
}
.ops-tile.is-feature .ops-tile-title, .ops-tile.is-feature .ops-tile-fig {
  color: #fff;
}
.ops-tile.is-feature .ops-tile-ic {
  background: rgba(255, 255, 255, 0.12);
  border-color: rgba(255, 255, 255, 0.18);
  color: #fff;
}
.ops-tile.is-feature .ops-lbl {
  color: rgba(255, 255, 255, 0.55);
}
.ops-tile.is-feature .ops-health i {
  background: rgba(255, 255, 255, 0.2);
}

.ops-tile-ic {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 42px;
  height: 42px;
  border-radius: 12px;
  background: var(--tint-primary);
  border: 1px solid transparent;
  color: var(--bs-primary);
  font-size: 20px;
  transition: var(--transition);
}

.ops-tile-title {
  margin: 0;
  font-size: 15px;
  font-weight: 600;
  color: var(--bs-emphasis-color);
}

.ops-tile-fig {
  font-size: 26px;
  font-weight: 700;
  line-height: 1;
  font-variant-numeric: tabular-nums;
  letter-spacing: -0.02em;
  color: var(--bs-emphasis-color);
}

/* ---- the full-width tile ------------------------------------------------
   A tile spanning the whole grid cannot keep the stacked layout: the copy
   would run the full width and the figure would sit alone in dead space.
   From lg up it becomes three columns — identity, reading, controls — and
   drops the stacked min-height so it reads as a banner, not a short card. */
@media (min-width: 992px) {
  .ops-tile.is-wide {
    display: grid;
    grid-template-columns: 268px minmax(0, 1fr) auto;
    align-items: center;
    gap: 28px;
    min-height: 0;
    padding: 22px 24px;
  }
  .ops-tile.is-wide .ops-tile-foot {
    margin-top: 0;
    padding-top: 0;
    border-top: 0;
    flex-direction: column;
    align-items: flex-end;
    gap: 12px;
  }
}

/* identity column of the wide tile: icon beside the figure, not above it */
.ops-tile-lead {
  display: flex;
  align-items: center;
  gap: 14px;
}

.ops-tile-foot {
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 8px 10px;
  margin-top: auto;
  padding-top: 12px;
  border-top: 1px solid var(--bs-border-color);
}
.is-feature .ops-tile-foot {
  border-top-color: rgba(255, 255, 255, 0.14);
}

/* ============================================================
   3. LAUNCHER — large application tiles
   ============================================================ */
.ops-launch {
  position: relative;
  display: flex;
  align-items: center;
  gap: 16px;
  height: 100%;
  padding: 20px;
  border-radius: 14px;
  background: var(--bs-body-bg);
  border: 1px solid var(--bs-border-color);
  overflow: hidden;
  transition: var(--transition);
  /* a thin accent that fills from the left on hover */
}
.ops-launch::before {
  content: "";
  position: absolute;
  left: 0;
  top: 0;
  bottom: 0;
  width: 3px;
  background: linear-gradient(180deg, var(--bs-primary), #02a8b5);
  transform: scaleY(0);
  transform-origin: top;
  transition: var(--transition);
}
.ops-launch:hover {
  border-color: rgba(61, 94, 225, 0.3);
  box-shadow: var(--aix-glow);
}
.ops-launch:hover::before {
  transform: scaleY(1);
}
.ops-launch:hover .ops-launch-go {
  transform: translateX(4px);
  color: var(--bs-primary);
}

.ops-launch-ic {
  flex-shrink: 0;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 48px;
  height: 48px;
  border-radius: 14px;
  background: var(--tint-primary);
  color: var(--bs-primary);
  font-size: 22px;
}

.ops-launch-title {
  margin: 0 0 3px;
  font-size: 15px;
  font-weight: 600;
  color: var(--bs-emphasis-color);
}

.ops-launch-go {
  flex-shrink: 0;
  font-size: 18px;
  color: var(--bs-secondary-color);
  transition: var(--transition);
}

/* ============================================================
   4. OPERATIONS FEED — a status rail down the left of each card
   ============================================================ */
.ops-op {
  position: relative;
  display: flex;
  align-items: flex-start;
  gap: 14px;
  padding: 16px 18px 16px 22px;
  border-radius: 12px;
  background: var(--bs-body-bg);
  border: 1px solid var(--bs-border-color);
  transition: var(--transition);
}
.ops-op + .ops-op {
  margin-top: 12px;
}
.ops-op {
  /* the rail */
}
.ops-op::before {
  content: "";
  position: absolute;
  left: 10px;
  top: 16px;
  bottom: 16px;
  width: 3px;
  border-radius: 2px;
  background: #1ABE17;
}
.ops-op.is-running::before {
  background: var(--bs-primary);
}
.ops-op.is-queued::before {
  background: #EAB300;
}
.ops-op.is-alert::before {
  background: #E82646;
}
.ops-op:hover {
  box-shadow: var(--shadow);
}

.ops-op-ic {
  flex-shrink: 0;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 38px;
  height: 38px;
  border-radius: 11px;
  background: var(--bs-secondary-bg);
  border: 1px solid var(--bs-border-color);
  color: var(--bs-primary);
  font-size: 17px;
}

.ops-op-title {
  margin: 0 0 3px;
  font-size: 14px;
  font-weight: 600;
  color: var(--bs-emphasis-color);
}

/* ============================================================
   5. PIPELINE — six stages with a glowing connector
   ============================================================ */
.ops-pipe {
  position: relative;
  display: grid;
  grid-template-columns: repeat(6, minmax(0, 1fr));
  gap: 12px;
}
@media (max-width: 1199.98px) {
  .ops-pipe {
    grid-template-columns: repeat(3, minmax(0, 1fr));
    row-gap: 24px;
  }
}
@media (max-width: 575.98px) {
  .ops-pipe {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}

.ops-stage {
  position: relative;
  padding: 20px 16px 16px;
  border-radius: 14px;
  background: var(--bs-body-bg);
  border: 1px solid var(--bs-border-color);
  text-align: center;
  transition: var(--transition);
  /* the flowing connector to the next stage */
}
.ops-stage::after {
  content: "";
  position: absolute;
  left: calc(100% + 1px);
  top: 50%;
  width: 10px;
  height: 2px;
  background: var(--bs-border-color);
  z-index: 1;
}
.ops-stage:last-child::after {
  display: none;
}
.ops-stage.is-done {
  border-color: rgba(26, 190, 23, 0.3);
  background: #E8F9E8;
}
.ops-stage.is-done::after {
  background: #1ABE17;
}
.ops-stage.is-live {
  border-color: rgba(61, 94, 225, 0.35);
  box-shadow: var(--aix-glow);
}
@media (max-width: 1199.98px) {
  .ops-stage::after {
    display: none;
  }
}

.ops-stage-ic {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 44px;
  height: 44px;
  margin-bottom: 12px;
  border-radius: 50%;
  background: var(--bs-secondary-bg);
  border: 1px solid var(--bs-border-color);
  color: var(--bs-secondary-color);
  font-size: 20px;
}
.is-done .ops-stage-ic {
  background: #1ABE17;
  border-color: #1ABE17;
  color: #fff;
}
.is-live .ops-stage-ic {
  background: linear-gradient(135deg, var(--bs-primary), #02a8b5);
  border-color: transparent;
  color: #fff;
  animation: ops-breathe 2.6s ease-in-out infinite;
}

@keyframes ops-breathe {
  0%, 100% {
    box-shadow: 0 0 0 0 rgba(61, 94, 225, 0.45);
  }
  50% {
    box-shadow: 0 0 0 8px rgba(61, 94, 225, 0);
  }
}
.ops-stage-n {
  display: block;
  margin-bottom: 4px;
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.12em;
  color: var(--bs-secondary-color);
}

.ops-stage-title {
  margin: 0 0 4px;
  font-size: 14px;
  font-weight: 600;
  color: var(--bs-emphasis-color);
}

/* ============================================================
   6. AUTOMATION CARDS — a switch-led head, run times below
   ============================================================ */
.ops-auto {
  display: flex;
  flex-direction: column;
  height: 100%;
  border-radius: 14px;
  background: var(--bs-body-bg);
  border: 1px solid var(--bs-border-color);
  overflow: hidden;
  transition: var(--transition);
}
.ops-auto:hover {
  border-color: rgba(61, 94, 225, 0.28);
  box-shadow: var(--shadow-lift);
}

.ops-auto-head {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 16px 18px;
  background: var(--bs-secondary-bg);
  border-bottom: 1px solid var(--bs-border-color);
}

.ops-auto-title {
  margin: 0;
  font-size: 14.5px;
  font-weight: 600;
  color: var(--bs-emphasis-color);
}

.ops-auto-body {
  padding: 16px 18px;
}

.ops-kv {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 8px 0;
  font-size: 12.5px;
  color: var(--bs-secondary-color);
}
.ops-kv + .ops-kv {
  border-top: 1px dashed var(--bs-border-color);
}
.ops-kv b {
  font-weight: 600;
  color: var(--bs-emphasis-color);
}

/* ============================================================
   7. AGENT GALLERY — a ringed glyph and capability chips
   ============================================================ */
.ops-agent {
  position: relative;
  display: flex;
  flex-direction: column;
  height: 100%;
  padding: 20px;
  border-radius: 14px;
  background: var(--bs-body-bg);
  border: 1px solid var(--bs-border-color);
  overflow: hidden;
  transition: var(--transition);
}
.ops-agent:hover {
  border-color: rgba(61, 94, 225, 0.3);
  box-shadow: var(--shadow-lift);
}

.ops-agent-ic {
  position: relative;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 52px;
  height: 52px;
  margin-bottom: 14px;
  border-radius: 16px;
  background: linear-gradient(135deg, var(--tint-primary), var(--bs-secondary-bg));
  color: var(--bs-primary);
  font-size: 24px;
  /* a dashed orbit around the glyph */
}
.ops-agent-ic::after {
  content: "";
  position: absolute;
  inset: -6px;
  border-radius: 20px;
  border: 1px dashed var(--bs-border-color);
}

.ops-agent-name {
  margin: 0 0 4px;
  font-size: 15px;
  font-weight: 600;
  color: var(--bs-emphasis-color);
}

.ops-caps {
  display: flex;
  flex-wrap: wrap;
  gap: 5px;
  margin: 12px 0;
}
.ops-caps span {
  padding: 3px 9px;
  border-radius: 5px;
  background: var(--bs-secondary-bg);
  border: 1px solid var(--bs-border-color);
  font-size: 11px;
  color: var(--bs-secondary-color);
}

.ops-agent-foot {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  margin-top: auto;
  padding-top: 14px;
  border-top: 1px solid var(--bs-border-color);
}

/* ============================================================
   8. KNOWLEDGE TILES — a count in the corner
   ============================================================ */
.ops-know {
  position: relative;
  display: flex;
  align-items: flex-start;
  gap: 14px;
  height: 100%;
  padding: 18px;
  border-radius: 14px;
  background: var(--bs-secondary-bg);
  border: 1px solid transparent;
  transition: var(--transition);
}
.ops-know:hover {
  background: var(--bs-body-bg);
  border-color: rgba(61, 94, 225, 0.28);
  box-shadow: var(--shadow);
}

.ops-know-ic {
  flex-shrink: 0;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 40px;
  height: 40px;
  border-radius: 12px;
  background: var(--bs-body-bg);
  border: 1px solid var(--bs-border-color);
  color: var(--bs-primary);
  font-size: 18px;
}

.ops-know-title {
  margin: 0 0 3px;
  font-size: 14px;
  font-weight: 600;
  color: var(--bs-emphasis-color);
}

.ops-know-n {
  flex-shrink: 0;
  font-size: 15px;
  font-weight: 700;
  font-variant-numeric: tabular-nums;
  color: var(--bs-primary);
}

/* ============================================================
   9. COPILOT — a dark command launcher
   ============================================================ */
.ops-console {
  position: relative;
  overflow: hidden;
  border-radius: 18px;
  background: radial-gradient(70% 120% at 100% 0%, rgba(53, 214, 229, 0.16) 0%, transparent 55%), linear-gradient(150deg, var(--bs-secondary-color) 0%, var(--bs-emphasis-color) 100%);
  color: var(--bs-body-color);
  padding: 30px;
}
@media (max-width: 575.98px) {
  .ops-console {
    padding: 22px;
  }
}

.ops-console::before {
  content: "";
  position: absolute;
  inset: 0;
  background-image: linear-gradient(90deg, var(--bs-border-color) 1px, transparent 1px);
  background-size: 48px 100%;
  mask-image: linear-gradient(180deg, #000, transparent 70%);
  pointer-events: none;
}

.ops-cmd {
  position: relative;
  display: flex;
  align-items: center;
  gap: 14px;
  width: 100%;
  padding: 15px 18px;
  border-radius: 12px;
  background: rgba(255, 255, 255, 0.05);
  border: 1px solid var(--bs-border-color);
  color: var(--bs-body-color);
  transition: var(--transition);
}
.ops-cmd:hover {
  background: rgba(255, 255, 255, 0.1);
  border-color: rgba(108, 139, 255, 0.4);
  color: var(--bs-body-color);
  transform: translateX(3px);
}
.ops-cmd:hover .ops-cmd-ic {
  background: linear-gradient(135deg, var(--bs-primary), var(--accent-strong));
  color: #0E1526;
}

.ops-cmd-ic {
  flex-shrink: 0;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 40px;
  height: 40px;
  border-radius: 11px;
  background: rgba(255, 255, 255, 0.08);
  color: var(--bs-emphasis-color);
  font-size: 18px;
  transition: var(--transition);
}

.ops-cmd-title {
  margin: 0;
  font-size: 14px;
  font-weight: 600;
  color: var(--bs-emphasis-color);
}

/* a keyboard hint on the dark surface */
.ops-kbd {
  flex-shrink: 0;
  padding: 3px 8px;
  border-radius: 5px;
  background: rgba(255, 255, 255, 0.08);
  border: 1px solid var(--bs-border-color);
  font-size: 11px;
  font-weight: 600;
  color: rgba(255, 255, 255, 0.6);
}

/* ============================================================
   10. SHOWCASE — a corner ribbon on what is new
   ============================================================ */
.ops-new {
  position: relative;
  height: 100%;
  padding: 20px;
  border-radius: 14px;
  background: var(--bs-body-bg);
  border: 1px solid var(--bs-border-color);
  overflow: hidden;
  transition: var(--transition);
}
.ops-new:hover {
  transform: translateY(-3px);
  box-shadow: var(--shadow-lift);
}

/* the ribbon across the top-right corner */
.ops-ribbon {
  position: absolute;
  right: -34px;
  top: 14px;
  width: 130px;
  padding: 4px 0;
  transform: rotate(38deg);
  background: linear-gradient(90deg, var(--bs-primary), #02a8b5);
  color: #fff;
  text-align: center;
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.1em;
  text-transform: uppercase;
}
.ops-ribbon.is-soon {
  background: linear-gradient(90deg, #EAB300, #F9C55A);
}
.ops-ribbon.is-lab {
  background: linear-gradient(90deg, #4A00E5, #3D5EE1);
}

.ops-new-ic {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 44px;
  height: 44px;
  margin-bottom: 14px;
  border-radius: 13px;
  background: var(--tint-primary);
  color: var(--bs-primary);
  font-size: 20px;
}

.ops-new-title {
  margin: 0 0 6px;
  padding-right: 40px;
  font-size: 15px;
  font-weight: 600;
  color: var(--bs-emphasis-color);
}

/* ============================================================
   WORKSPACE OFFCANVAS — a glass rail stepper
   ============================================================ */
.offcanvas.offcanvas-end.ops-ws {
  width: 90% !important;
  max-width: 1500px !important;
}
@media (max-width: 991.98px) {
  .offcanvas.offcanvas-end.ops-ws {
    width: 100% !important;
  }
}
.offcanvas.offcanvas-end.ops-ws .offcanvas-body {
  padding: 24px;
}

/* the workspace head keeps the dark mission treatment */
.ops-ws-head {
  position: relative;
  display: flex;
  align-items: center;
  gap: 18px;
  flex-wrap: wrap;
  padding: 22px;
  overflow: hidden;
  background: radial-gradient(70% 140% at 0% 0%, rgba(108, 139, 255, 0.3) 0%, transparent 58%), linear-gradient(150deg, var(--bs-secondary-color) 0%, var(--bs-emphasis-color) 100%);
  color: var(--bs-body-color);
}

.ops-ws-ic {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 56px;
  height: 56px;
  flex-shrink: 0;
  border-radius: 16px;
  background: rgba(255, 255, 255, 0.1);
  border: 1px solid var(--bs-border-color);
  color: #fff;
  font-size: 26px;
  backdrop-filter: blur(8px);
}

.ops-ws-title {
  margin: 0 0 4px;
  font-size: 19px;
  font-weight: 600;
  letter-spacing: -0.01em;
  color: var(--bs-emphasis-color);
}

/* the stepper: pills on a rail, the completed portion glowing */
.ops-steps {
  position: relative;
  display: grid;
  grid-template-columns: repeat(5, minmax(0, 1fr));
  gap: 0;
  list-style: none;
  margin: 0;
  padding: 0;
  background: var(--bs-body-bg);
  border-bottom: 1px solid var(--bs-border-color);
}
@media (max-width: 767.98px) {
  .ops-steps {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}

.ops-step {
  position: relative;
  display: flex;
  align-items: center;
  gap: 11px;
  width: 100%;
  padding: 18px 16px;
  border: 0;
  background: transparent;
  text-align: left;
  transition: var(--transition);
  /* hairline between steps */
}
.ops-step + .ops-step, .ops-step {
  border-right: 1px solid var(--bs-border-color);
}
.ops-step:last-child {
  border-right: 0;
}
.ops-step {
  /* the glow bar under the active step */
}
.ops-step::after {
  content: "";
  position: absolute;
  left: 0;
  right: 0;
  bottom: -1px;
  height: 3px;
  background: transparent;
  transition: var(--transition);
}
.ops-step:hover {
  background: var(--bs-secondary-bg);
}
.ops-step.active {
  background: var(--tint-primary);
}
.ops-step.active::after {
  background: linear-gradient(90deg, var(--bs-primary), #02a8b5);
  box-shadow: 0 0 12px rgba(61, 94, 225, 0.5);
}
.ops-step.active .ops-step-n {
  background: linear-gradient(135deg, var(--bs-primary), #02a8b5);
  border-color: transparent;
  color: #fff;
}
.ops-step.active .ops-step-txt span:last-child {
  color: var(--bs-emphasis-color);
}

.ops-step-n {
  flex-shrink: 0;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 32px;
  height: 32px;
  border-radius: 11px;
  background: var(--bs-secondary-bg);
  border: 1px solid var(--bs-border-color);
  color: var(--bs-secondary-color);
  font-size: 12px;
  font-weight: 700;
  font-variant-numeric: tabular-nums;
  transition: var(--transition);
}

.ops-step-txt {
  display: flex;
  flex-direction: column;
  min-width: 0;
  line-height: 1.25;
}
.ops-step-txt span:first-child {
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--bs-secondary-color);
}
.ops-step-txt span:last-child {
  font-size: 13px;
  font-weight: 600;
  color: var(--bs-secondary-color);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

/* panels inside the workspace */
.ops-box {
  height: 100%;
  border-radius: 14px;
  background: var(--bs-body-bg);
  border: 1px solid var(--bs-border-color);
  overflow: hidden;
}

.ops-box-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 14px 16px;
  background: var(--bs-secondary-bg);
  border-bottom: 1px solid var(--bs-border-color);
}
.ops-box-head h6 {
  margin: 0;
  font-size: 13px;
  font-weight: 600;
  color: var(--bs-emphasis-color);
}

.ops-box-body {
  padding: 16px;
}

/* progress readout used while intelligence generates */
.ops-prog {
  display: block;
  height: 6px;
  border-radius: 3px;
  background: linear-gradient(90deg, var(--bs-primary) 0 calc(var(--p, 0) * 1%), var(--bs-tertiary-bg) calc(var(--p, 0) * 1%) 100%);
}

.ops-quote {
  padding: 15px 17px;
  border-radius: 12px;
  background: linear-gradient(135deg, var(--tint-primary), var(--bs-secondary-bg));
  border: 1px solid var(--bs-border-color);
  font-size: 13px;
  line-height: 1.68;
  color: var(--bs-emphasis-color);
}

/* ============================================================
   PREMIUM ACCORDION + EMPTY STATE
   ============================================================ */
.ops-acc .accordion-item {
  margin-bottom: 10px;
  background: var(--bs-body-bg);
  border: 1px solid var(--bs-border-color);
  border-radius: 12px !important;
  overflow: hidden;
}
.ops-acc .accordion-button {
  padding: 15px 17px;
  font-size: 13.5px;
  font-weight: 600;
  color: var(--bs-emphasis-color);
  background: var(--bs-body-bg);
  box-shadow: none;
}
.ops-acc .accordion-button:not(.collapsed) {
  background: var(--tint-primary);
  color: var(--bs-primary);
}
.ops-acc .accordion-button:focus {
  box-shadow: none;
}
.ops-acc .accordion-body {
  padding: 15px 17px;
  font-size: 13px;
  line-height: 1.65;
  color: var(--bs-secondary-color);
  border-top: 1px solid var(--bs-border-color);
}

.ops-empty {
  padding: 40px 24px;
  text-align: center;
  border-radius: 14px;
  background: rgba(255, 255, 255, 0.04);
  border: 1px dashed var(--bs-border-color);
  color: var(--bs-body-color);
}

.ops-empty-ic {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 56px;
  height: 56px;
  margin-bottom: 14px;
  border-radius: 16px;
  background: rgba(255, 255, 255, 0.07);
  border: 1px solid var(--bs-border-color);
  color: #fff;
  font-size: 25px;
}

/* ============================================================
   25. STUDENT SUCCESS  —  prefix `lrn-`

   The tenth family, and the only one addressed to a student rather than to
   staff. Its language is warmer and lighter: streak grids, quest bars,
   squircle progress frames, a day schedule and milestone tracks.

     aix-  enclosed cards, hairline dividers, chevron steppers
     atn-  banded surfaces, a vertical spine, stations, arc gauges
     sdt-  portrait medallion, chapter numerals, date gutter, dot scales
     tto-  slot grids, bracketed marks, before/after bars, a horizontal track
     hwk-  paper sheets, margin rules, grade seals, rubric strips
     tch-  tinted bands, facet bars, definition rows, medals, folded corners
     fam-  paired avatars, message threads, drop capitals, calendar chips
     rev-  dotted leaders, tabular amounts, probability blocks, forecast cone
     ops-  dark mission surface, glass panels, bento spans, glowing pipeline
     lrn-  streak grids, quest bars, squircle frames, a day schedule,
           milestone tracks and achievement badges

   Nothing here overrides a rule from the families above.
   ============================================================ */
@media (prefers-reduced-motion: reduce) {
  [class*=lrn-],
  [class*=lrn-]::before,
  [class*=lrn-]::after {
    animation: none !important;
    transition: none !important;
  }
}
/* ---- section heading: a soft squircle glyph and a ruled title -------- */
.lrn-hd {
  display: flex;
  align-items: center;
  gap: 14px;
  margin-bottom: 24px;
}
@media (max-width: 767.98px) {
  .lrn-hd {
    flex-wrap: wrap;
  }
}

.lrn-hd-ic {
  flex-shrink: 0;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 46px;
  height: 46px;
  border-radius: 16px;
  background: linear-gradient(135deg, var(--tint-primary), #E6F9FF);
  border: 1px solid var(--bs-border-color);
  color: var(--bs-primary);
  font-size: 21px;
}

.lrn-hd-title {
  position: relative;
  display: inline-block;
  margin: 0 0 6px;
  padding-bottom: 6px;
  font-size: 20px;
  font-weight: 600;
  letter-spacing: -0.01em;
  color: var(--bs-emphasis-color);
  /* a short gradient rule under the title only */
}
.lrn-hd-title::after {
  content: "";
  position: absolute;
  left: 0;
  bottom: 0;
  width: 42px;
  height: 3px;
  border-radius: 2px;
  background: linear-gradient(90deg, var(--bs-primary), #02a8b5);
}

.lrn-hd-sub {
  margin: 0;
  font-size: 13px;
  color: var(--bs-secondary-color);
  max-width: 700px;
}

/* ---- shared pieces ---------------------------------------------------- */
.lrn-lbl {
  display: block;
  font-size: 10.5px;
  font-weight: 600;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--bs-secondary-color);
}

.lrn-chip {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  padding: 4px 10px;
  border-radius: 8px;
  font-size: 11px;
  font-weight: 600;
  background: var(--bs-secondary-bg);
  border: 1px solid var(--bs-border-color);
  color: var(--bs-emphasis-color);
  white-space: nowrap;
}
.lrn-chip i {
  font-size: 13px;
}
.lrn-chip.is-ai {
  background: var(--tint-primary);
  border-color: rgba(61, 94, 225, 0.2);
  color: var(--bs-primary);
}
.lrn-chip.is-go {
  background: #E8F9E8;
  border-color: #D1F2D1;
  color: #1ABE17;
}
.lrn-chip.is-now {
  background: #E7F1FC;
  border-color: #CFE2FA;
  color: #0F65CD;
}
.lrn-chip.is-soon {
  background: #FEF8EA;
  border-color: #FDF1D6;
  color: #EAB300;
}
.lrn-chip.is-hot {
  background: #FDE9ED;
  border-color: #FAD4DA;
  color: #E82646;
}
html[data-theme=dark] .lrn-chip.is-go {
  background: rgba(26, 190, 23, 0.16);
  border-color: rgba(26, 190, 23, 0.32);
  color: color-mix(in srgb, #1ABE17 60%, white);
}
html[data-theme=dark] .lrn-chip.is-now {
  background: rgba(15, 101, 205, 0.16);
  border-color: rgba(15, 101, 205, 0.32);
  color: color-mix(in srgb, #0F65CD 60%, white);
}
html[data-theme=dark] .lrn-chip.is-soon {
  background: rgba(234, 179, 0, 0.16);
  border-color: rgba(234, 179, 0, 0.32);
  color: color-mix(in srgb, #EAB300 60%, white);
}
html[data-theme=dark] .lrn-chip.is-hot {
  background: rgba(232, 38, 70, 0.16);
  border-color: rgba(232, 38, 70, 0.32);
  color: color-mix(in srgb, #E82646 60%, white);
}

/* difficulty: three ascending bars */
.lrn-diff {
  display: inline-flex;
  align-items: flex-end;
  gap: 3px;
  height: 12px;
}
.lrn-diff i {
  width: 4px;
  border-radius: 1px;
  background: var(--bs-tertiary-bg);
}
.lrn-diff i:nth-child(1) {
  height: 50%;
}
.lrn-diff i:nth-child(2) {
  height: 75%;
}
.lrn-diff i:nth-child(3) {
  height: 100%;
}
.lrn-diff i.on {
  background: var(--bs-primary);
}
.lrn-diff.is-hard i.on {
  background: #E82646;
}
.lrn-diff.is-mid i.on {
  background: #EAB300;
}

/* ============================================================
   HERO — a bright success hub with a streak grid
   ============================================================ */
.lrn-hub {
  position: relative;
  overflow: hidden;
  border-radius: 20px;
  background: radial-gradient(80% 130% at 0% 0%, rgba(61, 94, 225, 0.16) 0%, transparent 52%), radial-gradient(70% 120% at 100% 100%, rgba(2, 168, 181, 0.16) 0%, transparent 52%), var(--bs-body-bg);
  border: 1px solid var(--bs-border-color);
  box-shadow: var(--shadow);
}

/* soft floating shapes, the only decoration on the surface */
.lrn-hub::before,
.lrn-hub::after {
  content: "";
  position: absolute;
  border-radius: 40%;
  pointer-events: none;
}

.lrn-hub::before {
  width: 220px;
  height: 220px;
  right: 8%;
  top: -110px;
  background: rgba(61, 94, 225, 0.07);
  animation: lrn-float 16s ease-in-out infinite;
}

.lrn-hub::after {
  width: 160px;
  height: 160px;
  left: 12%;
  bottom: -100px;
  background: rgba(2, 168, 181, 0.08);
  animation: lrn-float 20s ease-in-out infinite reverse;
}

@keyframes lrn-float {
  0%, 100% {
    transform: translate(0, 0) rotate(0deg);
  }
  50% {
    transform: translate(18px, -14px) rotate(28deg);
  }
}
.lrn-hub-inner {
  position: relative;
  display: grid;
  grid-template-columns: minmax(0, 1fr) 348px;
  gap: 34px;
  padding: 32px;
}
@media (max-width: 1299.98px) {
  .lrn-hub-inner {
    grid-template-columns: minmax(0, 1fr);
    gap: 26px;
  }
}
@media (max-width: 575.98px) {
  .lrn-hub-inner {
    padding: 22px;
  }
}

.lrn-hub-hello {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  padding: 6px 14px 6px 6px;
  border-radius: 999px;
  background: var(--bs-body-bg);
  border: 1px solid var(--bs-border-color);
  box-shadow: var(--shadow);
  font-size: 12px;
  font-weight: 600;
  color: var(--bs-emphasis-color);
}
.lrn-hub-hello .avatar {
  width: 26px;
  height: 26px;
}

.lrn-hub-title {
  margin: 16px 0 10px;
  font-size: 32px;
  line-height: 1.2;
  font-weight: 600;
  letter-spacing: -0.02em;
  color: var(--bs-emphasis-color);
}
.lrn-hub-title em {
  font-style: normal;
  background: linear-gradient(90deg, var(--bs-primary), #02a8b5);
  -webkit-background-clip: text;
  background-clip: text;
  -webkit-text-fill-color: transparent;
}
@media (max-width: 767.98px) {
  .lrn-hub-title {
    font-size: 25px;
  }
}

/* today's mission, set on a tinted shelf */
.lrn-mission {
  display: flex;
  align-items: center;
  gap: 16px;
  margin-top: 22px;
  padding: 18px;
  border-radius: 16px;
  background: linear-gradient(120deg, var(--tint-primary), var(--bs-secondary-bg));
  border: 1px solid var(--bs-border-color);
}
@media (max-width: 575.98px) {
  .lrn-mission {
    flex-wrap: wrap;
  }
}

/* a squircle frame that fills to --p, used for mission and journey cards */
.lrn-frame {
  position: relative;
  flex-shrink: 0;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 62px;
  height: 62px;
  border-radius: 20px;
  background: var(--bs-body-bg);
  color: var(--bs-primary);
  font-size: 24px;
  font-weight: 700;
  /* the frame itself is a conic sweep masked to a ring */
}
.lrn-frame::before {
  content: "";
  position: absolute;
  inset: 0;
  border-radius: 20px;
  background: conic-gradient(from 180deg, var(--bs-primary) 0deg calc(var(--p, 0) * 3.6deg), var(--bs-tertiary-bg) calc(var(--p, 0) * 3.6deg) 360deg);
  -webkit-mask: linear-gradient(#000 0 0) content-box, linear-gradient(#000 0 0);
  -webkit-mask-composite: xor;
  mask: linear-gradient(#000 0 0) content-box, linear-gradient(#000 0 0);
  mask-composite: exclude;
  padding: 3px;
}
.lrn-frame.is-sm {
  width: 46px;
  height: 46px;
  border-radius: 15px;
  font-size: 17px;
}

.lrn-hub-facts {
  display: flex;
  flex-wrap: wrap;
  gap: 14px 30px;
  margin-top: 22px;
  padding-top: 18px;
  border-top: 1px solid var(--bs-border-color);
}

.lrn-fact {
  display: flex;
  flex-direction: column;
  gap: 3px;
  line-height: 1.25;
}
.lrn-fact b {
  font-size: 16px;
  font-weight: 600;
  color: var(--bs-emphasis-color);
}

/* ---- the streak panel ---- */
.lrn-streak-panel {
  display: flex;
  flex-direction: column;
  gap: 16px;
  padding: 22px;
  border-radius: 18px;
  background: var(--bs-body-bg);
  border: 1px solid var(--bs-border-color);
  box-shadow: var(--aix-glow);
}

.lrn-flame {
  display: flex;
  align-items: center;
  gap: 14px;
}
.lrn-flame i {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 48px;
  height: 48px;
  border-radius: 16px;
  background: linear-gradient(135deg, #EAB300, #E82646);
  color: #fff;
  font-size: 24px;
}
.lrn-flame b {
  font-size: 28px;
  font-weight: 700;
  line-height: 1;
  font-variant-numeric: tabular-nums;
  color: var(--bs-emphasis-color);
}

/* the streak grid — four weeks of study days */
.lrn-streak {
  display: grid;
  grid-template-columns: repeat(7, minmax(0, 1fr));
  gap: 5px;
}
.lrn-streak i {
  aspect-ratio: 1;
  border-radius: 6px;
  background: var(--bs-secondary-bg);
  border: 1px solid var(--bs-border-color);
}
.lrn-streak i.d1 {
  background: rgba(61, 94, 225, 0.22);
  border-color: transparent;
}
.lrn-streak i.d2 {
  background: rgba(61, 94, 225, 0.48);
  border-color: transparent;
}
.lrn-streak i.d3 {
  background: var(--bs-primary);
  border-color: transparent;
}
.lrn-streak i.today {
  background: linear-gradient(135deg, #EAB300, #E82646);
  border-color: transparent;
}

.lrn-streak-days {
  display: grid;
  grid-template-columns: repeat(7, minmax(0, 1fr));
  gap: 5px;
  font-size: 10px;
  font-weight: 600;
  text-align: center;
  color: var(--bs-secondary-color);
}

/* ============================================================
   JOURNEY CARDS — a squircle frame, chips, then actions
   ============================================================ */
.lrn-card {
  display: flex;
  flex-direction: column;
  gap: 13px;
  height: 100%;
  padding: 18px;
  border-radius: 16px;
  background: var(--bs-body-bg);
  border: 1px solid var(--bs-border-color);
  transition: var(--transition);
}
.lrn-card:hover {
  border-color: rgba(61, 94, 225, 0.3);
  box-shadow: var(--shadow-lift);
  transform: translateY(-2px);
}

.lrn-card-title {
  margin: 0 0 3px;
  font-size: 15px;
  font-weight: 600;
  color: var(--bs-emphasis-color);
}

/* the AI line, quoted softly */
.lrn-say {
  display: flex;
  align-items: flex-start;
  gap: 9px;
  padding: 11px 13px;
  border-radius: 12px;
  background: var(--tint-primary);
  font-size: 12.5px;
  line-height: 1.55;
  color: var(--bs-emphasis-color);
}
.lrn-say i {
  flex-shrink: 0;
  margin-top: 1px;
  color: var(--bs-primary);
  font-size: 15px;
}

.lrn-meta {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 8px;
  padding-top: 12px;
  margin-top: auto;
  border-top: 1px solid var(--bs-border-color);
}

/* ============================================================
   EXPLAINABLE AI — a breadcrumb trail across the top
   ============================================================ */
.lrn-why {
  position: relative;
  height: 100%;
  padding: 20px;
  border-radius: 16px;
  background: var(--bs-body-bg);
  border: 1px solid var(--bs-border-color);
  transition: var(--transition);
}
.lrn-why:hover {
  box-shadow: var(--shadow-lift);
}

/* the trail: observation, reasoning, evidence, action */
.lrn-trail {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 6px;
  padding-bottom: 14px;
  margin-bottom: 16px;
  border-bottom: 1px dashed var(--bs-border-color);
}
.lrn-trail span {
  padding: 3px 9px;
  border-radius: 7px;
  background: var(--bs-secondary-bg);
  border: 1px solid var(--bs-border-color);
  font-size: 10.5px;
  font-weight: 600;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  color: var(--bs-secondary-color);
}
.lrn-trail span.on {
  background: var(--tint-primary);
  border-color: rgba(61, 94, 225, 0.22);
  color: var(--bs-primary);
}
.lrn-trail i {
  font-size: 13px;
  color: var(--bs-border-color);
}

.lrn-why-obs {
  margin: 0 0 12px;
  font-size: 16px;
  font-weight: 600;
  color: var(--bs-emphasis-color);
}

.lrn-block {
  margin-bottom: 14px;
}
.lrn-block span:first-child {
  display: block;
  margin-bottom: 4px;
  font-size: 10.5px;
  font-weight: 600;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--bs-secondary-color);
}

.lrn-ev {
  display: flex;
  align-items: flex-start;
  gap: 8px;
  padding: 5px 0;
  font-size: 12.5px;
  color: var(--bs-secondary-color);
}
.lrn-ev i {
  flex-shrink: 0;
  margin-top: 5px;
  font-size: 6px;
  color: var(--bs-primary);
}

.lrn-why-foot {
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 12px;
  padding-top: 14px;
  border-top: 1px solid var(--bs-border-color);
}

/* ============================================================
   DAY PLANNER — a time column with study blocks
   ============================================================ */
.lrn-day {
  display: flex;
  flex-direction: column;
}

.lrn-slot {
  display: grid;
  grid-template-columns: 78px 1fr;
  gap: 18px;
  align-items: stretch;
}
@media (max-width: 575.98px) {
  .lrn-slot {
    grid-template-columns: 58px 1fr;
    gap: 12px;
  }
}

.lrn-time {
  position: relative;
  padding: 18px 0;
  text-align: right;
  font-size: 12px;
  font-weight: 600;
  font-variant-numeric: tabular-nums;
  color: var(--bs-secondary-color);
  /* the rail running through the times */
}
.lrn-time::after {
  content: "";
  position: absolute;
  right: -10px;
  top: 0;
  bottom: 0;
  width: 2px;
  background: var(--bs-border-color);
}
.lrn-slot:first-child .lrn-time::after {
  top: 22px;
}
.lrn-slot:last-child .lrn-time::after {
  bottom: calc(100% - 22px);
}

.lrn-block-card {
  display: flex;
  align-items: center;
  gap: 14px;
  margin: 6px 0;
  padding: 14px 16px;
  border-radius: 14px;
  background: var(--bs-body-bg);
  border: 1px solid var(--bs-border-color);
  border-left: 4px solid var(--bs-primary);
  transition: var(--transition);
}
.lrn-block-card:hover {
  box-shadow: var(--shadow-lift);
  transform: translateX(3px);
}
.lrn-block-card.is-done {
  border-left-color: #1ABE17;
  background: var(--bs-secondary-bg);
}
.lrn-block-card.is-now {
  border-left-color: #EAB300;
  box-shadow: var(--aix-glow);
}
@media (max-width: 575.98px) {
  .lrn-block-card {
    flex-wrap: wrap;
  }
}

.lrn-block-title {
  margin: 0 0 2px;
  font-size: 14.5px;
  font-weight: 600;
  color: var(--bs-emphasis-color);
}

/* a slim progress rule used inside blocks and goals */
.lrn-bar {
  display: block;
  height: 5px;
  border-radius: 3px;
  background: linear-gradient(90deg, var(--bs-primary) 0 calc(var(--p, 0) * 1%), var(--bs-tertiary-bg) calc(var(--p, 0) * 1%) 100%);
}
.lrn-bar.is-go {
  background: linear-gradient(90deg, #1ABE17 0 calc(var(--p, 0) * 1%), var(--bs-tertiary-bg) calc(var(--p, 0) * 1%) 100%);
}

/* ============================================================
   COACH CARDS — a bold call to action
   ============================================================ */
.lrn-coach {
  display: flex;
  flex-direction: column;
  height: 100%;
  border-radius: 16px;
  background: var(--bs-body-bg);
  border: 1px solid var(--bs-border-color);
  overflow: hidden;
  transition: var(--transition);
}
.lrn-coach:hover {
  border-color: rgba(61, 94, 225, 0.3);
  box-shadow: var(--shadow-lift);
}
.lrn-coach:hover .lrn-coach-ic {
  transform: scale(1.06) rotate(-4deg);
}

.lrn-coach-top {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  padding: 16px 18px 0;
}

.lrn-coach-ic {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 46px;
  height: 46px;
  border-radius: 16px;
  background: linear-gradient(135deg, var(--bs-primary), #02a8b5);
  color: #fff;
  font-size: 21px;
  transition: var(--transition);
}

.lrn-coach-body {
  display: flex;
  flex-direction: column;
  gap: 8px;
  flex: 1 1 auto;
  padding: 14px 18px 18px;
}

.lrn-coach-title {
  margin: 0;
  font-size: 15px;
  font-weight: 600;
  color: var(--bs-emphasis-color);
}

.lrn-coach-foot {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  margin-top: auto;
  padding-top: 12px;
  border-top: 1px dashed var(--bs-border-color);
}

/* ============================================================
   GOAL TRACKS — milestones along a filled rail
   ============================================================ */
.lrn-goal {
  padding: 18px 20px;
  border-radius: 16px;
  background: var(--bs-body-bg);
  border: 1px solid var(--bs-border-color);
  transition: var(--transition);
}
.lrn-goal + .lrn-goal {
  margin-top: 14px;
}
.lrn-goal:hover {
  box-shadow: var(--shadow);
}

.lrn-goal-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 12px;
  margin-bottom: 18px;
}

.lrn-goal-title {
  margin: 0;
  font-size: 15px;
  font-weight: 600;
  color: var(--bs-emphasis-color);
}

/* the track: a rail with milestone dots sitting on it */
.lrn-track {
  position: relative;
  display: flex;
  justify-content: space-between;
  padding-top: 22px;
  /* the unfilled rail */
}
.lrn-track::before {
  content: "";
  position: absolute;
  left: 6px;
  right: 6px;
  top: 6px;
  height: 3px;
  border-radius: 2px;
  background: var(--bs-tertiary-bg);
}
.lrn-track {
  /* the filled portion */
}
.lrn-track::after {
  content: "";
  position: absolute;
  left: 6px;
  top: 6px;
  width: calc((100% - 12px) * var(--p, 0) / 100);
  height: 3px;
  border-radius: 2px;
  background: linear-gradient(90deg, var(--bs-primary), #02a8b5);
}

.lrn-mile {
  position: relative;
  z-index: 1;
  flex: 1 1 0;
  text-align: center;
  font-size: 11px;
  color: var(--bs-secondary-color);
}
.lrn-mile::before {
  content: "";
  position: absolute;
  left: 50%;
  top: -22px;
  transform: translateX(-50%);
  width: 13px;
  height: 13px;
  border-radius: 50%;
  background: var(--bs-body-bg);
  border: 3px solid var(--bs-tertiary-bg);
}
.lrn-mile:first-child::before {
  left: 6px;
  transform: none;
}
.lrn-mile:last-child::before {
  left: auto;
  right: 6px;
  transform: none;
}
.lrn-mile.is-done::before {
  background: var(--bs-primary);
  border-color: var(--bs-primary);
}
.lrn-mile.is-now::before {
  border-color: var(--bs-primary);
  box-shadow: 0 0 0 4px var(--tint-primary);
}

/* ============================================================
   COMPANION TILES — icon, title, arrow
   ============================================================ */
.lrn-do {
  display: flex;
  align-items: center;
  gap: 14px;
  height: 100%;
  padding: 16px;
  border-radius: 14px;
  background: var(--bs-body-bg);
  border: 1px solid var(--bs-border-color);
  transition: var(--transition);
}
.lrn-do:hover {
  border-color: rgba(61, 94, 225, 0.3);
  background: var(--tint-primary);
}
.lrn-do:hover .lrn-do-go {
  transform: translateX(4px);
  color: var(--bs-primary);
}

.lrn-do-ic {
  flex-shrink: 0;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 42px;
  height: 42px;
  border-radius: 14px;
  background: var(--bs-secondary-bg);
  border: 1px solid var(--bs-border-color);
  color: var(--bs-primary);
  font-size: 19px;
}

.lrn-do-go {
  flex-shrink: 0;
  font-size: 17px;
  color: var(--bs-secondary-color);
  transition: var(--transition);
}

/* ============================================================
   GROWTH STORY — badges on a dashed rail
   ============================================================ */
.lrn-story {
  position: relative;
  padding-left: 62px;
}
.lrn-story::before {
  content: "";
  position: absolute;
  left: 23px;
  top: 16px;
  bottom: 16px;
  border-left: 2px dashed var(--bs-border-color);
}

.lrn-beat {
  position: relative;
  padding: 16px 18px;
  border-radius: 14px;
  background: var(--bs-secondary-bg);
  border: 1px solid transparent;
  transition: var(--transition);
}
.lrn-beat + .lrn-beat {
  margin-top: 14px;
}
.lrn-beat:hover {
  background: var(--bs-body-bg);
  border-color: var(--bs-border-color);
  box-shadow: var(--shadow);
}
.lrn-beat {
  /* the badge sits on the rail */
}
.lrn-beat::before {
  content: "";
  position: absolute;
  left: -62px;
  top: 14px;
  width: 48px;
  height: 48px;
  border-radius: 16px;
  background: var(--bs-body-bg);
  border: 1px solid var(--bs-border-color);
}
.lrn-beat.is-done::before {
  background: linear-gradient(135deg, var(--bs-primary), #02a8b5);
  border-color: transparent;
}
.lrn-beat.is-win::before {
  background: linear-gradient(135deg, #EAB300, #E82646);
  border-color: transparent;
}

.lrn-beat-ic {
  position: absolute;
  left: -62px;
  top: 14px;
  z-index: 1;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 48px;
  height: 48px;
  font-size: 20px;
  color: var(--bs-secondary-color);
}
.is-done .lrn-beat-ic, .is-win .lrn-beat-ic {
  color: #fff;
}

.lrn-beat-title {
  margin: 0 0 3px;
  font-size: 14.5px;
  font-weight: 600;
  color: var(--bs-emphasis-color);
}

/* ============================================================
   OPPORTUNITY ROWS
   ============================================================ */
.lrn-opp {
  display: flex;
  align-items: center;
  gap: 14px;
  height: 100%;
  padding: 16px;
  border-radius: 14px;
  background: var(--bs-body-bg);
  border: 1px solid var(--bs-border-color);
  transition: var(--transition);
}
.lrn-opp:hover {
  border-color: rgba(61, 94, 225, 0.3);
  box-shadow: var(--shadow-lift);
}

.lrn-opp-ic {
  flex-shrink: 0;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 44px;
  height: 44px;
  border-radius: 50%;
  background: var(--tint-primary);
  color: var(--bs-primary);
  font-size: 20px;
}
.lrn-opp-ic.is-go {
  background: #E8F9E8;
  color: #1ABE17;
}
.lrn-opp-ic.is-soon {
  background: #FEF8EA;
  color: #EAB300;
}
.lrn-opp-ic.is-now {
  background: #E7F1FC;
  color: #0F65CD;
}

.lrn-opp-title {
  margin: 0 0 2px;
  font-size: 14px;
  font-weight: 600;
  color: var(--bs-emphasis-color);
}

/* ============================================================
   INSPIRATION TILES — soft tinted, quoted
   ============================================================ */
.lrn-tip {
  position: relative;
  height: 100%;
  padding: 18px 20px;
  border-radius: 16px;
  background: linear-gradient(150deg, var(--tint-primary) 0%, var(--bs-body-bg) 60%);
  border: 1px solid var(--bs-border-color);
  transition: var(--transition);
}
.lrn-tip:hover {
  box-shadow: var(--shadow-lift);
}
.lrn-tip.is-go {
  background: linear-gradient(150deg, #E8F9E8 0%, var(--bs-body-bg) 60%);
}
.lrn-tip.is-soon {
  background: linear-gradient(150deg, #FEF8EA 0%, var(--bs-body-bg) 60%);
}
.lrn-tip.is-now {
  background: linear-gradient(150deg, #E7F1FC 0%, var(--bs-body-bg) 60%);
}

.lrn-tip-ic {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 38px;
  height: 38px;
  margin-bottom: 12px;
  border-radius: 13px;
  background: var(--bs-body-bg);
  border: 1px solid var(--bs-border-color);
  color: var(--bs-primary);
  font-size: 17px;
}

.lrn-tip-title {
  margin: 0 0 6px;
  font-size: 14px;
  font-weight: 600;
  color: var(--bs-emphasis-color);
}

/* ============================================================
   WORKSPACE OFFCANVAS — a quest bar stepper
   ============================================================ */
.offcanvas.offcanvas-end.lrn-ws {
  width: 88% !important;
  max-width: 1420px !important;
}
@media (max-width: 991.98px) {
  .offcanvas.offcanvas-end.lrn-ws {
    width: 100% !important;
  }
}
.offcanvas.offcanvas-end.lrn-ws .offcanvas-body {
  padding: 22px;
}

.lrn-ws-head {
  display: flex;
  align-items: center;
  gap: 18px;
  flex-wrap: wrap;
  padding: 22px;
  background: radial-gradient(70% 130% at 0% 0%, rgba(61, 94, 225, 0.14) 0%, transparent 54%), radial-gradient(60% 120% at 100% 100%, rgba(2, 168, 181, 0.14) 0%, transparent 54%), var(--bs-body-bg);
  border-bottom: 1px solid var(--bs-border-color);
}

/* one rounded bar cut into five; the active segment grows to show its label */
.lrn-quest {
  display: flex;
  gap: 6px;
  list-style: none;
  margin: 0;
  padding: 16px 22px;
  background: var(--bs-secondary-bg);
  border-bottom: 1px solid var(--bs-border-color);
}
.lrn-quest li {
  display: flex;
}
@media (max-width: 767.98px) {
  .lrn-quest {
    flex-wrap: wrap;
  }
  .lrn-quest li {
    flex: 1 1 45%;
  }
}

.lrn-questbtn {
  display: flex;
  align-items: center;
  gap: 10px;
  width: 100%;
  padding: 11px 16px;
  border: 1px solid var(--bs-border-color);
  border-radius: 999px;
  background: var(--bs-body-bg);
  white-space: nowrap;
  transition: var(--transition);
}
.lrn-questbtn:hover {
  border-color: rgba(61, 94, 225, 0.35);
}
.lrn-questbtn {
  /* inactive steps shrink to the number, the active one takes the room */
}
li:has(.lrn-questbtn) {
  flex: 0 1 auto;
}
li:has(.lrn-questbtn.active) {
  flex: 1 1 auto;
}
.lrn-questbtn .lrn-questbtn-txt {
  display: none;
}
.lrn-questbtn.active {
  background: linear-gradient(135deg, var(--bs-primary), #02a8b5);
  border-color: transparent;
  box-shadow: 0 8px 20px rgba(61, 94, 225, 0.28);
}
.lrn-questbtn.active .lrn-questbtn-n {
  background: rgba(255, 255, 255, 0.22);
  color: #fff;
}
.lrn-questbtn.active .lrn-questbtn-txt {
  display: flex;
  color: #fff;
}
@media (max-width: 767.98px) {
  .lrn-questbtn .lrn-questbtn-txt {
    display: flex;
  }
}

.lrn-questbtn-n {
  flex-shrink: 0;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 26px;
  height: 26px;
  border-radius: 50%;
  background: var(--bs-secondary-bg);
  color: var(--bs-secondary-color);
  font-size: 11px;
  font-weight: 700;
  font-variant-numeric: tabular-nums;
  transition: var(--transition);
}

.lrn-questbtn-txt {
  flex-direction: column;
  min-width: 0;
  line-height: 1.2;
  text-align: left;
}
.lrn-questbtn-txt span:first-child {
  font-size: 9.5px;
  font-weight: 600;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  opacity: 0.75;
}
.lrn-questbtn-txt span:last-child {
  font-size: 13px;
  font-weight: 600;
}

/* panels inside the workspace */
.lrn-box {
  height: 100%;
  border-radius: 14px;
  background: var(--bs-body-bg);
  border: 1px solid var(--bs-border-color);
  overflow: hidden;
}

.lrn-box-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 13px 16px;
  background: var(--bs-secondary-bg);
  border-bottom: 1px solid var(--bs-border-color);
}
.lrn-box-head h6 {
  margin: 0;
  font-size: 13px;
  font-weight: 600;
  color: var(--bs-emphasis-color);
}

.lrn-box-body {
  padding: 16px;
}

.lrn-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 9px 0;
  font-size: 13px;
  color: var(--bs-emphasis-color);
}
.lrn-row + .lrn-row {
  border-top: 1px dashed var(--bs-border-color);
}
.lrn-row b {
  font-weight: 600;
}

/* ============================================================
   PREMIUM ACCORDION + EMPTY STATE
   ============================================================ */
.lrn-acc .accordion-item {
  margin-bottom: 10px;
  background: var(--bs-body-bg);
  border: 1px solid var(--bs-border-color);
  border-radius: 14px !important;
  overflow: hidden;
}
.lrn-acc .accordion-button {
  padding: 14px 16px;
  font-size: 13.5px;
  font-weight: 600;
  color: var(--bs-emphasis-color);
  background: var(--bs-body-bg);
  box-shadow: none;
}
.lrn-acc .accordion-button:not(.collapsed) {
  background: var(--tint-primary);
  color: var(--bs-primary);
}
.lrn-acc .accordion-button:focus {
  box-shadow: none;
}
.lrn-acc .accordion-body {
  padding: 15px 16px;
  font-size: 13px;
  line-height: 1.65;
  color: var(--bs-secondary-color);
  border-top: 1px solid var(--bs-border-color);
}

.lrn-empty {
  padding: 40px 24px;
  text-align: center;
  border-radius: 16px;
  background: linear-gradient(150deg, var(--tint-primary), var(--bs-body-bg));
  border: 1px dashed var(--bs-border-color);
}

.lrn-empty-ic {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 58px;
  height: 58px;
  margin-bottom: 14px;
  border-radius: 20px;
  background: var(--bs-body-bg);
  border: 1px solid var(--bs-border-color);
  box-shadow: var(--shadow);
  color: var(--bs-primary);
  font-size: 26px;
}

/*-----------------
    Notifications — reusable notification centre components

    A shared vocabulary for notification surfaces anywhere in the product,
    not styles for one page. Class prefix `ntf-`.

    The language here is an inbox rather than a workspace: date dividers,
    an unread rail down the left of each row, category chips, priority
    ribs and a sticky filter bar. Nothing here depends on the AI families
    in `_ai-insights.scss` and nothing overrides them.

    Contents
      1.  Tokens
      2.  Hero
      3.  Sticky filter toolbar
      4.  Feed — groups, rows, states
      5.  Category cards
      6.  Priority cards
      7.  Quick actions
      8.  Timeline
      9.  Insights + announcements
      10. Preferences
      11. Offcanvas + modal + empty state
-----------------*/
/* ============================================================
   1. TOKENS
   ============================================================ */
@media (prefers-reduced-motion: reduce) {
  [class*=ntf-],
  [class*=ntf-]::before,
  [class*=ntf-]::after {
    animation: none !important;
    transition: none !important;
  }
}
/* ---- shared small pieces ---------------------------------------------- */
.ntf-lbl {
  display: block;
  font-size: 10.5px;
  font-weight: 600;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--bs-secondary-color);
}

/* category chip — a coloured dot and a name */
.ntf-chip {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 3px 10px;
  border-radius: 999px;
  background: var(--bs-secondary-bg);
  border: 1px solid var(--bs-border-color);
  font-size: 11px;
  font-weight: 600;
  color: var(--bs-emphasis-color);
  white-space: nowrap;
}
.ntf-chip::before {
  content: "";
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: var(--bs-primary);
}
.ntf-chip.is-academic::before {
  background: #3D5EE1;
}
.ntf-chip.is-attendance::before {
  background: #0F65CD;
}
.ntf-chip.is-fees::before {
  background: #1ABE17;
}
.ntf-chip.is-exams::before {
  background: #4A00E5;
}
.ntf-chip.is-library::before {
  background: #02a8b5;
}
.ntf-chip.is-transport::before {
  background: #EAB300;
}
.ntf-chip.is-hostel::before {
  background: #6FCCD8;
}
.ntf-chip.is-medical::before {
  background: #E82646;
}
.ntf-chip.is-hr::before {
  background: #E83E8C;
}
.ntf-chip.is-security::before {
  background: #202C4B;
}
.ntf-chip.is-system::before {
  background: #677788;
}
.ntf-chip {
  /* a plain variant with no dot, for counts and meta */
}
.ntf-chip.is-plain::before {
  display: none;
}

/* priority badge — a small rib rather than a pill */
.ntf-pri {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  color: var(--bs-secondary-color);
}
.ntf-pri::before {
  content: "";
  width: 3px;
  height: 12px;
  border-radius: 2px;
  background: var(--bs-tertiary-bg);
}
.ntf-pri.is-critical {
  color: #E82646;
}
.ntf-pri.is-critical::before {
  background: #E82646;
}
.ntf-pri.is-high {
  color: #EAB300;
}
.ntf-pri.is-high::before {
  background: #EAB300;
}
.ntf-pri.is-medium {
  color: #0F65CD;
}
.ntf-pri.is-medium::before {
  background: #0F65CD;
}
.ntf-pri.is-low {
  color: #1ABE17;
}
.ntf-pri.is-low::before {
  background: #1ABE17;
}

/* an unread count bubble */
.ntf-count {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 22px;
  height: 22px;
  padding: 0 7px;
  border-radius: 999px;
  background: var(--bs-primary);
  color: #fff;
  font-size: 11px;
  font-weight: 700;
  font-variant-numeric: tabular-nums;
}
.ntf-count.is-quiet {
  background: var(--bs-secondary-bg);
  border: 1px solid var(--bs-border-color);
  color: var(--bs-secondary-color);
}
.ntf-count.is-alert {
  background: #E82646;
}

/* ============================================================
   2. HERO
   ============================================================ */
.ntf-hero {
  position: relative;
  overflow: hidden;
  border-radius: var(--radius);
  background: radial-gradient(70% 130% at 100% 0%, #F2F5FF 0%, transparent 58%), var(--bs-body-bg);
  border: 1px solid var(--bs-border-color);
  box-shadow: var(--shadow);
}

/* a stack of faint envelopes in the corner, the only decoration */
.ntf-hero::after {
  content: "";
  position: absolute;
  right: 34px;
  top: -30px;
  width: 150px;
  height: 150px;
  border-radius: 26px;
  border: 1px solid var(--bs-border-color);
  transform: rotate(24deg);
  opacity: 0.5;
  pointer-events: none;
}

.ntf-hero-inner {
  position: relative;
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 26px;
  padding: 26px 28px;
}
@media (max-width: 575.98px) {
  .ntf-hero-inner {
    padding: 22px;
  }
}

.ntf-hero-title {
  margin: 12px 0 8px;
  font-size: 27px;
  font-weight: 600;
  letter-spacing: -0.02em;
  line-height: 1.2;
  color: var(--bs-emphasis-color);
}
@media (max-width: 767.98px) {
  .ntf-hero-title {
    font-size: 22px;
  }
}

/* the readouts sit on one ruled line, no boxes */
.ntf-hero-rail {
  display: flex;
  flex-wrap: wrap;
  gap: 14px 30px;
  margin-top: 18px;
  padding-top: 16px;
  border-top: 1px solid var(--bs-border-color);
}

.ntf-stat {
  display: flex;
  flex-direction: column;
  gap: 3px;
  line-height: 1.25;
}
.ntf-stat b {
  font-size: 19px;
  font-weight: 600;
  font-variant-numeric: tabular-nums;
  color: var(--bs-emphasis-color);
}
.ntf-stat b small {
  font-size: 12px;
  font-weight: 500;
  color: var(--bs-secondary-color);
}

/* ============================================================
   3. STICKY FILTER TOOLBAR
   ============================================================ */
.ntf-bar {
  position: sticky;
  top: 0;
  z-index: 5;
  padding: 14px 16px;
  border-radius: var(--radius);
  background: var(--bs-body-bg);
  border: 1px solid var(--bs-border-color);
  box-shadow: var(--shadow);
}
@media (max-width: 991.98px) {
  .ntf-bar {
    position: static;
  }
}

/* the quick filters read as a segmented row of pills */
.ntf-quick {
  display: flex;
  flex-wrap: wrap;
  gap: 7px;
  padding-top: 12px;
  margin-top: 12px;
  border-top: 1px solid var(--bs-border-color);
}

.ntf-tab {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  padding: 6px 13px;
  border-radius: 999px;
  background: var(--bs-secondary-bg);
  border: 1px solid transparent;
  font-size: 12px;
  font-weight: 600;
  color: var(--bs-secondary-color);
  transition: var(--transition);
  white-space: nowrap;
}
.ntf-tab i {
  font-size: 14px;
}
.ntf-tab:hover {
  background: var(--bs-tertiary-bg);
  color: var(--bs-emphasis-color);
}
.ntf-tab.active {
  background: var(--tint-primary);
  border-color: rgba(61, 94, 225, 0.24);
  color: var(--bs-primary);
}

/* ============================================================
   4. FEED
   ============================================================ */
.ntf-feed {
  border-radius: var(--radius);
  background: var(--bs-body-bg);
  border: 1px solid var(--bs-border-color);
  overflow: hidden;
}

/* a sticky date divider between groups */
.ntf-group {
  position: sticky;
  top: 0;
  z-index: 2;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 11px 18px;
  background: var(--bs-secondary-bg);
  border-bottom: 1px solid var(--bs-border-color);
}
.ntf-group + .ntf-row {
  border-top: 0;
}
.ntf-group span:first-child {
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--bs-emphasis-color);
}

/* a notification row */
.ntf-row {
  position: relative;
  display: grid;
  grid-template-columns: 46px minmax(0, 1fr) auto;
  gap: 14px;
  padding: 16px 18px 16px 22px;
  border-top: 1px solid var(--bs-border-color);
  transition: var(--transition);
}
.ntf-row:first-child {
  border-top: 0;
}
.ntf-row {
  /* the unread rail down the left edge */
}
.ntf-row::before {
  content: "";
  position: absolute;
  left: 0;
  top: 0;
  bottom: 0;
  width: 3px;
  background: transparent;
  transition: var(--transition);
}
.ntf-row:hover {
  background: var(--bs-secondary-bg);
}
.ntf-row:hover .ntf-row-tools {
  opacity: 1;
  transform: translateX(0);
}
.ntf-row {
  /* unread rows are tinted and carry the rail */
}
.ntf-row.is-unread {
  background: var(--tint-primary);
}
.ntf-row.is-unread::before {
  background: var(--bs-primary);
}
.ntf-row.is-unread:hover {
  background: #ECEFFC;
}
.ntf-row.is-unread .ntf-row-title {
  font-weight: 600;
}
.ntf-row.is-critical::before {
  background: #E82646;
}
.ntf-row {
  /* a pinned row keeps a marker whatever its read state */
}
.ntf-row.is-pinned::after {
  content: "\ea5f";
  position: absolute;
  left: 8px;
  top: 18px;
  font-family: "tabler-icons" !important;
  font-size: 11px;
  color: var(--bs-primary);
}
@media (max-width: 767.98px) {
  .ntf-row {
    grid-template-columns: 40px minmax(0, 1fr);
    row-gap: 10px;
  }
}

/* the avatar column, with a small module glyph pinned to it */
.ntf-ava {
  position: relative;
  width: 46px;
  height: 46px;
}
.ntf-ava img, .ntf-ava > .avatar {
  width: 100%;
  height: 100%;
  border-radius: 12px;
  object-fit: cover;
}
@media (max-width: 767.98px) {
  .ntf-ava {
    width: 40px;
    height: 40px;
  }
}

.ntf-ava-badge {
  position: absolute;
  right: -5px;
  bottom: -5px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 21px;
  height: 21px;
  border-radius: 50%;
  background: var(--bs-body-bg);
  border: 1px solid var(--bs-border-color);
  box-shadow: var(--shadow);
  font-size: 11px;
  color: var(--bs-primary);
}

/* a glyph-only avatar for system notifications */
.ntf-ava-sys {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 100%;
  height: 100%;
  border-radius: 12px;
  background: var(--bs-secondary-bg);
  border: 1px solid var(--bs-border-color);
  color: var(--bs-primary);
  font-size: 20px;
}

.ntf-row-title {
  margin: 0 0 3px;
  font-size: 14px;
  font-weight: 500;
  color: var(--bs-emphasis-color);
}
.ntf-row-title b {
  font-weight: 600;
}

.ntf-row-txt {
  margin: 0 0 8px;
  font-size: 13px;
  line-height: 1.6;
  color: var(--bs-secondary-color);
}

.ntf-row-meta {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 6px 12px;
  font-size: 11.5px;
  color: var(--bs-secondary-color);
}

/* an attachment pill */
.ntf-file {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 4px 10px;
  border-radius: var(--radius-sm);
  background: var(--bs-body-bg);
  border: 1px solid var(--bs-border-color);
  font-size: 11.5px;
  color: var(--bs-emphasis-color);
}
.ntf-file i {
  font-size: 14px;
  color: var(--bs-secondary-color);
}

/* a quoted preview of the underlying record */
.ntf-preview {
  margin: 10px 0 0;
  padding: 10px 13px;
  border-radius: var(--radius-sm);
  background: var(--bs-body-bg);
  border: 1px solid var(--bs-border-color);
  border-left: 3px solid var(--bs-tertiary-bg);
  font-size: 12.5px;
  line-height: 1.6;
  color: var(--bs-secondary-color);
}

/* the right column: time above, tools that appear on hover */
.ntf-row-side {
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  justify-content: space-between;
  gap: 10px;
  white-space: nowrap;
}
@media (max-width: 767.98px) {
  .ntf-row-side {
    grid-column: 1/-1;
    flex-direction: row;
    align-items: center;
    justify-content: space-between;
  }
}

.ntf-row-tools {
  display: flex;
  align-items: center;
  gap: 4px;
  opacity: 0;
  transform: translateX(6px);
  transition: var(--transition);
}
@media (max-width: 991.98px) {
  .ntf-row-tools {
    opacity: 1;
    transform: none;
  }
}

.ntf-tool {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 30px;
  height: 30px;
  border-radius: var(--radius-sm);
  background: var(--bs-body-bg);
  border: 1px solid var(--bs-border-color);
  color: var(--bs-secondary-color);
  font-size: 15px;
  transition: var(--transition);
}
.ntf-tool:hover {
  background: var(--tint-primary);
  border-color: var(--bs-primary);
  color: var(--bs-primary);
}

/* the foot of the feed */
.ntf-feed-foot {
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 12px;
  padding: 14px 18px;
  background: var(--bs-secondary-bg);
  border-top: 1px solid var(--bs-border-color);
}

/* ============================================================
   5. CATEGORY CARDS
   ============================================================ */
.ntf-cat {
  position: relative;
  display: flex;
  flex-direction: column;
  gap: 10px;
  height: 100%;
  padding: 16px;
  border-radius: var(--radius);
  background: var(--bs-body-bg);
  border: 1px solid var(--bs-border-color);
  transition: var(--transition);
}
.ntf-cat:hover {
  border-color: rgba(61, 94, 225, 0.3);
  box-shadow: var(--shadow-lift);
  transform: translateY(-2px);
}

.ntf-cat-ic {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 40px;
  height: 40px;
  border-radius: 12px;
  background: var(--bs-secondary-bg);
  border: 1px solid var(--bs-border-color);
  color: var(--bs-primary);
  font-size: 19px;
}

.ntf-cat-title {
  margin: 0;
  font-size: 14px;
  font-weight: 600;
  color: var(--bs-emphasis-color);
}

/* ============================================================
   6. PRIORITY CARDS — a thick rib along the top edge
   ============================================================ */
.ntf-prio {
  position: relative;
  height: 100%;
  padding: 20px 18px 18px;
  border-radius: var(--radius);
  background: var(--bs-body-bg);
  border: 1px solid var(--bs-border-color);
  overflow: hidden;
  transition: var(--transition);
}
.ntf-prio::before {
  content: "";
  position: absolute;
  left: 0;
  right: 0;
  top: 0;
  height: 4px;
  background: var(--bs-tertiary-bg);
}
.ntf-prio.is-critical::before {
  background: #E82646;
}
.ntf-prio.is-high::before {
  background: #EAB300;
}
.ntf-prio.is-medium::before {
  background: #0F65CD;
}
.ntf-prio.is-low::before {
  background: #1ABE17;
}
.ntf-prio:hover {
  box-shadow: var(--shadow-lift);
}

.ntf-prio-fig {
  display: block;
  margin: 10px 0 4px;
  font-size: 30px;
  font-weight: 700;
  line-height: 1;
  font-variant-numeric: tabular-nums;
  letter-spacing: -0.02em;
  color: var(--bs-emphasis-color);
}

.ntf-prio-latest {
  margin-top: 14px;
  padding-top: 14px;
  border-top: 1px dashed var(--bs-border-color);
}

/* ============================================================
   7. QUICK ACTIONS
   ============================================================ */
.ntf-act {
  display: flex;
  align-items: center;
  gap: 13px;
  height: 100%;
  padding: 15px 16px;
  border-radius: var(--radius);
  background: var(--bs-body-bg);
  border: 1px solid var(--bs-border-color);
  transition: var(--transition);
}
.ntf-act:hover {
  border-color: rgba(61, 94, 225, 0.3);
  background: var(--tint-primary);
}
.ntf-act:hover .ntf-act-ic {
  background: var(--bs-primary);
  border-color: var(--bs-primary);
  color: #fff;
}

.ntf-act-ic {
  flex-shrink: 0;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 38px;
  height: 38px;
  border-radius: 11px;
  background: var(--bs-secondary-bg);
  border: 1px solid var(--bs-border-color);
  color: var(--bs-primary);
  font-size: 17px;
  transition: var(--transition);
}

/* ============================================================
   8. TIMELINE — a horizontal delivery track
   ============================================================ */
.ntf-track-flow {
  display: grid;
  grid-template-columns: repeat(5, minmax(0, 1fr));
  gap: 10px;
}
@media (max-width: 991.98px) {
  .ntf-track-flow {
    grid-template-columns: repeat(2, minmax(0, 1fr));
    row-gap: 22px;
  }
}
@media (max-width: 480px) {
  .ntf-track-flow {
    grid-template-columns: minmax(0, 1fr);
  }
}

.ntf-step {
  position: relative;
  padding-top: 40px;
  text-align: center;
}
.ntf-step::before {
  content: "";
  position: absolute;
  left: calc(50% + 18px);
  right: calc(-50% + 18px);
  top: 15px;
  height: 2px;
  background: var(--bs-tertiary-bg);
}
.ntf-step:last-child::before {
  display: none;
}
.ntf-step.is-done::before {
  background: #1ABE17;
}
.ntf-step::after {
  content: "";
  position: absolute;
  left: 50%;
  top: 0;
  transform: translateX(-50%);
  width: 32px;
  height: 32px;
  border-radius: 10px;
  background: var(--bs-body-bg);
  border: 2px solid var(--bs-tertiary-bg);
}
.ntf-step.is-done::after {
  background: #1ABE17;
  border-color: #1ABE17;
}
.ntf-step.is-now::after {
  border-color: var(--bs-primary);
  box-shadow: 0 0 0 4px var(--tint-primary);
}
@media (max-width: 991.98px) {
  .ntf-step::before {
    display: none;
  }
}

.ntf-step-ic {
  position: absolute;
  left: 50%;
  top: 0;
  transform: translateX(-50%);
  z-index: 1;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 32px;
  height: 32px;
  font-size: 15px;
  color: var(--bs-secondary-color);
}
.ntf-step.is-done .ntf-step-ic {
  color: #fff;
}
.ntf-step.is-now .ntf-step-ic {
  color: var(--bs-primary);
}

.ntf-step-title {
  margin: 0 0 3px;
  font-size: 13.5px;
  font-weight: 600;
  color: var(--bs-emphasis-color);
}

/* ============================================================
   9. INSIGHTS + ANNOUNCEMENTS
   ============================================================ */
.ntf-note {
  display: flex;
  align-items: flex-start;
  gap: 13px;
  height: 100%;
  padding: 16px 18px;
  border-radius: var(--radius);
  background: var(--bs-secondary-bg);
  border: 1px solid transparent;
  transition: var(--transition);
}
.ntf-note:hover {
  background: var(--bs-body-bg);
  border-color: var(--bs-border-color);
  box-shadow: var(--shadow);
}

.ntf-note-ic {
  flex-shrink: 0;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 38px;
  height: 38px;
  border-radius: 11px;
  background: var(--bs-body-bg);
  border: 1px solid var(--bs-border-color);
  color: var(--bs-primary);
  font-size: 17px;
}

.ntf-note-title {
  margin: 0 0 3px;
  font-size: 13.5px;
  font-weight: 600;
  color: var(--bs-emphasis-color);
}

/* announcement cards carry a tinted head strip */
.ntf-ann {
  display: flex;
  flex-direction: column;
  height: 100%;
  border-radius: var(--radius);
  background: var(--bs-body-bg);
  border: 1px solid var(--bs-border-color);
  overflow: hidden;
  transition: var(--transition);
}
.ntf-ann:hover {
  box-shadow: var(--shadow-lift);
  transform: translateY(-2px);
}

.ntf-ann-head {
  display: flex;
  align-items: center;
  gap: 11px;
  padding: 13px 16px;
  background: var(--tint-primary);
}
.ntf-ann-head.is-warn {
  background: #FEF8EA;
}
.ntf-ann-head.is-alert {
  background: #FDE9ED;
}
.ntf-ann-head.is-good {
  background: #E8F9E8;
}
.ntf-ann-head.is-info {
  background: #E7F1FC;
}

.ntf-ann-body {
  display: flex;
  flex-direction: column;
  gap: 8px;
  flex: 1 1 auto;
  padding: 16px;
}

.ntf-ann-title {
  margin: 0;
  font-size: 14.5px;
  font-weight: 600;
  color: var(--bs-emphasis-color);
}

.ntf-ann-foot {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  margin-top: auto;
  padding-top: 12px;
  border-top: 1px solid var(--bs-border-color);
}

/* ============================================================
   10. PREFERENCES
   ============================================================ */
.ntf-pref {
  display: flex;
  align-items: center;
  gap: 14px;
  height: 100%;
  padding: 16px;
  border-radius: var(--radius);
  background: var(--bs-body-bg);
  border: 1px solid var(--bs-border-color);
  transition: var(--transition);
}
.ntf-pref:hover {
  box-shadow: var(--shadow);
}

.ntf-pref-ic {
  flex-shrink: 0;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 42px;
  height: 42px;
  border-radius: 50%;
  background: var(--bs-secondary-bg);
  border: 1px solid var(--bs-border-color);
  color: var(--bs-primary);
  font-size: 19px;
}

.ntf-pref-title {
  margin: 0 0 2px;
  font-size: 14px;
  font-weight: 600;
  color: var(--bs-emphasis-color);
}

/* ============================================================
   11. OFFCANVAS + MODAL + EMPTY STATE
   ============================================================ */
.offcanvas.offcanvas-end.ntf-panel {
  width: 88% !important;
  max-width: 1400px !important;
}
@media (max-width: 991.98px) {
  .offcanvas.offcanvas-end.ntf-panel {
    width: 100% !important;
  }
}
.offcanvas.offcanvas-end.ntf-panel .offcanvas-body {
  padding: 22px;
}

.ntf-panel-head {
  display: flex;
  align-items: flex-start;
  gap: 16px;
  flex-wrap: wrap;
  padding: 22px;
  background: radial-gradient(60% 130% at 100% 0%, #F2F5FF 0%, transparent 60%), var(--bs-body-bg);
  border-bottom: 1px solid var(--bs-border-color);
}

.ntf-box {
  height: 100%;
  border-radius: var(--radius);
  background: var(--bs-body-bg);
  border: 1px solid var(--bs-border-color);
  overflow: hidden;
}

.ntf-box-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 13px 16px;
  background: var(--bs-secondary-bg);
  border-bottom: 1px solid var(--bs-border-color);
}
.ntf-box-head h6 {
  margin: 0;
  font-size: 13px;
  font-weight: 600;
  color: var(--bs-emphasis-color);
}

.ntf-box-body {
  padding: 16px;
}

.ntf-line {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 9px 0;
  font-size: 13px;
  color: var(--bs-emphasis-color);
}
.ntf-line + .ntf-line {
  border-top: 1px dashed var(--bs-border-color);
}
.ntf-line b {
  font-weight: 600;
}

/* a comment thread inside the panel */
.ntf-comment {
  display: flex;
  gap: 12px;
  padding: 12px 0;
}
.ntf-comment + .ntf-comment {
  border-top: 1px solid var(--bs-border-color);
}
.ntf-comment p {
  margin: 0;
  font-size: 13px;
  line-height: 1.6;
  color: var(--bs-secondary-color);
}

/* an audit line */
.ntf-audit {
  display: flex;
  align-items: flex-start;
  gap: 10px;
  padding: 8px 0;
  font-size: 12.5px;
  color: var(--bs-secondary-color);
}
.ntf-audit + .ntf-audit {
  border-top: 1px dotted var(--bs-border-color);
}
.ntf-audit time {
  flex-shrink: 0;
  width: 96px;
  font-variant-numeric: tabular-nums;
}
.ntf-audit b {
  font-weight: 600;
  color: var(--bs-emphasis-color);
}

.ntf-modal .modal-content {
  border-radius: var(--radius);
  border: 0;
}
.ntf-modal .modal-header {
  align-items: flex-start;
  padding: 20px 22px;
  border-bottom: 1px solid var(--bs-border-color);
}
.ntf-modal .modal-body {
  padding: 22px;
}
.ntf-modal .modal-footer {
  padding: 16px 22px;
  border-top: 1px solid var(--bs-border-color);
}

.ntf-empty {
  padding: 48px 24px;
  text-align: center;
  border-radius: var(--radius);
  background: var(--bs-secondary-bg);
  border: 1px dashed var(--bs-border-color);
}

.ntf-empty-ic {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 60px;
  height: 60px;
  margin-bottom: 14px;
  border-radius: 18px;
  background: var(--bs-body-bg);
  border: 1px solid var(--bs-border-color);
  box-shadow: var(--shadow);
  color: var(--bs-primary);
  font-size: 26px;
}

.ntf-empty-title {
  margin: 0 0 4px;
  font-size: 15px;
  font-weight: 600;
  color: var(--bs-emphasis-color);
}

/*-----------------
	Dashboard widgets — merged in from the former
	components/_ui-dashboard-widgets.scss. These are generic, reusable
	components; they live with their own kind rather than in a page-shaped file.
-----------------*/
/* ---------- TOASTS ---------- */
#tdToasts {
  position: fixed;
  top: 76px;
  right: 20px;
  z-index: 3000;
  display: flex;
  flex-direction: column;
  gap: 10px;
}

#tdToasts .toast {
  min-width: 250px;
}

/*-----------------
    Settings module

    Every Settings screen — profile, branding, identity, configuration,
    compliance, audit trail and each settings sub-module — lives here. The
    blocks below were previously ten separate partials under components/,
    which made them look reusable when they are page styles for one module.
    Order is preserved exactly as it was compiled before the merge.
-----------------*/
/*===== Settings top tabs =====*/
/* An editorial underline bar for settings-family pages that were moved from
   a left-hand link list to a horizontal switcher above the content. No pill
   track — the tabs sit directly on a hairline rail, and only the active one
   earns a gradient underline and a filled icon, so the bar reads as a piece
   of typography rather than a segmented control. */
.settings-toptabs {
  position: relative;
  display: flex;
  flex-wrap: wrap;
  align-items: flex-end;
  gap: 4px 30px;
  padding: 0 4px;
  border-bottom: 1px solid var(--bs-border-color);
  margin-bottom: 28px;
}

.settings-toptabs-link {
  position: relative;
  display: inline-flex;
  align-items: center;
  gap: 10px;
  padding: 14px 2px 13px;
  font-size: 14px;
  font-weight: 600;
  color: var(--bs-secondary-color);
  white-space: nowrap;
  transition: color 0.18s cubic-bezier(0.4, 0, 0.2, 1);
  /* the underline — scaled to nothing until active, so it grows in
     rather than just appearing */
}
.settings-toptabs-link::after {
  content: "";
  position: absolute;
  left: 0;
  right: 0;
  bottom: -1px;
  height: 2.5px;
  border-radius: 2px 2px 0 0;
  background: linear-gradient(90deg, var(--bs-primary), rgb(125.7775, 114.0035714286, 233.1964285714));
  transform: scaleX(0);
  transform-origin: left center;
  opacity: 0;
  transition: transform 0.22s cubic-bezier(0.4, 0, 0.2, 1), opacity 0.22s;
}
.settings-toptabs-link:hover {
  color: var(--heading);
}
.settings-toptabs-link:hover .settings-toptabs-ic {
  background: var(--surface-soft);
  border-color: rgba(var(--bs-primary-rgb), 0.3);
  color: var(--bs-primary);
}
.settings-toptabs-link.active {
  color: var(--bs-primary);
}
.settings-toptabs-link.active::after {
  transform: scaleX(1);
  opacity: 1;
}
.settings-toptabs-link.active .settings-toptabs-ic {
  background: linear-gradient(155deg, var(--bs-primary) 0%, rgb(28.7410714286, 60.35625, 185.8589285714) 100%);
  border-color: transparent;
  color: #fff;
  box-shadow: 0 4px 10px -2px rgba(var(--bs-primary-rgb), 0.5);
}
@media (max-width: 575.98px) {
  .settings-toptabs-link {
    width: 100%;
    justify-content: flex-start;
  }
}

.settings-toptabs-ic {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 28px;
  height: 28px;
  flex-shrink: 0;
  border-radius: 9px;
  background: var(--surface);
  border: 1px solid var(--bs-border-color);
  color: var(--bs-secondary-color);
  font-size: 14px;
  transition: 0.18s cubic-bezier(0.4, 0, 0.2, 1);
}

@media (max-width: 575.98px) {
