}

/* status badge — a dot and a word */
.meta-badge {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 4px 11px;
  border-radius: 6px;
  background: var(--surface-soft);
  border: 1px solid var(--bs-border-color);
  font-size: 11px;
  font-weight: 600;
  color: var(--heading);
