}
.meta-badge::before {
  content: "";
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: var(--bs-secondary-color);
}
.meta-badge.is-active {
  color: #1ABE17;
  background: #E8F9E8;
  border-color: #D1F2D1;
}
.meta-badge.is-active::before {
  background: #1ABE17;
}
.meta-badge.is-pending {
  color: #EAB300;
  background: #FEF8EA;
  border-color: #FDF1D6;
}
.meta-badge.is-pending::before {
  background: #EAB300;
}
.meta-badge.is-expiring {
  color: #E82646;
  background: #FDE9ED;
  border-color: #FAD4DA;
}
.meta-badge.is-expiring::before {
  background: #E82646;
}
.meta-badge.is-draft {
  color: #0F65CD;
  background: #E7F1FC;
  border-color: #CFE2FA;
}
.meta-badge.is-draft::before {
