  --p: 87;
}

.fin-p-88 {
  --p: 88;
}

.fin-p-89 {
  --p: 89;
}

.fin-p-90 {
  --p: 90;
}

.fin-p-91 {
  --p: 91;
}

.fin-p-92 {
  --p: 92;
}

.fin-p-93 {
  --p: 93;
}

.fin-p-94 {
  --p: 94;
}

.fin-p-95 {
  --p: 95;
}

.fin-p-96 {
  --p: 96;
}

.fin-p-97 {
  --p: 97;
}

.fin-p-98 {
  --p: 98;
}

.fin-p-99 {
  --p: 99;
}

.fin-p-100 {
  --p: 100;
}

/* small caps label used above groups of values */
.fin-lbl {
  display: block;
  margin: 0 0 4px;
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--bs-secondary-color);
}

/* an amount, set in tabular figures so columns of money line up */
.fin-amt {
  font-variant-numeric: tabular-nums;
  font-feature-settings: "tnum" 1;
  font-weight: 600;
  color: var(--bs-emphasis-color);
}

/* ---- status badges ----------------------------------------------------- */
.fin-badge {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 4px 10px;
  border-radius: 999px;
  background: var(--bs-secondary-bg);
  border: 1px solid var(--bs-border-color);
  font-size: 11.5px;
  font-weight: 600;
  line-height: 1.4;
  white-space: nowrap;
  color: var(--bs-secondary-color);
}
.fin-badge::before {
  content: "";
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: currentColor;
  flex-shrink: 0;
}
.fin-badge.is-live {
  background: var(--fin-money-soft);
  border-color: rgba(26, 190, 23, 0.28);
  color: rgb(21.0197183099, 153.6056338028, 18.5943661972);
}
.fin-badge.is-test {
  background: var(--tint-warning);
  border-color: rgba(234, 179, 0, 0.32);
  color: rgb(162.6, 124.3820512821, 0);
}
.fin-badge.is-review {
  background: var(--tint-primary);
  border-color: rgba(61, 94, 225, 0.26);
  color: var(--bs-primary);
}
.fin-badge.is-alert {
  background: var(--fin-alert-soft);
  border-color: rgba(232, 38, 70, 0.26);
  color: var(--fin-alert);
}
.fin-badge.is-off {
  opacity: 0.85;
}
.fin-badge {
  /* a badge with no dot, for plain metadata */
}
.fin-badge.is-plain::before {
  display: none;
}

/* ---- a thin proportion meter ------------------------------------------- */
.fin-meter {
  position: relative;
  height: 6px;
  border-radius: 999px;
  background: var(--bs-tertiary-bg);
  overflow: hidden;
}
.fin-meter span {
  position: absolute;
  inset: 0 auto 0 0;
  width: calc(var(--p, 0) * 1%);
  border-radius: inherit;
  background: var(--bs-primary);
  transition: width var(--transition);
}
.fin-meter.is-money span {
  background: var(--fin-money);
}
.fin-meter.is-warn span {
  background: var(--bs-warning);
}

/* ============================================================
   2. SETTINGS HERO
   A banded surface that names what is being edited and, just as
   importantly, WHICH environment it will land in.
   ============================================================ */
.fin-hero {
  position: relative;
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  align-items: flex-end;
  gap: 24px 32px;
  padding: 26px 28px;
  margin-bottom: 24px;
  border-radius: var(--radius);
  background: linear-gradient(112deg, var(--tint-primary) 0%, rgba(255, 255, 255, 0) 46%), var(--bs-body-bg);
  border: 1px solid var(--bs-border-color);
  box-shadow: var(--shadow);
  overflow: hidden;
  /* a hairline rule of the accent along the top edge */
}
.fin-hero::before {
  content: "";
  position: absolute;
  inset: 0 0 auto 0;
  height: 3px;
  background: linear-gradient(90deg, var(--bs-primary), var(--fin-money));
}
@media (max-width: 1199.98px) {
  .fin-hero {
    grid-template-columns: minmax(0, 1fr);
    align-items: flex-start;
  }
}
@media (max-width: 575.98px) {
  .fin-hero {
    padding: 20px;
  }
}

.fin-hero-top {
  display: flex;
  align-items: center;
  gap: 14px;
  margin-bottom: 14px;
  flex-wrap: wrap;
}

.fin-hero-crest {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 52px;
  height: 52px;
  flex-shrink: 0;
  border-radius: 16px;
  background: var(--bs-primary);
  color: #fff;
  font-size: 25px;
  box-shadow: 0 8px 18px rgba(61, 94, 225, 0.28);
}

.fin-hero-title {
  margin: 0;
  font-size: 26px;
  font-weight: 700;
  line-height: 1.2;
  color: var(--bs-emphasis-color);
}
@media (max-width: 575.98px) {
  .fin-hero-title {
    font-size: 21px;
  }
}

.fin-hero-sub {
  margin: 4px 0 0;
  max-width: 62ch;
  font-size: 13.5px;
  line-height: 1.6;
  color: var(--bs-secondary-color);
}

/* the environment chip — deliberately loud, because it changes consequences */
.fin-hero-env {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 6px 12px;
  border-radius: 999px;
  background: var(--bs-emphasis-color);
  color: #fff;
  font-size: 11.5px;
  font-weight: 600;
  letter-spacing: 0.06em;
  text-transform: uppercase;
}
.fin-hero-env i {
  font-size: 14px;
}
.fin-hero-env.is-test {
  background: rgb(172.8, 132.1846153846, 0);
}

/* facts sit on a single rule, divided by hairlines */
.fin-hero-facts {
  display: flex;
  flex-wrap: wrap;
  margin-top: 20px;
  padding-top: 18px;
  border-top: 1px solid var(--bs-border-color);
}

.fin-hero-fact {
  display: flex;
  flex-direction: column;
  gap: 3px;
  flex: 1 1 0;
  min-width: 150px;
  padding: 0 20px;
}
.fin-hero-fact:first-child {
  padding-left: 0;
}
.fin-hero-fact + .fin-hero-fact {
  border-left: 1px solid var(--bs-border-color);
}
.fin-hero-fact span {
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.07em;
  text-transform: uppercase;
  color: var(--bs-secondary-color);
}
.fin-hero-fact strong {
  font-size: 14.5px;
  font-weight: 600;
  color: var(--bs-emphasis-color);
}
@media (max-width: 767.98px) {
  .fin-hero-fact {
    flex: 1 1 46%;
    padding: 10px 14px;
  }
  .fin-hero-fact:first-child {
    padding-left: 14px;
  }
  .fin-hero-fact + .fin-hero-fact {
    border-left: 0;
  }
}

.fin-hero-actions {
  display: flex;
  align-items: center;
  gap: 10px;
  flex-wrap: wrap;
}
@media (max-width: 1199.98px) {
  .fin-hero-actions {
    width: 100%;
  }
}

/* ============================================================
   3. STICKY CENTRE NAVIGATION
   Every page of the centre, always visible, current one marked.
   ============================================================ */
.fin-nav {
  position: sticky;
  top: calc(60px + 16px);
  max-height: calc(100vh - 60px - 32px);
  padding: 14px;
  border-radius: var(--radius);
  background: var(--bs-body-bg);
  border: 1px solid var(--bs-border-color);
  box-shadow: var(--shadow);
  overflow-y: auto;
  /* Bootstrap's `.nav` sets `flex-wrap: wrap`; inside a column flex box with
     a capped height that wraps the overflow into a SECOND COLUMN instead of
     scrolling, which shows as a horizontal scrollbar. The rail must scroll
     vertically and never wrap. */
  flex-wrap: nowrap;
  overflow-x: hidden;
}
.fin-nav > * {
  flex-shrink: 0;
}
@media (max-width: 991.98px) {
  .fin-nav {
    position: static;
    max-height: none;
  }
}

.fin-nav-hdr {
  display: block;
  padding: 12px 10px 6px;
  font-size: 10.5px;
  font-weight: 700;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--bs-secondary-color);
}
.fin-nav-hdr:first-child {
  padding-top: 2px;
}

.fin-nav-link {
  position: relative;
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 9px 12px;
  border-radius: var(--radius-sm);
  font-size: 13.5px;
  font-weight: 500;
  color: var(--bs-emphasis-color);
  text-decoration: none;
  transition: var(--transition);
}
.fin-nav-link i {
  flex-shrink: 0;
  font-size: 17px;
  color: var(--bs-secondary-color);
  transition: var(--transition);
}
.fin-nav-link span:first-of-type {
  flex: 1 1 auto;
  min-width: 0;
}
.fin-nav-link:hover {
  background: var(--bs-secondary-bg);
  color: var(--bs-emphasis-color);
}
.fin-nav-link.active {
  background: var(--tint-primary);
  color: var(--bs-primary);
  font-weight: 600;
}
.fin-nav-link.active i {
  color: var(--bs-primary);
}
.fin-nav-link.active {
  /* a short mark against the left edge, rather than a full border */
}
.fin-nav-link.active::before {
  content: "";
  position: absolute;
  left: 0;
  top: 50%;
  transform: translateY(-50%);
  width: 3px;
  height: 18px;
  border-radius: 0 3px 3px 0;
  background: var(--bs-primary);
}

/* a quiet marker for a page that is configured, or not yet */
.fin-nav-tag {
  flex-shrink: 0;
  padding: 2px 7px;
  border-radius: 999px;
  background: var(--bs-secondary-bg);
  font-size: 10px;
  font-weight: 600;
  color: var(--bs-secondary-color);
}
.fin-nav-tag.is-set {
  background: var(--fin-money-soft);
  color: rgb(21.0197183099, 153.6056338028, 18.5943661972);
}
.fin-nav-tag.is-warn {
  background: var(--tint-warning);
  color: rgb(152.4, 116.5794871795, 0);
}

.fin-nav-foot {
  margin-top: 14px;
  padding: 14px 12px 6px;
  border-top: 1px solid var(--bs-border-color);
}

/* ============================================================
   4. CONFIGURATION WORKSPACE + PREMIUM TABS
   ============================================================ */
.fin-ws {
  border-radius: var(--radius);
  background: var(--bs-body-bg);
  border: 1px solid var(--bs-border-color);
  box-shadow: var(--shadow);
  overflow: hidden;
}

.fin-ws-head {
  display: flex;
  align-items: center;
  gap: 16px;
  flex-wrap: wrap;
  padding: 18px 22px;
  background: var(--bs-secondary-bg);
  border-bottom: 1px solid var(--bs-border-color);
}

.fin-ws-title {
  margin: 0;
  font-size: 16px;
  font-weight: 700;
  color: var(--bs-emphasis-color);
}
.fin-ws-title + p {
  margin: 2px 0 0;
  font-size: 12.5px;
  color: var(--bs-secondary-color);
}

.fin-ws-body {
  padding: 22px;
}
@media (max-width: 575.98px) {
  .fin-ws-body {
    padding: 18px 16px;
  }
}

/* premium tabs — a rail of pills on a recessed track */
.fin-tabs {
  display: flex;
  gap: 4px;
  padding: 4px;
  border-radius: 11px;
  background: var(--bs-body-bg);
  border: 1px solid var(--bs-border-color);
  overflow-x: auto;
  scrollbar-width: none;
  flex-wrap: nowrap;
}
.fin-tabs::-webkit-scrollbar {
  display: none;
}

.fin-tab {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  padding: 8px 15px;
  border: 0;
  border-radius: 8px;
  background: transparent;
  font-size: 13px;
  font-weight: 600;
  white-space: nowrap;
  color: var(--bs-secondary-color);
  transition: var(--transition);
}
.fin-tab i {
  font-size: 16px;
}
.fin-tab:hover {
  background: var(--bs-secondary-bg);
  color: var(--bs-emphasis-color);
}
.fin-tab.active {
  background: var(--bs-primary);
  color: #fff;
  box-shadow: 0 4px 12px rgba(61, 94, 225, 0.26);
}
.fin-tab {
  /* a count riding along with the label */
}
.fin-tab .fin-tab-n {
  padding: 1px 6px;
  border-radius: 999px;
  background: rgba(0, 0, 0, 0.07);
  font-size: 10.5px;
  line-height: 1.6;
}
.fin-tab.active .fin-tab-n {
  background: rgba(255, 255, 255, 0.24);
}

/* ============================================================
   5. CONFIGURATION CARDS + SETTING ROWS
   ============================================================ */
.fin-card {
  display: flex;
  flex-direction: column;
  height: 100%;
  border-radius: var(--radius);
  background: var(--bs-body-bg);
  border: 1px solid var(--bs-border-color);
  transition: var(--transition);
}
.fin-card:hover {
  border-color: var(--fin-border-strong);
  box-shadow: var(--shadow-lift);
}
.fin-card {
  /* a card whose whole surface opens the workspace */
}
.fin-card.is-clickable {
  cursor: pointer;
}

.fin-card-head {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 16px 18px;
  border-bottom: 1px solid var(--bs-border-color);
}

.fin-card-ic {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 40px;
  height: 40px;
  flex-shrink: 0;
  border-radius: 12px;
  background: var(--tint-primary);
  color: var(--bs-primary);
  font-size: 19px;
}
.fin-card-ic.is-money {
  background: var(--fin-money-soft);
  color: rgb(21.0197183099, 153.6056338028, 18.5943661972);
}
.fin-card-ic.is-warn {
  background: var(--tint-warning);
  color: rgb(162.6, 124.3820512821, 0);
}
.fin-card-ic.is-alert {
  background: var(--fin-alert-soft);
  color: var(--fin-alert);
}

.fin-card-title {
  margin: 0;
  font-size: 14.5px;
  font-weight: 600;
  color: var(--bs-emphasis-color);
}

.fin-card-body {
  flex: 1 1 auto;
  padding: 6px 18px 14px;
}

.fin-card-foot {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  flex-wrap: wrap;
  padding: 12px 18px;
  background: var(--bs-secondary-bg);
  border-top: 1px solid var(--bs-border-color);
}

/* one setting: what it is, what it is set to, and the control that changes it */
.fin-row {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  align-items: center;
  gap: 10px 16px;
  padding: 12px 0;
}
.fin-row + .fin-row {
  border-top: 1px solid var(--bs-border-color);
}
@media (max-width: 575.98px) {
  .fin-row {
    grid-template-columns: minmax(0, 1fr);
  }
  .fin-row .fin-row-ctl {
    justify-content: flex-start;
  }
}

.fin-row-key {
  min-width: 0;
}
.fin-row-key strong {
  display: block;
  font-size: 13.5px;
  font-weight: 500;
  color: var(--bs-emphasis-color);
}
.fin-row-key span {
  display: block;
  margin-top: 2px;
  font-size: 12px;
  line-height: 1.55;
  color: var(--bs-secondary-color);
}

.fin-row-ctl {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  gap: 10px;
  white-space: nowrap;
}

/* a compact input that sits inside a row without dominating it */
.fin-input,
.fin-select {
  min-width: 150px;
  padding: 7px 12px;
  border-radius: var(--radius-sm);
  background-color: var(--bs-body-bg);
  border: 1px solid var(--bs-border-color);
  font-size: 13px;
  color: var(--bs-emphasis-color);
  transition: var(--transition);
}
.fin-input:focus,
.fin-select:focus {
  border-color: var(--bs-primary);
  box-shadow: 0 0 0 3px var(--tint-primary);
  outline: 0;
}
@media (max-width: 575.98px) {
  .fin-input,
  .fin-select {
    min-width: 0;
    width: 100%;
  }
}

.fin-select {
  padding-right: 30px;
}

/* an amount field with its currency fixed to the front */
.fin-money-field {
  display: inline-flex;
  align-items: stretch;
  border-radius: var(--radius-sm);
  border: 1px solid var(--bs-border-color);
  overflow: hidden;
}
.fin-money-field .fin-money-sym {
  display: inline-flex;
  align-items: center;
  padding: 0 10px;
  background: var(--bs-secondary-bg);
  border-right: 1px solid var(--bs-border-color);
  font-size: 13px;
  font-weight: 600;
  color: var(--bs-secondary-color);
}
.fin-money-field input {
  width: 108px;
  padding: 7px 10px;
  border: 0;
  font-size: 13px;
  font-variant-numeric: tabular-nums;
  color: var(--bs-emphasis-color);
}
.fin-money-field input:focus {
  outline: 0;
}
.fin-money-field:focus-within {
  border-color: var(--bs-primary);
  box-shadow: 0 0 0 3px var(--tint-primary);
}

/* ============================================================
   6. PAYMENT PROVIDER CARDS
   A provider shows its mark, the mode it is running in, its
   credentials as a masked fingerprint, and its cost.
   ============================================================ */
.fin-prov {
  position: relative;
  display: flex;
  flex-direction: column;
  height: 100%;
  border-radius: var(--radius);
  background: var(--bs-body-bg);
  border: 1px solid var(--bs-border-color);
  transition: var(--transition);
  overflow: hidden;
}
.fin-prov:hover {
  border-color: var(--fin-border-strong);
  box-shadow: var(--shadow-lift);
}
.fin-prov {
  /* the live provider is marked along its leading edge */
}
.fin-prov.is-primary::after {
  content: "";
  position: absolute;
  inset: 0 auto 0 0;
  width: 3px;
  background: var(--fin-money);
}
.fin-prov.is-disabled {
  background: var(--bs-secondary-bg);
}
.fin-prov.is-disabled .fin-prov-mark,
.fin-prov.is-disabled .fin-prov-name {
  opacity: 0.7;
}

.fin-prov-head {
  display: flex;
  align-items: flex-start;
  gap: 13px;
  padding: 18px 18px 14px;
}

.fin-prov-mark {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 46px;
  height: 46px;
  flex-shrink: 0;
  border-radius: 13px;
  background: var(--bs-secondary-bg);
  border: 1px solid var(--bs-border-color);
  font-size: 22px;
  color: var(--bs-emphasis-color);
}

.fin-prov-name {
  margin: 0;
  font-size: 15px;
  font-weight: 600;
  color: var(--bs-emphasis-color);
}
.fin-prov-name + p {
  margin: 2px 0 0;
  font-size: 12px;
  line-height: 1.55;
  color: var(--bs-secondary-color);
}

/* the credential fingerprint — enough to identify a key, never enough to use it */
.fin-prov-key {
  display: flex;
  align-items: center;
  gap: 8px;
  margin: 0 18px 14px;
  padding: 9px 12px;
  border-radius: var(--radius-sm);
  background: var(--bs-secondary-bg);
  border: 1px dashed var(--fin-border-strong);
  font-size: 12px;
  color: var(--bs-secondary-color);
}
.fin-prov-key code {
  font-size: 12px;
  letter-spacing: 0.04em;
  color: var(--bs-emphasis-color);
}

/* provider facts, on their own hairline grid */
.fin-prov-facts {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  border-top: 1px solid var(--bs-border-color);
}

.fin-prov-fact {
  padding: 11px 18px;
}
.fin-prov-fact:nth-child(odd) {
  border-right: 1px solid var(--bs-border-color);
}
.fin-prov-fact:nth-child(n+3) {
  border-top: 1px solid var(--bs-border-color);
}
.fin-prov-fact span {
  display: block;
  font-size: 10.5px;
  font-weight: 600;
  letter-spacing: 0.07em;
  text-transform: uppercase;
  color: var(--bs-secondary-color);
}
.fin-prov-fact strong {
  display: block;
  margin-top: 2px;
  font-size: 13px;
  font-weight: 600;
  font-variant-numeric: tabular-nums;
  color: var(--bs-emphasis-color);
}

.fin-prov-foot {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  padding: 12px 18px;
  background: var(--bs-secondary-bg);
  border-top: 1px solid var(--bs-border-color);
}

/* ============================================================
   7. BUSINESS RULE ROWS
   A rule reads as a sentence: when this, then that.
   ============================================================ */
.fin-rule {
  display: grid;
  grid-template-columns: 34px minmax(0, 1fr) auto;
  align-items: center;
  gap: 16px;
  padding: 15px 18px;
  border-radius: var(--radius);
  background: var(--bs-body-bg);
  border: 1px solid var(--bs-border-color);
  transition: var(--transition);
}
.fin-rule + .fin-rule {
  margin-top: 10px;
}
.fin-rule:hover {
  border-color: var(--fin-border-strong);
  box-shadow: var(--shadow);
}
.fin-rule.is-off {
  background: var(--bs-secondary-bg);
}
.fin-rule.is-off .fin-rule-body {
  opacity: 0.68;
}
@media (max-width: 767.98px) {
  .fin-rule {
    grid-template-columns: 34px minmax(0, 1fr);
    row-gap: 12px;
  }
  .fin-rule .fin-rule-ctl {
    grid-column: 2/-1;
    justify-content: flex-start;
  }
}

/* the rule's order in the chain — order matters when rules stack */
.fin-rule-n {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 34px;
  height: 34px;
  border-radius: 10px;
  background: var(--bs-secondary-bg);
  border: 1px solid var(--bs-border-color);
  font-size: 12.5px;
  font-weight: 700;
  font-variant-numeric: tabular-nums;
  color: var(--bs-secondary-color);
}

.fin-rule-body {
  min-width: 0;
}

.fin-rule-line {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-wrap: wrap;
  font-size: 13.5px;
  line-height: 1.6;
  color: var(--bs-emphasis-color);
  /* the arrow between condition and outcome */
}
.fin-rule-line i.ti-arrow-narrow-right {
  color: var(--bs-secondary-color);
  font-size: 17px;
}

/* the variable parts of the sentence, marked so the rule can be scanned */
.fin-rule-cond,
.fin-rule-then {
  padding: 2px 9px;
  border-radius: 7px;
  font-size: 12.5px;
  font-weight: 600;
}

.fin-rule-cond {
  background: var(--tint-primary);
  color: var(--bs-primary);
}

.fin-rule-then {
  background: var(--fin-money-soft);
  color: rgb(19.7746478873, 144.5070422535, 17.4929577465);
}

.fin-rule-note {
  display: block;
  margin-top: 4px;
  font-size: 12px;
  color: var(--bs-secondary-color);
}

.fin-rule-ctl {
  display: flex;
  align-items: center;
  gap: 12px;
  justify-content: flex-end;
}

/* ============================================================
   8. FEATURE CARDS
   Status, what it does, what it needs, and the switch.
   ============================================================ */
.fin-feature {
  display: flex;
  flex-direction: column;
  gap: 12px;
  height: 100%;
  padding: 18px;
  border-radius: var(--radius);
  background: var(--bs-body-bg);
  border: 1px solid var(--bs-border-color);
  transition: var(--transition);
}
.fin-feature:hover {
  box-shadow: var(--shadow-lift);
}
.fin-feature {
  /* an enabled feature tints and solidifies its glyph */
}
.fin-feature.is-on {
  border-color: rgba(61, 94, 225, 0.26);
  background: linear-gradient(160deg, var(--tint-primary), var(--bs-body-bg) 58%);
}
.fin-feature.is-on .fin-feature-ic {
  background: var(--bs-primary);
  border-color: transparent;
  color: #fff;
}

.fin-feature-top {
  display: flex;
  align-items: flex-start;
  gap: 12px;
}

.fin-feature-ic {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 42px;
  height: 42px;
  flex-shrink: 0;
  border-radius: 13px;
  background: var(--bs-secondary-bg);
  border: 1px solid var(--bs-border-color);
  color: var(--bs-primary);
  font-size: 20px;
  transition: var(--transition);
}

.fin-feature-title {
  margin: 0;
  font-size: 14.5px;
  font-weight: 600;
  color: var(--bs-emphasis-color);
}

.fin-feature-txt {
  margin: 0;
  font-size: 12.5px;
  line-height: 1.6;
  color: var(--bs-secondary-color);
}

/* the things this feature depends on, named plainly */
.fin-deps {
  display: flex;
  align-items: center;
  gap: 6px;
  flex-wrap: wrap;
}

.fin-dep {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  padding: 3px 9px;
  border-radius: 7px;
  background: var(--bs-secondary-bg);
  border: 1px solid var(--bs-border-color);
  font-size: 11.5px;
  font-weight: 500;
  color: var(--bs-secondary-color);
}
.fin-dep i {
  font-size: 13px;
}
.fin-dep.is-missing {
  background: var(--fin-alert-soft);
  border-color: rgba(232, 38, 70, 0.24);
  color: var(--fin-alert);
}

.fin-feature-foot {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  margin-top: auto;
  padding-top: 12px;
  border-top: 1px solid var(--bs-border-color);
}

/* ============================================================
   9. PREMIUM ACCORDION
   ============================================================ */
.fin-acc {
  border-radius: var(--radius);
  border: 1px solid var(--bs-border-color);
  background: var(--bs-body-bg);
  overflow: hidden;
}
.fin-acc .accordion-item {
  border: 0;
  background: transparent;
}
.fin-acc .accordion-item + .accordion-item {
  border-top: 1px solid var(--bs-border-color);
}
.fin-acc .accordion-button {
  gap: 12px;
  padding: 16px 18px;
  background: var(--bs-body-bg);
  font-size: 14px;
  font-weight: 600;
  color: var(--bs-emphasis-color);
  box-shadow: none;
}
.fin-acc .accordion-button::after {
  margin-left: 0;
}
.fin-acc .accordion-button:not(.collapsed) {
  background: var(--tint-primary);
  color: var(--bs-primary);
}
.fin-acc .accordion-button:focus {
  box-shadow: 0 0 0 3px var(--tint-primary);
}
.fin-acc .accordion-button i {
  font-size: 18px;
}
.fin-acc {
  /* pushes anything after it to the right of the header */
}
.fin-acc .fin-acc-spacer {
  margin-left: auto;
}
.fin-acc .accordion-body {
  padding: 4px 18px 18px;
}

/* ============================================================
   10. INFORMATION CENTRE PANELS
   ============================================================ */
.fin-note {
  display: flex;
  flex-direction: column;
  gap: 10px;
  height: 100%;
  padding: 18px;
  border-radius: var(--radius);
  background: var(--bs-body-bg);
  border: 1px solid var(--bs-border-color);
  border-left: 3px solid var(--bs-primary);
}
.fin-note.is-money {
  border-left-color: var(--fin-money);
}
.fin-note.is-warn {
  border-left-color: var(--bs-warning);
}
.fin-note.is-alert {
  border-left-color: var(--fin-alert);
}

.fin-note-head {
  display: flex;
  align-items: center;
  gap: 9px;
}
.fin-note-head i {
  font-size: 18px;
  color: var(--bs-primary);
}
.is-money .fin-note-head i {
  color: rgb(21.0197183099, 153.6056338028, 18.5943661972);
}
.is-warn .fin-note-head i {
  color: rgb(162.6, 124.3820512821, 0);
}
.is-alert .fin-note-head i {
  color: var(--fin-alert);
}
.fin-note-head h6 {
  margin: 0;
  font-size: 14px;
  font-weight: 600;
  color: var(--bs-emphasis-color);
}

.fin-note-list {
  margin: 0;
  padding: 0;
  list-style: none;
}
.fin-note-list li {
  position: relative;
  padding: 6px 0 6px 18px;
  font-size: 12.5px;
  line-height: 1.6;
  color: var(--bs-secondary-color);
  /* a small dash rather than a bullet */
}
.fin-note-list li::before {
  content: "";
  position: absolute;
  left: 0;
  top: 14px;
  width: 9px;
  height: 1px;
  background: var(--fin-border-strong);
}
.fin-note-list li + li {
  border-top: 1px solid var(--bs-border-color);
}
.fin-note-list li strong {
  color: var(--bs-emphasis-color);
  font-weight: 600;
}

/* a recent change, showing what moved from what to what */
.fin-delta {
  display: flex;
  align-items: center;
  gap: 7px;
  flex-wrap: wrap;
  margin-top: 3px;
  font-size: 12px;
}
.fin-delta del {
  text-decoration: line-through;
  color: var(--bs-secondary-color);
}
.fin-delta ins {
  text-decoration: none;
  font-weight: 600;
  color: rgb(19.7746478873, 144.5070422535, 17.4929577465);
}
.fin-delta i {
  font-size: 14px;
  color: var(--bs-secondary-color);
}

/* ============================================================
   11. CONFIGURATION TIMELINE
   Horizontal on a wide screen, vertical when there is no room.
   ============================================================ */
.fin-tl {
  display: grid;
  grid-template-columns: repeat(5, minmax(0, 1fr));
  gap: 0;
  padding: 24px 22px 22px;
  border-radius: var(--radius);
  background: var(--bs-body-bg);
  border: 1px solid var(--bs-border-color);
}
@media (max-width: 991.98px) {
  .fin-tl {
    grid-template-columns: minmax(0, 1fr);
    padding: 18px;
  }
}

.fin-tl-step {
  position: relative;
  padding: 0 18px;
  /* the connecting rule runs behind the markers */
}
.fin-tl-step::before {
  content: "";
  position: absolute;
  left: 0;
  right: 0;
  top: 13px;
  height: 2px;
  background: var(--bs-tertiary-bg);
}
.fin-tl-step:first-child::before {
  left: 50%;
}
.fin-tl-step:last-child::before {
  right: 50%;
}
.fin-tl-step {
  /* a completed step carries the accent through to the next marker */
}
.fin-tl-step.is-done::before {
  background: var(--bs-primary);
}
.fin-tl-step.is-current ::before {
  background: var(--bs-primary);
}
@media (max-width: 991.98px) {
  .fin-tl-step {
    padding: 0 0 22px 30px;
  }
  .fin-tl-step::before {
    left: 13px;
    right: auto;
    top: 0;
    bottom: 0;
    width: 2px;
    height: auto;
  }
  .fin-tl-step:first-child::before {
    left: 13px;
    top: 13px;
  }
  .fin-tl-step:last-child::before {
    right: auto;
    bottom: auto;
    height: 13px;
  }
}

.fin-tl-dot {
  position: relative;
  z-index: 1;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 28px;
  height: 28px;
  margin-bottom: 12px;
  border-radius: 50%;
  background: var(--bs-body-bg);
  border: 2px solid var(--bs-tertiary-bg);
  font-size: 14px;
  color: var(--bs-secondary-color);
}
.is-done .fin-tl-dot {
  background: var(--bs-primary);
  border-color: var(--bs-primary);
  color: #fff;
}
.is-current .fin-tl-dot {
  border-color: var(--bs-primary);
  color: var(--bs-primary);
  box-shadow: 0 0 0 4px var(--tint-primary);
}
@media (max-width: 991.98px) {
  .fin-tl-dot {
    position: absolute;
    left: -30px;
    top: 0;
    margin-bottom: 0;
  }
}

.fin-tl-title {
  margin: 0;
  font-size: 13.5px;
  font-weight: 600;
  color: var(--bs-emphasis-color);
}

.fin-tl-meta {
  display: block;
  margin-top: 2px;
  font-size: 11.5px;
  color: var(--bs-secondary-color);
}

.fin-tl-txt {
  margin: 6px 0 0;
  font-size: 12px;
  line-height: 1.6;
  color: var(--bs-secondary-color);
}

/* ============================================================
   12. OFFCANVAS, MODAL HELPERS, EMPTY STATE
   ============================================================ */
/* The theme sets `.offcanvas.offcanvas-end { width: auto !important }` in
   `_popup.scss`. Two classes plus `!important` beats any single-class rule,
   so the workspace has to match on three classes to win. */
.offcanvas.offcanvas-end.fin-ws-canvas {
  width: 88% !important;
  max-width: 1180px !important;
}

.fin-canvas-head {
  display: flex;
  align-items: flex-start;
  gap: 14px;
  padding: 20px 24px;
  background: var(--bs-secondary-bg);
  border-bottom: 1px solid var(--bs-border-color);
}

.fin-canvas-body {
  padding: 22px 24px 32px;
}

/* a section inside the workspace panel */
.fin-sect + .fin-sect {
  margin-top: 26px;
  padding-top: 22px;
  border-top: 1px solid var(--bs-border-color);
}

.fin-sect-title {
  display: flex;
  align-items: center;
  gap: 8px;
  margin: 0 0 14px;
  font-size: 13px;
  font-weight: 700;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--bs-emphasis-color);
}
.fin-sect-title i {
  font-size: 17px;
  color: var(--bs-primary);
}

/* key/value pairs with a dotted leader, as on a statement */
.fin-kv {
  display: flex;
  align-items: baseline;
  gap: 8px;
  margin: 0;
  padding: 8px 0;
  font-size: 13px;
}
.fin-kv + .fin-kv {
  border-top: 1px solid var(--bs-border-color);
}
.fin-kv dt {
  order: 0;
  flex-shrink: 0;
  font-weight: 400;
  color: var(--bs-secondary-color);
}
.fin-kv {
  /* The leader is a pseudo-element ordered between the term and the
     description, so the markup stays a valid `dl` with nothing but
     `dt`/`dd` inside it. */
}
.fin-kv::before {
  content: "";
  order: 1;
  flex: 1 1 auto;
  min-width: 14px;
  height: 1px;
  border-bottom: 1px dotted var(--fin-border-strong);
  transform: translateY(-3px);
}
.fin-kv dd {
  order: 2;
  margin: 0;
  font-weight: 600;
  font-variant-numeric: tabular-nums;
  text-align: right;
  color: var(--bs-emphasis-color);
}

/* a validation result: what was checked and whether it passed */
.fin-check {
  display: flex;
  align-items: flex-start;
  gap: 10px;
  padding: 10px 0;
  font-size: 13px;
  line-height: 1.6;
  color: var(--bs-emphasis-color);
}
.fin-check + .fin-check {
  border-top: 1px solid var(--bs-border-color);
}
.fin-check > i {
  flex-shrink: 0;
  margin-top: 1px;
  font-size: 17px;
  color: rgb(21.0197183099, 153.6056338028, 18.5943661972);
}
.fin-check.is-warn > i {
  color: rgb(162.6, 124.3820512821, 0);
}
.fin-check.is-alert > i {
  color: var(--fin-alert);
}
.fin-check span {
  display: block;
  font-size: 12px;
  color: var(--bs-secondary-color);
}

/* audit entries — a date gutter and the change beside it */
.fin-audit {
  display: grid;
  grid-template-columns: 108px minmax(0, 1fr);
  gap: 14px;
  padding: 12px 0;
}
.fin-audit + .fin-audit {
  border-top: 1px solid var(--bs-border-color);
}
@media (max-width: 575.98px) {
  .fin-audit {
    grid-template-columns: minmax(0, 1fr);
    gap: 4px;
  }
}

.fin-audit-when {
  font-size: 12px;
  font-variant-numeric: tabular-nums;
  color: var(--bs-secondary-color);
}
.fin-audit-when strong {
  display: block;
  font-size: 12.5px;
  font-weight: 600;
  color: var(--bs-emphasis-color);
}

.fin-audit-what {
  font-size: 13px;
  line-height: 1.6;
  color: var(--bs-emphasis-color);
}
.fin-audit-what span {
  display: block;
  margin-top: 2px;
  font-size: 12px;
  color: var(--bs-secondary-color);
}

/* ---- empty state ------------------------------------------------------- */
.fin-empty {
  display: flex;
  flex-direction: column;
  align-items: center;
  text-align: center;
  gap: 6px;
  padding: 40px 24px;
  border-radius: var(--radius);
  background: var(--bs-secondary-bg);
  border: 1px dashed var(--fin-border-strong);
}
.fin-empty i {
  font-size: 32px;
  color: var(--bs-secondary-color);
  opacity: 0.8;
}
.fin-empty h6 {
  margin: 8px 0 0;
  font-size: 14.5px;
  font-weight: 600;
  color: var(--bs-emphasis-color);
}
.fin-empty p {
  margin: 0;
  max-width: 46ch;
  font-size: 12.5px;
  line-height: 1.6;
  color: var(--bs-secondary-color);
}
.fin-empty .btn {
  margin-top: 10px;
}

/*===== email settings =====*/
/*-----------------
    Email Settings — mail delivery configuration components

    Reusable pieces for the Email Settings & Mail Delivery Configuration
    Center. Class prefix `eml-`.

    The visual language is a mail operations console rather than a settings
    page: values are presented the way a message header presents them, a dark
    transcript panel shows the live SMTP handshake, provider health is read
    off signal bars, DNS authentication is shown as records with a pass seal,
    and templates are previewed as miniature letters.

    It borrows nothing from `_financial-settings.scss` or `_settings.scss`
    and overrides nothing in them.

    Contents
      1.  Tokens + shared pieces
      2.  Workspace hero + connection console
      3.  Sticky section navigation
      4.  Configuration panels + header rows
      5.  Mail provider rows
      6.  Sender identity cards
      7.  Template cards
      8.  Rules, queue and log rows
      9.  Authentication records
      10. Premium accordion
      11. Mail activity timeline
      12. Offcanvas, panel helpers and empty state
-----------------*/
/* ============================================================
   1. TOKENS + SHARED PIECES
   ============================================================ */
:root {
  --eml-border: var(--bs-border-color, #E9EDF4);
  --eml-border-strong: #EDF1F6;
  --eml-ok: #1ABE17;
  --eml-ok-soft: #E8F9E8;
  --eml-bad: #E82646;
  --eml-bad-soft: #FDE9ED;
  --eml-ink: #101828;
  --eml-ink-line: rgba(255, 255, 255, .09);
  --eml-ink-text: rgba(255, 255, 255, .68);
}

@media (prefers-reduced-motion: reduce) {
  [class*=eml-],
  [class*=eml-]::before,
  [class*=eml-]::after {
    animation: none !important;
    transition: none !important;
  }
}
