.aig-mono {
  font-family: var(--font-mono);
  font-size: 12.5px;
  letter-spacing: -0.01em;
}

.aig-lbl {
  display: block;
  margin: 0 0 6px;
  font-size: 10.5px;
  font-weight: 700;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--bs-secondary-color);
}

/* ---- status badges ----------------------------------------------------- */
.aig-badge {
  /* geometry, typography and surface come from the shared badge component */
}
.aig-badge i {
  font-size: 13px;
}
.aig-badge.is-on {
  background: var(--aig-ok-soft);
  border-color: rgba(26, 190, 23, 0.28);
  color: rgb(19.7746478873, 144.5070422535, 17.4929577465);
}
.aig-badge.is-warn {
  background: var(--tint-warning);
  border-color: rgba(234, 179, 0, 0.34);
  color: rgb(142.2, 108.7769230769, 0);
}
.aig-badge.is-stop {
  background: var(--aig-stop-soft);
  border-color: rgba(232, 38, 70, 0.26);
  color: var(--aig-stop);
}
.aig-badge.is-accent {
  background: var(--tint-primary);
  border-color: rgba(74, 0, 229, 0.2);
  color: var(--bs-primary);
}

/* a model reference, always in the machine face because it is an identifier */
.aig-chip {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 3px 9px;
  border-radius: 7px;
  background: var(--aig-model-soft);
  border: 1px solid rgba(2, 168, 181, 0.3);
  font-family: var(--font-mono);
  font-size: 11px;
  font-weight: 600;
  white-space: nowrap;
  color: rgb(1.2196721311, 102.4524590164, 110.3803278689);
}
.aig-chip i {
  font-size: 12px;
}
.aig-chip.is-plain {
  background: var(--bs-secondary-bg);
  border-color: var(--bs-border-color);
  color: var(--bs-emphasis-color);
}
.aig-chip.is-none {
  background: transparent;
  border-style: dashed;
  border-color: var(--aig-border-strong);
  color: var(--bs-secondary-color);
}

/* ============================================================
   2. CONFIGURATION HERO
   ============================================================ */
.aig-hero {
  position: relative;
  padding: 26px 28px;
  margin-bottom: 26px;
  border-radius: var(--radius);
  background: var(--bs-body-bg);
  border: 1px solid var(--bs-border-color);
  box-shadow: var(--shadow);
  overflow: hidden;
  /* a fine grid, the way a model console suggests a latent space without
     drawing a chart */
}
.aig-hero::before {
  content: "";
  position: absolute;
  inset: 0;
  background-image: linear-gradient(var(--bs-border-color) 1px, transparent 1px), linear-gradient(90deg, var(--bs-border-color) 1px, transparent 1px);
  background-size: 34px 34px;
  opacity: 0.5;
  mask-image: radial-gradient(120% 90% at 100% 0%, #000, transparent 62%);
  -webkit-mask-image: radial-gradient(120% 90% at 100% 0%, #000, transparent 62%);
  pointer-events: none;
}
.aig-hero > * {
  position: relative;
}
@media (max-width: 575.98px) {
  .aig-hero {
    padding: 20px;
  }
}

.aig-hero-top {
  display: flex;
  align-items: center;
  gap: 16px;
  flex-wrap: wrap;
}

.aig-hero-crest {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 54px;
  height: 54px;
  flex-shrink: 0;
  border-radius: 17px;
  background: var(--bs-primary);
  color: #fff;
  font-size: 26px;
  box-shadow: 0 8px 20px rgba(43, 22, 106, 0.3);
}

.aig-hero-title {
  margin: 0;
  font-size: 26px;
  font-weight: 700;
  line-height: 1.2;
  color: var(--bs-emphasis-color);
}
@media (max-width: 575.98px) {
  .aig-hero-title {
    font-size: 21px;
  }
}

.aig-hero-sub {
  margin: 4px 0 0;
  max-width: 66ch;
  font-size: 13.5px;
  line-height: 1.65;
  color: var(--bs-secondary-color);
}

/* the hero's facts, run along one rule and divided by hairlines */
.aig-hero-facts {
  display: flex;
  flex-wrap: wrap;
  margin-top: 22px;
  padding-top: 20px;
  border-top: 1px solid var(--bs-border-color);
}

.aig-hero-fact {
  flex: 1 1 0;
  min-width: 170px;
  padding: 0 20px;
}
.aig-hero-fact:first-child {
  padding-left: 0;
}
.aig-hero-fact + .aig-hero-fact {
  border-left: 1px solid var(--bs-border-color);
}
.aig-hero-fact span {
  display: block;
  font-size: 10.5px;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--bs-secondary-color);
}
.aig-hero-fact strong {
  display: flex;
  align-items: center;
  gap: 7px;
  margin-top: 4px;
  font-size: 14px;
  font-weight: 600;
  color: var(--bs-emphasis-color);
}
@media (max-width: 767.98px) {
  .aig-hero-fact {
    flex: 1 1 46%;
    padding: 10px 14px;
  }
  .aig-hero-fact:first-child {
    padding-left: 14px;
  }
  .aig-hero-fact + .aig-hero-fact {
    border-left: 0;
  }
}

.aig-hero-actions {
  display: flex;
  align-items: center;
  gap: 10px;
  flex-wrap: wrap;
  margin-top: 20px;
}

/* ============================================================
   3. STICKY SECTION NAVIGATION
   ============================================================ */
.aig-nav {
  position: sticky;
  top: calc(60px + 16px);
  max-height: calc(100vh - 60px - 32px);
  padding: 10px;
  border-radius: var(--radius);
  background: var(--bs-body-bg);
  border: 1px solid var(--bs-border-color);
  box-shadow: var(--shadow);
  overflow-y: auto;
  /* Bootstrap's `.nav` wraps; in a capped-height column that wraps
     overflow into a second column instead of scrolling. */
  flex-wrap: nowrap;
  overflow-x: hidden;
}
.aig-nav > * {
  flex-shrink: 0;
}
@media (max-width: 991.98px) {
  .aig-nav {
    position: static;
    max-height: none;
  }
}

.aig-nav-link {
  position: relative;
  display: flex;
  align-items: center;
  gap: 11px;
  width: 100%;
  padding: 9px 12px;
  border: 0;
  border-radius: var(--radius-sm);
  background: transparent;
  font-size: 13.5px;
  font-weight: 500;
  text-align: left;
  color: var(--bs-emphasis-color);
  transition: var(--transition);
}
.aig-nav-link > i {
  flex-shrink: 0;
  font-size: 17px;
  color: var(--bs-secondary-color);
  transition: var(--transition);
}
.aig-nav-link .aig-nav-txt {
  flex: 1 1 auto;
  min-width: 0;
}
.aig-nav-link .aig-nav-n {
  flex-shrink: 0;
  font-family: var(--font-mono);
  font-size: 10.5px;
  font-weight: 600;
  color: var(--bs-secondary-color);
}
.aig-nav-link:hover {
  background: var(--bs-secondary-bg);
}
.aig-nav-link {
  /* the active row is tinted and carries a short accent bar inside its
     own rounded edge, rather than a full-height border */
}
.aig-nav-link.active {
  background: var(--tint-primary);
  color: var(--bs-primary);
  font-weight: 600;
}
.aig-nav-link.active > i,
.aig-nav-link.active .aig-nav-n {
  color: var(--bs-primary);
}
.aig-nav-link.active::before {
  content: "";
  position: absolute;
  left: 4px;
  top: 12px;
  bottom: 12px;
  width: 3px;
  border-radius: 3px;
  background: var(--bs-primary);
}

.aig-nav-foot {
  margin-top: 10px;
  padding: 14px 12px 6px;
  border-top: 1px solid var(--bs-border-color);
}

/* ============================================================
   4. CONFIGURATION CARDS + SETTING ROWS
   ============================================================ */
.aig-card {
  display: flex;
  flex-direction: column;
  height: 100%;
  border-radius: var(--radius);
  background: var(--bs-body-bg);
  border: 1px solid var(--bs-border-color);
  transition: var(--transition);
  overflow: hidden;
}
.aig-card:hover {
  border-color: var(--aig-border-strong);
  box-shadow: var(--shadow-lift);
}

.aig-card-head {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 16px 18px 13px;
  border-bottom: 1px solid var(--bs-border-color);
}

.aig-card-ic {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 38px;
  height: 38px;
  flex-shrink: 0;
  border-radius: 12px;
  background: var(--tint-primary);
  color: var(--bs-primary);
  font-size: 19px;
}
.aig-card-ic.is-model {
  background: var(--aig-model-soft);
  color: rgb(1.2196721311, 102.4524590164, 110.3803278689);
}
.aig-card-ic.is-warn {
  background: var(--tint-warning);
  color: rgb(142.2, 108.7769230769, 0);
}
.aig-card-ic.is-stop {
  background: var(--aig-stop-soft);
  color: var(--aig-stop);
}

.aig-card-title {
  margin: 0;
  font-size: 14.5px;
  font-weight: 600;
  color: var(--bs-emphasis-color);
}
.aig-card-title + p {
  margin: 1px 0 0;
  font-size: 11.5px;
  color: var(--bs-secondary-color);
}

.aig-card-body {
  flex: 1 1 auto;
  padding: 4px 18px 14px;
}

.aig-card-foot {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  flex-wrap: wrap;
  padding: 11px 18px;
  background: var(--bs-secondary-bg);
  border-top: 1px solid var(--bs-border-color);
}

.aig-row {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  align-items: center;
  gap: 8px 14px;
  padding: 10px 0;
}
.aig-row + .aig-row {
  border-top: 1px solid var(--bs-border-color);
}
.aig-row .aig-row-key {
  min-width: 0;
  font-size: 13px;
  color: var(--bs-emphasis-color);
}
.aig-row .aig-row-key small {
  display: block;
  margin-top: 2px;
  font-size: 11.5px;
  line-height: 1.55;
  color: var(--bs-secondary-color);
}
.aig-row .aig-row-val {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  gap: 8px;
  font-size: 13px;
  font-weight: 600;
  color: var(--bs-emphasis-color);
}
@media (max-width: 575.98px) {
  .aig-row {
    grid-template-columns: minmax(0, 1fr);
  }
  .aig-row .aig-row-val {
    justify-content: flex-start;
  }
}

.aig-input,
.aig-select {
  min-width: 148px;
  padding: 6px 11px;
  border-radius: var(--radius-sm);
  background-color: var(--bs-body-bg);
  border: 1px solid var(--bs-border-color);
  font-size: 13px;
  font-weight: 400;
  color: var(--bs-emphasis-color);
  transition: var(--transition);
}
.aig-input:focus,
.aig-select:focus {
  border-color: var(--bs-primary);
  box-shadow: 0 0 0 3px var(--tint-primary);
  outline: 0;
}
@media (max-width: 575.98px) {
  .aig-input,
  .aig-select {
    min-width: 0;
    width: 100%;
  }
}

.aig-secret {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  padding: 5px 11px;
  border-radius: var(--radius-sm);
  background: var(--bs-secondary-bg);
  border: 1px dashed var(--aig-border-strong);
  font-family: var(--font-mono);
  font-size: 12px;
  color: var(--bs-emphasis-color);
}
.aig-secret i {
  font-size: 14px;
  color: var(--bs-secondary-color);
}

/* ============================================================
   5. PROVIDER CARDS
   The endpoint is carried on a dark strip at the head, because a
   provider is identified by where it is reached, not by its name.
   ============================================================ */
.aig-prov {
  display: flex;
  flex-direction: column;
  height: 100%;
  border-radius: var(--radius);
  background: var(--bs-body-bg);
  border: 1px solid var(--bs-border-color);
  transition: var(--transition);
  overflow: hidden;
}
.aig-prov:hover {
  border-color: var(--aig-border-strong);
  box-shadow: var(--shadow-lift);
}
.aig-prov.is-default {
  border-color: var(--bs-primary);
  box-shadow: 0 0 0 3px var(--tint-primary);
}
.aig-prov.is-off .aig-prov-bar,
.aig-prov.is-off .aig-prov-name {
  opacity: 0.62;
}

.aig-prov-bar {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 8px 14px;
  background: var(--bs-emphasis-color);
  font-family: var(--font-mono);
  font-size: 10.5px;
  color: rgba(255, 255, 255, 0.68);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.aig-prov-bar i {
  flex-shrink: 0;
  font-size: 13px;
  color: rgba(255, 255, 255, 0.4);
}

.aig-prov-body {
  flex: 1 1 auto;
  display: flex;
  flex-direction: column;
  gap: 12px;
  padding: 16px;
}

.aig-prov-top {
  display: flex;
  align-items: flex-start;
  gap: 12px;
}

.aig-prov-mark {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 42px;
  height: 42px;
  flex-shrink: 0;
  border-radius: 13px;
  background: var(--bs-secondary-bg);
  border: 1px solid var(--bs-border-color);
  font-size: 20px;
  color: var(--bs-emphasis-color);
}

.aig-prov-name {
  margin: 0;
  font-size: 14.5px;
  font-weight: 600;
  color: var(--bs-emphasis-color);
}
.aig-prov-name + p {
  margin: 2px 0 0;
  font-size: 11.5px;
  line-height: 1.55;
  color: var(--bs-secondary-color);
}

/* the models this provider makes available, as chips */
.aig-prov-models {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
}

.aig-prov-foot {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  margin-top: auto;
  padding-top: 12px;
  border-top: 1px solid var(--bs-border-color);
}

/* ============================================================
   6. MODEL PLATES + CONTEXT RULER
   ============================================================ */
.aig-model {
  display: flex;
  flex-direction: column;
  height: 100%;
  border-radius: var(--radius);
  background: var(--bs-body-bg);
  border: 1px solid var(--bs-border-color);
  transition: var(--transition);
  overflow: hidden;
}
.aig-model:hover {
  border-color: var(--aig-border-strong);
  box-shadow: var(--shadow-lift);
}
.aig-model.is-off {
  background: var(--bs-secondary-bg);
}
.aig-model.is-off .aig-model-id {
  opacity: 0.66;
}

.aig-model-head {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 14px 16px 12px;
}

.aig-model-id {
  margin: 0;
  font-family: var(--font-mono);
  font-size: 14px;
  font-weight: 600;
  letter-spacing: -0.01em;
  color: var(--bs-emphasis-color);
  word-break: break-all;
}
.aig-model-id + p {
  margin: 2px 0 0;
  font-size: 11.5px;
  color: var(--bs-secondary-color);
}

.aig-model-body {
  flex: 1 1 auto;
  padding: 0 16px 12px;
}

/* ---- context ruler ----------------------------------------------------
   A context window is a length, so it is drawn as one: a measured track
   with the reserved portion filled and the scale marked beneath. */
.aig-ruler .aig-ruler-track {
  position: relative;
  height: 10px;
  border-radius: 4px;
  background: var(--bs-tertiary-bg);
  overflow: hidden;
  /* what a typical request actually occupies */
}
.aig-ruler .aig-ruler-track span {
  position: absolute;
  inset: 0 auto 0 0;
  width: calc(var(--p, 0) * 1%);
  background: var(--aig-model);
}
.aig-ruler .aig-ruler-track {
  /* the reserve kept for the response */
}
.aig-ruler .aig-ruler-track em {
  position: absolute;
  top: 0;
  bottom: 0;
  left: calc(var(--p, 0) * 1%);
  width: calc(var(--q, 0) * 1%);
  background: repeating-linear-gradient(45deg, rgba(2, 168, 181, 0.34) 0 4px, transparent 4px 8px);
}
.aig-ruler .aig-ruler-scale {
  display: flex;
  justify-content: space-between;
  margin-top: 5px;
  font-family: var(--font-mono);
  font-size: 10px;
  color: var(--bs-secondary-color);
}
.aig-ruler .aig-ruler-meta {
  margin-top: 6px;
  font-size: 11.5px;
  line-height: 1.55;
  color: var(--bs-secondary-color);
}
.aig-ruler .aig-ruler-meta b {
  font-family: var(--font-mono);
  font-weight: 600;
  color: var(--bs-emphasis-color);
}

.aig-model-foot {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  margin-top: auto;
  padding: 10px 16px;
  background: var(--bs-secondary-bg);
  border-top: 1px solid var(--bs-border-color);
}

/* ============================================================
   7. SAMPLING DIALS + TOKEN COLUMN
   ============================================================ */
/* a parameter with a marked position on its range, not a slider control */
.aig-dial + .aig-dial {
  margin-top: 14px;
}
.aig-dial .aig-dial-top {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 10px;
  margin-bottom: 6px;
}
.aig-dial .aig-dial-top span {
  font-size: 12px;
  color: var(--bs-secondary-color);
}
.aig-dial .aig-dial-top b {
  font-family: var(--font-mono);
  font-size: 12.5px;
  font-weight: 600;
  color: var(--bs-emphasis-color);
}
.aig-dial .aig-dial-track {
  position: relative;
  height: 4px;
  border-radius: 999px;
  background: var(--bs-tertiary-bg);
  /* the marker */
}
.aig-dial .aig-dial-track i {
  position: absolute;
  top: 50%;
  left: calc(var(--p, 0) * 1%);
  width: 13px;
  height: 13px;
  margin: -6.5px 0 0 -6.5px;
  border-radius: 50%;
  background: var(--bs-body-bg);
  border: 3px solid var(--bs-primary);
}
.aig-dial .aig-dial-track {
  /* the travelled part of the range */
}
.aig-dial .aig-dial-track::before {
  content: "";
  position: absolute;
  inset: 0 auto 0 0;
  width: calc(var(--p, 0) * 1%);
  border-radius: inherit;
  background: var(--bs-primary);
}
.aig-dial .aig-dial-ends {
  display: flex;
  justify-content: space-between;
  margin-top: 5px;
  font-family: var(--font-mono);
  font-size: 10px;
  color: var(--bs-secondary-color);
}

/* ---- token column -----------------------------------------------------
   A monthly budget read vertically, which keeps the figures beside it and
   makes an overspend obvious as height rather than as a number. */
.aig-budget {
  display: flex;
  align-items: flex-end;
  gap: 16px;
}

.aig-column {
  position: relative;
  flex-shrink: 0;
  width: 46px;
  height: 132px;
  border-radius: 8px;
  background: var(--bs-tertiary-bg);
  overflow: hidden;
  /* used */
}
.aig-column span {
  position: absolute;
  inset: auto 0 0 0;
  height: calc(var(--p, 0) * 1%);
  background: var(--bs-primary);
}
.aig-column {
  /* the ceiling mark */
}
.aig-column::after {
  content: "";
  position: absolute;
  left: 0;
  right: 0;
  bottom: calc(var(--q, 100) * 1%);
  height: 2px;
  background: var(--aig-stop);
}

.aig-budget-facts {
  flex: 1 1 auto;
  min-width: 0;
}
.aig-budget-facts div {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 10px;
  padding: 5px 0;
  font-size: 12.5px;
  color: var(--bs-secondary-color);
}
.aig-budget-facts div + div {
  border-top: 1px solid var(--bs-border-color);
}
.aig-budget-facts div b {
  font-family: var(--font-mono);
  font-weight: 600;
  color: var(--bs-emphasis-color);
}

/* ============================================================
   8. FEATURE ROUTING ROWS
   Which feature is answered by which model, and who may see it.
   ============================================================ */
.aig-feat {
  display: grid;
  grid-template-columns: 42px minmax(0, 1.3fr) minmax(0, 1fr) auto;
  align-items: center;
  gap: 16px;
  padding: 14px 16px;
  border-radius: var(--radius);
  background: var(--bs-body-bg);
  border: 1px solid var(--bs-border-color);
  transition: var(--transition);
}
.aig-feat + .aig-feat {
  margin-top: 9px;
}
.aig-feat:hover {
  border-color: var(--aig-border-strong);
  box-shadow: var(--shadow);
}
.aig-feat.is-off {
  background: var(--bs-secondary-bg);
}
.aig-feat.is-off .aig-feat-body {
  opacity: 0.66;
}
@media (max-width: 1199.98px) {
  .aig-feat {
    grid-template-columns: 42px minmax(0, 1fr) auto;
  }
  .aig-feat .aig-feat-route {
    grid-column: 2/-1;
  }
}
@media (max-width: 575.98px) {
  .aig-feat {
    grid-template-columns: 42px minmax(0, 1fr);
  }
  .aig-feat .aig-feat-act {
    grid-column: 2/-1;
    justify-content: flex-start;
  }
}

.aig-feat-ic {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 42px;
  height: 42px;
  border-radius: 13px;
  background: var(--tint-primary);
  color: var(--bs-primary);
  font-size: 20px;
}

.aig-feat-body {
  min-width: 0;
}
.aig-feat-body strong {
  display: block;
  font-size: 13.5px;
  font-weight: 600;
  color: var(--bs-emphasis-color);
}
.aig-feat-body p {
  margin: 2px 0 0;
  font-size: 12px;
  line-height: 1.55;
  color: var(--bs-secondary-color);
}

/* the routing itself, read as an arrow into a named model */
.aig-feat-route {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-wrap: wrap;
  min-width: 0;
}
.aig-feat-route > i {
  font-size: 16px;
  color: var(--bs-secondary-color);
}

.aig-feat-act {
  display: flex;
  align-items: center;
  gap: 10px;
  justify-content: flex-end;
}

/* ============================================================
   9. PROMPT TEMPLATES
   Shown as the text they are, with the variables picked out and
   the system instruction separated from the task.
   ============================================================ */
.aig-prompt {
  display: flex;
  flex-direction: column;
  height: 100%;
  border-radius: var(--radius);
  background: var(--bs-body-bg);
  border: 1px solid var(--bs-border-color);
  transition: var(--transition);
  overflow: hidden;
}
.aig-prompt:hover {
  border-color: var(--aig-border-strong);
  box-shadow: var(--shadow-lift);
}
.aig-prompt.is-draft .aig-prompt-text {
  opacity: 0.68;
}

.aig-prompt-head {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 14px 16px 11px;
}

.aig-prompt-name {
  margin: 0;
  font-size: 13.5px;
  font-weight: 600;
  color: var(--bs-emphasis-color);
}
.aig-prompt-name + p {
  margin: 1px 0 0;
  font-size: 11.5px;
  color: var(--bs-secondary-color);
}

/* the prompt body, on a recessed surface with a marker rule */
.aig-prompt-text {
  margin: 0 16px;
  padding: 12px 14px;
  border-radius: var(--radius-sm);
  background: var(--bs-secondary-bg);
  border-left: 3px solid var(--bs-primary);
  font-size: 12.5px;
  line-height: 1.7;
  color: var(--bs-emphasis-color);
  white-space: pre-line;
}
.aig-prompt-text + .aig-prompt-text {
  margin-top: 8px;
  border-left-color: var(--aig-model);
}
.aig-prompt-text {
  /* the role this segment plays */
}
.aig-prompt-text .aig-prompt-role {
  display: block;
  margin-bottom: 5px;
  font-family: var(--font-mono);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--bs-secondary-color);
}
.aig-prompt-text {
  /* a variable filled in at run time */
}
.aig-prompt-text var {
  padding: 0 4px;
  border-radius: 4px;
  background: var(--tint-primary);
  font-family: var(--font-mono);
  font-size: 11.5px;
  font-style: normal;
  color: var(--bs-primary);
}

.aig-prompt-foot {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  /* `auto` rather than a fixed gap, so the footer sits on the bottom edge
     however short the prompt above it is */
  margin-top: auto;
  padding: 11px 16px;
  background: var(--bs-secondary-bg);
  border-top: 1px solid var(--bs-border-color);
}

/* the space between the last prompt segment and the footer */
.aig-prompt-text:last-of-type {
  margin-bottom: 14px;
}

/* ============================================================
   10. AUTOMATION ROWS + PERMISSION MATRIX
   ============================================================ */
.aig-auto {
  display: grid;
  grid-template-columns: 8px minmax(0, 1fr) auto;
  align-items: center;
  gap: 14px;
  padding: 13px 16px;
  border-radius: var(--radius-sm);
  background: var(--bs-body-bg);
  border: 1px solid var(--bs-border-color);
}
.aig-auto + .aig-auto {
  margin-top: 8px;
}
.aig-auto {
  /* a rib carrying whether the automation ran cleanly */
}
.aig-auto::before {
  content: "";
  width: 4px;
  height: 28px;
  border-radius: 3px;
  background: var(--bs-success);
}
.aig-auto.is-warn::before {
  background: var(--bs-warning);
}
.aig-auto.is-stop::before {
  background: var(--aig-stop);
}
.aig-auto.is-off {
  background: var(--bs-secondary-bg);
}
.aig-auto.is-off::before {
  background: var(--aig-border-strong);
}
.aig-auto.is-off .aig-auto-body {
  opacity: 0.68;
}
@media (max-width: 767.98px) {
  .aig-auto {
    grid-template-columns: 8px minmax(0, 1fr);
    row-gap: 10px;
  }
  .aig-auto .aig-auto-side {
    grid-column: 2/-1;
    justify-content: flex-start;
  }
}

.aig-auto-body {
  min-width: 0;
}
.aig-auto-body strong {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-wrap: wrap;
  font-size: 13px;
  font-weight: 600;
  color: var(--bs-emphasis-color);
}
.aig-auto-body span {
  display: block;
  margin-top: 2px;
  font-size: 11.5px;
  line-height: 1.55;
  color: var(--bs-secondary-color);
}

.aig-auto-side {
  display: flex;
  align-items: center;
  gap: 10px;
  justify-content: flex-end;
  flex-wrap: wrap;
}

/* ---- permission matrix ------------------------------------------------- */
.aig-perm {
  display: grid;
  grid-template-columns: minmax(0, 1fr) repeat(4, 68px);
  align-items: center;
  gap: 8px;
  padding: 10px 0;
}
.aig-perm + .aig-perm {
  border-top: 1px solid var(--bs-border-color);
}
.aig-perm.is-head {
  padding-bottom: 8px;
  border-bottom: 2px solid var(--bs-border-color);
}
.aig-perm.is-head span {
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.07em;
  text-transform: uppercase;
  text-align: center;
  color: var(--bs-secondary-color);
}
.aig-perm.is-head span:first-child {
  text-align: left;
}
.aig-perm .aig-perm-name {
  min-width: 0;
  font-size: 13px;
  color: var(--bs-emphasis-color);
}
.aig-perm .aig-perm-name small {
  display: block;
  margin-top: 2px;
  font-size: 11.5px;
  color: var(--bs-secondary-color);
}
@media (max-width: 767.98px) {
  .aig-perm {
    grid-template-columns: minmax(0, 1fr) repeat(4, 1fr);
    gap: 4px;
  }
}

.aig-dot {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 26px;
  height: 26px;
  margin: 0 auto;
  border-radius: 8px;
  background: var(--bs-secondary-bg);
  border: 1px solid var(--bs-border-color);
  font-size: 15px;
  color: var(--aig-border-strong);
}
.aig-dot.is-yes {
  background: var(--aig-ok-soft);
  border-color: rgba(26, 190, 23, 0.28);
  color: rgb(19.7746478873, 144.5070422535, 17.4929577465);
}
.aig-dot.is-limited {
  background: var(--tint-warning);
  border-color: rgba(234, 179, 0, 0.32);
  color: rgb(142.2, 108.7769230769, 0);
}

/* ============================================================
   11. PREMIUM ACCORDION + ACTIVITY FLOW
   ============================================================ */
.aig-acc {
  border-radius: var(--radius);
  border: 1px solid var(--bs-border-color);
  overflow: hidden;
}
.aig-acc .accordion-item {
  border: 0;
  background: var(--bs-body-bg);
}
.aig-acc .accordion-item + .accordion-item {
  border-top: 1px solid var(--bs-border-color);
}
.aig-acc .accordion-button {
  gap: 11px;
  padding: 15px 18px;
  background: var(--bs-body-bg);
  font-size: 13.5px;
  font-weight: 600;
  color: var(--bs-emphasis-color);
  box-shadow: none;
}
.aig-acc .accordion-button::after {
  margin-left: 0;
}
.aig-acc .accordion-button:not(.collapsed) {
  background: var(--bs-primary);
  color: #fff;
}
.aig-acc .accordion-button:not(.collapsed)::after {
  filter: invert(1) grayscale(1) brightness(2);
}
.aig-acc .accordion-button:focus {
  box-shadow: 0 0 0 3px var(--tint-primary);
}
.aig-acc .accordion-button i {
  font-size: 17px;
}
.aig-acc .aig-acc-spacer {
  margin-left: auto;
}
.aig-acc .accordion-body {
  padding: 6px 18px 18px;
}

/* ---- activity flow ----------------------------------------------------
   A rule runs horizontally through the middle of the row and the stages
   sit alternately above and below it, which reads as a signal path. */
.aig-flow {
  position: relative;
  display: flex;
  gap: 14px;
  padding: 8px 4px;
  overflow-x: auto;
  scrollbar-width: thin;
  /* the rule itself */
}
.aig-flow::before {
  content: "";
  position: absolute;
  left: 0;
  right: 0;
  top: 50%;
  height: 2px;
  margin-top: -1px;
  background: var(--bs-tertiary-bg);
}

.aig-flow-stage {
  position: relative;
  flex: 1 0 232px;
  padding: 106px 0 0;
  /* the node on the rule */
}
.aig-flow-stage::after {
  content: "";
  position: absolute;
  left: 22px;
  top: 50%;
  width: 13px;
  height: 13px;
  margin-top: -6.5px;
  border-radius: 50%;
  background: var(--bs-body-bg);
  border: 3px solid var(--bs-tertiary-bg);
  z-index: 1;
}
.aig-flow-stage.is-done::after {
  background: var(--bs-success);
  border-color: var(--bs-success);
}
.aig-flow-stage.is-current::after {
  border-color: var(--bs-primary);
  box-shadow: 0 0 0 4px var(--tint-primary);
}
.aig-flow-stage {
  /* every second stage lifts above the rule instead of hanging below it */
}
.aig-flow-stage:nth-child(even) {
  padding: 0 0 106px;
}
@media (max-width: 991.98px) {
  .aig-flow-stage {
    padding: 106px 0 0;
  }
  .aig-flow-stage:nth-child(even) {
    padding: 106px 0 0;
  }
}

.aig-flow-card {
  padding: 13px 15px;
  border-radius: var(--radius);
  background: var(--bs-body-bg);
  border: 1px solid var(--bs-border-color);
  box-shadow: var(--shadow);
}
.aig-flow-card h6 {
  margin: 0;
  font-size: 13px;
  font-weight: 600;
  color: var(--bs-emphasis-color);
}
.aig-flow-card time {
  display: block;
  margin-top: 2px;
  font-family: var(--font-mono);
  font-size: 10.5px;
  color: var(--bs-secondary-color);
}
.aig-flow-card p {
  margin: 6px 0 0;
  font-size: 12px;
  line-height: 1.6;
  color: var(--bs-secondary-color);
}

/* ============================================================
   12. RECOMMENDATION CARDS
   The heading sits in a pill that straddles the top edge.
   ============================================================ */
.aig-rec {
  position: relative;
  display: flex;
  flex-direction: column;
  gap: 10px;
  height: 100%;
  margin-top: 14px;
  padding: 26px 18px 18px;
  border-radius: var(--radius);
  background: var(--bs-body-bg);
  border: 1px solid var(--bs-border-color);
  transition: var(--transition);
}
.aig-rec:hover {
  box-shadow: var(--shadow-lift);
}

.aig-rec-pill {
  position: absolute;
  left: 18px;
  top: -14px;
  display: inline-flex;
  align-items: center;
  gap: 6px;
  height: 28px;
  padding: 0 13px;
  border-radius: 999px;
  background: var(--bs-primary);
  font-size: 10.5px;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: #fff;
}
.aig-rec-pill i {
  font-size: 13px;
}
.aig-rec-pill.is-model {
  background: rgb(1.4426229508, 121.1803278689, 130.5573770492);
}
.aig-rec-pill.is-warn {
  background: rgb(172.8, 132.1846153846, 0);
}
.aig-rec-pill.is-ok {
  background: rgb(22.2647887324, 162.7042253521, 19.6957746479);
}

.aig-rec-title {
  margin: 0;
  font-size: 14px;
  font-weight: 600;
  color: var(--bs-emphasis-color);
}

.aig-rec-txt {
  margin: 0;
  font-size: 12.5px;
  line-height: 1.65;
  color: var(--bs-secondary-color);
}

.aig-rec-foot {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  margin-top: auto;
  padding-top: 12px;
  border-top: 1px solid var(--bs-border-color);
}

/* ============================================================
   13. OFFCANVAS, PANEL HELPERS, EMPTY STATE
   ============================================================ */
/* The theme sets `.offcanvas.offcanvas-end { width: auto !important }`; the
   workspace has to match on three classes to beat it. */
.offcanvas.offcanvas-end.aig-canvas {
  width: 88% !important;
  max-width: 1180px !important;
}

.aig-canvas-head {
  display: flex;
  align-items: center;
  gap: 14px;
  padding: 20px 24px;
  background: var(--bs-primary);
  color: #fff;
}
.aig-canvas-head .aig-card-ic {
  background: rgba(255, 255, 255, 0.14);
  color: #fff;
}
.aig-canvas-head .offcanvas-title {
  color: #fff;
}
.aig-canvas-head p {
  color: rgba(255, 255, 255, 0.6);
}
.aig-canvas-head .btn-close {
  filter: invert(1) grayscale(1);
  opacity: 0.7;
}

.aig-canvas-body {
  padding: 22px 24px 30px;
}

.aig-sect + .aig-sect {
  margin-top: 24px;
  padding-top: 20px;
  border-top: 1px solid var(--bs-border-color);
}

.aig-sect-title {
  display: flex;
  align-items: center;
  gap: 8px;
  margin: 0 0 13px;
  font-size: 12px;
  font-weight: 700;
  letter-spacing: 0.09em;
  text-transform: uppercase;
  color: var(--bs-emphasis-color);
}
.aig-sect-title i {
  font-size: 16px;
  color: var(--bs-primary);
}

.aig-check {
  display: flex;
  align-items: flex-start;
  gap: 10px;
  padding: 9px 0;
  font-size: 13px;
  line-height: 1.6;
  color: var(--bs-emphasis-color);
}
.aig-check + .aig-check {
  border-top: 1px solid var(--bs-border-color);
}
.aig-check > i {
  flex-shrink: 0;
  margin-top: 1px;
  font-size: 16px;
  color: rgb(19.7746478873, 144.5070422535, 17.4929577465);
}
.aig-check.is-warn > i {
  color: rgb(142.2, 108.7769230769, 0);
}
.aig-check.is-stop > i {
  color: var(--aig-stop);
}
.aig-check span {
  display: block;
  font-size: 12px;
  color: var(--bs-secondary-color);
}

.aig-audit {
  display: grid;
  grid-template-columns: 150px minmax(0, 1fr);
  gap: 14px;
  padding: 11px 0;
}
.aig-audit + .aig-audit {
  border-top: 1px solid var(--bs-border-color);
}
@media (max-width: 575.98px) {
  .aig-audit {
    grid-template-columns: minmax(0, 1fr);
    gap: 3px;
  }
}

.aig-audit-when {
  font-family: var(--font-mono);
  font-size: 11.5px;
  color: var(--bs-secondary-color);
}
.aig-audit-when strong {
  display: block;
  font-size: 12px;
  font-weight: 600;
  color: var(--bs-emphasis-color);
}

.aig-audit-what {
  font-size: 13px;
  line-height: 1.6;
  color: var(--bs-emphasis-color);
}
.aig-audit-what span {
  display: block;
  margin-top: 2px;
  font-size: 12px;
  color: var(--bs-secondary-color);
}

/* ---- empty state ------------------------------------------------------- */
.aig-empty {
  display: flex;
  flex-direction: column;
  align-items: center;
  text-align: center;
  gap: 5px;
  padding: 38px 24px;
  border-radius: var(--radius);
  background: var(--bs-secondary-bg);
  border: 1px dashed var(--aig-border-strong);
}
.aig-empty i {
  font-size: 30px;
  color: var(--bs-secondary-color);
  opacity: 0.8;
}
.aig-empty h6 {
  margin: 8px 0 0;
  font-size: 14px;
  font-weight: 600;
  color: var(--bs-emphasis-color);
}
.aig-empty p {
  margin: 0;
  max-width: 48ch;
  font-size: 12.5px;
  line-height: 1.6;
  color: var(--bs-secondary-color);
}
.aig-empty .btn {
  margin-top: 10px;
}

/*===== custom fields =====*/
/*-----------------
	Custom Fields — dynamic form configuration components

	A shared vocabulary for the Custom Fields & Dynamic Form Configuration
	Center: the reusable fields themselves, the modules they are bound to,
	the validation that guards them, the layout that arranges them and the
	rules that make them move. Class prefix `cfx-`.

	The visual language is a low-code field builder, not a settings form.
	The pieces are the ones this subject needs and no other page does: a
	field plate carrying its type glyph and its machine name in monospace,
	a module plate whose field budget is drawn as a split required/optional
	bar, a live preview surface drawn on a dotted canvas, validation stated
	as rule chips rather than switches, and a rule card written as
	when/then.

	It borrows nothing from `_settings.scss` or `_ai-settings.scss` — those
	govern option lists; this one governs a schema.

	Contents
	  1.  Tokens + shared pieces
	  2.  Builder hero
	  3.  Sticky module navigation
	  4.  Module cards
	  5.  Field cards + type glyphs
	  6.  Field preview canvas
	  7.  Validation cards + rule chips
	  8.  Layout / section cards
	  9.  Dynamic rule cards (when → then)
	  10. Activity timeline
	  11. Template cards
	  12. Insight cards
	  13. Premium accordion + tabs
	  14. Offcanvas workspace, modals, empty state
-----------------*/
/* ============================================================
   1. TOKENS + SHARED PIECES
   ============================================================ */
:root {
  /* A cool slate-cyan, mixed rather than taken straight, so the builder
     reads as a schema tool and not as another blue settings page. */
  --field-accent: rgb(13.4, 120.88, 140.72);
  --field-accent-line: rgb(189.22, 232.38, 235.76);
  --field-req: #E82646;
  --field-req-soft: #FDE9ED;
  --field-opt: #0F65CD;
  --field-opt-soft: #E7F1FC;
  --field-ok: #1ABE17;
  --field-ok-soft: #E8F9E8;
  --field-draft: #4A00E5;
  --field-draft-soft: rgb(236.9, 229.5, 252.4);
  --field-grid: rgb(228.24, 229.68, 233.4);
}

[data-bs-theme=dark] {
  --field-accent-line: rgba(2, 168, 181, .34);
  --field-grid: rgba(255, 255, 255, .14);
}

/* Small eyebrow label used above every section heading. */
.field-metric-label {
  display: block;
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--bs-secondary-color);
  margin-bottom: 4px;
}

/* Machine name of a field / module — always monospace, always selectable. */
.field-key {
  font-family: var(--font-mono);
  font-size: 11.5px;
  color: var(--bs-secondary-color);
  background: var(--bs-secondary-bg);
  border: 1px solid var(--bs-border-color);
  border-radius: 6px;
  padding: 1px 6px;
  display: inline-block;
  max-width: 100%;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  vertical-align: middle;
}

/* Status / meta badge. Modifiers colour it; the base is neutral. */
.field-status-badge {
  /* geometry, typography and surface come from the shared badge component */
}
.field-status-badge i {
  font-size: 12px;
}
.field-status-badge.is-published {
  background: var(--field-ok-soft);
  color: var(--bs-success);
  border-color: transparent;
}
.field-status-badge.is-draft {
  background: var(--field-draft-soft);
  color: var(--field-draft);
  border-color: transparent;
}
.field-status-badge.is-required {
  background: var(--field-req-soft);
  color: var(--field-req);
  border-color: transparent;
}
.field-status-badge.is-optional {
  background: var(--field-opt-soft);
  color: var(--field-opt);
  border-color: transparent;
}
.field-status-badge.is-warn {
  background: var(--tint-warning);
  color: rgb(172.8, 132.1846153846, 0);
  border-color: transparent;
}
.field-status-badge.is-accent {
  background: var(--tint-primary);
  color: var(--bs-primary);
  border-color: transparent;
}
.field-status-badge.is-archived {
  background: var(--bs-secondary-bg);
  color: var(--bs-secondary-color);
  border-style: dashed;
}

/* Field-type badge — carries the glyph of the input it produces. */
.type {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  font-size: 11px;
  font-weight: 600;
  padding: 2px 9px 2px 4px;
  border-radius: 999px;
  background: var(--tint-primary);
  color: var(--bs-primary);
  white-space: nowrap;
}
.type i {
  font-size: 12px;
  width: 17px;
  height: 17px;
  border-radius: 50%;
  background: var(--bs-body-bg);
  display: inline-flex;
  align-items: center;
  justify-content: center;
}

/* A split meter: required portion first, optional portion after. */
.field-progress-meter {
  height: 6px;
  border-radius: 999px;
  background: var(--track);
  display: flex;
  overflow: hidden;
}
.field-progress-meter span {
  display: block;
  height: 100%;
}
.field-progress-meter span:first-child {
  background: var(--field-req);
}
.field-progress-meter span:last-child {
  background: var(--field-opt);
}

/* Percentage helpers for the meter and coverage bars. */
/* ============================================================
   2. BUILDER HERO
   ============================================================ */
.hero {
  position: relative;
  overflow: hidden;
  border: 1px solid var(--bs-border-color);
  border-radius: var(--radius);
  background: radial-gradient(120% 160% at 100% 0%, var(--tint-primary) 0%, transparent 58%), var(--bs-body-bg);
  padding: 26px 26px 22px;
  margin-bottom: 24px;
  box-shadow: var(--shadow);
  /* The dotted canvas is the signature of this page — a field grid the
     builder snaps to, drawn faintly behind the hero content. */
}
.hero::before {
  content: "";
  position: absolute;
  inset: 0;
  background-image: radial-gradient(var(--field-grid) 1px, transparent 1px);
  background-size: 18px 18px;
  opacity: 0.35;
  pointer-events: none;
}
.hero > * {
  position: relative;
}

.hero-top {
  display: flex;
  align-items: flex-start;
  gap: 16px;
  flex-wrap: wrap;
}

.hero-crest {
  width: 54px;
  height: 54px;
  flex-shrink: 0;
  border-radius: var(--radius);
  background: var(--bs-primary);
  color: #fff;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 26px;
  box-shadow: 0 8px 20px rgba(2, 168, 181, 0.28);
}

.hero-title {
  font-size: 26px;
  font-weight: 700;
  color: var(--bs-emphasis-color);
  line-height: 1.25;
  margin-bottom: 6px;
}

.hero-subtitle {
  font-size: 13.5px;
  color: var(--bs-secondary-color);
  max-width: 74ch;
  margin-bottom: 0;
}

/* Hero facts read as a schema summary strip, not as KPI cards. */
.hero-facts {
  display: flex;
  flex-wrap: wrap;
  gap: 0;
  margin-top: 22px;
  border: 1px solid var(--bs-border-color);
  border-radius: var(--radius);
  background: var(--bs-body-bg);
  overflow: hidden;
}

.hero-fact {
  flex: 1 1 168px;
  min-width: 150px;
  padding: 13px 16px;
  border-right: 1px solid var(--bs-border-color);
}
.hero-fact:last-child {
  border-right: 0;
}
.hero-fact span {
  display: block;
  font-size: 11px;
  letter-spacing: 0.07em;
  text-transform: uppercase;
  color: var(--bs-secondary-color);
  margin-bottom: 4px;
}
.hero-fact strong {
  display: flex;
  align-items: center;
  gap: 7px;
  flex-wrap: wrap;
  font-size: 16px;
  font-weight: 700;
  color: var(--bs-emphasis-color);
  line-height: 1.3;
}
.hero-fact small {
  font-size: 12px;
  font-weight: 400;
  color: var(--bs-secondary-color);
}

.hero-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin-top: 18px;
}

/* ============================================================
   3. STICKY MODULE NAVIGATION
   ============================================================ */
.field-navigation {
  position: sticky;
  top: 76px;
  border: 1px solid var(--bs-border-color);
  border-radius: var(--radius);
  background: var(--bs-body-bg);
  padding: 8px;
  box-shadow: var(--shadow);
  max-height: calc(100vh - 100px);
  overflow-y: auto;
}
.field-navigation::-webkit-scrollbar {
  width: 5px;
}
.field-navigation::-webkit-scrollbar-thumb {
  background: var(--track);
  border-radius: 999px;
}

.navigation-header {
  font-size: 10.5px;
  font-weight: 600;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--bs-secondary-color);
  padding: 10px 10px 6px;
}

.field-navigation-link {
  display: flex;
  align-items: center;
  gap: 10px;
  width: 100%;
  text-align: left;
  border: 0;
  background: transparent;
  color: var(--bs-emphasis-color);
  font-size: 13.5px;
  font-weight: 500;
  padding: 9px 11px;
  border-radius: var(--radius-sm);
  transition: var(--transition);
}
.field-navigation-link > i {
  font-size: 17px;
  color: var(--bs-secondary-color);
  flex-shrink: 0;
  transition: var(--transition);
}
.field-navigation-link .navigation-text {
  flex: 1 1 auto;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.field-navigation-link .navigation-n {
  font-size: 11px;
  font-weight: 600;
  color: var(--bs-secondary-color);
  background: var(--bs-secondary-bg);
  border-radius: 999px;
  padding: 1px 7px;
  flex-shrink: 0;
}
.field-navigation-link:hover {
  background: var(--bs-secondary-bg);
}
.field-navigation-link.active {
  background: var(--bs-primary);
  color: #fff;
}
.field-navigation-link.active > i,
.field-navigation-link.active .navigation-n {
  color: #fff;
}
.field-navigation-link.active .navigation-n {
  background: rgba(255, 255, 255, 0.18);
}

.navigation-footer {
  border-top: 1px solid var(--bs-border-color);
  margin-top: 8px;
  padding: 14px 11px 6px;
}

/* Coverage bar in the nav footer. */
.cover {
  height: 8px;
  border-radius: 999px;
  background: var(--track);
  overflow: hidden;
  margin-bottom: 8px;
}
.cover span {
  display: block;
  height: 100%;
  border-radius: 999px;
  background: linear-gradient(90deg, var(--bs-primary), var(--field-accent-line));
}

/* ============================================================
   4. MODULE CARDS
   ============================================================ */
.module {
  position: relative;
  height: 100%;
  display: flex;
  flex-direction: column;
  border: 1px solid var(--bs-border-color);
  border-radius: var(--radius);
  background: var(--bs-body-bg);
  box-shadow: var(--shadow);
  transition: var(--transition);
  overflow: hidden;
}
.module:hover {
  border-color: var(--field-accent-line);
  box-shadow: var(--shadow-lift);
  transform: translateY(-2px);
}

.module-header {
  display: flex;
  align-items: flex-start;
  gap: 12px;
  padding: 16px 16px 12px;
}

.module-icon {
  width: 42px;
  height: 42px;
  flex-shrink: 0;
  border-radius: var(--radius-sm);
  background: var(--tint-primary);
  color: var(--bs-primary);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 21px;
}

.module-name {
  font-size: 15px;
  font-weight: 700;
  color: var(--bs-emphasis-color);
  margin-bottom: 3px;
  line-height: 1.3;
}

/* The field budget: total, then the required/optional split beneath it. */
.module-count {
  display: flex;
  align-items: baseline;
  gap: 6px;
  padding: 0 16px;
}
.module-count b {
  font-size: 26px;
  font-weight: 700;
  color: var(--bs-emphasis-color);
  line-height: 1;
}
.module-count span {
  font-size: 12px;
  color: var(--bs-secondary-color);
}

.module-split {
  padding: 10px 16px 0;
}
.module-split .module-legend {
  display: flex;
  gap: 14px;
  margin-top: 8px;
  font-size: 12px;
  color: var(--bs-secondary-color);
}
.module-split .module-legend span {
  display: inline-flex;
  align-items: center;
  gap: 5px;
}
.module-split .module-legend span::before {
  content: "";
  width: 7px;
  height: 7px;
  border-radius: 2px;
  background: var(--field-opt);
}
.module-split .module-legend span.is-req::before {
  background: var(--field-req);
}
.module-split .module-legend b {
  color: var(--bs-emphasis-color);
  font-weight: 600;
}

.module-footer {
  margin-top: auto;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  flex-wrap: wrap;
  padding: 14px 16px;
  border-top: 1px solid var(--bs-border-color);
  background: var(--bs-secondary-bg);
  font-size: 12px;
  color: var(--bs-secondary-color);
}

/* ============================================================
   5. FIELD CARDS + TYPE GLYPHS
   ============================================================ */
.field {
  position: relative;
  height: 100%;
  display: flex;
  flex-direction: column;
  border: 1px solid var(--bs-border-color);
  border-radius: var(--radius);
  background: var(--bs-body-bg);
  box-shadow: var(--shadow);
  transition: var(--transition);
  cursor: pointer;
  /* The drag rail — this is a builder, so a field can be reordered. */
}
.field::before {
  content: "";
  position: absolute;
  left: 0;
  top: 14px;
  bottom: 14px;
  width: 3px;
  border-radius: 0 3px 3px 0;
  background: var(--bs-primary);
  opacity: 0;
  transition: var(--transition);
}
.field:hover, .field:focus-visible {
  border-color: var(--field-accent-line);
  box-shadow: var(--shadow-lift);
  outline: 0;
}
.field:hover::before, .field:focus-visible::before {
  opacity: 1;
}
.field.is-draft {
  border-style: dashed;
}
.field.is-archived {
  opacity: 0.72;
}

.field-header {
  display: flex;
  align-items: flex-start;
  gap: 11px;
  padding: 14px 14px 10px;
}

.field-glyph {
  width: 38px;
  height: 38px;
  flex-shrink: 0;
  border-radius: var(--radius-sm);
  border: 1px solid var(--bs-border-color);
  background: var(--bs-secondary-bg);
  color: var(--bs-emphasis-color);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 19px;
}

.field-name {
  font-size: 14px;
  font-weight: 600;
  color: var(--bs-emphasis-color);
  margin-bottom: 4px;
  line-height: 1.35;
}

.field-meta {
  display: flex;
  align-items: center;
  gap: 6px;
  flex-wrap: wrap;
  padding: 0 14px 12px;
}

.field-footer {
  margin-top: auto;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  padding: 10px 14px;
  border-top: 1px solid var(--bs-border-color);
  font-size: 12px;
  color: var(--bs-secondary-color);
}

/* Type palette — every supported field type as a pickable glyph tile. */
.palette {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(126px, 1fr));
  gap: 10px;
}

.field-tile {
  display: flex;
  align-items: center;
  gap: 9px;
  padding: 10px 11px;
  border: 1px solid var(--bs-border-color);
  border-radius: var(--radius-sm);
  background: var(--bs-body-bg);
  color: var(--bs-emphasis-color);
  font-size: 12.5px;
  font-weight: 500;
  text-align: left;
  width: 100%;
  transition: var(--transition);
}
.field-tile i {
  font-size: 17px;
  color: var(--bs-primary);
  flex-shrink: 0;
}
.field-tile span {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.field-tile:hover {
  border-color: var(--field-accent-line);
  background: var(--tint-primary);
  transform: translateY(-1px);
}
.field-tile.is-active {
  border-color: var(--bs-primary);
  background: var(--tint-primary);
  box-shadow: inset 0 0 0 1px var(--bs-primary);
}

/* ============================================================
   6. FIELD PREVIEW CANVAS
   ============================================================ */
.canvas {
  border: 1px solid var(--bs-border-color);
  border-radius: var(--radius);
  background-color: var(--bs-body-bg);
  background-image: radial-gradient(var(--field-grid) 1px, transparent 1px);
  background-size: 16px 16px;
  padding: 18px;
}

.preview {
  border: 1px solid var(--bs-border-color);
  border-radius: var(--radius-sm);
  background: var(--bs-body-bg);
  padding: 14px;
  box-shadow: var(--shadow);
}
.preview + .preview {
  margin-top: 12px;
}
.preview .preview-label {
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: 12.5px;
  font-weight: 600;
  color: var(--bs-emphasis-color);
  margin-bottom: 6px;
}
.preview .preview-label .star {
  color: var(--field-req);
}
.preview .preview-help {
  font-size: 11.5px;
  color: var(--bs-secondary-color);
  margin: 6px 0 0;
}

/* A dashed slot where the next field will land. */
.slot {
  border: 1px dashed var(--border-strong);
  border-radius: var(--radius-sm);
  background: transparent;
  color: var(--bs-secondary-color);
  font-size: 12.5px;
  font-weight: 500;
  padding: 16px;
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 7px;
  transition: var(--transition);
}
.slot:hover {
  border-color: var(--bs-primary);
  color: var(--bs-primary);
  background: var(--tint-primary);
}

/* ============================================================
   7. VALIDATION CARDS + RULE CHIPS
   ============================================================ */
.guard {
  display: flex;
  align-items: flex-start;
  gap: 12px;
  height: 100%;
  padding: 14px;
  border: 1px solid var(--bs-border-color);
  border-left: 3px solid var(--bs-primary);
  border-radius: var(--radius-sm);
  background: var(--bs-body-bg);
  box-shadow: var(--shadow);
  transition: var(--transition);
}
.guard:hover {
  box-shadow: var(--shadow-lift);
}
.guard.is-req {
  border-left-color: var(--field-req);
}
.guard.is-warn {
  border-left-color: var(--bs-warning);
}
.guard.is-ok {
  border-left-color: var(--bs-success);
}
.guard .guard-icon {
  width: 34px;
  height: 34px;
  flex-shrink: 0;
  border-radius: var(--radius-sm);
  background: var(--bs-secondary-bg);
  color: var(--bs-emphasis-color);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 17px;
}
.guard .guard-title {
  font-size: 13.5px;
  font-weight: 600;
  color: var(--bs-emphasis-color);
  margin-bottom: 2px;
}
.guard p {
  font-size: 12px;
  color: var(--bs-secondary-color);
  margin-bottom: 0;
}

/* A validation rule stated as an expression. */
.expression {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-family: var(--font-mono);
  font-size: 11.5px;
  color: var(--bs-emphasis-color);
  background: var(--bs-secondary-bg);
  border: 1px solid var(--bs-border-color);
  border-radius: 6px;
  padding: 3px 8px;
  margin: 6px 6px 0 0;
}
.expression b {
  color: var(--bs-primary);
  font-weight: 600;
}

/* ============================================================
   8. LAYOUT / SECTION CARDS
   ============================================================ */
.field-panel {
  border: 1px solid var(--bs-border-color);
  border-radius: var(--radius);
  background: var(--bs-body-bg);
  box-shadow: var(--shadow);
  display: flex;
  flex-direction: column;
}

.field-panel-header {
  display: flex;
  align-items: center;
  gap: 11px;
  padding: 14px 16px;
  border-bottom: 1px solid var(--bs-border-color);
}
.field-panel-header .field-panel-icon {
  width: 34px;
  height: 34px;
  flex-shrink: 0;
  border-radius: var(--radius-sm);
  background: var(--tint-primary);
  color: var(--bs-primary);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 17px;
}
.field-panel-header .field-panel-title {
  font-size: 14px;
  font-weight: 600;
  color: var(--bs-emphasis-color);
  margin-bottom: 1px;
}
.field-panel-header p {
  font-size: 12px;
  color: var(--bs-secondary-color);
  margin-bottom: 0;
}

.field-panel-body {
  padding: 14px 16px;
  flex: 1 1 auto;
}

.field-panel-footer {
  padding: 12px 16px;
  border-top: 1px solid var(--bs-border-color);
  background: var(--bs-secondary-bg);
  border-radius: 0 0 var(--radius) var(--radius);
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  flex-wrap: wrap;
  font-size: 12px;
  color: var(--bs-secondary-color);
}

/* A key/value line inside any panel. */
.field-info-row {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 10px 0;
  border-bottom: 1px dashed var(--bs-border-color);
}
.field-info-row:last-child {
  border-bottom: 0;
  padding-bottom: 0;
}
.field-info-row:first-child {
  padding-top: 0;
}
.field-info-row .field-row-key {
  flex: 1 1 auto;
  font-size: 13px;
  font-weight: 500;
  color: var(--bs-emphasis-color);
}
.field-info-row .field-row-key small {
  display: block;
  font-size: 11.5px;
  font-weight: 400;
  color: var(--bs-secondary-color);
  margin-top: 1px;
}
.field-info-row .field-row-value {
  flex: 0 0 auto;
  display: flex;
  align-items: center;
  gap: 8px;
}

/* A compact column diagram for the layout section. */
.columns {
  display: flex;
  gap: 6px;
}
.columns span {
  flex: 1 1 0;
  height: 34px;
  border-radius: 6px;
  border: 1px dashed var(--border-strong);
  background: var(--bs-secondary-bg);
}
.columns.is-active span {
  border-style: solid;
  border-color: var(--field-accent-line);
  background: var(--tint-primary);
}

/* ============================================================
   9. DYNAMIC RULE CARDS (WHEN → THEN)
   ============================================================ */
.field-rule {
  height: 100%;
  border: 1px solid var(--bs-border-color);
  border-radius: var(--radius);
  background: var(--bs-body-bg);
  box-shadow: var(--shadow);
  padding: 15px;
  transition: var(--transition);
}
.field-rule:hover {
  border-color: var(--field-accent-line);
  box-shadow: var(--shadow-lift);
}
.field-rule .rule-top {
  display: flex;
  align-items: center;
  gap: 9px;
  margin-bottom: 12px;
}
.field-rule .rule-top i {
  font-size: 18px;
  color: var(--bs-primary);
}
.field-rule .rule-top .rule-title {
  flex: 1 1 auto;
  font-size: 13.5px;
  font-weight: 600;
  color: var(--bs-emphasis-color);
  margin-bottom: 0;
}

.field-clause {
  position: relative;
  padding: 8px 10px 8px 52px;
  border-radius: var(--radius-sm);
  background: var(--bs-secondary-bg);
  font-size: 12.5px;
  color: var(--bs-emphasis-color);
}
.field-clause + .field-clause {
  margin-top: 6px;
}
.field-clause {
  /* WHEN / THEN keyword rendered in the gutter. */
}
.field-clause::before {
  content: attr(data-kw);
  position: absolute;
  left: 10px;
  top: 9px;
  font-family: var(--font-mono);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.06em;
  color: var(--bs-primary);
}
.field-clause code {
  font-family: var(--font-mono);
  font-size: 11.5px;
  color: var(--bs-emphasis-color);
  background: var(--bs-body-bg);
  border: 1px solid var(--bs-border-color);
  border-radius: 5px;
  padding: 0 4px;
}

/* ============================================================
   10. ACTIVITY TIMELINE
   ============================================================ */
.flow {
  position: relative;
  padding-left: 30px;
  margin: 0;
  list-style: none;
}
.flow::before {
  content: "";
  position: absolute;
  left: 11px;
  top: 6px;
  bottom: 6px;
  width: 2px;
  background: var(--track);
}

.flow-item {
  position: relative;
  padding-bottom: 20px;
}
.flow-item:last-child {
  padding-bottom: 0;
}
.flow-item::before {
  content: "";
  position: absolute;
  left: -25px;
  top: 3px;
  width: 12px;
  height: 12px;
  border-radius: 50%;
  background: var(--bs-body-bg);
  border: 2px solid var(--track);
}
.flow-item.is-done::before {
  background: var(--bs-success);
  border-color: var(--bs-success);
}
.flow-item.is-current::before {
  background: var(--bs-primary);
  border-color: var(--bs-primary);
  box-shadow: 0 0 0 4px var(--tint-primary);
}
.flow-item .flow-title {
  font-size: 13.5px;
  font-weight: 600;
  color: var(--bs-emphasis-color);
  margin-bottom: 2px;
}
.flow-item p {
  font-size: 12px;
  color: var(--bs-secondary-color);
  margin-bottom: 0;
}
.flow-item time {
  font-size: 11.5px;
  color: var(--bs-secondary-color);
}

/* ============================================================
   11. TEMPLATE CARDS
   ============================================================ */
.field-template {
  position: relative;
  height: 100%;
  display: flex;
  flex-direction: column;
  border: 1px solid var(--bs-border-color);
  border-radius: var(--radius);
  background: var(--bs-body-bg);
  box-shadow: var(--shadow);
  overflow: hidden;
  transition: var(--transition);
}
.field-template:hover {
  border-color: var(--field-accent-line);
  box-shadow: var(--shadow-lift);
  transform: translateY(-2px);
}
.field-template {
  /* A miniature of the form the template produces. */
}
.field-template .template-thumb {
  height: 82px;
  padding: 12px 14px;
  background-color: var(--tint-primary);
  background-image: radial-gradient(var(--field-grid) 1px, transparent 1px);
  background-size: 14px 14px;
  display: flex;
  flex-direction: column;
  gap: 6px;
  border-bottom: 1px solid var(--bs-border-color);
}
.field-template .template-thumb span {
  height: 8px;
  border-radius: 3px;
  background: var(--bs-body-bg);
  border: 1px solid var(--bs-border-color);
  display: block;
}
.field-template .field-template-body {
  padding: 14px;
  flex: 1 1 auto;
}
.field-template .field-template-title {
  font-size: 14px;
  font-weight: 600;
  color: var(--bs-emphasis-color);
  margin-bottom: 3px;
}
.field-template .template-stats {
  display: flex;
  gap: 16px;
  margin-top: 11px;
}
.field-template .template-stats div {
  line-height: 1.2;
}
.field-template .template-stats b {
  display: block;
  font-size: 16px;
  font-weight: 700;
  color: var(--bs-emphasis-color);
}
.field-template .template-stats span {
  font-size: 11px;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  color: var(--bs-secondary-color);
}
.field-template .field-template-footer {
  display: flex;
  gap: 8px;
  padding: 12px 14px;
  border-top: 1px solid var(--bs-border-color);
  background: var(--bs-secondary-bg);
}

/* ============================================================
   12. INSIGHT CARDS
   ============================================================ */
.insight {
  height: 100%;
  border: 1px solid var(--bs-border-color);
  border-radius: var(--radius);
  background: var(--bs-body-bg);
  box-shadow: var(--shadow);
  padding: 16px;
}
.insight .insight-top {
  display: flex;
  align-items: center;
  gap: 9px;
  margin-bottom: 12px;
}
.insight .insight-top i {
  width: 30px;
  height: 30px;
  border-radius: 8px;
  background: var(--tint-primary);
  color: var(--bs-primary);
  display: inline-flex;
  align-items: center;
  justify-content: center;
  font-size: 16px;
}
.insight .insight-top .insight-title {
  font-size: 13.5px;
  font-weight: 600;
  color: var(--bs-emphasis-color);
  margin-bottom: 0;
}
.insight.is-warn .insight-top i {
  background: var(--tint-warning);
  color: rgb(172.8, 132.1846153846, 0);
}
.insight.is-stop .insight-top i {
  background: var(--field-req-soft);
  color: var(--field-req);
}

/* A ranked usage line inside an insight card. */
.rank {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 7px 0;
  border-bottom: 1px dashed var(--bs-border-color);
}
.rank:last-child {
  border-bottom: 0;
  padding-bottom: 0;
}
.rank .rank-n {
  width: 20px;
  font-family: var(--font-mono);
  font-size: 11px;
  color: var(--bs-secondary-color);
  flex-shrink: 0;
}
.rank .rank-name {
  flex: 1 1 auto;
  font-size: 12.5px;
  color: var(--bs-emphasis-color);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.rank .rank-bar {
  flex: 0 0 78px;
  height: 5px;
  border-radius: 999px;
  background: var(--track);
  overflow: hidden;
}
.rank .rank-bar span {
  display: block;
  height: 100%;
  border-radius: 999px;
  background: var(--bs-primary);
}
.rank .rank-v {
  flex: 0 0 auto;
  font-size: 11.5px;
  font-weight: 600;
  color: var(--bs-emphasis-color);
}

/* ============================================================
   13. PREMIUM ACCORDION + TABS
   ============================================================ */
.field-accordion .accordion-item {
  border: 1px solid var(--bs-border-color);
  border-radius: var(--radius) !important;
  background: var(--bs-body-bg);
  margin-bottom: 10px;
  overflow: hidden;
  box-shadow: var(--shadow);
}
.field-accordion .accordion-button {
  background: var(--bs-body-bg);
  color: var(--bs-emphasis-color);
  font-size: 13.5px;
  font-weight: 600;
  padding: 14px 16px;
  box-shadow: none;
}
.field-accordion .accordion-button:not(.collapsed) {
  background: var(--tint-primary);
  color: var(--bs-primary);
}
.field-accordion .accordion-button:focus {
  box-shadow: none;
  border-color: transparent;
}
.field-accordion .accordion-button::after {
  width: 24px;
  height: 24px;
  background-size: 15px;
}
.field-accordion .accordion-body {
  padding: 6px 16px 16px;
  font-size: 13px;
  color: var(--bs-secondary-color);
}

/* Segmented tabs used inside the offcanvas workspace. */
.segment {
  display: inline-flex;
  flex-wrap: wrap;
  gap: 4px;
  padding: 4px;
  border: 1px solid var(--bs-border-color);
  border-radius: 999px;
  background: var(--bs-secondary-bg);
}
.segment .nav-link {
  border: 0;
  border-radius: 999px;
  padding: 6px 14px;
  font-size: 12.5px;
  font-weight: 500;
  color: var(--bs-secondary-color);
  background: transparent;
  transition: var(--transition);
}
.segment .nav-link:hover {
  color: var(--bs-emphasis-color);
}
.segment .nav-link.active {
  background: var(--bs-body-bg);
  color: var(--bs-primary);
  box-shadow: var(--shadow);
}

/* ============================================================
   14. OFFCANVAS WORKSPACE, MODALS, EMPTY STATE
   ============================================================ */
.field-detail-panel {
  width: 88% !important;
  max-width: 1400px;
}
.field-detail-panel .offcanvas-header {
  border-bottom: 1px solid var(--bs-border-color);
  padding: 16px 22px;
  align-items: flex-start;
  gap: 14px;
}
.field-detail-panel .offcanvas-body {
  padding: 20px 22px 28px;
  background: var(--bs-secondary-bg);
}

@media (max-width: 991.98px) {
  .field-detail-panel {
    width: 100% !important;
  }
}
.field-detail-title {
  font-size: 19px;
  font-weight: 700;
  color: var(--bs-emphasis-color);
  margin-bottom: 4px;
  line-height: 1.3;
}

.field-modal-icon {
  width: 40px;
  height: 40px;
  border-radius: var(--radius-sm);
  background: var(--tint-primary);
  color: var(--bs-primary);
  display: inline-flex;
  align-items: center;
  justify-content: center;
  font-size: 20px;
}
.field-modal-icon.is-stop {
  background: var(--field-req-soft);
  color: var(--field-req);
}

.empty-state {
  border: 1px dashed var(--border-strong);
  border-radius: var(--radius);
  background-color: var(--bs-body-bg);
  background-image: radial-gradient(var(--field-grid) 1px, transparent 1px);
  background-size: 16px 16px;
  padding: 44px 24px;
  text-align: center;
}
.empty-state i {
  font-size: 32px;
  color: var(--bs-secondary-color);
  margin-bottom: 10px;
  display: block;
}
.empty-state .empty-title {
  font-size: 15px;
  font-weight: 600;
  color: var(--bs-emphasis-color);
  margin-bottom: 4px;
}
.empty-state p {
  font-size: 12.5px;
  color: var(--bs-secondary-color);
  max-width: 46ch;
  margin: 0 auto 14px;
}

/* Section heading shared by every workspace pane. */
.field-section-header {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 14px;
  flex-wrap: wrap;
  margin-bottom: 16px;
}
.field-section-header h2 {
  font-size: 19px;
  font-weight: 700;
  color: var(--bs-emphasis-color);
  margin-bottom: 3px;
}
.field-section-header p {
  font-size: 13px;
  color: var(--bs-secondary-color);
  margin-bottom: 0;
  max-width: 72ch;
}

@media (max-width: 1199.98px) {
  .settings-profile .border-start {
    border-left: none !important;
    padding: 0px !important;
  }
}

@media (max-width: 767.98px) {
  div.dataTables_wrapper div.dataTables_length, div.dataTables_wrapper div.dataTables_filter, div.dataTables_wrapper div.dataTables_info, div.dataTables_wrapper div.dataTables_paginate {
    text-align: start !important;
  }
}

/*-----------------
	Communications — announcement workspace components

	A shared vocabulary for the Announcements & Communication Center: the
	announcements themselves, who they go to, the channels that carry them,
	what is queued to go out, and the templates they are written from.
	Class prefix `cmx-`.

	The visual language is a publishing desk. An announcement is treated as
	a piece with a cover, a priority rail down its left edge, and a
	delivery footer stating which channels carried it and how far it got.
	Audience and channel cards are read as delivery instruments — a
	recipient count with a read-rate bar underneath — not as dashboard
	tiles.

	Contents
	  1. Tokens + shared pieces
	  2. Announcement cards
	  3. Audience cards
	  4. Template cards
	  5. Schedule cards
	  6. Channel cards
	  7. Offcanvas workspace + modals
	  8. Broadcast scheduler
	  9. SMS communication center
	  10. WhatsApp communication center
	  11. Notification & parent communication center
-----------------*/
/* ============================================================
   1. TOKENS + SHARED PIECES
   ============================================================ */
:root {
  /* A deep editorial indigo-blue, distinct from the plain brand blue so
     the communication desk reads as its own surface. */
  --message-accent: rgb(52.88, 80, 183);
  --message-accent-line: rgb(196.8, 206.7, 246);
  --message-urgent: #E82646;
  --message-urgent-soft: #FDE9ED;
  --message-high: #EAB300;
  --message-high-soft: #FEF8EA;
  --message-normal: #0F65CD;
  --message-normal-soft: #E7F1FC;
  --message-live: #1ABE17;
  --message-live-soft: #E8F9E8;
  --message-draft: #4A00E5;
  --message-draft-soft: rgb(236.9, 229.5, 252.4);
}

[data-theme=dark],
[data-bs-theme=dark],
html.darkmode {
  --message-accent-line: rgba(61, 94, 225, .38);
  --message-urgent-soft: rgba(234, 84, 85, 0.18);
  --message-high-soft: rgba(255, 159, 67, 0.18);
  --message-normal-soft: rgba(0, 207, 232, 0.18);
  --message-live-soft: rgba(40, 199, 111, 0.18);
  --message-draft-soft: rgba(115, 103, 240, 0.18);
}
[data-theme=dark] .message-status-badge.is-high,
[data-bs-theme=dark] .message-status-badge.is-high,
html.darkmode .message-status-badge.is-high {
  color: var(--message-high);
}

.message-metric-label {
  display: block;
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--bs-secondary-color);
  margin-bottom: 4px;
}

/* Section heading shared by every block on the page. */
.message-section-header {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 14px;
  flex-wrap: wrap;
  margin-bottom: 16px;
}
.message-section-header h2 {
  font-size: 20px;
  font-weight: 700;
  color: var(--bs-emphasis-color);
  margin-bottom: 3px;
}
.message-section-header p {
  font-size: 13px;
  color: var(--bs-secondary-color);
  margin-bottom: 0;
  max-width: 74ch;
}

/* Status / meta badge. */
.message-status-badge {
  /* geometry, typography and surface come from the shared badge component */
}
.message-status-badge i {
  font-size: 12px;
}
.message-status-badge.is-live {
  background: var(--message-live-soft);
  color: var(--message-live);
  border-color: transparent;
}
.message-status-badge.is-draft {
  background: var(--message-draft-soft);
  color: var(--message-draft);
  border-color: transparent;
}
.message-status-badge.is-scheduled {
  background: var(--message-normal-soft);
  color: var(--message-normal);
  border-color: transparent;
}
.message-status-badge.is-urgent {
  background: var(--message-urgent-soft);
  color: var(--message-urgent);
  border-color: transparent;
}
.message-status-badge.is-high {
  background: var(--message-high-soft);
  color: rgb(172.8, 132.1846153846, 0);
  border-color: transparent;
}
.message-status-badge.is-accent {
  background: var(--tint-primary);
  color: var(--bs-primary);
  border-color: transparent;
}
.message-status-badge.is-expired {
  border-style: dashed;
}

/* Category tag — the subject of the announcement, always plain. */
.category {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.05em;
  text-transform: uppercase;
  color: var(--bs-primary);
}
.category::before {
  content: "";
  width: 6px;
  height: 6px;
  border-radius: 2px;
  background: currentcolor;
}

/* Channel pip — a channel this piece was carried on. */
.pip {
  width: 24px;
  height: 24px;
  border-radius: 7px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  font-size: 13px;
  background: var(--bs-secondary-bg);
  color: var(--bs-secondary-color);
  border: 1px solid var(--bs-border-color);
}
.pip.is-on {
  background: var(--tint-primary);
  color: var(--bs-primary);
  border-color: transparent;
}
.pip.is-off {
  opacity: 0.45;
}

.pips {
  display: inline-flex;
  gap: 4px;
}

/* Read-rate bar, used on announcement, audience and channel cards. */
.rate {
  height: 5px;
  border-radius: 999px;
  background: var(--track);
  overflow: hidden;
}
.rate span {
  display: block;
  height: 100%;
  border-radius: 999px;
  background: var(--bs-primary);
}
.rate.is-live span {
  background: var(--message-live);
}
.rate.is-warn span {
  background: var(--message-high);
}

/* Small key/value line reused inside card bodies. */
.info-row {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 9px 0;
  border-bottom: 1px dashed var(--bs-border-color);
}
.info-row:last-child {
  border-bottom: 0;
  padding-bottom: 0;
}
.info-row:first-child {
  padding-top: 0;
}
.info-row .row-key {
  flex: 1 1 auto;
  font-size: 13px;
  font-weight: 500;
  color: var(--bs-emphasis-color);
}
.info-row .row-key small {
  display: block;
  font-size: 11.5px;
  font-weight: 400;
  color: var(--bs-secondary-color);
  margin-top: 1px;
}
.info-row .row-value {
  flex: 0 0 auto;
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 13px;
  color: var(--bs-emphasis-color);
}

/* ============================================================
   2. ANNOUNCEMENT CARDS
   ============================================================ */
.message-post {
  position: relative;
  height: 100%;
  display: flex;
  flex-direction: column;
  border: 1px solid var(--bs-border-color);
  border-radius: var(--radius);
  background: var(--bs-body-bg);
  box-shadow: var(--shadow);
  overflow: hidden;
  transition: var(--transition);
}
.message-post:hover {
  border-color: var(--message-accent-line);
  box-shadow: var(--shadow-lift);
  transform: translateY(-2px);
}
.message-post {
  /* Priority rail — the one piece of colour on an otherwise calm card. */
}
.message-post::before {
  content: "";
  position: absolute;
  left: 0;
  top: 0;
  bottom: 0;
  width: 3px;
  background: var(--message-normal);
  z-index: 2;
}
.message-post.is-urgent::before {
  background: var(--message-urgent);
}
.message-post.is-high::before {
  background: var(--message-high);
}
.message-post.is-draft {
  border-style: dashed;
}
.message-post.is-draft::before {
  background: var(--message-draft);
}

.post-cover {
  position: relative;
  display: block;
  height: 148px;
  overflow: hidden;
  background: var(--bs-secondary-bg);
}
.post-cover img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition: transform 0.4s cubic-bezier(0.4, 0, 0.2, 1);
}
.message-post:hover .post-cover img {
  transform: scale(1.04);
}
.post-cover {
  /* Status sits on the cover so the body stays about the content. */
}
.post-cover .post-status {
  position: absolute;
  top: 10px;
  left: 12px;
  display: inline-flex;
  gap: 5px;
  flex-wrap: wrap;
}
.post-cover .post-acknowledgement {
  position: absolute;
  top: 10px;
  right: 12px;
  display: inline-flex;
  align-items: center;
  gap: 4px;
  font-size: 11px;
  font-weight: 600;
  padding: 2px 9px;
  border-radius: 999px;
  background: rgba(20, 20, 43, 0.72);
  color: #fff;
  backdrop-filter: blur(4px);
}

.post-body {
  padding: 14px 16px;
  flex: 1 1 auto;
}
.post-body .post-title {
  font-size: 15.5px;
  font-weight: 600;
  color: var(--bs-emphasis-color);
  line-height: 1.35;
  margin: 6px 0 5px;
}
.post-body .post-title a {
  color: inherit;
}
.post-body .post-summary {
  font-size: 12.5px;
  color: var(--bs-secondary-color);
  margin-bottom: 0;
  display: -webkit-box;
  -webkit-line-clamp: 2;
  line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
}

/* Dates and attachments — the practical facts, set apart from the copy. */
.post-facts {
  display: flex;
  flex-wrap: wrap;
  gap: 6px 16px;
  margin-top: 12px;
  font-size: 11.5px;
  color: var(--bs-secondary-color);
}
.post-facts span {
  display: inline-flex;
  align-items: center;
  gap: 5px;
}
.post-facts b {
  color: var(--bs-emphasis-color);
  font-weight: 600;
}

.post-reach {
  padding: 0 16px 12px;
}
.post-reach .post-reach-top {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 8px;
  font-size: 11.5px;
  color: var(--bs-secondary-color);
  margin-bottom: 5px;
}
.post-reach .post-reach-top b {
  color: var(--bs-emphasis-color);
  font-weight: 600;
}

.post-footer {
  margin-top: auto;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  flex-wrap: wrap;
  padding: 11px 16px;
  border-top: 1px solid var(--bs-border-color);
  background: var(--bs-secondary-bg);
}

/* ============================================================
   3. AUDIENCE CARDS
   ============================================================ */
.audience {
  height: 100%;
  display: flex;
  flex-direction: column;
  border: 1px solid var(--bs-border-color);
  border-radius: var(--radius);
  background: var(--bs-body-bg);
  box-shadow: var(--shadow);
  padding: 16px;
  transition: var(--transition);
}
.audience:hover {
  border-color: var(--message-accent-line);
  box-shadow: var(--shadow-lift);
}
.audience .audience-top {
  display: flex;
  align-items: center;
  gap: 11px;
  margin-bottom: 14px;
}
.audience .audience-top .audience-icon {
  width: 38px;
  height: 38px;
  flex-shrink: 0;
  border-radius: var(--radius-sm);
  background: var(--tint-primary);
  color: var(--bs-primary);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 19px;
}
.audience .audience-top .audience-name {
  font-size: 14.5px;
  font-weight: 600;
  color: var(--bs-emphasis-color);
  margin-bottom: 1px;
}
.audience .audience-top small {
  font-size: 11.5px;
  color: var(--bs-secondary-color);
}
.audience .audience-count {
  display: flex;
  align-items: baseline;
  gap: 6px;
  margin-bottom: 12px;
}
.audience .audience-count b {
  font-size: 24px;
  font-weight: 700;
  color: var(--bs-emphasis-color);
  line-height: 1;
}
.audience .audience-count span {
  font-size: 12px;
  color: var(--bs-secondary-color);
}
.audience .audience-footer {
  margin-top: auto;
  padding-top: 12px;
  border-top: 1px dashed var(--bs-border-color);
  font-size: 11.5px;
  color: var(--bs-secondary-color);
}

/* ============================================================
   4. TEMPLATE CARDS
   ============================================================ */
.template {
  height: 100%;
  display: flex;
  flex-direction: column;
  border: 1px solid var(--bs-border-color);
  border-radius: var(--radius);
  background: var(--bs-body-bg);
  box-shadow: var(--shadow);
  overflow: hidden;
  transition: var(--transition);
}
.template:hover {
  border-color: var(--message-accent-line);
  box-shadow: var(--shadow-lift);
  transform: translateY(-2px);
}
.template {
  /* A miniature of the notice the template writes. */
}
.template .template-preview {
  padding: 14px 16px 12px;
  background: var(--tint-primary);
  border-bottom: 1px solid var(--bs-border-color);
}
.template .template-preview .template-mini {
  border-radius: var(--radius-sm);
  background: var(--bs-body-bg);
  border: 1px solid var(--bs-border-color);
  padding: 10px 12px;
}
.template .template-preview .template-mini b {
  display: block;
  font-size: 12px;
  font-weight: 600;
  color: var(--bs-emphasis-color);
  margin-bottom: 7px;
}
.template .template-preview .template-mini i {
  display: block;
  height: 6px;
  border-radius: 3px;
  background: var(--track);
  margin-bottom: 5px;
}
.template .template-preview .template-mini i:last-child {
  margin-bottom: 0;
}
.template .template-body {
  padding: 13px 16px;
  flex: 1 1 auto;
}
.template .template-body .template-title {
  font-size: 14px;
  font-weight: 600;
  color: var(--bs-emphasis-color);
  margin: 5px 0 4px;
}
.template .template-body p {
  font-size: 12px;
  color: var(--bs-secondary-color);
  margin-bottom: 0;
}
.template .template-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  padding: 11px 16px;
  border-top: 1px solid var(--bs-border-color);
  background: var(--bs-secondary-bg);
  font-size: 11.5px;
  color: var(--bs-secondary-color);
}

/* ============================================================
   5. SCHEDULE CARDS
   ============================================================ */
.schedule {
  display: flex;
  gap: 0;
  height: 100%;
  border: 1px solid var(--bs-border-color);
  border-radius: var(--radius);
  background: var(--bs-body-bg);
  box-shadow: var(--shadow);
  overflow: hidden;
  transition: var(--transition);
}
.schedule:hover {
  border-color: var(--message-accent-line);
  box-shadow: var(--shadow-lift);
}
.schedule {
  /* The date block reads as a tear-off from a desk calendar. */
}
.schedule .schedule-when {
  flex: 0 0 92px;
  padding: 14px 10px;
  text-align: center;
  background: var(--tint-primary);
  border-right: 1px solid var(--bs-border-color);
  display: flex;
  flex-direction: column;
  justify-content: center;
}
.schedule .schedule-when .schedule-day {
  font-size: 26px;
  font-weight: 700;
  color: var(--bs-primary);
  line-height: 1;
}
.schedule .schedule-when .schedule-month {
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--bs-primary);
  margin-top: 3px;
}
.schedule .schedule-when .schedule-time {
  font-size: 11.5px;
  color: var(--bs-secondary-color);
  margin-top: 7px;
  padding-top: 7px;
  border-top: 1px dashed var(--border-strong);
}
.schedule .schedule-main {
  flex: 1 1 auto;
  padding: 13px 15px;
  min-width: 0;
}
.schedule .schedule-main .schedule-title {
  font-size: 14px;
  font-weight: 600;
  color: var(--bs-emphasis-color);
  margin-bottom: 4px;
}
.schedule .schedule-meta {
  display: flex;
  flex-wrap: wrap;
  gap: 5px 14px;
  margin-top: 10px;
  font-size: 11.5px;
  color: var(--bs-secondary-color);
}
.schedule .schedule-meta span {
  display: inline-flex;
  align-items: center;
  gap: 5px;
}
.schedule .schedule-meta b {
  color: var(--bs-emphasis-color);
  font-weight: 600;
}

/* ============================================================
   6. CHANNEL CARDS
   ============================================================ */
.channel {
  position: relative;
  height: 100%;
  display: flex;
  flex-direction: column;
  border: 1px solid var(--bs-border-color);
  border-radius: var(--radius);
  background: var(--bs-body-bg);
  box-shadow: var(--shadow);
  padding: 16px;
  transition: var(--transition);
}
.channel:hover {
  border-color: var(--message-accent-line);
  box-shadow: var(--shadow-lift);
}
.channel.is-off {
  background: var(--bs-secondary-bg);
}
.channel .channel-top {
  display: flex;
  align-items: flex-start;
  gap: 11px;
  margin-bottom: 12px;
}
.channel .channel-top .channel-icon {
  width: 40px;
  height: 40px;
  flex-shrink: 0;
  border-radius: var(--radius-sm);
  background: var(--tint-primary);
  color: var(--bs-primary);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 20px;
}
.channel .channel-top .channel-name {
  font-size: 14.5px;
  font-weight: 600;
  color: var(--bs-emphasis-color);
  margin-bottom: 2px;
}
.channel .channel-top p {
  font-size: 11.5px;
  color: var(--bs-secondary-color);
  margin-bottom: 0;
}
.channel .channel-footer {
  margin-top: auto;
  padding-top: 12px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  border-top: 1px dashed var(--bs-border-color);
  font-size: 11.5px;
  color: var(--bs-secondary-color);
}

/* ============================================================
   7. OFFCANVAS WORKSPACE + MODALS
   ============================================================ */
.message-detail-panel {
  width: 88% !important;
  max-width: 1400px;
}
.message-detail-panel .offcanvas-header {
  border-bottom: 1px solid var(--bs-border-color);
  padding: 16px 22px;
  align-items: flex-start;
  gap: 14px;
}
.message-detail-panel .offcanvas-body {
  padding: 20px 22px 28px;
  background: var(--bs-secondary-bg);
}

@media (max-width: 991.98px) {
  .message-detail-panel {
    width: 100% !important;
  }
}
.detail-title {
  font-size: 20px;
  font-weight: 700;
  color: var(--bs-emphasis-color);
  margin-bottom: 5px;
  line-height: 1.3;
}

/* A plain panel used to group anything inside the offcanvas or a modal. */
.message-panel {
  display: flex;
  flex-direction: column;
  border: 1px solid var(--bs-border-color);
  border-radius: var(--radius);
  background: var(--bs-body-bg);
  box-shadow: var(--shadow);
}
.message-panel .message-panel-header {
  display: flex;
  align-items: center;
  gap: 11px;
  padding: 13px 16px;
  border-bottom: 1px solid var(--bs-border-color);
}
.message-panel .message-panel-header .panel-icon {
  width: 32px;
  height: 32px;
  flex-shrink: 0;
  border-radius: var(--radius-sm);
  background: var(--tint-primary);
  color: var(--bs-primary);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 16px;
}
.message-panel .message-panel-header .panel-title {
  font-size: 14px;
  font-weight: 600;
  color: var(--bs-emphasis-color);
  margin-bottom: 0;
}
.message-panel .message-panel-body {
  padding: 14px 16px;
  flex: 1 1 auto;
}
.message-panel .panel-footer {
  padding: 11px 16px;
  border-top: 1px solid var(--bs-border-color);
  background: var(--bs-secondary-bg);
  border-radius: 0 0 var(--radius) var(--radius);
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  flex-wrap: wrap;
  font-size: 12px;
  color: var(--bs-secondary-color);
}

/* The announcement as the recipient sees it. */
.reader {
  border: 1px solid var(--bs-border-color);
  border-radius: var(--radius);
  background: var(--bs-body-bg);
  overflow: hidden;
}
.reader .reader-cover {
  height: 210px;
}
.reader .reader-cover img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}
.reader .reader-body {
  padding: 20px 22px 24px;
}
.reader .reader-body h3 {
  font-size: 22px;
  font-weight: 700;
  color: var(--bs-emphasis-color);
  line-height: 1.3;
  margin: 8px 0 10px;
}
.reader .reader-body p {
  font-size: 13.5px;
  line-height: 1.7;
  color: var(--bs-secondary-color);
}
.reader .reader-body h6 {
  font-size: 14px;
  font-weight: 600;
  color: var(--bs-emphasis-color);
  margin: 18px 0 8px;
}
.reader .reader-body ul {
  padding-left: 18px;
  font-size: 13.5px;
  line-height: 1.8;
  color: var(--bs-secondary-color);
}

/* Attachment row. */
.file {
  display: flex;
  align-items: center;
  gap: 11px;
  padding: 9px 11px;
  border: 1px solid var(--bs-border-color);
  border-radius: var(--radius-sm);
  background: var(--bs-body-bg);
  transition: var(--transition);
}
.file + .file {
  margin-top: 8px;
}
.file:hover {
  border-color: var(--message-accent-line);
}
.file i {
  width: 32px;
  height: 32px;
  flex-shrink: 0;
  border-radius: 8px;
  background: var(--bs-secondary-bg);
  color: var(--bs-primary);
  display: inline-flex;
  align-items: center;
  justify-content: center;
  font-size: 16px;
}
.file .message-file-name {
  flex: 1 1 auto;
  min-width: 0;
  font-size: 12.5px;
  font-weight: 500;
  color: var(--bs-emphasis-color);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.file .message-file-name small {
  display: block;
  font-size: 11px;
  font-weight: 400;
  color: var(--bs-secondary-color);
}

/* Comment thread inside the offcanvas. */
.comment {
  display: flex;
  gap: 11px;
  padding: 12px 0;
  border-bottom: 1px dashed var(--bs-border-color);
}
.comment:last-child {
  border-bottom: 0;
  padding-bottom: 0;
}
.comment img {
  width: 34px;
  height: 34px;
  border-radius: 50%;
  object-fit: cover;
  flex-shrink: 0;
}
.comment .comment-who {
  display: flex;
  align-items: baseline;
  gap: 8px;
  flex-wrap: wrap;
  margin-bottom: 3px;
}
.comment .comment-who b {
  font-size: 13px;
  font-weight: 600;
  color: var(--bs-emphasis-color);
}
.comment .comment-who time {
  font-size: 11px;
  color: var(--bs-secondary-color);
}
.comment p {
  font-size: 12.5px;
  color: var(--bs-secondary-color);
  margin-bottom: 0;
  line-height: 1.6;
}

/* Compact related-announcement row. */
.message-related-item {
  display: flex;
  align-items: center;
  gap: 11px;
  padding: 10px 0;
  border-bottom: 1px dashed var(--bs-border-color);
}
.message-related-item:last-child {
  border-bottom: 0;
  padding-bottom: 0;
}
.message-related-item img {
  width: 46px;
  height: 40px;
  border-radius: 7px;
  object-fit: cover;
  flex-shrink: 0;
}
.message-related-item .related-text {
  flex: 1 1 auto;
  min-width: 0;
}
.message-related-item .related-text b {
  display: block;
  font-size: 12.5px;
  font-weight: 600;
  color: var(--bs-emphasis-color);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.message-related-item .related-text small {
  font-size: 11px;
  color: var(--bs-secondary-color);
}

.message-modal-icon {
  width: 40px;
  height: 40px;
  border-radius: var(--radius-sm);
  background: var(--tint-primary);
  color: var(--bs-primary);
  display: inline-flex;
  align-items: center;
  justify-content: center;
  font-size: 20px;
}

/* ============================================================
   8. BROADCAST SCHEDULER

   The scheduler shares the badges, pips, rows, panels, reader and
   offcanvas above — a broadcast is an announcement that has not left
   yet. What it adds is the machinery of *when*: a departure clock on
   every card, a recurrence rule stated in words, a per-channel queue,
   and an approval that has to clear before the clock matters.
   ============================================================ */
/* --- Broadcast card ----------------------------------------- */
.broadcast {
  position: relative;
  height: 100%;
  display: flex;
  flex-direction: column;
  border: 1px solid var(--bs-border-color);
  border-radius: var(--radius);
  background: var(--bs-body-bg);
  box-shadow: var(--shadow);
  overflow: hidden;
  transition: var(--transition);
}
.broadcast:hover {
  border-color: var(--message-accent-line);
  box-shadow: var(--shadow-lift);
  transform: translateY(-2px);
}
.broadcast {
  /* State rail — reads at a glance across a wall of cards. */
}
.broadcast::before {
  content: "";
  position: absolute;
  left: 0;
  top: 0;
  bottom: 0;
  width: 3px;
  background: var(--message-normal);
  z-index: 2;
}
.broadcast.is-paused::before {
  background: var(--message-high);
}
.broadcast.is-draft {
  border-style: dashed;
}
.broadcast.is-draft::before {
  background: var(--message-draft);
}
.broadcast.is-cancelled {
  opacity: 0.72;
}
.broadcast.is-cancelled::before {
  background: var(--bs-secondary-color);
}
.broadcast.is-sent::before {
  background: var(--message-live);
}

/* The departure block: when this leaves, and from which time zone. */
.broadcast-when {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 13px 15px;
  background: var(--tint-primary);
  border-bottom: 1px solid var(--bs-border-color);
}
.broadcast-when .clock {
  flex: 0 0 auto;
  text-align: center;
  line-height: 1;
}
.broadcast-when .clock b {
  display: block;
  font-size: 20px;
  font-weight: 700;
  color: var(--bs-primary);
}
.broadcast-when .clock span {
  display: block;
  font-size: 10.5px;
  font-weight: 600;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--bs-primary);
  margin-top: 4px;
}
.broadcast-when .broadcast-when-text {
  flex: 1 1 auto;
  min-width: 0;
  padding-left: 12px;
  border-left: 1px dashed var(--border-strong);
}
.broadcast-when .broadcast-when-text b {
  display: block;
  font-size: 13.5px;
  font-weight: 600;
  color: var(--bs-emphasis-color);
}
.broadcast-when .broadcast-when-text small {
  display: block;
  font-size: 11px;
  color: var(--bs-secondary-color);
  margin-top: 2px;
}

.broadcast-body {
  padding: 13px 15px;
  flex: 1 1 auto;
}
.broadcast-body .broadcast-title {
  font-size: 15px;
  font-weight: 600;
  color: var(--bs-emphasis-color);
  line-height: 1.35;
  margin: 6px 0 5px;
}
.broadcast-body .broadcast-title a {
  color: inherit;
}
.broadcast-body .broadcast-description {
  font-size: 12.5px;
  color: var(--bs-secondary-color);
  margin-bottom: 0;
  display: -webkit-box;
  -webkit-line-clamp: 2;
  line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
}

.broadcast-facts {
  display: flex;
  flex-wrap: wrap;
  gap: 6px 14px;
  margin-top: 11px;
  font-size: 11.5px;
  color: var(--bs-secondary-color);
}
.broadcast-facts span {
  display: inline-flex;
  align-items: center;
  gap: 5px;
}
.broadcast-facts b {
  color: var(--bs-emphasis-color);
  font-weight: 600;
}

.broadcast-footer {
  margin-top: auto;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  flex-wrap: wrap;
  padding: 11px 15px;
  border-top: 1px solid var(--bs-border-color);
  background: var(--bs-secondary-bg);
}

/* --- Recurrence rule, written out --------------------------- */
.recurrence {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  font-size: 11px;
  font-weight: 600;
  padding: 2px 9px;
  border-radius: 999px;
  background: var(--bs-body-bg);
  color: var(--bs-emphasis-color);
  border: 1px dashed var(--border-strong);
  white-space: nowrap;
}
.recurrence i {
  font-size: 12px;
  color: var(--bs-primary);
}
.recurrence.is-once {
  border-style: solid;
  color: var(--bs-secondary-color);
}

/* --- Channel queue meter ------------------------------------ */
.queue {
  display: flex;
  gap: 3px;
  margin-top: 4px;
}
.queue span {
  flex: 1 1 0;
  height: 18px;
  border-radius: 3px;
  background: var(--track);
}
.queue span.is-filled {
  background: var(--bs-primary);
}
.queue span.is-warn {
  background: var(--message-high);
}
.queue span.is-done {
  background: var(--message-live);
}

/* --- Schedule state card ------------------------------------ */
.state {
  height: 100%;
  display: flex;
  flex-direction: column;
  border: 1px solid var(--bs-border-color);
  border-radius: var(--radius);
  background: var(--bs-body-bg);
  box-shadow: var(--shadow);
  padding: 15px;
  transition: var(--transition);
}
.state:hover {
  border-color: var(--message-accent-line);
  box-shadow: var(--shadow-lift);
}
.state .state-top {
  display: flex;
  align-items: center;
  gap: 10px;
  margin-bottom: 12px;
}
.state .state-top .state-icon {
  width: 36px;
  height: 36px;
  flex-shrink: 0;
  border-radius: var(--radius-sm);
  background: var(--tint-primary);
  color: var(--bs-primary);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 18px;
}
.state .state-top .state-name {
  font-size: 14px;
  font-weight: 600;
  color: var(--bs-emphasis-color);
  margin-bottom: 0;
}
.state .state-top .state-n {
  font-size: 18px;
  font-weight: 700;
  color: var(--bs-emphasis-color);
  margin-left: auto;
}
.state.is-warn .state-icon {
  background: var(--message-high-soft);
  color: rgb(172.8, 132.1846153846, 0);
}
.state.is-done .state-icon {
  background: var(--message-live-soft);
  color: var(--message-live);
}
.state.is-stop .state-icon {
  background: var(--message-urgent-soft);
  color: var(--message-urgent);
}
.state.is-draft .state-icon {
  background: var(--message-draft-soft);
  color: var(--message-draft);
}

/* --- Approval card ------------------------------------------ */
.approval {
  height: 100%;
  display: flex;
  flex-direction: column;
  border: 1px solid var(--bs-border-color);
  border-left: 3px solid var(--message-high);
  border-radius: var(--radius-sm);
  background: var(--bs-body-bg);
  box-shadow: var(--shadow);
  padding: 14px;
  transition: var(--transition);
}
.approval:hover {
  box-shadow: var(--shadow-lift);
}
.approval.is-approved {
  border-left-color: var(--message-live);
}
.approval.is-rejected {
  border-left-color: var(--message-urgent);
}
.approval.is-scheduled {
  border-left-color: var(--message-normal);
}
.approval.is-review {
  border-left-color: var(--message-draft);
}
.approval .approval-title {
  font-size: 14px;
  font-weight: 600;
  color: var(--bs-emphasis-color);
  line-height: 1.35;
  margin-bottom: 8px;
}
.approval .approval-who {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-bottom: 4px;
  font-size: 12px;
  color: var(--bs-secondary-color);
}
.approval .approval-who img {
  width: 24px;
  height: 24px;
  border-radius: 50%;
  object-fit: cover;
}
.approval .approval-who b {
  color: var(--bs-emphasis-color);
  font-weight: 600;
}
.approval .approval-footer {
  margin-top: auto;
  padding-top: 12px;
  display: flex;
  align-items: center;
  gap: 6px;
  flex-wrap: wrap;
}

/* --- Quick action card -------------------------------------- */
.quick-action {
  display: flex;
  align-items: center;
  gap: 12px;
  width: 100%;
  height: 100%;
  text-align: left;
  padding: 15px;
  border: 1px solid var(--bs-border-color);
  border-radius: var(--radius);
  background: var(--bs-body-bg);
  box-shadow: var(--shadow);
  transition: var(--transition);
}
.quick-action i.message-action-icon {
  width: 40px;
  height: 40px;
  flex-shrink: 0;
  border-radius: var(--radius-sm);
  background: var(--tint-primary);
  color: var(--bs-primary);
  display: inline-flex;
  align-items: center;
  justify-content: center;
  font-size: 20px;
  transition: var(--transition);
}
.quick-action .action-text {
  flex: 1 1 auto;
  min-width: 0;
}
.quick-action .action-text b {
  display: block;
  font-size: 13.5px;
  font-weight: 600;
  color: var(--bs-emphasis-color);
  margin-bottom: 2px;
}
.quick-action .action-text small {
  font-size: 11.5px;
  color: var(--bs-secondary-color);
}
.quick-action .message-action-go {
  flex: 0 0 auto;
  font-size: 16px;
  color: var(--bs-secondary-color);
  transition: var(--transition);
}
.quick-action:hover {
  border-color: var(--message-accent-line);
  box-shadow: var(--shadow-lift);
  transform: translateY(-2px);
}
.quick-action:hover i.message-action-icon {
  background: var(--bs-primary);
  color: #fff;
}
.quick-action:hover .message-action-go {
  color: var(--bs-primary);
  transform: translateX(2px);
}

/* ============================================================
   9. SMS COMMUNICATION CENTER

   SMS is the one channel with a hard budget — 160 characters to a
   segment, and every segment costs money and arrives separately. So
   the pieces here are built around that constraint: a composer whose
   counter is part of the furniture rather than a footnote, merge
   fields that are visibly placeholders, a recipient card that reads
   as selected or not, and a preview drawn as the handset it lands on.

   Everything else — badges, rows, panels, offcanvas, template and
   action cards — is reused from the sections above.
   ============================================================ */
/* --- Composer workspace ------------------------------------- */
.compose {
  border: 1px solid var(--bs-border-color);
  border-radius: var(--radius);
  background: var(--bs-body-bg);
  box-shadow: var(--shadow);
  overflow: hidden;
}
.compose .compose-header {
  display: flex;
  align-items: center;
  gap: 11px;
  padding: 14px 16px;
  border-bottom: 1px solid var(--bs-border-color);
}
.compose .compose-header .compose-icon {
  width: 36px;
  height: 36px;
  flex-shrink: 0;
  border-radius: var(--radius-sm);
  background: var(--bs-primary);
  color: #fff;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 18px;
}
.compose .compose-header .compose-title {
  font-size: 15px;
  font-weight: 600;
  color: var(--bs-emphasis-color);
  margin-bottom: 1px;
}
.compose .compose-header p {
  font-size: 12px;
  color: var(--bs-secondary-color);
  margin-bottom: 0;
}
.compose .compose-body {
  padding: 16px;
}
.compose .compose-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  flex-wrap: wrap;
  padding: 13px 16px;
  border-top: 1px solid var(--bs-border-color);
  background: var(--bs-secondary-bg);
}

/* The editor surface — a plain field, but framed so it reads as the
   message body rather than as one more form input. */
.editor {
  border: 1px solid var(--bs-border-color);
  border-radius: var(--radius-sm);
  background: var(--bs-body-bg);
  overflow: hidden;
}
.editor .editor-bar {
  display: flex;
  align-items: center;
  gap: 4px;
  flex-wrap: wrap;
  padding: 7px 9px;
  border-bottom: 1px solid var(--bs-border-color);
  background: var(--bs-secondary-bg);
}
.editor .editor-bar button {
  width: 28px;
  height: 28px;
  border: 0;
  border-radius: 7px;
  background: transparent;
  color: var(--bs-secondary-color);
  display: inline-flex;
  align-items: center;
  justify-content: center;
  font-size: 15px;
  transition: var(--transition);
}
.editor .editor-bar button:hover {
  background: var(--bs-body-bg);
  color: var(--bs-primary);
}
.editor .editor-bar .editor-sep {
  width: 1px;
  height: 18px;
  background: var(--bs-border-color);
  margin: 0 4px;
}
.editor textarea.form-control {
  border: 0;
  border-radius: 0;
  resize: vertical;
  font-size: 13.5px;
  line-height: 1.7;
  min-height: 150px;
  background-color: transparent !important;
  color: var(--bs-emphasis-color);
}
.editor textarea.form-control:focus {
  box-shadow: none;
}

/* --- Character / segment counter ---------------------------- */
.counter {
  display: flex;
  align-items: center;
  gap: 14px;
  flex-wrap: wrap;
  padding: 11px 13px;
  border: 1px solid var(--bs-border-color);
  border-radius: var(--radius-sm);
  background: var(--bs-secondary-bg);
}
.counter .counter-figure {
  line-height: 1.15;
}
.counter .counter-figure b {
  display: block;
  font-size: 17px;
  font-weight: 700;
  color: var(--bs-emphasis-color);
}
.counter .counter-figure span {
  font-size: 10.5px;
  font-weight: 600;
  letter-spacing: 0.07em;
  text-transform: uppercase;
  color: var(--bs-secondary-color);
}
.counter .counter-bar {
  flex: 1 1 120px;
  min-width: 110px;
}

/* Segment ticks — one block per 160-character segment. */
.segments {
  display: flex;
  gap: 3px;
}
.segments span {
  flex: 1 1 0;
  height: 6px;
  border-radius: 999px;
  background: var(--track);
}
.segments span.is-used {
  background: var(--bs-primary);
}
.segments span.is-part {
  background: var(--message-accent-line);
}
.segments span.is-over {
  background: var(--message-high);
}

/* --- Merge field chip --------------------------------------- */
.merge {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  font-family: "SFMono-Regular", "Menlo", "Consolas", "Liberation Mono", monospace;
  font-size: 11.5px;
  font-weight: 500;
  padding: 3px 9px;
  border-radius: 6px;
  background: var(--tint-primary);
  color: var(--bs-primary);
  border: 1px solid transparent;
  transition: var(--transition);
  white-space: nowrap;
}
.merge i {
  font-size: 12px;
}
.merge:hover {
  border-color: var(--bs-primary);
  background: var(--bs-body-bg);
}

.merges {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
}

/* --- Recipient selection card ------------------------------- */
.pick {
  position: relative;
  height: 100%;
  display: flex;
  align-items: flex-start;
  gap: 11px;
  padding: 14px;
  border: 1px solid var(--bs-border-color);
  border-radius: var(--radius);
  background: var(--bs-body-bg);
  box-shadow: var(--shadow);
  transition: var(--transition);
  cursor: pointer;
}
.pick:hover {
  border-color: var(--message-accent-line);
  box-shadow: var(--shadow-lift);
}
.pick {
  /* Selected reads through the border and the tick, not a fill — a
     wall of filled cards would be unreadable. */
}
.pick.is-picked {
  border-color: var(--bs-primary);
  box-shadow: inset 0 0 0 1px var(--bs-primary), var(--shadow);
}
.pick.is-picked .pick-icon {
  background: var(--bs-primary);
  color: #fff;
}
.pick .pick-icon {
  width: 38px;
  height: 38px;
  flex-shrink: 0;
  border-radius: var(--radius-sm);
  background: var(--tint-primary);
  color: var(--bs-primary);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 19px;
  transition: var(--transition);
}
.pick .pick-text {
  flex: 1 1 auto;
  min-width: 0;
}
.pick .pick-text b {
  display: block;
  font-size: 13.5px;
  font-weight: 600;
  color: var(--bs-emphasis-color);
  margin-bottom: 2px;
}
.pick .pick-text .pick-n {
  font-size: 17px;
  font-weight: 700;
  color: var(--bs-emphasis-color);
  line-height: 1.2;
}
.pick .pick-text .pick-n small {
  font-size: 11.5px;
  font-weight: 400;
  color: var(--bs-secondary-color);
  margin-left: 4px;
}
.pick .pick-text .pick-last {
  display: block;
  font-size: 11px;
  color: var(--bs-secondary-color);
  margin-top: 6px;
  padding-top: 6px;
  border-top: 1px dashed var(--bs-border-color);
}
.pick .form-check-input {
  flex-shrink: 0;
  margin-top: 2px;
}

/* --- Upload dropzone ---------------------------------------- */
.dropzone {
  border: 1px dashed var(--border-strong);
  border-radius: var(--radius);
  background: var(--bs-body-bg);
  padding: 26px 20px;
  text-align: center;
  transition: var(--transition);
}
.dropzone:hover {
  border-color: var(--bs-primary);
  background: var(--tint-primary);
}
.dropzone > i {
  display: block;
  font-size: 30px;
  color: var(--bs-primary);
  margin-bottom: 8px;
}
.dropzone b {
  display: block;
  font-size: 14px;
  font-weight: 600;
  color: var(--bs-emphasis-color);
  margin-bottom: 3px;
}
.dropzone p {
  font-size: 12px;
  color: var(--bs-secondary-color);
  margin: 0 auto 12px;
  max-width: 44ch;
}

/* --- Mobile message preview --------------------------------- */
.phone {
  max-width: 300px;
  margin: 0 auto;
  /* always a dark bezel/status bar, like a phone's own chrome — not
     var(--bs-emphasis-color), which flips light in dark mode and left
     white text on a near-white bar; fixed to the colour light mode
     already rendered, so light mode is unchanged */
  border: 8px solid #202C4B;
  border-radius: 28px;
  background: var(--bs-secondary-bg);
  overflow: hidden;
  box-shadow: var(--shadow-lift);
}
.phone .phone-top {
  background: #202C4B;
  color: #fff;
  padding: 4px 14px 10px;
  text-align: center;
}
.phone .phone-top b {
  display: block;
  font-size: 12.5px;
  font-weight: 600;
}
.phone .phone-top small {
  font-size: 10.5px;
  opacity: 0.7;
}
.phone .phone-body {
  padding: 14px 12px 18px;
  min-height: 190px;
  background: var(--bs-secondary-bg);
}
.phone {
  /* The message as it lands: a received bubble, tail on the left. */
}
.phone .message-bubble {
  position: relative;
  background: var(--bs-body-bg);
  border: 1px solid var(--bs-border-color);
  border-radius: 14px 14px 14px 3px;
  padding: 10px 12px;
  font-size: 12.5px;
  line-height: 1.6;
  color: var(--bs-emphasis-color);
  box-shadow: var(--shadow);
}
.phone .message-bubble + .message-bubble {
  margin-top: 8px;
}
.phone .message-bubble mark {
  background: var(--tint-primary);
  color: var(--bs-primary);
  padding: 0 3px;
  border-radius: 3px;
  font-weight: 600;
}
.phone .bubble-time {
  display: block;
  font-size: 10px;
  color: var(--bs-secondary-color);
  margin: 5px 0 0 4px;
}

/* --- SMS log card ------------------------------------------- */
.log {
  position: relative;
  height: 100%;
  display: flex;
  flex-direction: column;
  border: 1px solid var(--bs-border-color);
  border-radius: var(--radius);
  background: var(--bs-body-bg);
  box-shadow: var(--shadow);
  padding: 14px;
  transition: var(--transition);
}
.log:hover {
  border-color: var(--message-accent-line);
  box-shadow: var(--shadow-lift);
}
.log {
  /* Delivery outcome as a corner flag rather than a full-width band. */
}
.log::after {
  content: "";
  position: absolute;
  top: 14px;
  right: 14px;
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--message-live);
}
.log.is-failed::after {
  background: var(--message-urgent);
}
.log.is-pending::after {
  background: var(--message-high);
}
.log.is-queued::after {
  background: var(--message-normal);
}
.log .log-title {
  font-size: 13.5px;
  font-weight: 600;
  color: var(--bs-emphasis-color);
  line-height: 1.35;
  margin: 0 18px 8px 0;
}
.log .log-to {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 12.5px;
  color: var(--bs-emphasis-color);
  margin-bottom: 10px;
}
.log .log-to i {
  width: 28px;
  height: 28px;
  flex-shrink: 0;
  border-radius: 8px;
  background: var(--bs-secondary-bg);
  color: var(--bs-secondary-color);
  display: inline-flex;
  align-items: center;
  justify-content: center;
  font-size: 14px;
}
.log .log-to small {
  display: block;
  font-size: 11px;
  color: var(--bs-secondary-color);
}
.log {
  /* A failure is stated, not hidden behind a status pill. */
}
.log .log-why {
  font-size: 11.5px;
  color: var(--message-urgent);
  background: var(--message-urgent-soft);
  border-radius: 6px;
  padding: 5px 8px;
  margin-top: 8px;
}
.log .log-footer {
  margin-top: auto;
  padding-top: 11px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  flex-wrap: wrap;
  border-top: 1px dashed var(--bs-border-color);
  font-size: 11px;
  color: var(--bs-secondary-color);
}

/* ============================================================
   10. WHATSAPP COMMUNICATION CENTER

   A conversation channel rather than a broadcast one, so the centre of
   this page is an inbox and a chat, not a composer. Everything already
   defined above — badges, rows, panels, template cards, action cards,
   dropzone, merge fields, offcanvas — is reused as-is.

   The one page-wide change is the accent: `.whatsapp` remaps the accent
   tokens to WhatsApp's green, so every shared component picks it up
   without a second copy of any rule. Put the class on the content
   wrapper, and on the offcanvas and modals, which live outside it.
   ============================================================ */
.whatsapp {
  --message-accent: rgb(35.3, 154.22, 92.82);
  --message-accent-line: rgb(167.8, 237.4, 193.8);
}

[data-bs-theme=dark] .whatsapp {
  --message-accent: rgb(93.68, 222.44, 141.78);
  --message-accent-line: rgba(37, 211, 102, .38);
}

/* --- Conversation inbox ------------------------------------- */
.inbox {
  display: flex;
  flex-direction: column;
  height: 100%;
  border: 1px solid var(--bs-border-color);
  border-radius: var(--radius);
  background: var(--bs-body-bg);
  box-shadow: var(--shadow);
  overflow: hidden;
}
.inbox .inbox-header {
  padding: 13px 14px;
  border-bottom: 1px solid var(--bs-border-color);
}
.inbox .inbox-list {
  flex: 1 1 auto;
  overflow-y: auto;
  max-height: 560px;
}
.inbox .inbox-list::-webkit-scrollbar {
  width: 5px;
}
.inbox .inbox-list::-webkit-scrollbar-thumb {
  background: var(--track);
  border-radius: 999px;
}
.inbox .inbox-footer {
  padding: 11px 14px;
  border-top: 1px solid var(--bs-border-color);
  background: var(--bs-secondary-bg);
  font-size: 11.5px;
  color: var(--bs-secondary-color);
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
}

/* Section label inside the list — Pinned, Today, Earlier. */
.inbox-section {
  position: sticky;
  top: 0;
  z-index: 1;
  padding: 7px 14px;
  font-size: 10.5px;
  font-weight: 600;
  letter-spacing: 0.09em;
  text-transform: uppercase;
  color: var(--bs-secondary-color);
  background: var(--bs-secondary-bg);
  border-bottom: 1px solid var(--bs-border-color);
}

/* A single conversation row. */
.thread {
  position: relative;
  display: flex;
  align-items: flex-start;
  gap: 11px;
  width: 100%;
  text-align: left;
  padding: 12px 14px;
  border: 0;
  border-bottom: 1px solid var(--bs-border-color);
  background: transparent;
  transition: var(--transition);
}
.thread:hover {
  background: var(--bs-secondary-bg);
}
.thread {
  /* Active thread carries a rail, not a fill, so the avatar and the
     preview text keep their contrast. */
}
.thread.is-active {
  background: var(--tint-primary);
}
.thread.is-active::before {
  content: "";
  position: absolute;
  left: 0;
  top: 0;
  bottom: 0;
  width: 3px;
  background: var(--bs-primary);
}
.thread.is-unread .thread-name, .thread.is-unread .thread-preview {
  color: var(--bs-emphasis-color);
  font-weight: 600;
}
.thread .thread-avatar {
  position: relative;
  flex: 0 0 auto;
}
.thread .thread-avatar img {
  width: 40px;
  height: 40px;
  border-radius: 50%;
  object-fit: cover;
}
.thread .thread-avatar {
  /* Presence dot, cut out of the avatar edge. */
}
.thread .thread-avatar::after {
  content: "";
  position: absolute;
  right: -1px;
  bottom: -1px;
  width: 11px;
  height: 11px;
  border-radius: 50%;
  background: var(--bs-secondary-color);
  border: 2px solid var(--bs-body-bg);
}
.thread .thread-avatar.is-online::after {
  background: var(--message-live);
}
.thread .thread-text {
  flex: 1 1 auto;
  min-width: 0;
}
.thread .thread-top {
  display: flex;
  align-items: baseline;
  gap: 8px;
  margin-bottom: 2px;
}
.thread .thread-name {
  flex: 1 1 auto;
  min-width: 0;
  font-size: 13.5px;
  font-weight: 500;
  color: var(--bs-emphasis-color);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.thread .thread-time {
  flex: 0 0 auto;
  font-size: 10.5px;
  color: var(--bs-secondary-color);
}
.thread .thread-preview {
  display: flex;
  align-items: center;
  gap: 5px;
  font-size: 12px;
  color: var(--bs-secondary-color);
  margin-bottom: 0;
}
.thread .thread-preview span {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.thread .thread-preview > i {
  flex-shrink: 0;
  font-size: 13px;
}
.thread .thread-meta {
  display: flex;
  align-items: center;
  gap: 5px;
  margin-top: 6px;
  flex-wrap: wrap;
}
.thread .thread-n {
  flex: 0 0 auto;
  min-width: 18px;
  height: 18px;
  padding: 0 5px;
  border-radius: 999px;
  background: var(--bs-primary);
  color: #fff;
  font-size: 10.5px;
  font-weight: 700;
  display: inline-flex;
  align-items: center;
  justify-content: center;
}
.thread .thread-pin {
  font-size: 13px;
  color: var(--bs-secondary-color);
}

/* --- Chat workspace ----------------------------------------- */
.message-chat {
  display: flex;
  flex-direction: column;
  height: 100%;
  border: 1px solid var(--bs-border-color);
  border-radius: var(--radius);
  background: var(--bs-body-bg);
  box-shadow: var(--shadow);
  overflow: hidden;
}
.message-chat .message-chat-header {
  display: flex;
  align-items: center;
  gap: 11px;
  padding: 12px 15px;
  border-bottom: 1px solid var(--bs-border-color);
}
.message-chat .message-chat-header img {
  width: 40px;
  height: 40px;
  border-radius: 50%;
  object-fit: cover;
  flex-shrink: 0;
}
.message-chat .message-chat-header .chat-who {
  flex: 1 1 auto;
  min-width: 0;
}
.message-chat .message-chat-header .chat-who b {
  display: block;
  font-size: 14.5px;
  font-weight: 600;
  color: var(--bs-emphasis-color);
  line-height: 1.3;
}
.message-chat .message-chat-header .chat-who small {
  font-size: 11.5px;
  color: var(--bs-secondary-color);
}
.message-chat {
  /* The canvas carries the faint pattern a messaging app has, so the
     bubbles read as a conversation rather than a list of rows. */
}
.message-chat .chat-canvas {
  flex: 1 1 auto;
  overflow-y: auto;
  max-height: 480px;
  padding: 18px 16px;
  background-color: var(--bs-secondary-bg);
  background-image: radial-gradient(var(--border-strong) 1px, transparent 1px);
  background-size: 22px 22px;
}
.message-chat .chat-canvas::-webkit-scrollbar {
  width: 5px;
}
.message-chat .chat-canvas::-webkit-scrollbar-thumb {
  background: var(--track);
  border-radius: 999px;
}

/* Day divider inside the canvas. */
.message-day {
  display: flex;
  align-items: center;
  justify-content: center;
  margin: 4px 0 16px;
}
.message-day span {
  font-size: 10.5px;
  font-weight: 600;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--bs-secondary-color);
  background: var(--bs-body-bg);
  border: 1px solid var(--bs-border-color);
  border-radius: 999px;
  padding: 3px 12px;
}

/* --- Message bubble ----------------------------------------- */
.message-message {
  display: flex;
  margin-bottom: 12px;
}
.message-message .message-in {
  max-width: 78%;
  background: var(--bs-body-bg);
  border: 1px solid var(--bs-border-color);
  border-radius: 14px 14px 14px 3px;
  padding: 9px 12px;
  box-shadow: var(--shadow);
}
.message-message .message-in p {
  font-size: 13px;
  line-height: 1.6;
  color: var(--bs-emphasis-color);
  margin-bottom: 0;
}
.message-message .message-meta {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  gap: 4px;
  font-size: 10px;
  color: var(--bs-secondary-color);
  margin-top: 4px;
  /* Read receipt — the double tick, blue once seen. */
}
.message-message .message-meta i.is-read {
  color: var(--message-normal);
}
.message-message {
  /* Outgoing sits right, tinted, with the tail mirrored. */
}
.message-message.is-out {
  justify-content: flex-end;
}
.message-message.is-out .message-in {
  background: var(--tint-primary);
  border-color: transparent;
  border-radius: 14px 14px 3px 14px;
}
.message-message {
  /* An outgoing message sent from a registered template is labelled,
     because a template send is billed and a session reply is not. */
}
.message-message .message-template {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  font-size: 10px;
  font-weight: 600;
  color: var(--bs-primary);
  margin-bottom: 5px;
}

/* Attachment bubbles: document, voice note and image. */
.message-attachment {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 8px;
  border-radius: 9px;
  background: var(--bs-secondary-bg);
  min-width: 210px;
}
.message-attachment > i {
  width: 34px;
  height: 34px;
  flex-shrink: 0;
  border-radius: 8px;
  background: var(--bs-body-bg);
  color: var(--bs-primary);
  display: inline-flex;
  align-items: center;
  justify-content: center;
  font-size: 17px;
}
.message-attachment .attachment-text {
  flex: 1 1 auto;
  min-width: 0;
  font-size: 12px;
  font-weight: 500;
  color: var(--bs-emphasis-color);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.message-attachment .attachment-text small {
  display: block;
  font-size: 10.5px;
  font-weight: 400;
  color: var(--bs-secondary-color);
}

/* Voice note — a static waveform, not a control. */
.wave {
  display: flex;
  align-items: center;
  gap: 2px;
  flex: 1 1 auto;
  height: 22px;
}
.wave span {
  flex: 1 1 0;
  background: var(--message-accent-line);
  border-radius: 999px;
  min-height: 3px;
}
.wave .h-1 {
  height: 25%;
}
.wave .h-2 {
  height: 45%;
}
.wave .h-3 {
  height: 70%;
}
.wave .h-4 {
  height: 100%;
}
.wave .h-5 {
  height: 55%;
}

.message-image {
  display: block;
  width: 190px;
  max-width: 100%;
  border-radius: 9px;
  margin-bottom: 6px;
}

/* --- Composer ----------------------------------------------- */
.composer {
  border-top: 1px solid var(--bs-border-color);
  background: var(--bs-body-bg);
  padding: 11px 14px;
}
.composer .composer-row {
  display: flex;
  align-items: flex-end;
  gap: 8px;
}
.composer .composer-row .form-control {
  resize: none;
}
.composer .composer-tools {
  display: flex;
  align-items: center;
  gap: 3px;
  flex-shrink: 0;
}
.composer .composer-tools button {
  width: 34px;
  height: 34px;
  border: 0;
  border-radius: 9px;
  background: transparent;
  color: var(--bs-secondary-color);
  display: inline-flex;
  align-items: center;
  justify-content: center;
  font-size: 17px;
  transition: var(--transition);
}
.composer .composer-tools button:hover {
  background: var(--bs-secondary-bg);
  color: var(--bs-primary);
}

/* Quick reply chip above the composer. */
.quick-reply {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  font-size: 11.5px;
  font-weight: 500;
  padding: 4px 11px;
  border-radius: 999px;
  background: var(--bs-body-bg);
  color: var(--bs-emphasis-color);
  border: 1px solid var(--bs-border-color);
  white-space: nowrap;
  transition: var(--transition);
}
.quick-reply i {
  font-size: 12px;
  color: var(--bs-primary);
}
.quick-reply:hover {
  border-color: var(--bs-primary);
  background: var(--tint-primary);
}

.qrs {
  display: flex;
  gap: 6px;
  flex-wrap: wrap;
  margin-bottom: 9px;
}

/* --- Broadcast queue card ----------------------------------- */
.message-quote {
  position: relative;
  height: 100%;
  display: flex;
  flex-direction: column;
  padding: 14px 14px 14px 17px;
  border: 1px solid var(--bs-border-color);
  border-radius: var(--radius);
  background: var(--bs-body-bg);
  box-shadow: var(--shadow);
  transition: var(--transition);
}
.message-quote:hover {
  border-color: var(--message-accent-line);
  box-shadow: var(--shadow-lift);
}
.message-quote::before {
  content: "";
  position: absolute;
  left: 0;
  top: 0;
  bottom: 0;
  width: 3px;
  border-radius: var(--radius) 0 0 var(--radius);
  background: var(--message-normal);
}
.message-quote.is-draft::before {
  background: var(--message-draft);
}
.message-quote.is-processing::before {
  background: var(--message-high);
}
.message-quote.is-sent::before, .message-quote.is-delivered::before {
  background: var(--message-live);
}
.message-quote.is-failed::before {
  background: var(--message-urgent);
}
.message-quote.is-cancelled {
  opacity: 0.72;
}
.message-quote.is-cancelled::before {
  background: var(--bs-secondary-color);
}
.message-quote .message-quote-title {
  font-size: 13.5px;
  font-weight: 600;
  color: var(--bs-emphasis-color);
  line-height: 1.35;
  margin-bottom: 6px;
}
.message-quote .message-quote-message {
  font-size: 12px;
  color: var(--bs-secondary-color);
  margin-bottom: 10px;
  display: -webkit-box;
  -webkit-line-clamp: 2;
  line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
}
.message-quote .message-quote-footer {
  margin-top: auto;
  padding-top: 11px;
  border-top: 1px dashed var(--bs-border-color);
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  flex-wrap: wrap;
  font-size: 11px;
  color: var(--bs-secondary-color);
}

/* --- Media library tile ------------------------------------- */
.message-media {
  position: relative;
  height: 100%;
  display: flex;
  flex-direction: column;
  border: 1px solid var(--bs-border-color);
  border-radius: var(--radius);
  background: var(--bs-body-bg);
  box-shadow: var(--shadow);
  overflow: hidden;
  transition: var(--transition);
}
.message-media:hover {
  border-color: var(--message-accent-line);
  box-shadow: var(--shadow-lift);
  transform: translateY(-2px);
}
.message-media .media-thumb {
  position: relative;
  height: 104px;
  background: var(--bs-secondary-bg);
  display: flex;
  align-items: center;
  justify-content: center;
  border-bottom: 1px solid var(--bs-border-color);
}
.message-media .media-thumb img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}
.message-media .media-thumb > i {
  font-size: 30px;
  color: var(--bs-primary);
}
.message-media .media-thumb .media-kind {
  position: absolute;
  top: 8px;
  left: 8px;
  font-size: 10px;
  font-weight: 600;
  letter-spacing: 0.05em;
  text-transform: uppercase;
  padding: 2px 8px;
  border-radius: 999px;
  background: rgba(20, 20, 43, 0.72);
  color: #fff;
  backdrop-filter: blur(4px);
}
.message-media .message-media-body {
  padding: 11px 12px;
  flex: 1 1 auto;
}
.message-media .message-media-body b {
  display: block;
  font-size: 12.5px;
  font-weight: 600;
  color: var(--bs-emphasis-color);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.message-media .message-media-body small {
  font-size: 11px;
  color: var(--bs-secondary-color);
}
.message-media .media-footer {
  display: flex;
  gap: 6px;
  padding: 10px 12px;
  border-top: 1px solid var(--bs-border-color);
  background: var(--bs-secondary-bg);
}

/* ============================================================
   11. NOTIFICATION & PARENT COMMUNICATION CENTER

   Three channels governed together — email, push and the parent
   communications that ride on either. Almost everything is reused from
   the sections above: channel cards, audience cards, template cards,
   log cards, action cards, panels, rows, badges, dropzone, merge
   fields, handset preview and the offcanvas.

   What this page adds is the distinction it lives on: delivered is not
   read. A notification card states both, stacked, because a 99%
   delivery rate against a 40% read rate is the whole story. `.notification`
   remaps the accent to a violet so the centre is not mistaken for the
   announcements desk; put it on the content wrapper and on the
   offcanvas and modals, which sit outside it.
   ============================================================ */
.notification {
  --message-accent: rgb(81.7, 53.8, 150.6);
  --message-accent-line: rgb(203.32, 188.02, 230.52);
}

[data-bs-theme=dark] .notification {
  --message-accent: rgb(160.76, 132.86, 210.36);
  --message-accent-line: rgba(103, 58, 183, .44);
}

/* --- Notification card -------------------------------------- */
.message-note-item {
  position: relative;
  height: 100%;
  display: flex;
  flex-direction: column;
  border: 1px solid var(--bs-border-color);
  border-radius: var(--radius);
  background: var(--bs-body-bg);
  box-shadow: var(--shadow);
  overflow: hidden;
  transition: var(--transition);
}
.message-note-item:hover {
  border-color: var(--message-accent-line);
  box-shadow: var(--shadow-lift);
  transform: translateY(-2px);
}
.message-note-item {
  /* Priority rail. */
}
.message-note-item::before {
  content: "";
  position: absolute;
  left: 0;
  top: 0;
  bottom: 0;
  width: 3px;
  background: var(--message-normal);
  z-index: 2;
}
.message-note-item.is-urgent::before {
  background: var(--message-urgent);
}
.message-note-item.is-high::before {
  background: var(--message-high);
}
.message-note-item.is-sent::before {
  background: var(--message-live);
}
.message-note-item.is-draft {
  border-style: dashed;
}
.message-note-item.is-draft::before {
  background: var(--message-draft);
}
.message-note-item.is-archived {
  opacity: 0.72;
}
.message-note-item.is-archived::before {
  background: var(--bs-secondary-color);
}
.message-note-item .note-body {
  padding: 14px 15px;
  flex: 1 1 auto;
}
.message-note-item .note-title {
  font-size: 15px;
  font-weight: 600;
  color: var(--bs-emphasis-color);
  line-height: 1.35;
  margin: 6px 0 5px;
}
.message-note-item .note-title a {
  color: inherit;
}
.message-note-item .note-description {
  font-size: 12.5px;
  color: var(--bs-secondary-color);
  margin-bottom: 0;
  display: -webkit-box;
  -webkit-line-clamp: 2;
  line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
}
.message-note-item .note-facts {
  display: flex;
  flex-wrap: wrap;
  gap: 6px 14px;
  margin-top: 11px;
  font-size: 11.5px;
  color: var(--bs-secondary-color);
}
.message-note-item .note-facts span {
  display: inline-flex;
  align-items: center;
  gap: 5px;
}
.message-note-item .note-facts b {
  color: var(--bs-emphasis-color);
  font-weight: 600;
}
.message-note-item {
  /* Author line — who sent it is part of the record, not metadata. */
}
.message-note-item .message-note-by {
  display: flex;
  align-items: center;
  gap: 7px;
  margin-top: 12px;
  padding-top: 11px;
  border-top: 1px dashed var(--bs-border-color);
  font-size: 11.5px;
  color: var(--bs-secondary-color);
}
.message-note-item .message-note-by img {
  width: 22px;
  height: 22px;
  border-radius: 50%;
  object-fit: cover;
}
.message-note-item .message-note-by b {
  color: var(--bs-emphasis-color);
  font-weight: 600;
}
.message-note-item .note-footer {
  margin-top: auto;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  flex-wrap: wrap;
  padding: 11px 15px;
  border-top: 1px solid var(--bs-border-color);
  background: var(--bs-secondary-bg);
}

/* --- Delivered versus read ---------------------------------- */
.dual {
  padding: 0 15px 12px;
}
.dual .dual-row {
  display: flex;
  align-items: center;
  gap: 9px;
}
.dual .dual-row + .dual-row {
  margin-top: 6px;
}
.dual .dual-row > span:first-child {
  flex: 0 0 62px;
  font-size: 10.5px;
  font-weight: 600;
  letter-spacing: 0.05em;
  text-transform: uppercase;
  color: var(--bs-secondary-color);
}
.dual .dual-row .dual-bar {
  flex: 1 1 auto;
  height: 5px;
  border-radius: 999px;
  background: var(--track);
  overflow: hidden;
}
.dual .dual-row .dual-bar span {
  display: block;
  height: 100%;
  border-radius: 999px;
  background: var(--message-live);
}
.dual .dual-row {
  /* The read bar is deliberately the accent, not green — read is a
     different achievement from delivered and should not look like
     the same success. */
}
.dual .dual-row.is-read .dual-bar span {
  background: var(--bs-primary);
}
.dual .dual-row > b {
  flex: 0 0 auto;
  font-size: 11.5px;
  font-weight: 600;
  color: var(--bs-emphasis-color);
  min-width: 34px;
  text-align: right;
}

/* --- Parent communication card ------------------------------ */
.message-push {
  height: 100%;
  display: flex;
  flex-direction: column;
  border: 1px solid var(--bs-border-color);
  border-radius: var(--radius);
  background: var(--bs-body-bg);
  box-shadow: var(--shadow);
  padding: 15px;
  transition: var(--transition);
}
.message-push:hover {
  border-color: var(--message-accent-line);
  box-shadow: var(--shadow-lift);
}
.message-push .push-top {
  display: flex;
  align-items: center;
  gap: 10px;
  margin-bottom: 11px;
}
.message-push .push-top .push-icon {
  width: 36px;
  height: 36px;
  flex-shrink: 0;
  border-radius: var(--radius-sm);
  background: var(--tint-primary);
  color: var(--bs-primary);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 18px;
}
.message-push .push-top .push-name {
  flex: 1 1 auto;
  min-width: 0;
  font-size: 14px;
  font-weight: 600;
  color: var(--bs-emphasis-color);
  margin-bottom: 0;
}
.message-push {
  /* The message itself, quoted — the point of a communication card is
     what it actually says, not its configuration. */
}
.message-push .push-quote {
  position: relative;
  font-size: 12.5px;
  line-height: 1.6;
  color: var(--bs-emphasis-color);
  background: var(--bs-secondary-bg);
  border-radius: var(--radius-sm);
  padding: 10px 12px 10px 26px;
  margin-bottom: 12px;
}
.message-push .push-quote::before {
  content: "“";
  position: absolute;
  left: 9px;
  top: 4px;
  font-size: 22px;
  line-height: 1;
  color: var(--message-accent-line);
}
.message-push .push-footer {
  margin-top: auto;
  padding-top: 11px;
  border-top: 1px dashed var(--bs-border-color);
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  flex-wrap: wrap;
  font-size: 11.5px;
  color: var(--bs-secondary-color);
}

/*-----------------
	Automation — workflow rule components

	A shared vocabulary for the Workflow Rules Center: the rules
	themselves, the modules they belong to, the trigger that starts
	them, the conditions that gate them and the actions they run.
	Class prefix `wfx-`.

	The visual language is a rule engine, not a flowchart editor. A
	workflow is drawn as the sentence it actually is — WHEN something
	happens, IF these conditions hold, THEN run these actions — with
	the three clauses set apart from each other and the action chain
	numbered in the order it executes. Conditions carry their boolean
	operator on the connector between them rather than inside a form
	control, because AND and OR are the part people misread.

	Contents
	  1. Tokens + shared pieces
	  2. Workflow rule cards
	  3. Trigger / condition / action clauses
	  4. Action chain
	  5. Category cards
	  6. Template cards
	  7. Conditions builder
	  8. Quick actions
	  9. Offcanvas, panels and modals
-----------------*/
/* ============================================================
   1. TOKENS + SHARED PIECES
   ============================================================ */
:root {
  /* A deep engineered blue-grey, mixed rather than taken straight, so
     the automation console reads as machinery rather than as another
     communication surface. */
  --rule-accent: rgb(22.14, 77.06, 150.4);
  --rule-accent-line: rgb(178.2, 205.72, 239);
  /* The three clauses each keep their own colour throughout the page. */
  --rule-when: #4A00E5;
  --rule-when-soft: rgb(238.71, 232.05, 252.66);
  --rule-if: #EAB300;
  --rule-if-soft: #FEF8EA;
  --rule-then: #1ABE17;
  --rule-then-soft: #E8F9E8;
  --rule-on: #1ABE17;
  --rule-on-soft: #E8F9E8;
  --rule-stop: #E82646;
  --rule-stop-soft: #FDE9ED;
}

[data-bs-theme=dark] {
  --rule-accent-line: rgba(15, 101, 205, .4);
  --rule-when-soft: rgba(74, 0, 229, .18);
}

.rule-metric-label {
  display: block;
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--bs-secondary-color);
  margin-bottom: 4px;
}

.rule-section-header {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 14px;
  flex-wrap: wrap;
  margin-bottom: 16px;
}
.rule-section-header h2 {
  font-size: 20px;
  font-weight: 700;
  color: var(--bs-emphasis-color);
  margin-bottom: 3px;
}
.rule-section-header p {
  font-size: 13px;
  color: var(--bs-secondary-color);
  margin-bottom: 0;
  max-width: 74ch;
}

.rule-status-badge {
  /* geometry, typography and surface come from the shared badge component */
}
.rule-status-badge i {
  font-size: 12px;
}
.rule-status-badge.is-on {
  background: var(--rule-on-soft);
  color: var(--rule-on);
  border-color: transparent;
}
.rule-status-badge.is-off {
  border-style: dashed;
}
.rule-status-badge.is-draft {
  background: var(--rule-when-soft);
  color: var(--rule-when);
  border-color: transparent;
}
.rule-status-badge.is-warn {
  background: var(--rule-if-soft);
  color: rgb(172.8, 132.1846153846, 0);
  border-color: transparent;
}
.rule-status-badge.is-stop {
  background: var(--rule-stop-soft);
  color: var(--rule-stop);
  border-color: transparent;
}
.rule-status-badge.is-accent {
  background: var(--tint-primary);
  color: var(--bs-primary);
  border-color: transparent;
}

/* A field or variable, always monospace and always selectable. */
.key {
  font-family: var(--font-mono);
  font-size: 11.5px;
  color: var(--bs-emphasis-color);
  background: var(--bs-secondary-bg);
  border: 1px solid var(--bs-border-color);
  border-radius: 5px;
  padding: 1px 6px;
  display: inline-block;
  max-width: 100%;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  vertical-align: middle;
}

/* Priority marker — three stacked bars, filled to the level set. */
.priority {
  display: inline-flex;
  align-items: flex-end;
  gap: 2px;
  height: 12px;
  vertical-align: middle;
}
.priority span {
  width: 3px;
  border-radius: 1px;
  background: var(--track);
}
.priority span:nth-child(1) {
  height: 5px;
}
.priority span:nth-child(2) {
  height: 8px;
}
.priority span:nth-child(3) {
  height: 12px;
}
.priority span.is-lit {
  background: var(--bs-primary);
}
.priority.is-high span.is-lit {
  background: var(--rule-if);
}
.priority.is-critical span.is-lit {
  background: var(--rule-stop);
}

.rule-info-row {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 9px 0;
  border-bottom: 1px dashed var(--bs-border-color);
}
.rule-info-row:last-child {
  border-bottom: 0;
  padding-bottom: 0;
}
.rule-info-row:first-child {
  padding-top: 0;
}
.rule-info-row .rule-row-key {
  flex: 1 1 auto;
  font-size: 13px;
  font-weight: 500;
  color: var(--bs-emphasis-color);
}
.rule-info-row .rule-row-key small {
  display: block;
  font-size: 11.5px;
  font-weight: 400;
  color: var(--bs-secondary-color);
  margin-top: 1px;
}
.rule-info-row .rule-row-value {
  flex: 0 0 auto;
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 13px;
  color: var(--bs-emphasis-color);
}

/* ============================================================
   2. WORKFLOW RULE CARDS
   ============================================================ */
.rule {
  position: relative;
  height: 100%;
  display: flex;
  flex-direction: column;
  border: 1px solid var(--bs-border-color);
  border-radius: var(--radius);
  background: var(--bs-body-bg);
  box-shadow: var(--shadow);
  overflow: hidden;
  transition: var(--transition);
}
.rule:hover {
  border-color: var(--rule-accent-line);
  box-shadow: var(--shadow-lift);
  transform: translateY(-2px);
}
.rule {
  /* Live rail. A disabled rule loses it entirely rather than changing
     colour — the absence is what should register. */
}
.rule::before {
  content: "";
  position: absolute;
  left: 0;
  top: 0;
  bottom: 0;
  width: 3px;
  background: var(--rule-on);
  z-index: 2;
}
.rule.is-off {
  background: var(--bs-secondary-bg);
}
.rule.is-off::before {
  background: transparent;
}
.rule.is-draft {
  border-style: dashed;
}
.rule.is-draft::before {
  background: var(--rule-when);
}
.rule.is-error::before {
  background: var(--rule-stop);
}
.rule .rule-header {
  display: flex;
  align-items: flex-start;
  gap: 11px;
  padding: 14px 15px 10px;
}
.rule .rule-header .rule-icon {
  width: 36px;
  height: 36px;
  flex-shrink: 0;
  border-radius: var(--radius-sm);
  background: var(--tint-primary);
  color: var(--bs-primary);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 18px;
}
.rule .rule-header .rule-name {
  font-size: 14.5px;
  font-weight: 600;
  color: var(--bs-emphasis-color);
  line-height: 1.35;
  margin-bottom: 3px;
}
.rule .rule-header .rule-name a {
  color: inherit;
}
.rule .rule-header .rule-description {
  font-size: 12px;
  color: var(--bs-secondary-color);
  margin-bottom: 0;
  display: -webkit-box;
  -webkit-line-clamp: 2;
  line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
}
.rule .rule-clauses {
  padding: 0 15px;
}
.rule .rule-meta {
  display: flex;
  flex-wrap: wrap;
  gap: 6px 14px;
  padding: 12px 15px 0;
  font-size: 11.5px;
  color: var(--bs-secondary-color);
}
.rule .rule-meta span {
  display: inline-flex;
  align-items: center;
  gap: 5px;
}
.rule .rule-meta b {
  color: var(--bs-emphasis-color);
  font-weight: 600;
}
.rule .rule-by {
  display: flex;
  align-items: center;
  gap: 7px;
  margin: 12px 15px 0;
  padding-top: 11px;
  border-top: 1px dashed var(--bs-border-color);
  font-size: 11.5px;
  color: var(--bs-secondary-color);
}
.rule .rule-by img {
  width: 22px;
  height: 22px;
  border-radius: 50%;
  object-fit: cover;
}
.rule .rule-by b {
  color: var(--bs-emphasis-color);
  font-weight: 600;
}
.rule .rule-footer {
  margin-top: auto;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  flex-wrap: wrap;
  padding: 11px 15px;
  margin-top: 12px;
  border-top: 1px solid var(--bs-border-color);
  background: var(--bs-secondary-bg);
}

/* ============================================================
   3. TRIGGER / CONDITION / ACTION CLAUSES

   The rule read as a sentence. The keyword sits in the gutter so the
   three clauses line up down the left edge of every card on the page.
   ============================================================ */
.clause {
  position: relative;
  padding: 7px 10px 7px 54px;
  border-radius: var(--radius-sm);
  background: var(--bs-secondary-bg);
  font-size: 12.5px;
  line-height: 1.5;
  color: var(--bs-emphasis-color);
}
.clause + .clause {
  margin-top: 5px;
}
.clause::before {
  content: attr(data-kw);
  position: absolute;
  left: 10px;
  top: 8px;
  font-family: var(--font-mono);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.06em;
  color: var(--bs-primary);
}
.clause.is-when {
  background: var(--rule-when-soft);
}
.clause.is-when::before {
  color: var(--rule-when);
}
.clause.is-if {
  background: var(--rule-if-soft);
}
.clause.is-if::before {
  color: rgb(162.6, 124.3820512821, 0);
}
.clause.is-then {
  background: var(--rule-then-soft);
}
.clause.is-then::before {
  color: var(--rule-then);
}
.clause code {
  font-family: var(--font-mono);
  font-size: 11.5px;
  color: var(--bs-emphasis-color);
  background: var(--bs-body-bg);
  border: 1px solid var(--bs-border-color);
  border-radius: 5px;
  padding: 0 4px;
}

/* ============================================================
   4. ACTION CHAIN
   ============================================================ */
.chain {
  list-style: none;
  padding: 0;
  margin: 0;
  counter-reset: wfx-step;
}
.chain li {
  position: relative;
  counter-increment: wfx-step;
  display: flex;
  align-items: flex-start;
  gap: 11px;
  padding: 10px 0;
}
.chain li + li {
  border-top: 1px dashed var(--bs-border-color);
}
.chain li {
  /* The execution order is the point, so it is numbered rather than
     bulleted, and the number is what the eye lands on. */
}
.chain li::before {
  content: counter(wfx-step);
  flex: 0 0 auto;
  width: 24px;
  height: 24px;
  border-radius: 50%;
  background: var(--rule-then-soft);
  color: var(--rule-then);
  font-family: var(--font-mono);
  font-size: 11px;
  font-weight: 700;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  margin-top: 1px;
}
.chain li.is-skipped {
  opacity: 0.6;
}
.chain li.is-skipped::before {
  background: var(--bs-secondary-bg);
  color: var(--bs-secondary-color);
}
.chain li.is-failed::before {
  background: var(--rule-stop-soft);
  color: var(--rule-stop);
}
.chain .chain-text {
  flex: 1 1 auto;
  min-width: 0;
}
.chain .chain-text b {
  display: block;
  font-size: 13px;
  font-weight: 600;
  color: var(--bs-emphasis-color);
  margin-bottom: 2px;
}
.chain .chain-text small {
  font-size: 11.5px;
  color: var(--bs-secondary-color);
}

/* Compact action pip row, used on the rule cards. */
.actions {
  display: inline-flex;
  gap: 4px;
}
.actions .rule-action {
  width: 24px;
  height: 24px;
  border-radius: 7px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  font-size: 13px;
  background: var(--rule-then-soft);
  color: var(--rule-then);
}

/* ============================================================
   5. CATEGORY CARDS
   ============================================================ */
.rule-category {
  display: flex;
  align-items: center;
  gap: 11px;
  width: 100%;
  height: 100%;
  text-align: left;
  padding: 14px;
  border: 1px solid var(--bs-border-color);
  border-radius: var(--radius);
  background: var(--bs-body-bg);
  box-shadow: var(--shadow);
  transition: var(--transition);
}
.rule-category i.category-icon {
  width: 38px;
  height: 38px;
  flex-shrink: 0;
  border-radius: var(--radius-sm);
  background: var(--tint-primary);
  color: var(--bs-primary);
  display: inline-flex;
  align-items: center;
  justify-content: center;
  font-size: 19px;
  transition: var(--transition);
}
.rule-category .category-text {
  flex: 1 1 auto;
  min-width: 0;
}
.rule-category .category-text b {
  display: block;
  font-size: 13.5px;
  font-weight: 600;
  color: var(--bs-emphasis-color);
  margin-bottom: 2px;
}
.rule-category .category-text small {
  font-size: 11.5px;
  color: var(--bs-secondary-color);
}
.rule-category .category-n {
  flex: 0 0 auto;
  font-size: 17px;
  font-weight: 700;
  color: var(--bs-emphasis-color);
}
.rule-category:hover {
  border-color: var(--rule-accent-line);
  box-shadow: var(--shadow-lift);
  transform: translateY(-2px);
}
.rule-category:hover i.category-icon {
  background: var(--bs-primary);
  color: #fff;
}
.rule-category.is-empty {
  border-style: dashed;
}
.rule-category.is-empty .category-n {
  color: var(--bs-secondary-color);
}

/* ============================================================
   6. TEMPLATE CARDS
   ============================================================ */
.rule-template {
  height: 100%;
  display: flex;
  flex-direction: column;
  border: 1px solid var(--bs-border-color);
  border-radius: var(--radius);
  background: var(--bs-body-bg);
  box-shadow: var(--shadow);
  overflow: hidden;
  transition: var(--transition);
}
.rule-template:hover {
  border-color: var(--rule-accent-line);
  box-shadow: var(--shadow-lift);
  transform: translateY(-2px);
}
.rule-template .template-header {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 13px 15px;
  border-bottom: 1px solid var(--bs-border-color);
}
.rule-template .template-header .template-icon {
  width: 34px;
  height: 34px;
  flex-shrink: 0;
  border-radius: var(--radius-sm);
  background: var(--tint-primary);
  color: var(--bs-primary);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 17px;
}
.rule-template .template-header .template-name {
  flex: 1 1 auto;
  min-width: 0;
  font-size: 13.5px;
  font-weight: 600;
  color: var(--bs-emphasis-color);
  margin-bottom: 0;
}
.rule-template .rule-template-body {
  padding: 13px 15px;
  flex: 1 1 auto;
}
.rule-template .rule-template-body p {
  font-size: 12px;
  color: var(--bs-secondary-color);
  margin-bottom: 10px;
}
.rule-template .rule-template-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  padding: 11px 15px;
  border-top: 1px solid var(--bs-border-color);
  background: var(--bs-secondary-bg);
  font-size: 11.5px;
  color: var(--bs-secondary-color);
}

/* ============================================================
   7. CONDITIONS BUILDER
   ============================================================ */
.builder {
  border: 1px solid var(--bs-border-color);
  border-radius: var(--radius);
  background: var(--bs-body-bg);
  box-shadow: var(--shadow);
  overflow: hidden;
}
.builder .builder-header {
  display: flex;
  align-items: center;
  gap: 11px;
  padding: 13px 16px;
  border-bottom: 1px solid var(--bs-border-color);
}
.builder .builder-header .builder-icon {
  width: 34px;
  height: 34px;
  flex-shrink: 0;
  border-radius: var(--radius-sm);
  background: var(--rule-if-soft);
  color: rgb(162.6, 124.3820512821, 0);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 17px;
}
.builder .builder-header .builder-title {
  font-size: 14px;
  font-weight: 600;
  color: var(--bs-emphasis-color);
  margin-bottom: 1px;
}
.builder .builder-header p {
  font-size: 12px;
  color: var(--bs-secondary-color);
  margin-bottom: 0;
}
.builder .builder-body {
  padding: 16px;
}
.builder .builder-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  flex-wrap: wrap;
  padding: 12px 16px;
  border-top: 1px solid var(--bs-border-color);
  background: var(--bs-secondary-bg);
  font-size: 12px;
  color: var(--bs-secondary-color);
}

/* A condition group — an indented block sharing one boolean operator. */
.group {
  position: relative;
  border: 1px solid var(--bs-border-color);
  border-radius: var(--radius-sm);
  background: var(--bs-secondary-bg);
  padding: 12px 12px 12px 16px;
}
.group + .group {
  margin-top: 26px;
}
.group {
  /* The bracket down the left edge is what makes the grouping legible
     at a glance, which is exactly where nested rules go wrong. */
}
.group::before {
  content: "";
  position: absolute;
  left: 6px;
  top: 12px;
  bottom: 12px;
  width: 2px;
  border-radius: 2px;
  background: var(--rule-accent-line);
}

.condition {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-wrap: wrap;
  padding: 8px 10px;
  border: 1px solid var(--bs-border-color);
  border-radius: var(--radius-sm);
  background: var(--bs-body-bg);
  font-size: 12.5px;
  color: var(--bs-emphasis-color);
}
.condition .condition-op {
  font-family: var(--font-mono);
  font-size: 11.5px;
  color: var(--bs-secondary-color);
}
.condition .form-select-sm,
.condition .form-control-sm {
  width: auto;
  min-width: 120px;
  font-size: 12.5px;
}
.condition .condition-x {
  margin-left: auto;
  border: 0;
  background: transparent;
  color: var(--bs-secondary-color);
  font-size: 15px;
  line-height: 1;
  padding: 2px;
}
.condition .condition-x:hover {
  color: var(--rule-stop);
}

/* The boolean connector between two conditions — a pill on the rule
   line, so AND and OR cannot be skimmed past. */
.join {
  display: flex;
  align-items: center;
  gap: 8px;
  margin: 8px 0;
}
.join::before, .join::after {
  content: "";
  flex: 1 1 auto;
  height: 1px;
  background: var(--bs-border-color);
}
.join .join-pill {
  flex: 0 0 auto;
  display: inline-flex;
  border-radius: 999px;
  border: 1px solid var(--bs-border-color);
  background: var(--bs-body-bg);
  padding: 2px;
  overflow: hidden;
}
.join .join-pill button {
  border: 0;
  background: transparent;
  border-radius: 999px;
  padding: 2px 12px;
  font-family: var(--font-mono);
  font-size: 10.5px;
  font-weight: 700;
  letter-spacing: 0.06em;
  color: var(--bs-secondary-color);
  transition: var(--transition);
}
.join .join-pill button.is-active {
  background: var(--bs-primary);
  color: #fff;
}

/* A variable chip, insertable into a condition value. */
.variable {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  font-family: var(--font-mono);
  font-size: 11.5px;
  padding: 3px 9px;
  border-radius: 6px;
  background: var(--tint-primary);
  color: var(--bs-primary);
  border: 1px solid transparent;
  transition: var(--transition);
  white-space: nowrap;
}
.variable i {
  font-size: 12px;
}
.variable:hover {
  border-color: var(--bs-primary);
  background: var(--bs-body-bg);
}

.vars {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
}

/* ============================================================
   8. QUICK ACTIONS
   ============================================================ */
.rule-quick-action {
  display: flex;
  align-items: center;
  gap: 12px;
  width: 100%;
  height: 100%;
  text-align: left;
  padding: 15px;
  border: 1px solid var(--bs-border-color);
  border-radius: var(--radius);
  background: var(--bs-body-bg);
  box-shadow: var(--shadow);
  transition: var(--transition);
}
.rule-quick-action i.rule-action-icon {
  width: 40px;
  height: 40px;
  flex-shrink: 0;
  border-radius: var(--radius-sm);
  background: var(--tint-primary);
  color: var(--bs-primary);
  display: inline-flex;
  align-items: center;
  justify-content: center;
  font-size: 20px;
  transition: var(--transition);
}
.rule-quick-action .rule-action-text {
  flex: 1 1 auto;
  min-width: 0;
}
.rule-quick-action .rule-action-text b {
  display: block;
  font-size: 13.5px;
  font-weight: 600;
  color: var(--bs-emphasis-color);
  margin-bottom: 2px;
}
.rule-quick-action .rule-action-text small {
  font-size: 11.5px;
  color: var(--bs-secondary-color);
}
.rule-quick-action .rule-action-go {
  flex: 0 0 auto;
  font-size: 16px;
  color: var(--bs-secondary-color);
  transition: var(--transition);
}
.rule-quick-action:hover {
  border-color: var(--rule-accent-line);
  box-shadow: var(--shadow-lift);
  transform: translateY(-2px);
}
.rule-quick-action:hover i.rule-action-icon {
  background: var(--bs-primary);
  color: #fff;
}
.rule-quick-action:hover .rule-action-go {
  color: var(--bs-primary);
  transform: translateX(2px);
}

/* ============================================================
   9. OFFCANVAS, PANELS AND MODALS
   ============================================================ */
.rule-detail-panel {
  width: 88% !important;
  max-width: 1400px;
}
.rule-detail-panel .offcanvas-header {
  border-bottom: 1px solid var(--bs-border-color);
  padding: 16px 22px;
  align-items: flex-start;
  gap: 14px;
}
.rule-detail-panel .offcanvas-body {
  padding: 20px 22px 28px;
  background: var(--bs-secondary-bg);
}

@media (max-width: 991.98px) {
  .rule-detail-panel {
    width: 100% !important;
  }
}
.rule-detail-title {
  font-size: 20px;
  font-weight: 700;
  color: var(--bs-emphasis-color);
  margin-bottom: 5px;
  line-height: 1.3;
}

.rule-panel {
  height: 100%;
  display: flex;
  flex-direction: column;
  border: 1px solid var(--bs-border-color);
  border-radius: var(--radius);
  background: var(--bs-body-bg);
  box-shadow: var(--shadow);
}
.rule-panel .rule-panel-header {
  display: flex;
  align-items: center;
  gap: 11px;
  padding: 13px 16px;
  border-bottom: 1px solid var(--bs-border-color);
}
.rule-panel .rule-panel-header .rule-panel-icon {
  width: 32px;
  height: 32px;
  flex-shrink: 0;
  border-radius: var(--radius-sm);
  background: var(--tint-primary);
  color: var(--bs-primary);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 16px;
}
.rule-panel .rule-panel-header .rule-panel-title {
  font-size: 14px;
  font-weight: 600;
  color: var(--bs-emphasis-color);
  margin-bottom: 0;
}
.rule-panel .rule-panel-body {
  padding: 14px 16px;
  flex: 1 1 auto;
}
.rule-panel .rule-panel-footer {
  padding: 11px 16px;
  border-top: 1px solid var(--bs-border-color);
  background: var(--bs-secondary-bg);
  border-radius: 0 0 var(--radius) var(--radius);
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  flex-wrap: wrap;
  font-size: 12px;
  color: var(--bs-secondary-color);
}

/* An execution-history row: one past run, with its outcome. */
.run {
  display: flex;
  align-items: center;
  gap: 11px;
  padding: 10px 0;
  border-bottom: 1px dashed var(--bs-border-color);
}
.run:last-child {
  border-bottom: 0;
  padding-bottom: 0;
}
.run > i {
  width: 28px;
  height: 28px;
  flex-shrink: 0;
  border-radius: 8px;
  background: var(--rule-on-soft);
  color: var(--rule-on);
  display: inline-flex;
  align-items: center;
  justify-content: center;
  font-size: 14px;
}
.run.is-failed > i {
  background: var(--rule-stop-soft);
  color: var(--rule-stop);
}
.run.is-skipped > i {
  background: var(--bs-secondary-bg);
  color: var(--bs-secondary-color);
}
.run .run-text {
  flex: 1 1 auto;
  min-width: 0;
  font-size: 12.5px;
  color: var(--bs-emphasis-color);
}
.run .run-text small {
  display: block;
  font-size: 11px;
  color: var(--bs-secondary-color);
}
.run .run-when {
  flex: 0 0 auto;
  font-size: 11px;
  color: var(--bs-secondary-color);
}

/* A dependency edge — this rule feeds, or is fed by, another. */
.dependency {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 10px 0;
  border-bottom: 1px dashed var(--bs-border-color);
}
.dependency:last-child {
  border-bottom: 0;
  padding-bottom: 0;
}
.dependency > i {
  font-size: 16px;
  color: var(--bs-primary);
  flex-shrink: 0;
}
.dependency .dependency-text {
  flex: 1 1 auto;
  min-width: 0;
}
.dependency .dependency-text b {
  display: block;
  font-size: 12.5px;
  font-weight: 600;
  color: var(--bs-emphasis-color);
}
.dependency .dependency-text small {
  font-size: 11px;
  color: var(--bs-secondary-color);
}

.rule-modal-icon {
  width: 40px;
  height: 40px;
  border-radius: var(--radius-sm);
  background: var(--tint-primary);
  color: var(--bs-primary);
  display: inline-flex;
  align-items: center;
  justify-content: center;
  font-size: 20px;
}
.rule-modal-icon.is-stop {
  background: var(--rule-stop-soft);
  color: var(--rule-stop);
}

.rule-dropzone {
  border: 1px dashed var(--border-strong);
  border-radius: var(--radius);
  background: var(--bs-body-bg);
  padding: 26px 20px;
  text-align: center;
  transition: var(--transition);
}
.rule-dropzone:hover {
  border-color: var(--bs-primary);
  background: var(--tint-primary);
}
.rule-dropzone > i {
  display: block;
  font-size: 30px;
  color: var(--bs-primary);
  margin-bottom: 8px;
}
.rule-dropzone b {
  display: block;
  font-size: 14px;
  font-weight: 600;
  color: var(--bs-emphasis-color);
  margin-bottom: 3px;
}
.rule-dropzone p {
  font-size: 12px;
  color: var(--bs-secondary-color);
  margin: 0 auto 12px;
  max-width: 46ch;
}

/*-----------------
	Alumni — community platform components

	A shared vocabulary for the Alumni Network Platform: the members
	themselves, the chapters they organise into, the mentorship they
	offer, the opportunities they post, the events they attend and
	the stories the school tells about them. Class prefix `alx-`.

	The visual language is a professional community, not a directory.
	A member is drawn as a community tile rather than a contact card:
	the thing that leads is what they can offer the network — mentor,
	recruit, speak — carried as intent pills rather than buried in a
	field list. Chapters, opportunities and events each get their own
	silhouette so the eye can tell the sections apart while scrolling,
	and nothing on the page repeats the shape of a data table.

	Contents
	  1. Tokens + shared pieces
	  2. Community tiles
	  3. Chapter cards
	  4. Career + mentorship rosters
	  5. Opportunity postings
	  6. Event cards
	  7. Spotlight stories
	  8. Community resources
	  9. Community actions
	 10. Offcanvas, panels and modals
-----------------*/
/* ============================================================
   1. TOKENS + SHARED PIECES
   ============================================================ */
:root {
  --community-radius: 14px;
  --community-radius-sm: 9px;
  --community-border: var(--bs-border-color, #E9EDF4);
  --community-border-strong: #EDF1F6;
  --community-surface: #ffffff;
  --community-surface-soft: #F8FAFC;
  --community-surface-hover: rgb(247.24, 248.56, 253.8);
  --community-text: #202C4B;
  --community-muted: #677788;
  --community-accent: rgb(68.92, 51.28, 131.16);
  --community-accent-soft: rgb(242.84, 239.24, 249.24);
  --community-accent-line: rgb(209.4, 195.9, 233.4);
  --community-mono: "SFMono-Regular", "Menlo", "Consolas", monospace;
  --community-shadow: 0 1px 2px rgba(17, 24, 39, .05);
  --community-shadow-lift: 0 10px 28px rgba(17, 24, 39, .10);
  --community-ease: .18s cubic-bezier(.4, 0, .2, 1);
}

/* Sticky toolbar shell — rides just under the fixed 60px layout header.
   Released below lg, where the header itself stops being fixed. */
.toolbar-sticky {
  position: sticky;
  top: 64px;
  z-index: 4;
}
@media (max-width: 991.98px) {
  .toolbar-sticky {
    position: static;
  }
}

/* Section heading — a rule that runs out from the label */
.section-header {
  display: flex;
  align-items: center;
  gap: 14px;
  margin-bottom: 16px;
}
.section-header .section-title {
  font-size: 18px;
  font-weight: 600;
  color: var(--community-text);
  margin: 0;
  white-space: nowrap;
}
.section-header .section-subtitle {
  font-size: 13px;
  color: var(--community-muted);
  margin: 2px 0 0;
}
.section-header .section-rule {
  flex: 1 1 auto;
  height: 1px;
  background: linear-gradient(90deg, var(--community-border) 0%, transparent 100%);
}

/* Micro label */
.metric-label {
  display: block;
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.07em;
  text-transform: uppercase;
  color: var(--community-muted);
  margin-bottom: 3px;
}

/* Skill / interest chip */
.member-tag {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  height: 24px;
  padding: 0 9px;
  border-radius: 999px;
  border: 1px solid var(--community-border);
  background: var(--community-surface-soft);
  font-size: 11.5px;
  font-weight: 500;
  color: var(--community-text);
}
.member-tag i {
  font-size: 13px;
  color: var(--community-muted);
}
.member-tag.is-accent {
  border-color: var(--community-accent-line);
  background: var(--community-accent-soft);
  color: var(--community-accent);
}
.member-tag.is-accent i {
  color: currentcolor;
}

/* Status badge */
.status-badge {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  height: 22px;
  padding: 0 8px;
  border-radius: 6px;
  font-size: 11px;
  font-weight: 600;
  background: var(--community-surface-soft);
  color: var(--community-muted);
}
.status-badge i {
  font-size: 12px;
}
.status-badge.is-open {
  background: rgb(227.52, 247.2, 227.16);
  color: rgb(27.56, 152.04, 36.52);
}
.status-badge.is-soon {
  background: rgb(252.06, 244.36, 219.3);
  color: rgb(149.16, 122.3, 31.5);
}
.status-badge.is-closed {
  background: rgb(252.7, 233.3, 236.5);
  color: rgb(176, 39.68, 71.4);
}
.status-badge.is-accent {
  background: var(--community-accent-soft);
  color: var(--community-accent);
}
.status-badge.is-featured {
  background: var(--community-accent);
  color: #ffffff;
}

/* Avatar stack — who else is here */
.avatar-stack {
  display: flex;
  align-items: center;
}
.avatar-stack img,
.avatar-stack span.more {
  width: 26px;
  height: 26px;
  border-radius: 50%;
  border: 2px solid var(--community-surface);
  margin-left: -8px;
  object-fit: cover;
}
.avatar-stack img:first-child,
.avatar-stack span.more:first-child {
  margin-left: 0;
}
.avatar-stack span.more {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  background: var(--community-surface-soft);
  color: var(--community-muted);
  font-size: 10px;
  font-weight: 700;
}

/* Capacity meter — a fill bar, deliberately not a chart */
.progress-meter {
  height: 5px;
  border-radius: 999px;
  background: var(--community-surface-soft);
  overflow: hidden;
}
.progress-meter span {
  display: block;
  height: 100%;
  border-radius: inherit;
  background: var(--community-accent);
}
.progress-meter.is-warm span {
  background: #EAB300;
}
.progress-meter.is-full span {
  background: #E82646;
}

/* ============================================================
   2. COMMUNITY TILES
   ============================================================ */
.tile {
  position: relative;
  display: flex;
  flex-direction: column;
  height: 100%;
  border: 1px solid var(--community-border);
  border-radius: var(--community-radius);
  background: var(--community-surface);
  box-shadow: var(--community-shadow);
  overflow: hidden;
  width: 100%;
  transition: box-shadow var(--community-ease), border-color var(--community-ease), transform var(--community-ease);
}
.tile:hover {
  border-color: var(--community-accent-line);
  box-shadow: var(--community-shadow-lift);
  transform: translateY(-2px);
}

/* Identity band — cover strip the avatar sits across */
.tile-band {
  position: relative;
  height: 62px;
  background: linear-gradient(135deg, var(--community-accent) 0%, #524ccc 100%);
  /* A faint grid so the band reads as texture, not a colour block */
}
.tile-band::after {
  content: "";
  position: absolute;
  inset: 0;
  background-image: linear-gradient(rgba(255, 255, 255, 0.1) 1px, transparent 1px), linear-gradient(90deg, rgba(255, 255, 255, 0.1) 1px, transparent 1px);
  background-size: 22px 22px;
}
.tile-band .tile-batch {
  position: absolute;
  top: 10px;
  right: 12px;
  z-index: 2;
  display: inline-flex;
  align-items: center;
  gap: 4px;
  height: 22px;
  padding: 0 9px;
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.18);
  border: 1px solid rgba(255, 255, 255, 0.34);
  color: #ffffff;
  font-family: var(--community-mono);
  font-size: 11px;
  font-weight: 600;
}

.tile-identity {
  position: relative;
  display: flex;
  align-items: flex-end;
  gap: 12px;
  padding: 0 16px;
  margin-top: -26px;
  /* Lets the name and role ellipsis instead of forcing the flex row wider */
}
.tile-identity > div {
  min-width: 0;
}
.tile-identity .tile-avatar {
  position: relative;
  flex-shrink: 0;
  width: 62px;
  height: 62px;
  border-radius: 14px;
  border: 3px solid var(--community-surface);
  object-fit: cover;
  background: var(--community-surface-soft);
}
.tile-identity .tile-dot {
  position: absolute;
  left: 62px;
  bottom: 4px;
  width: 12px;
  height: 12px;
  border-radius: 50%;
  border: 2px solid var(--community-surface);
  background: #1ABE17;
}
.tile-identity .tile-name {
  font-size: 15.5px;
  font-weight: 600;
  color: var(--community-text);
  margin: 0 0 1px;
}
.tile-identity .tile-name a {
  color: inherit;
}
.tile-identity .tile-name a:hover {
  color: var(--community-accent);
}
.tile-identity .tile-role {
  font-size: 12.5px;
  color: var(--community-muted);
  margin: 0;
  padding-bottom: 3px;
}

.tile-body {
  flex: 1 1 auto;
  padding: 14px 16px 0;
}

/* Company / industry / country facts, three to a row */
.tile-facts {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 10px;
  padding: 10px 12px;
  border: 1px solid var(--community-border);
  border-radius: var(--community-radius-sm);
  background: var(--community-surface-soft);
  margin-bottom: 12px;
}
.tile-facts p {
  margin: 0;
  font-size: 12.5px;
  font-weight: 500;
  color: var(--community-text);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

/* Intent pills — what this member offers the network */
.intents {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  margin-bottom: 12px;
}

.intent {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  height: 26px;
  padding: 0 10px;
  border-radius: 7px;
  border: 1px dashed var(--community-border-strong);
  background: transparent;
  color: var(--community-muted);
  font-size: 11.5px;
  font-weight: 600;
}
.intent i {
  font-size: 14px;
}
.intent {
  /* Solid + coloured only when the member has actually opted in, so a
     scan of the grid reads availability without reading any labels. */
}
.intent.is-on {
  border-style: solid;
}
.intent.is-on.is-mentor {
  border-color: rgb(154.24, 226.4, 152.92);
  background: rgb(232.1, 248.5, 231.8);
  color: rgb(27.68, 149.12, 37.56);
}
.intent.is-on.is-recruit {
  border-color: rgb(149.4, 187.24, 233);
  background: rgb(231, 239.6, 250);
  color: rgb(19.76, 85.04, 168.6);
}
.intent.is-on.is-speak {
  border-color: rgb(245.76, 221.56, 142.8);
  background: rgb(252.06, 244.36, 219.3);
  color: rgb(141.08, 116.9, 34.5);
}

/* Achievement line */
.tile-note {
  display: flex;
  align-items: flex-start;
  gap: 7px;
  font-size: 12.5px;
  color: var(--community-muted);
  margin-bottom: 12px;
}
.tile-note i {
  flex-shrink: 0;
  margin-top: 1px;
  font-size: 15px;
  color: #EAB300;
}

.tile-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  padding: 11px 16px;
  border-top: 1px solid var(--community-border);
  background: rgb(251.78, 252.7, 253.62);
}
.tile-footer .tile-connections {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 11.5px;
  color: var(--community-muted);
}

/* Compact icon button used across footers */
.icon-button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 30px;
  height: 30px;
  border-radius: 8px;
  border: 1px solid var(--community-border);
  background: var(--community-surface);
  color: var(--community-muted);
  transition: all var(--community-ease);
}
.icon-button i {
  font-size: 15px;
}
.icon-button:hover {
  border-color: var(--community-accent-line);
  background: var(--community-accent-soft);
  color: var(--community-accent);
}

/* ============================================================
   3. CHAPTER CARDS
   ============================================================ */
.chapter {
  position: relative;
  display: flex;
  flex-direction: column;
  height: 100%;
  width: 100%;
  padding: 16px 16px 14px 20px;
  border: 1px solid var(--community-border);
  border-radius: var(--community-radius);
  background: var(--community-surface);
  box-shadow: var(--community-shadow);
  transition: box-shadow var(--community-ease), border-color var(--community-ease);
  /* Regional rail — the one piece of colour that distinguishes chapters */
}
.chapter::before {
  content: "";
  position: absolute;
  left: 0;
  top: 14px;
  bottom: 14px;
  width: 3px;
  border-radius: 0 3px 3px 0;
  background: var(--chapter-hue, var(--community-accent));
}
.chapter:hover {
  border-color: var(--community-accent-line);
  box-shadow: var(--community-shadow-lift);
}
.chapter.hue-teal {
  --chapter-hue: #02a8b5;
}
.chapter.hue-purple {
  --chapter-hue: #4A00E5;
}
.chapter.hue-warning {
  --chapter-hue: #EAB300;
}
.chapter.hue-success {
  --chapter-hue: #1ABE17;
}
.chapter.hue-info {
  --chapter-hue: #0F65CD;
}
.chapter.hue-danger {
  --chapter-hue: #E82646;
}

.chapter-header {
  display: flex;
  align-items: center;
  gap: 11px;
  margin-bottom: 13px;
}
.chapter-header .crest {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  width: 42px;
  height: 42px;
  border-radius: 12px;
  background: color-mix(in srgb, var(--chapter-hue, var(--community-accent)) 12%, #ffffff);
  color: var(--chapter-hue, var(--community-accent));
}
.chapter-header .crest i {
  font-size: 21px;
}
.chapter-header h6 {
  font-size: 14.5px;
  font-weight: 600;
  color: var(--community-text);
  margin: 0 0 1px;
}
.chapter-header p {
  font-size: 12px;
  color: var(--community-muted);
  margin: 0;
}

/* Meetup strip */
.meetup {
  display: flex;
  align-items: center;
  gap: 9px;
  padding: 9px 11px;
  border-radius: var(--community-radius-sm);
  background: var(--community-surface-soft);
  margin-bottom: 12px;
}
.meetup i {
  font-size: 16px;
  color: var(--chapter-hue, var(--community-accent));
}
.meetup .meetup-text {
  font-size: 12.5px;
  font-weight: 500;
  color: var(--community-text);
  line-height: 1.35;
}
.meetup .meetup-text small {
  display: block;
  font-size: 11px;
  font-weight: 400;
  color: var(--community-muted);
}

.chapter-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  margin-top: auto;
  padding-top: 12px;
  border-top: 1px dashed var(--community-border);
}
.chapter-footer .coordinator {
  display: flex;
  align-items: center;
  gap: 7px;
  min-width: 0;
}
.chapter-footer .coordinator img {
  width: 26px;
  height: 26px;
  border-radius: 50%;
  object-fit: cover;
}
.chapter-footer .coordinator span {
  font-size: 12px;
  color: var(--community-text);
  font-weight: 500;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.chapter-footer .coordinator small {
  display: block;
  font-size: 10.5px;
  font-weight: 400;
  color: var(--community-muted);
}

/* ============================================================
   4. CAREER + MENTORSHIP ROSTERS
   ============================================================ */
.roster {
  height: 100%;
  width: 100%;
  border: 1px solid var(--community-border);
  border-radius: var(--community-radius);
  background: var(--community-surface);
  box-shadow: var(--community-shadow);
  overflow: hidden;
}

.roster-header {
  display: flex;
  align-items: center;
  gap: 11px;
  padding: 14px 16px;
  border-bottom: 1px solid var(--community-border);
}
.roster-header .roster-icon {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  width: 38px;
  height: 38px;
  border-radius: 11px;
  background: var(--community-accent-soft);
  color: var(--community-accent);
}
.roster-header .roster-icon i {
  font-size: 19px;
}
.roster-header h6 {
  font-size: 14px;
  font-weight: 600;
  margin: 0 0 1px;
  color: var(--community-text);
}
.roster-header p {
  font-size: 11.5px;
  color: var(--community-muted);
  margin: 0;
}

/* One person inside a roster */
.person {
  display: flex;
  align-items: center;
  gap: 11px;
  padding: 11px 16px;
  border-bottom: 1px solid var(--community-border);
  transition: background var(--community-ease);
}
.person:last-child {
  border-bottom: 0;
}
.person:hover {
  background: var(--community-surface-hover);
}
.person img {
  width: 36px;
  height: 36px;
  border-radius: 10px;
  object-fit: cover;
  flex-shrink: 0;
}
.person .person-main {
  flex: 1 1 auto;
  min-width: 0;
}
.person .person-name {
  font-size: 13px;
  font-weight: 600;
  color: var(--community-text);
  margin: 0 0 1px;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.person .person-org {
  font-size: 11.5px;
  color: var(--community-muted);
  margin: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.person .person-meta {
  flex-shrink: 0;
  text-align: right;
}
.person .person-meta .years {
  display: block;
  font-family: var(--community-mono);
  font-size: 12px;
  font-weight: 600;
  color: var(--community-text);
}
.person .person-meta small {
  font-size: 10px;
  color: var(--community-muted);
}

/* Availability dot + word */
.availability {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  font-size: 11px;
  font-weight: 600;
  color: var(--community-muted);
}
.availability::before {
  content: "";
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: currentcolor;
}
.availability.is-free {
  color: rgb(27.8, 146.2, 38.6);
}
.availability.is-limited {
  color: rgb(137.04, 114.2, 36);
}
.availability.is-busy {
  color: #677788;
}

.roster-footer {
  padding: 11px 16px;
  border-top: 1px solid var(--community-border);
  background: rgb(251.78, 252.7, 253.62);
}

/* ============================================================
   5. OPPORTUNITY POSTINGS
   ============================================================ */
.post {
  position: relative;
  display: flex;
  flex-direction: column;
  height: 100%;
  padding: 15px 16px 14px;
  border: 1px solid var(--community-border);
  border-radius: var(--community-radius);
  background: var(--community-surface);
  box-shadow: var(--community-shadow);
  transition: box-shadow var(--community-ease), border-color var(--community-ease);
}
.post:hover {
  border-color: var(--community-accent-line);
  box-shadow: var(--community-shadow-lift);
}

/* Category worn on the top edge rather than as another badge in the body */
.post-category {
  position: absolute;
  top: -1px;
  left: 16px;
  height: 3px;
  width: 46px;
  border-radius: 0 0 3px 3px;
  background: var(--post-hue, var(--community-accent));
}

.post-header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 10px;
  margin-bottom: 11px;
}
.post-header h6 {
  font-size: 14.5px;
  font-weight: 600;
  color: var(--community-text);
  margin: 0 0 3px;
  line-height: 1.35;
}
.post-header .post-org {
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: 12px;
  color: var(--community-muted);
}
.post-header .post-org img {
  width: 18px;
  height: 18px;
  border-radius: 5px;
  object-fit: cover;
}

.post-meta {
  display: flex;
  flex-wrap: wrap;
  gap: 6px 14px;
  margin-bottom: 12px;
  font-size: 12px;
  color: var(--community-muted);
}
.post-meta span {
  display: inline-flex;
  align-items: center;
  gap: 5px;
}
.post-meta i {
  font-size: 14px;
}

/* Deadline strip — the fact that decides whether the card matters */
.deadline {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  margin-top: auto;
  padding: 9px 11px;
  border-radius: var(--community-radius-sm);
  background: var(--community-surface-soft);
  font-size: 12px;
}
.deadline .deadline-when {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-weight: 500;
  color: var(--community-text);
}
.deadline .deadline-when i {
  font-size: 15px;
  color: var(--community-muted);
}

/* ============================================================
   6. EVENT CARDS
   ============================================================ */
.event {
  display: flex;
  height: 100%;
  width: 100%;
  border: 1px solid var(--community-border);
  border-radius: var(--community-radius);
  background: var(--community-surface);
  box-shadow: var(--community-shadow);
  overflow: hidden;
  transition: box-shadow var(--community-ease), border-color var(--community-ease);
}
.event:hover {
  border-color: var(--community-accent-line);
  box-shadow: var(--community-shadow-lift);
}

/* Date block — a torn calendar leaf down the left edge */
.event-date {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  width: 78px;
  padding: 14px 6px;
  border-right: 1px solid var(--community-border);
  background: linear-gradient(180deg, var(--community-accent-soft) 0%, var(--community-surface) 100%);
}
.event-date .event-day {
  font-size: 26px;
  font-weight: 700;
  line-height: 1;
  color: var(--community-accent);
}
.event-date .event-month {
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--community-muted);
  margin-top: 3px;
}
.event-date .event-time {
  font-size: 10.5px;
  color: var(--community-muted);
  margin-top: 7px;
  padding-top: 7px;
  border-top: 1px dashed var(--community-border);
  width: 100%;
  text-align: center;
}

.event-body {
  flex: 1 1 auto;
  min-width: 0;
  padding: 13px 15px;
  display: flex;
  flex-direction: column;
}
.event-body h6 {
  font-size: 14.5px;
  font-weight: 600;
  color: var(--community-text);
  margin: 0 0 4px;
}
.event-body .event-where {
  display: flex;
  flex-wrap: wrap;
  gap: 4px 13px;
  font-size: 12px;
  color: var(--community-muted);
  margin-bottom: 11px;
}
.event-body .event-where span {
  display: inline-flex;
  align-items: center;
  gap: 5px;
}
.event-body .event-where i {
  font-size: 14px;
}

.event-seats {
  margin-top: auto;
}
.event-seats .seats-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  font-size: 11.5px;
  color: var(--community-muted);
  margin-bottom: 5px;
}
.event-seats .seats-row b {
  color: var(--community-text);
}

.event-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  margin-top: 12px;
  padding-top: 11px;
  border-top: 1px solid var(--community-border);
}

/* ============================================================
   7. SPOTLIGHT STORIES
   ============================================================ */
.spotlight {
  position: relative;
  display: flex;
  flex-direction: column;
  height: 100%;
  border-radius: var(--community-radius);
  overflow: hidden;
  border: 1px solid var(--community-border);
  background: var(--community-surface);
  box-shadow: var(--community-shadow);
  transition: box-shadow var(--community-ease), transform var(--community-ease);
}
.spotlight:hover {
  box-shadow: var(--community-shadow-lift);
  transform: translateY(-2px);
}

.spotlight-photo {
  position: relative;
  height: 168px;
  overflow: hidden;
}
.spotlight-photo img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition: transform 0.3s cubic-bezier(0.4, 0, 0.2, 1);
}
.spotlight-photo {
  /* Scrim so the ribbon and award stay legible on any photo */
}
.spotlight-photo::after {
  content: "";
  position: absolute;
  inset: 0;
  background: linear-gradient(180deg, rgba(32, 44, 75, 0.48) 0%, rgba(32, 44, 75, 0) 46%, rgba(32, 44, 75, 0.72) 100%);
}
.spotlight-photo .spotlight-ribbon {
  position: absolute;
  top: 12px;
  left: 12px;
  z-index: 2;
}
.spotlight-photo .spotlight-award {
  position: absolute;
  left: 14px;
  right: 14px;
  bottom: 11px;
  z-index: 2;
  display: flex;
  align-items: center;
  gap: 7px;
  color: #ffffff;
  font-size: 12px;
  font-weight: 500;
}
.spotlight-photo .spotlight-award i {
  font-size: 16px;
  color: #EAB300;
}

.spotlight:hover .spotlight-photo img {
  transform: scale(1.04);
}

.spotlight-body {
  flex: 1 1 auto;
  padding: 14px 16px 0;
}
.spotlight-body h6 {
  font-size: 15.5px;
  font-weight: 600;
  line-height: 1.4;
  color: var(--community-text);
  margin: 0 0 7px;
}
.spotlight-body p {
  font-size: 12.5px;
  color: var(--community-muted);
  line-height: 1.6;
  margin: 0;
}

.spotlight-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  padding: 13px 16px;
}
.spotlight-footer .spotlight-who {
  display: flex;
  align-items: center;
  gap: 9px;
  min-width: 0;
}
.spotlight-footer .spotlight-who img {
  width: 32px;
  height: 32px;
  border-radius: 9px;
  object-fit: cover;
}
.spotlight-footer .spotlight-who b {
  display: block;
  font-size: 12.5px;
  font-weight: 600;
  color: var(--community-text);
}
.spotlight-footer .spotlight-who small {
  font-size: 11px;
  color: var(--community-muted);
}

/* ============================================================
   8. COMMUNITY RESOURCES
   ============================================================ */
/* Rounded glyph tile. Top level rather than nested under .resource because the
   offcanvas event rows reuse it outside a resource card. */
.resource-icon {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  width: 40px;
  height: 40px;
  border-radius: 11px;
  background: var(--community-surface-soft);
  color: var(--community-accent);
}
.resource-icon i {
  font-size: 20px;
}

.resource {
  display: flex;
  align-items: center;
  gap: 12px;
  height: 100%;
  padding: 13px 14px;
  border: 1px solid var(--community-border);
  border-radius: var(--community-radius);
  background: var(--community-surface);
  box-shadow: var(--community-shadow);
  transition: all var(--community-ease);
}
.resource:hover {
  border-color: var(--community-accent-line);
  background: var(--community-surface-hover);
  box-shadow: var(--community-shadow-lift);
}
.resource:hover .resource-go {
  color: var(--community-accent);
  transform: translateX(2px);
}
.resource .resource-main {
  flex: 1 1 auto;
  min-width: 0;
}
.resource .resource-main h6 {
  font-size: 13.5px;
  font-weight: 600;
  color: var(--community-text);
  margin: 0 0 2px;
}
.resource .resource-main p {
  font-size: 11.5px;
  color: var(--community-muted);
  margin: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.resource .resource-go {
  flex-shrink: 0;
  color: var(--community-muted);
  font-size: 17px;
  transition: all var(--community-ease);
}

/* ============================================================
   9. COMMUNITY ACTIONS
   ============================================================ */
.action {
  position: relative;
  display: block;
  height: 100%;
  padding: 16px 15px 14px;
  border: 1px solid var(--community-border);
  border-radius: var(--community-radius);
  background: var(--community-surface);
  box-shadow: var(--community-shadow);
  text-align: left;
  width: 100%;
  transition: all var(--community-ease);
}
.action:hover {
  border-color: var(--community-accent);
  box-shadow: var(--community-shadow-lift);
  transform: translateY(-2px);
}
.action .action-icon {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 38px;
  height: 38px;
  border-radius: 11px;
  background: var(--community-accent-soft);
  color: var(--community-accent);
  margin-bottom: 11px;
}
.action .action-icon i {
  font-size: 19px;
}
.action h6 {
  font-size: 13.5px;
  font-weight: 600;
  color: var(--community-text);
  margin: 0 0 3px;
}
.action p {
  font-size: 11.5px;
  color: var(--community-muted);
  line-height: 1.5;
  margin: 0;
}
.action .action-go {
  position: absolute;
  top: 16px;
  right: 15px;
  color: var(--community-border-strong);
  font-size: 16px;
  transition: all var(--community-ease);
}
.action:hover .action-go {
  color: var(--community-accent);
  transform: translateX(2px);
}

/* ============================================================
   10. OFFCANVAS, PANELS AND MODALS
   ============================================================ */
.detail-panel {
  width: 88%;
}
@media (max-width: 991.98px) {
  .detail-panel {
    width: 100%;
  }
}
.detail-panel .offcanvas-body {
  background: rgb(252.2, 253, 253.8);
}

/* Member header inside the offcanvas */
.detail-identity {
  display: flex;
  align-items: center;
  gap: 14px;
}
.detail-identity img {
  width: 56px;
  height: 56px;
  border-radius: 14px;
  object-fit: cover;
}
.detail-identity h5 {
  font-size: 17px;
  font-weight: 600;
  margin: 0 0 2px;
  color: var(--community-text);
}
.detail-identity p {
  font-size: 12.5px;
  color: var(--community-muted);
  margin: 0;
}

/* Generic panel used for every block in the offcanvas */
.panel {
  border: 1px solid var(--community-border);
  border-radius: var(--community-radius);
  background: var(--community-surface);
  box-shadow: var(--community-shadow);
  margin-bottom: 16px;
}
.panel .panel-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  padding: 12px 16px;
  border-bottom: 1px solid var(--community-border);
}
.panel .panel-header h6 {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 13.5px;
  font-weight: 600;
  color: var(--community-text);
  margin: 0;
}
.panel .panel-header h6 i {
  font-size: 16px;
  color: var(--community-accent);
}
.panel .panel-body {
  padding: 14px 16px;
}
.panel .panel-body.is-flush {
  padding: 0;
}

/* Definition rows — profile and education facts */
.facts {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(160px, 1fr));
  gap: 14px;
}
.facts .fact p {
  margin: 0;
  font-size: 13px;
  font-weight: 500;
  color: var(--community-text);
}

/* Professional journey — stacked posting blocks, not a timeline */
.journey .job {
  display: flex;
  gap: 12px;
  padding: 12px 16px;
  border-bottom: 1px solid var(--community-border);
}
.journey .job:last-child {
  border-bottom: 0;
}
.journey .job .job-logo {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  width: 38px;
  height: 38px;
  border-radius: 10px;
  border: 1px solid var(--community-border);
  background: var(--community-surface-soft);
  color: var(--community-muted);
}
.journey .job .job-logo i {
  font-size: 18px;
}
.journey .job h6 {
  font-size: 13px;
  font-weight: 600;
  color: var(--community-text);
  margin: 0 0 2px;
}
.journey .job .job-org {
  font-size: 12px;
  color: var(--community-muted);
  margin: 0 0 4px;
}
.journey .job .job-span {
  font-family: var(--community-mono);
  font-size: 11px;
  color: var(--community-muted);
  white-space: nowrap;
  margin-left: auto;
  flex-shrink: 0;
}
.journey .job.is-current .job-logo {
  border-color: var(--community-accent-line);
  background: var(--community-accent-soft);
  color: var(--community-accent);
}

/* Achievement rows */
.award {
  display: flex;
  align-items: flex-start;
  gap: 10px;
  padding: 10px 0;
  border-bottom: 1px dashed var(--community-border);
}
.award:first-child {
  padding-top: 0;
}
.award:last-child {
  border-bottom: 0;
  padding-bottom: 0;
}
.award i {
  flex-shrink: 0;
  margin-top: 1px;
  font-size: 17px;
  color: #EAB300;
}
.award b {
  display: block;
  font-size: 12.5px;
  font-weight: 600;
  color: var(--community-text);
}
.award small {
  font-size: 11.5px;
  color: var(--community-muted);
}

/* Community participation counters, no card chrome */
.tally {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(96px, 1fr));
  gap: 1px;
  background: var(--community-border);
  border-radius: var(--community-radius-sm);
  overflow: hidden;
}
.tally .tally-cell {
  padding: 12px 10px;
  background: var(--community-surface);
  text-align: center;
}
.tally .tally-cell b {
  display: block;
  font-size: 19px;
  font-weight: 700;
  color: var(--community-text);
  line-height: 1.15;
}
.tally .tally-cell small {
  font-size: 11px;
  color: var(--community-muted);
}

/* Gallery thumbs */
.gallery {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(92px, 1fr));
  gap: 8px;
}
.gallery img {
  width: 100%;
  aspect-ratio: 4/3;
  object-fit: cover;
  border-radius: var(--community-radius-sm);
  border: 1px solid var(--community-border);
}

/* Social links */
.social {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}
.social a {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  height: 32px;
  padding: 0 12px;
  border-radius: 8px;
  border: 1px solid var(--community-border);
  background: var(--community-surface-soft);
  font-size: 12px;
  font-weight: 500;
  color: var(--community-text);
  transition: all var(--community-ease);
}
.social a i {
  font-size: 15px;
  color: var(--community-muted);
}
.social a:hover {
  border-color: var(--community-accent-line);
  background: var(--community-accent-soft);
  color: var(--community-accent);
}
.social a:hover i {
  color: currentcolor;
}

/* Note entries */
.note-item {
  padding: 11px 12px;
  border-radius: var(--community-radius-sm);
  background: var(--community-surface-soft);
  border: 1px solid var(--community-border);
  margin-bottom: 9px;
}
.note-item:last-child {
  margin-bottom: 0;
}
.note-item p {
  font-size: 12.5px;
  color: var(--community-text);
  line-height: 1.55;
  margin: 0 0 6px;
}
.note-item .note-by {
  font-size: 11px;
  color: var(--community-muted);
}

/* Related alumni rows */
.related-item {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 9px 16px;
  border-bottom: 1px solid var(--community-border);
  transition: background var(--community-ease);
}
.related-item:last-child {
  border-bottom: 0;
}
.related-item:hover {
  background: var(--community-surface-hover);
}
.related-item img {
  width: 34px;
  height: 34px;
  border-radius: 9px;
  object-fit: cover;
}
.related-item .related-main {
  flex: 1 1 auto;
  min-width: 0;
}
.related-item .related-main b {
  display: block;
  font-size: 12.5px;
  font-weight: 600;
  color: var(--community-text);
}
.related-item .related-main small {
  font-size: 11px;
  color: var(--community-muted);
}

/* Modal header icon */
.modal-icon {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 36px;
  height: 36px;
  border-radius: 10px;
  background: var(--community-accent-soft);
  color: var(--community-accent);
  margin-right: 11px;
}
.modal-icon i {
  font-size: 18px;
}

/* ============================================================
   DARK THEME
   ============================================================ */
[data-theme=dark],
[data-bs-theme=dark] {
  --community-border: #2c3448;
  --community-border-strong: #3a4459;
  --community-surface: #1f2536;
  --community-surface-soft: #262d40;
  --community-surface-hover: #2a3145;
  --community-text: #e6e9f2;
  --community-muted: #9aa3b8;
  --community-accent: rgb(175.96, 152.56, 217.56);
  --community-accent-soft: rgba(103, 58, 183, .18);
  --community-accent-line: rgba(103, 58, 183, .42);
  --community-shadow: 0 1px 2px rgba(0, 0, 0, .32);
  --community-shadow-lift: 0 10px 28px rgba(0, 0, 0, .42);
}
[data-theme=dark] .tile-footer,
[data-theme=dark] .roster-footer,
[data-bs-theme=dark] .tile-footer,
[data-bs-theme=dark] .roster-footer {
  background: #232a3c;
}
[data-theme=dark] .intent,
[data-bs-theme=dark] .intent {
  border-color: #3a4459;
}
[data-theme=dark] .detail-panel .offcanvas-body,
[data-bs-theme=dark] .detail-panel .offcanvas-body {
  background: #1a2030;
}
[data-theme=dark] .tile-band::after,
[data-bs-theme=dark] .tile-band::after {
  background-image: linear-gradient(rgba(255, 255, 255, 0.06) 1px, transparent 1px), linear-gradient(90deg, rgba(255, 255, 255, 0.06) 1px, transparent 1px);
}

.sticky-item {
  position: sticky;
  top: 80px;
}

.choices[data-type*=select-multiple] .choices__inner {
  padding-top: 3px !important;
  padding-left: 10px !important;
}

.timepicker ~ .cal-icon, .datetimepicker ~ .cal-icon {
  display: none !important;
}

